INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Gn', 42, 'pt', '[{"numero": 1, "texto": "E vendo Jacó que no Egito havia alimentos, disse a seus filhos: Por que estais olhando uns para os outros?"}, {"numero": 2, "texto": "E disse: Eis que, eu ouvi que há alimentos no Egito; descei ali, e comprai dali para nós, para que possamos viver, e não nos morramos."}, {"numero": 3, "texto": "E desceram os dez irmãos de José a comprar trigo ao Egito."}, {"numero": 4, "texto": "Mas Jacó não enviou a Benjamim irmão de José com seus irmãos; porque disse: Não seja acaso que lhe aconteça algum desastre."}, {"numero": 5, "texto": "E vieram os filhos de Israel a comprar entre os que vinham: porque havia fome na terra de Canaã."}, {"numero": 6, "texto": "E José era o senhor da terra, que vendia a todo o povo da terra: e chegaram os irmãos de José, e inclinaram-se a ele rosto por terra."}, {"numero": 7, "texto": "E José quando viu seus irmãos, reconheceu-os; mas fez que não os conhecesse, e falou-lhes asperamente, e lhes disse: De onde viestes? Eles responderam: Da terra de Canaã, para comprar alimentos."}, {"numero": 8, "texto": "José, pois, reconheceu a seus irmãos; mas eles não o reconheceram."}, {"numero": 9, "texto": "Então se lembrou José dos sonhos que havia tido deles, e disse-lhes: Sois espias; viestes ver a fraqueza desta terra."}, {"numero": 10, "texto": "E eles lhe responderam: Não, meu senhor; teus servos vieram comprar alimentos."}, {"numero": 11, "texto": "Todos nós somos filhos de um homem; somos homens honestos; teus servos nunca foram espias."}, {"numero": 12, "texto": "E ele lhes disse: Não; viestes ver a fraqueza desta terra."}, {"numero": 13, "texto": "E eles responderam: Teus servos somos doze irmãos, filhos de um homem na terra de Canaã; e eis que o menor está hoje com nosso pai, e outro desapareceu."}, {"numero": 14, "texto": "E José lhes disse: Isso é o que vos disse, afirmando que sois espias;"}, {"numero": 15, "texto": "Nisto sereis provados: Vive Faraó que não saireis daqui, a não ser quando vosso irmão menor vier aqui."}, {"numero": 16, "texto": "Enviai um de vós, e traga a vosso irmão; e vós ficai presos, e vossas palavras serão provadas, se há verdade convosco: e se não, vive Faraó, que sois espias."}, {"numero": 17, "texto": "E juntou-os no cárcere por três dias."}, {"numero": 18, "texto": "E ao terceiro dia disse-lhes José: Fazei isto, e vivei; eu temo a Deus;"}, {"numero": 19, "texto": "Se sois homens honestos, fique preso na casa de vosso cárcere um de vossos irmãos; e vós ide, levai o alimento para a fome de vossa casa;"}, {"numero": 20, "texto": "Porém haveis de trazer-me a vosso irmão mais novo, e serão comprovadas vossas palavras, e não morrereis. E eles o fizeram assim."}, {"numero": 21, "texto": "E diziam um ao outro: Verdadeiramente pecamos contra nosso irmão, que vimos a angústia de sua alma quando nos rogava, e não o ouvimos; por isso veio sobre nós esta angústia."}, {"numero": 22, "texto": "Então Rúben lhes respondeu, dizendo: Não vos falei eu e disse: Não pequeis contra o jovem; e não escutastes? Eis que também o sangue dele é requerido."}, {"numero": 23, "texto": "E eles não sabiam que os entendia José, porque havia intérprete entre eles."}, {"numero": 24, "texto": "E apartou-se ele deles, e chorou: depois voltou a eles, e lhes falou, e tomou dentre eles a Simeão, e aprisionou-lhe à vista deles."}, {"numero": 25, "texto": "E mandou José que enchessem seus sacos de trigo, e devolvessem o dinheiro de cada um deles, pondo-o em seu saco, e lhes dessem comida para o caminho; e fez-se assim com eles."}, {"numero": 26, "texto": "E eles puseram seu trigo sobre seus asnos, e foram-se dali."}, {"numero": 27, "texto": "E abrindo um deles seu saco para dar de comer a seu asno no lugar de parada, viu seu dinheiro que estava na boca de seu saco."}, {"numero": 28, "texto": "E disse a seus irmãos: Meu dinheiro se me foi devolvido, e ainda ei-lo aqui em meu saco. Alarmou-se, então, o coração deles e, espantados, disseram um ao outro: Que é isto que Deus nos fez?"}, {"numero": 29, "texto": "E vindos a Jacó seu pai em terra de Canaã, contaram-lhe tudo o que lhes havia acontecido, dizendo:"}, {"numero": 30, "texto": "Aquele homem, senhor da terra, nos falou asperamente, e nos tratou como espias da terra:"}, {"numero": 31, "texto": "E nós lhe dissemos: Somos homens honestos, nunca fomos espias:"}, {"numero": 32, "texto": "Somos doze irmãos, filhos de nosso pai; um desapareceu, e o menor está hoje com nosso pai na terra de Canaã."}, {"numero": 33, "texto": "E aquele homem, senhor da terra, nos disse: Nisto conhecerei que sois homens honestos; deixai comigo um de vossos irmãos, e tomai para a fome de vossas casas, e ide,"}, {"numero": 34, "texto": "E trazei-me a vosso irmão o mais novo, para que eu saiba que não sois espias, mas sim homens honestos: assim vos darei a vosso irmão, e negociareis na terra."}, {"numero": 35, "texto": "E aconteceu que esvaziando eles seus sacos, eis que no saco de cada um estava o pacote de seu dinheiro: e vendo eles e seu pai os pacotes de seu dinheiro, tiveram temor."}, {"numero": 36, "texto": "Então seu pai Jacó lhes disse: Vós me privastes de meus filhos; José desapareceu, nem Simeão tampouco, e a Benjamim o levareis; contra mim são todas estas coisas."}, {"numero": 37, "texto": "E Rúben falou a seu pai, dizendo: Podes matar meus dois filhos, se eu não o devolver a ti; entrega-o em minha mão, que eu o devolverei a ti."}, {"numero": 38, "texto": "E ele disse: Não descerá meu filho convosco; que seu irmão é morto, e ele somente restou; e se lhe acontecer algum desastre no caminho por onde vades, fareis descer meus cabelos brancos com tristeza ao Xeol."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 42, 'en', '[{"numero": 1, "texto": "Now when Jacob saw that there was corn in Egypt, Jacob said unto his sons, Why do ye look one upon another?"}, {"numero": 2, "texto": "And he said, Behold, I have heard that there is corn in Egypt: get you down thither, and buy for us from thence; that we may live, and not die."}, {"numero": 3, "texto": "And Joseph''s ten brethren went down to buy corn in Egypt."}, {"numero": 4, "texto": "But Benjamin, Joseph''s brother, Jacob sent not with his brethren; for he said, Lest peradventure mischief befall him."}, {"numero": 5, "texto": "And the sons of Israel came to buy corn among those that came: for the famine was in the land of Canaan."}, {"numero": 6, "texto": "And Joseph was the governor over the land, and he it was that sold to all the people of the land: and Joseph''s brethren came, and bowed down themselves before him with their faces to the earth."}, {"numero": 7, "texto": "And Joseph saw his brethren, and he knew them, but made himself strange unto them, and spake roughly unto them; and he said unto them, Whence come ye? And they said, From the land of Canaan to buy food."}, {"numero": 8, "texto": "And Joseph knew his brethren, but they knew not him."}, {"numero": 9, "texto": "And Joseph remembered the dreams which he dreamed of them, and said unto them, Ye are spies; to see the nakedness of the land ye are come."}, {"numero": 10, "texto": "And they said unto him, Nay, my lord, but to buy food are thy servants come."}, {"numero": 11, "texto": "We are all one man''s sons; we are true men, thy servants are no spies."}, {"numero": 12, "texto": "And he said unto them, Nay, but to see the nakedness of the land ye are come."}, {"numero": 13, "texto": "And they said, Thy servants are twelve brethren, the sons of one man in the land of Canaan; and, behold, the youngest is this day with our father, and one is not."}, {"numero": 14, "texto": "And Joseph said unto them, That is it that I spake unto you, saying, Ye are spies:"}, {"numero": 15, "texto": "Hereby ye shall be proved: By the life of Pharaoh ye shall not go forth hence, except your youngest brother come hither."}, {"numero": 16, "texto": "Send one of you, and let him fetch your brother, and ye shall be kept in prison, that your words may be proved, whether there be any truth in you: or else by the life of Pharaoh surely ye are spies."}, {"numero": 17, "texto": "And he put them all together into ward three days."}, {"numero": 18, "texto": "And Joseph said unto them the third day, This do, and live; for I fear God:"}, {"numero": 19, "texto": "If ye be true men, let one of your brethren be bound in the house of your prison: go ye, carry corn for the famine of your houses:"}, {"numero": 20, "texto": "But bring your youngest brother unto me; so shall your words be verified, and ye shall not die. And they did so."}, {"numero": 21, "texto": "And they said one to another, We are verily guilty concerning our brother, in that we saw the anguish of his soul, when he besought us, and we would not hear; therefore is this distress come upon us."}, {"numero": 22, "texto": "And Reuben answered them, saying, Spake I not unto you, saying, Do not sin against the child; and ye would not hear? therefore, behold, also his blood is required."}, {"numero": 23, "texto": "And they knew not that Joseph understood them; for he spake unto them by an interpreter."}, {"numero": 24, "texto": "And he turned himself about from them, and wept; and returned to them again, and communed with them, and took from them Simeon, and bound him before their eyes."}, {"numero": 25, "texto": "Then Joseph commanded to fill their sacks with corn, and to restore every man''s money into his sack, and to give them provision for the way: and thus did he unto them."}, {"numero": 26, "texto": "And they laded their asses with the corn, and departed thence."}, {"numero": 27, "texto": "And as one of them opened his sack to give his ass provender in the inn, he espied his money; for, behold, it was in his sack''s mouth."}, {"numero": 28, "texto": "And he said unto his brethren, My money is restored; and, lo, it is even in my sack: and their heart failed them, and they were afraid, saying one to another, What is this that God hath done unto us?"}, {"numero": 29, "texto": "And they came unto Jacob their father unto the land of Canaan, and told him all that befell unto them; saying,"}, {"numero": 30, "texto": "The man, who is the lord of the land, spake roughly to us, and took us for spies of the country."}, {"numero": 31, "texto": "And we said unto him, We are true men; we are no spies:"}, {"numero": 32, "texto": "We be twelve brethren, sons of our father; one is not, and the youngest is this day with our father in the land of Canaan."}, {"numero": 33, "texto": "And the man, the lord of the country, said unto us, Hereby shall I know that ye are true men; leave one of your brethren here with me, and take food for the famine of your households, and be gone:"}, {"numero": 34, "texto": "And bring your youngest brother unto me: then shall I know that ye are no spies, but that ye are true men: so will I deliver you your brother, and ye shall traffick in the land."}, {"numero": 35, "texto": "And it came to pass as they emptied their sacks, that, behold, every man''s bundle of money was in his sack: and when both they and their father saw the bundles of money, they were afraid."}, {"numero": 36, "texto": "And Jacob their father said unto them, Me have ye bereaved of my children: Joseph is not, and Simeon is not, and ye will take Benjamin away: all these things are against me."}, {"numero": 37, "texto": "And Reuben spake unto his father, saying, Slay my two sons, if I bring him not to thee: deliver him into my hand, and I will bring him to thee again."}, {"numero": 38, "texto": "And he said, My son shall not go down with you; for his brother is dead, and he is left alone: if mischief befall him by the way in the which ye go, then shall ye bring down my gray hairs with sorrow to the grave."}]'::jsonb, 'King James Version'),
  ('Gn', 42, 'fr', '[{"numero": 1, "texto": "Jacob, voyant qu''''il y avait du blé en Egypte, dit à ses fils: Pourquoi vous regardez-vous les uns les autres?"}, {"numero": 2, "texto": "Il dit: Voici, j''''apprends qu''''il y a du blé en Egypte; descendez-y, pour nous en acheter là, afin que nous vivions et que nous ne mourions pas."}, {"numero": 3, "texto": "Dix frères de Joseph descendirent en Egypte, pour acheter du blé."}, {"numero": 4, "texto": "Jacob n''''envoya point avec eux Benjamin, frère de Joseph, dans la crainte qu''''il ne lui arrivât quelque malheur."}, {"numero": 5, "texto": "Les fils d''''Israël vinrent pour acheter du blé, au milieu de ceux qui venaient aussi; car la famine était dans le pays de Canaan."}, {"numero": 6, "texto": "Joseph commandait dans le pays; c''''est lui qui vendait du blé à tout le peuple du pays. Les frères de Joseph vinrent, et se prosternèrent devant lui la face contre terre."}, {"numero": 7, "texto": "Joseph vit ses frères et les reconnut; mais il feignit d''''être un étranger pour eux, il leur parla durement, et leur dit: D''''où venez-vous? Ils répondirent: Du pays de Canaan, pour acheter des vivres."}, {"numero": 8, "texto": "Joseph reconnut ses frères, mais eux ne le reconnurent pas."}, {"numero": 9, "texto": "Joseph se souvint des songes qu''''il avait eus à leur sujet, et il leur dit: Vous êtes des espions; c''''est pour observer les lieux faibles du pays que vous êtes venus."}, {"numero": 10, "texto": "Ils lui répondirent: Non, mon seigneur, tes serviteurs sont venus pour acheter du blé."}, {"numero": 11, "texto": "Nous sommes tous fils d''''un même homme; nous sommes sincères, tes serviteurs ne sont pas des espions."}, {"numero": 12, "texto": "Il leur dit: Nullement; c''''est pour observer les lieux faibles du pays que vous êtes venus."}, {"numero": 13, "texto": "Ils répondirent: Nous, tes serviteurs, sommes douze frères, fils d''''un même homme au pays de Canaan; et voici, le plus jeune est aujourd''''hui avec notre père, et il y en a un qui n''''est plus."}, {"numero": 14, "texto": "Joseph leur dit: Je viens de vous le dire, vous êtes des espions."}, {"numero": 15, "texto": "Voici comment vous serez éprouvés. Par la vie de Pharaon! vous ne sortirez point d''''ici que votre jeune frère ne soit venu."}, {"numero": 16, "texto": "Envoyez l''''un de vous pour chercher votre frère; et vous, restez prisonniers. Vos paroles seront éprouvées, et je saurai si la vérité est chez vous; sinon, par la vie de Pharaon! vous êtes des espions."}, {"numero": 17, "texto": "Et il les mit ensemble trois jours en prison."}, {"numero": 18, "texto": "Le troisième jour, Joseph leur dit: Faites ceci, et vous vivrez. Je crains Dieu!"}, {"numero": 19, "texto": "Si vous êtes sincères, que l''''un de vos frères reste enfermé dans votre prison; et vous, partez, emportez du blé pour nourrir vos familles,"}, {"numero": 20, "texto": "et amenez-moi votre jeune frère, afin que vos paroles soient éprouvées et que vous ne mouriez point. Et ils firent ainsi."}, {"numero": 21, "texto": "Ils se dirent alors l''''un à l''''autre: Oui, nous avons été coupables envers notre frère, car nous avons vu l''''angoisse de son âme, quand il nous demandait grâce, et nous ne l''''avons point écouté! C''''est pour cela que cette affliction nous arrive."}, {"numero": 22, "texto": "Ruben, prenant la parole, leur dit: Ne vous disais-je pas: Ne commettez point un crime envers cet enfant? Mais vous n''''avez point écouté. Et voici, son sang est redemandé."}, {"numero": 23, "texto": "Ils ne savaient pas que Joseph comprenait, car il se servait avec eux d''''un interprète."}, {"numero": 24, "texto": "Il s''''éloigna d''''eux, pour pleurer. Il revint, et leur parla; puis il prit parmi eux Siméon, et le fit enchaîner sous leurs yeux."}, {"numero": 25, "texto": "Joseph ordonna qu''''on remplît de blé leurs sacs, qu''''on remît l''''argent de chacun dans son sac, et qu''''on leur donnât des provisions pour la route. Et l''''on fit ainsi."}, {"numero": 26, "texto": "Ils chargèrent le blé sur leurs ânes, et partirent."}, {"numero": 27, "texto": "L''''un d''''eux ouvrit son sac pour donner du fourrage à son âne, dans le lieu où ils passèrent la nuit, et il vit l''''argent qui était à l''''entrée du sac."}, {"numero": 28, "texto": "Il dit à ses frères: Mon argent a été rendu, et le voici dans mon sac. Alors leur coeur fut en défaillance; et ils se dirent l''''un à l''''autre, en tremblant: Qu''''est-ce que Dieu nous a fait?"}, {"numero": 29, "texto": "Ils revinrent auprès de Jacob, leur père, dans le pays de Canaan, et ils lui racontèrent tout ce qui leur était arrivé. Ils dirent:"}, {"numero": 30, "texto": "L''''homme, qui est le seigneur du pays, nous a parlé durement, et il nous a pris pour des espions."}, {"numero": 31, "texto": "Nous lui avons dit: Nous sommes sincères, nous ne sommes pas des espions."}, {"numero": 32, "texto": "Nous sommes douze frères, fils de notre père; l''''un n''''est plus, et le plus jeune est aujourd''''hui avec notre père au pays de Canaan."}, {"numero": 33, "texto": "Et l''''homme, qui est le seigneur du pays, nous a dit: Voici comment je saurai si vous êtes sincères. Laissez auprès de moi l''''un de vos frères, prenez de quoi nourrir vos familles, partez,"}, {"numero": 34, "texto": "et amenez-moi votre jeune frère. Je saurai ainsi que vous n''''êtes pas des espions, que vous êtes sincères; je vous rendrai votre frère, et vous pourrez librement parcourir le pays."}, {"numero": 35, "texto": "Lorsqu''''ils vidèrent leurs sacs, voici, le paquet d''''argent de chacun était dans son sac. Ils virent, eux et leur père, leurs paquets d''''argent, et ils eurent peur."}, {"numero": 36, "texto": "Jacob, leur père, leur dit: Vous me privez de mes enfants! Joseph n''''est plus, Siméon n''''est plus, et vous prendriez Benjamin! C''''est sur moi que tout cela retombe."}, {"numero": 37, "texto": "Ruben dit à son père: Tu feras mourir mes deux fils si je ne te ramène pas Benjamin; remets-le entre mes mains, et je te le ramènerai."}, {"numero": 38, "texto": "Jacob dit: Mon fils ne descendra point avec vous; car son frère est mort, et il reste seul; s''''il lui arrivait un malheur dans le voyage que vous allez faire, vous feriez descendre mes cheveux blancs avec douleur dans le séjour des morts."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 42, 'es', '[{"numero": 1, "texto": "Y VIENDO Jacob que en Egipto había alimentos, dijo á sus hijos: ¿Por qué os estáis mirando?"}, {"numero": 2, "texto": "Y dijo: He aquí, yo he oído que hay víveres en Egipto; descended allá, y comprad de allí para nosotros, para que podamos vivir, y no nos muramos."}, {"numero": 3, "texto": "Y descendieron los diez hermanos de José á comprar trigo á Egipto."}, {"numero": 4, "texto": "Mas Jacob no envió á Benjamín hermano de José con sus hermanos; porque dijo: No sea acaso que le acontezca algún desastre."}, {"numero": 5, "texto": "Y vinieron los hijos de Israel á comprar entre los que venían: porque había hambre en la tierra de Canaán."}, {"numero": 6, "texto": "Y José era el señor de la tierra, que vendía á todo el pueblo de la tierra: y llegaron los hermanos de José, é inclináronse á él rostro por tierra."}, {"numero": 7, "texto": "Y José como vió á sus hermanos, conociólos; mas hizo que no los conocía, y hablóles ásperamente, y les dijo: ¿De dónde habéis venido? Ellos respondieron: De la tierra de Canaán á comprar alimentos."}, {"numero": 8, "texto": "José, pues, conoció á sus hermanos; pero ellos no le conocieron."}, {"numero": 9, "texto": "Entonces se acordó José de los sueños que había tenido de ellos, y díjoles: Espías sois; por ver lo descubierto del país habéis venido."}, {"numero": 10, "texto": "Y ellos le respondieron: No, señor mío: mas tus siervos han venido á comprar alimentos."}, {"numero": 11, "texto": "Todos nosotros somos hijos de un varón: somos hombres de verdad: tus siervos nunca fueron espías."}, {"numero": 12, "texto": "Y él les dijo: No; á ver lo descubierto del país habéis venido."}, {"numero": 13, "texto": "Y ellos respondieron: Tus siervos somos doce hermanos, hijos de un varón en la tierra de Canaán; y he aquí el menor está hoy con nuestro padre, y otro no parece."}, {"numero": 14, "texto": "Y José les dijo: Eso es lo que os he dicho, afirmando que sois espías:"}, {"numero": 15, "texto": "En esto seréis probados: Vive Faraón que no saldréis de aquí, sino cuando vuestro hermano menor aquí viniere."}, {"numero": 16, "texto": "Enviad uno de vosotros, y traiga á vuestro hermano; y vosotros quedad presos, y vuestras palabras serán probadas, si hay verdad con vosotros: y si no, vive Faraón, que sois espías."}, {"numero": 17, "texto": "Y juntólos en la cárcel por tres días."}, {"numero": 18, "texto": "Y al tercer día díjoles José: Haced esto, y vivid: Yo temo á Dios:"}, {"numero": 19, "texto": "Si sois hombres de verdad, quede preso en la casa de vuestra cárcel uno de vuestros hermanos; y vosotros id, llevad el alimento para el hambre de vuestra casa:"}, {"numero": 20, "texto": "Pero habéis de traerme á vuestro hermano menor, y serán verificadas vuestras palabras, y no moriréis. Y ellos lo hicieron así."}, {"numero": 21, "texto": "Y decían el uno al otro: Verdaderamente hemos pecado contra nuestro hermano, que vimos la angustia de su alma cuando nos rogaba, y no le oímos: por eso ha venido sobre nosotros esta angustia."}, {"numero": 22, "texto": "Entonces Rubén les respondió, diciendo: ¿No os hablé yo y dije: No pequéis contra el mozo; y no escuchasteis? He aquí también su sangre es requerida."}, {"numero": 23, "texto": "Y ellos no sabían que los entendía José, porque había intérprete entre ellos."}, {"numero": 24, "texto": "Y apartóse él de ellos, y lloró: después volvió á ellos, y les habló, y tomó de entre ellos á Simeón, y aprisionóle á vista de ellos."}, {"numero": 25, "texto": "Y mandó José que llenaran sus sacos de trigo, y devolviesen el dinero de cada uno de ellos, poniéndolo en su saco, y les diesen comida para el camino: é hízose así con ellos."}, {"numero": 26, "texto": "Y ellos pusieron su trigo sobre sus asnos, y fuéronse de allí."}, {"numero": 27, "texto": "Y abriendo uno de ellos su saco para dar de comer á su asno en el mesón, vió su dinero que estaba en la boca de su costal."}, {"numero": 28, "texto": "Y dijo á sus hermanos: Mi dinero se me ha devuelto, y aun helo aquí en mi saco. Sobresaltóseles entonces el corazón, y espantados dijeron el uno al otro: ¿Qué es esto que nos ha hecho Dios?"}, {"numero": 29, "texto": "Y venidos á Jacob su padre en tierra de Canaán, contáronle todo lo que les había acaecido, diciendo:"}, {"numero": 30, "texto": "Aquel varón, señor de la tierra, nos habló ásperamente, y nos trató como á espías de la tierra:"}, {"numero": 31, "texto": "Y nosotros le dijimos: Somos hombres de verdad, nunca fuimos espías:"}, {"numero": 32, "texto": "Somos doce hermanos, hijos de nuestro padre; uno no parece, y el menor está hoy con nuestro padre en la tierra de Canaán."}, {"numero": 33, "texto": "Y aquel varón, señor de la tierra, nos dijo: En esto conoceré que sois hombres de verdad; dejad conmigo uno de vuestros hermanos, y tomad para el hambre de vuestras casas, y andad,"}, {"numero": 34, "texto": "Y traedme á vuestro hermano el menor, para que yo sepa que no sois espías, sino hombres de verdad: así os daré á vuestro hermano, y negociaréis en la tierra."}, {"numero": 35, "texto": "Y aconteció que vaciando ellos sus sacos, he aquí que en el saco de cada uno estaba el atado de su dinero: y viendo ellos y su padre los atados de su dinero, tuvieron temor."}, {"numero": 36, "texto": "Entonces su padre Jacob les dijo: Habéisme privado de mis hijos; José no parece, ni Simeón tampoco, y á Benjamín le llevaréis: contra mí son todas estas cosas."}, {"numero": 37, "texto": "Y Rubén habló á su padre, diciendo: Harás morir á mis dos hijos, si no te lo volviere; entrégalo en mi mano, que yo lo volveré á ti."}, {"numero": 38, "texto": "Y él dijo: No descenderá mi hijo con vosotros; que su hermano es muerto, y él solo ha quedado: y si le aconteciere algún desastre en el camino por donde vais, haréis descender mis canas con dolor á la sepultura."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 43, 'pt', '[{"numero": 1, "texto": "E a fome era grande na terra."}, {"numero": 2, "texto": "E aconteceu que quando acabaram de comer o trigo que trouxeram do Egito, disse-lhes seu pai: Voltai, e comprai para nós um pouco de alimento."}, {"numero": 3, "texto": "E respondeu Judá, dizendo: Aquele homem nos advertiu com ânimo decidido, dizendo: Não vereis meu rosto sem vosso irmão convosco."}, {"numero": 4, "texto": "Se enviares a nosso irmão conosco, desceremos e te compraremos alimento:"}, {"numero": 5, "texto": "Porém se não lhe enviares, não desceremos: porque aquele homem nos disse: Não vereis meu rosto sem vosso irmão convosco."}, {"numero": 6, "texto": "E disse Israel: Por que me fizestes tanto mal, declarando ao homem que tínheis mais irmão?"}, {"numero": 7, "texto": "E eles responderam: Aquele homem nos perguntou expressamente por nós, e por nossa parentela, dizendo: Vive ainda vosso pai? Tendes outro irmão? E lhe declaramos conforme estas palavras. Podíamos nós saber que havia de dizer: Fazei vir a vosso irmão?"}, {"numero": 8, "texto": "Então Judá disse a Israel seu pai: Envia ao jovem comigo, e nos levantaremos e iremos, a fim que vivamos e não morramos nós, e tu, e nossos filhos."}, {"numero": 9, "texto": "Eu sou fiador dele; a mim me pedirás conta dele; se eu não o devolver a ti e o puser diante de ti, serei para ti o culpado todos os dias:"}, {"numero": 10, "texto": "Que se não nos tivéssemos detido, certo agora teríamos já voltado duas vezes."}, {"numero": 11, "texto": "Então Israel seu pai lhes respondeu: Pois que assim é, fazei-o; tomai do melhor da terra em vossos vasos, e levai àquele homem um presente, um pouco de bálsamo, e um pouco de mel, aromas e mirra, nozes e amêndoas."}, {"numero": 12, "texto": "E tomai em vossas mãos dobrado dinheiro, e levai em vossa mão o dinheiro que voltou nas bocas de vossos sacos; talvez tenha sido erro."}, {"numero": 13, "texto": "Tomai também a vosso irmão, e levantai-vos, e voltai àquele homem."}, {"numero": 14, "texto": "E o Deus Todo-Poderoso vos dê misericórdias diante daquele homem, e vos solte ao outro vosso irmão, e a este Benjamim. E se eu tiver de ser privado de meus filhos, assim seja."}, {"numero": 15, "texto": "Então tomaram aqueles homens o presente, e tomaram em sua mão dobrado dinheiro, e a Benjamim; e se levantaram, e desceram ao Egito, e apresentaram-se diante de José."}, {"numero": 16, "texto": "E viu José a Benjamim com eles, e disse ao mordomo de sua casa: Mete em casa a esses homens, e degola um animal, e prepara-o; porque estes homens comerão comigo ao meio-dia."}, {"numero": 17, "texto": "E fez o homem como José disse; e meteu aquele homem aos homens em casa de José."}, {"numero": 18, "texto": "E aqueles homens tiveram temor, quando foram metidos na casa de José, e diziam: Pelo dinheiro que voltou em nossos sacos a primeira vez nos trouxeram aqui, para virem contra nós, e nos atacar, e tomar por servos a nós, e a nossos asnos."}, {"numero": 19, "texto": "E aproximaram-se do mordomo da casa de José, e lhe falaram à entrada da casa."}, {"numero": 20, "texto": "E disseram: Ai, senhor meu, nós em realidade de verdade descemos ao princípio a comprar alimentos:"}, {"numero": 21, "texto": "E aconteceu que quando viemos ao lugar de parada e abrimos nossos sacos, eis que o dinheiro de cada um estava na boca de seu saco, nosso dinheiro em seu justo peso; e o devolvemos em nossas mãos."}, {"numero": 22, "texto": "Trouxemos também em nossas mãos outro dinheiro para comprar alimentos: nós não sabemos quem pôs nosso dinheiro em nossos sacos."}, {"numero": 23, "texto": "E ele respondeu: Paz a vós, não temais; vosso Deus e o Deus de vosso pai vos deu o tesouro em vossos sacos: vosso dinheiro veio a mim. E tirou a Simeão a eles."}, {"numero": 24, "texto": "E aquele homem levou àqueles homens na casa de José: e deu-lhes água, e lavaram seus pés: e deu de comer a seus asnos."}, {"numero": 25, "texto": "E eles prepararam o presente antes que viesse José ao meio-dia, porque haviam ouvido que ali haviam de comer pão."}, {"numero": 26, "texto": "E veio José a casa, e eles lhe trouxeram o presente que tinham em sua mão dentro de casa, e inclinaram-se a ele em terra."}, {"numero": 27, "texto": "Então ele lhes perguntou como estavam, e disse: Vosso pai, o ancião que dissestes, passa bem? Vive ainda?"}, {"numero": 28, "texto": "E eles responderam: Bem vai a teu servo nosso pai; ainda vive. E se inclinaram, e fizeram reverência."}, {"numero": 29, "texto": "E levantando ele seus olhos viu Benjamim seu irmão, filho de sua mãe, e disse: É este vosso irmão mais novo, de quem me falastes? E disse: Deus tenha misericórdia de ti, filho meu."}, {"numero": 30, "texto": "Então José se apressou, porque se comoveram suas entranhas por causa de seu irmão, e procurou onde chorar: e entrou-se em sua câmara, e chorou ali."}, {"numero": 31, "texto": "E lavou seu rosto, e saiu fora, e controlou-se, e disse: Ponde pão."}, {"numero": 32, "texto": "E puseram para ele à parte, e separadamente para eles, e à parte para os egípcios que com ele comiam: porque os egípcios não podem comer pão com os hebreus, o qual é abominação aos egípcios."}, {"numero": 33, "texto": "E sentaram-se diante dele, o mais velho conforme sua primogenitura, e o mais novo conforme sua idade menor; e estavam aqueles homens atônitos olhando-se um ao outro."}, {"numero": 34, "texto": "E ele tomou iguarias de diante de si para eles; mas a porção de Benjamim era cinco vezes como qualquer uma das deles. E beberam, e alegraram-se com ele."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 43, 'en', '[{"numero": 1, "texto": "And the famine was sore in the land."}, {"numero": 2, "texto": "And it came to pass, when they had eaten up the corn which they had brought out of Egypt, their father said unto them, Go again, buy us a little food."}, {"numero": 3, "texto": "And Judah spake unto him, saying, The man did solemnly protest unto us, saying, Ye shall not see my face, except your brother be with you."}, {"numero": 4, "texto": "If thou wilt send our brother with us, we will go down and buy thee food:"}, {"numero": 5, "texto": "But if thou wilt not send him, we will not go down: for the man said unto us, Ye shall not see my face, except your brother be with you."}, {"numero": 6, "texto": "And Israel said, Wherefore dealt ye so ill with me, as to tell the man whether ye had yet a brother?"}, {"numero": 7, "texto": "And they said, The man asked us straitly of our state, and of our kindred, saying, Is your father yet alive? have ye another brother? and we told him according to the tenor of these words: could we certainly know that he would say, Bring your brother down?"}, {"numero": 8, "texto": "And Judah said unto Israel his father, Send the lad with me, and we will arise and go; that we may live, and not die, both we, and thou, and also our little ones."}, {"numero": 9, "texto": "I will be surety for him; of my hand shalt thou require him: if I bring him not unto thee, and set him before thee, then let me bear the blame for ever:"}, {"numero": 10, "texto": "For except we had lingered, surely now we had returned this second time."}, {"numero": 11, "texto": "And their father Israel said unto them, If it must be so now, do this; take of the best fruits in the land in your vessels, and carry down the man a present, a little balm, and a little honey, spices, and myrrh, nuts, and almonds:"}, {"numero": 12, "texto": "And take double money in your hand; and the money that was brought again in the mouth of your sacks, carry it again in your hand; peradventure it was an oversight:"}, {"numero": 13, "texto": "Take also your brother, and arise, go again unto the man:"}, {"numero": 14, "texto": "And God Almighty give you mercy before the man, that he may send away your other brother, and Benjamin. If I be bereaved of my children, I am bereaved."}, {"numero": 15, "texto": "And the men took that present, and they took double money in their hand and Benjamin; and rose up, and went down to Egypt, and stood before Joseph."}, {"numero": 16, "texto": "And when Joseph saw Benjamin with them, he said to the ruler of his house, Bring these men home, and slay, and make ready; for these men shall dine with me at noon."}, {"numero": 17, "texto": "And the man did as Joseph bade; and the man brought the men into Joseph''s house."}, {"numero": 18, "texto": "And the men were afraid, because they were brought into Joseph''s house; and they said, Because of the money that was returned in our sacks at the first time are we brought in; that he may seek occasion against us, and fall upon us, and take us for bondmen, and our asses."}, {"numero": 19, "texto": "And they came near to the steward of Joseph''s house, and they communed with him at the door of the house,"}, {"numero": 20, "texto": "And said, O sir, we came indeed down at the first time to buy food:"}, {"numero": 21, "texto": "And it came to pass, when we came to the inn, that we opened our sacks, and, behold, every man''s money was in the mouth of his sack, our money in full weight: and we have brought it again in our hand."}, {"numero": 22, "texto": "And other money have we brought down in our hands to buy food: we cannot tell who put our money in our sacks."}, {"numero": 23, "texto": "And he said, Peace be to you, fear not: your God, and the God of your father, hath given you treasure in your sacks: I had your money. And he brought Simeon out unto them."}, {"numero": 24, "texto": "And the man brought the men into Joseph''s house, and gave them water, and they washed their feet; and he gave their asses provender."}, {"numero": 25, "texto": "And they made ready the present against Joseph came at noon: for they heard that they should eat bread there."}, {"numero": 26, "texto": "And when Joseph came home, they brought him the present which was in their hand into the house, and bowed themselves to him to the earth."}, {"numero": 27, "texto": "And he asked them of their welfare, and said, Is your father well, the old man of whom ye spake? Is he yet alive?"}, {"numero": 28, "texto": "And they answered, Thy servant our father is in good health, he is yet alive. And they bowed down their heads, and made obeisance."}, {"numero": 29, "texto": "And he lifted up his eyes, and saw his brother Benjamin, his mother''s son, and said, Is this your younger brother, of whom ye spake unto me? And he said, God be gracious unto thee, my son."}, {"numero": 30, "texto": "And Joseph made haste; for his bowels did yearn upon his brother: and he sought where to weep; and he entered into his chamber, and wept there."}, {"numero": 31, "texto": "And he washed his face, and went out, and refrained himself, and said, Set on bread."}, {"numero": 32, "texto": "And they set on for him by himself, and for them by themselves, and for the Egyptians, which did eat with him, by themselves: because the Egyptians might not eat bread with the Hebrews; for that is an abomination unto the Egyptians."}, {"numero": 33, "texto": "And they sat before him, the firstborn according to his birthright, and the youngest according to his youth: and the men marvelled one at another."}, {"numero": 34, "texto": "And he took and sent messes unto them from before him: but Benjamin''s mess was five times so much as any of their''s. And they drank, and were merry with him."}]'::jsonb, 'King James Version'),
  ('Gn', 43, 'fr', '[{"numero": 1, "texto": "La famine s''''appesantissait sur le pays."}, {"numero": 2, "texto": "Quand ils eurent fini de manger le blé qu''''ils avaient apporté d''''Egypte, Jacob dit à ses fils: Retournez, achetez-nous un peu de vivres."}, {"numero": 3, "texto": "Juda lui répondit: Cet homme nous a fait cette déclaration formelle: Vous ne verrez pas ma face, à moins que votre frère ne soit avec vous."}, {"numero": 4, "texto": "Si donc tu veux envoyer notre frère avec nous, nous descendrons, et nous t''''achèterons des vivres."}, {"numero": 5, "texto": "Mais si tu ne veux pas l''''envoyer, nous ne descendrons point, car cet homme nous a dit: Vous ne verrez pas ma face, à moins que votre frère ne soit avec vous."}, {"numero": 6, "texto": "Israël dit alors: Pourquoi avez-vous mal agi à mon égard, en disant à cet homme que vous aviez encore un frère?"}, {"numero": 7, "texto": "Ils répondirent: Cet homme nous a interrogés sur nous et sur notre famille, en disant: Votre père vit-il encore? avez-vous un frère? Et nous avons répondu à ces questions. Pouvions-nous savoir qu''''il dirait: Faites descendre votre frère?"}, {"numero": 8, "texto": "Juda dit à Israël, son père: Laisse venir l''''enfant avec moi, afin que nous nous levions et que nous partions; et nous vivrons et ne mourrons pas, nous, toi, et nos enfants."}, {"numero": 9, "texto": "Je réponds de lui; tu le redemanderas de ma main. Si je ne le ramène pas auprès de toi et si je ne le remets pas devant ta face, je serai pour toujours coupable envers toi."}, {"numero": 10, "texto": "Car si nous n''''eussions pas tardé, nous serions maintenant deux fois de retour."}, {"numero": 11, "texto": "Israël, leur père, leur dit: Puisqu''''il le faut, faites ceci. Prenez dans vos sacs des meilleures productions du pays, pour en porter un présent à cet homme, un peu de baume et un peu de miel, des aromates, de la myrrhe, des pistaches et des amandes."}, {"numero": 12, "texto": "Prenez avec vous de l''''argent au double, et remportez l''''argent qu''''on avait mis à l''''entrée de vos sacs: peut-être était-ce une erreur."}, {"numero": 13, "texto": "Prenez votre frère, et levez-vous; retournez vers cet homme."}, {"numero": 14, "texto": "Que le Dieu tout-puissant vous fasse trouver grâce devant cet homme, et qu''''il laisse revenir avec vous votre autre frère et Benjamin! Et moi, si je dois être privé de mes enfants, que j''''en sois privé!"}, {"numero": 15, "texto": "Ils prirent le présent; ils prirent avec eux de l''''argent au double, ainsi que Benjamin; ils se levèrent, descendirent en Egypte, et se présentèrent devant Joseph."}, {"numero": 16, "texto": "Dès que Joseph vit avec eux Benjamin, il dit à son intendant: Fais entrer ces gens dans la maison, tue et apprête; car ces gens mangeront avec moi à midi."}, {"numero": 17, "texto": "Cet homme fit ce que Joseph avait ordonné, et il conduisit ces gens dans la maison de Joseph."}, {"numero": 18, "texto": "Ils eurent peur lorsqu''''ils furent conduits à la maison de Joseph, et ils dirent: C''''est à cause de l''''argent remis l''''autre fois dans nos sacs qu''''on nous emmène; c''''est pour se jeter sur nous, se précipiter sur nous; c''''est pour nous prendre comme esclaves, et s''''emparer de nos ânes."}, {"numero": 19, "texto": "Ils s''''approchèrent de l''''intendant de la maison de Joseph, et lui adressèrent la parole, à l''''entrée de la maison."}, {"numero": 20, "texto": "Ils dirent: Pardon! mon seigneur, nous sommes déjà descendus une fois pour acheter des vivres."}, {"numero": 21, "texto": "Puis, quand nous arrivâmes, au lieu où nous devions passer la nuit, nous avons ouvert nos sacs; et voici, l''''argent de chacun était à l''''entrée de son sac, notre argent selon son poids: nous le rapportons avec nous."}, {"numero": 22, "texto": "Nous avons aussi apporté d''''autre argent, pour acheter des vivres. Nous ne savons pas qui avait mis notre argent dans nos sacs."}, {"numero": 23, "texto": "L''''intendant répondit: Que la paix soit avec vous! Ne craignez rien. C''''est votre Dieu, le Dieu de votre père, qui vous a donné un trésor dans vos sacs. Votre argent m''''est parvenu. Et il leur amena Siméon."}, {"numero": 24, "texto": "Cet homme les fit entrer dans la maison de Joseph; il leur donna de l''''eau et ils se lavèrent les pieds; il donna aussi du fourrage à leurs ânes."}, {"numero": 25, "texto": "Ils préparèrent leur présent, en attendant que Joseph vienne à midi; car on les avait informés qu''''ils mangeraient chez lui."}, {"numero": 26, "texto": "Quand Joseph fut arrivé à la maison, ils lui offrirent le présent qu''''ils avaient apporté, et ils se prosternèrent en terre devant lui."}, {"numero": 27, "texto": "Il leur demanda comment ils se portaient; et il dit: Votre vieux père, dont vous avez parlé, est-il en bonne santé? vit-il encore?"}, {"numero": 28, "texto": "Ils répondirent: Ton serviteur, notre père, est en bonne santé; il vit encore. Et ils s''''inclinèrent et se prosternèrent."}, {"numero": 29, "texto": "Joseph leva les yeux; et, jetant un regard sur Benjamin, son frère, fils de sa mère, il dit: Est-ce là votre jeune frère, dont vous m''''avez parlé? Et il ajouta: Dieu te fasse miséricorde, mon fils!"}, {"numero": 30, "texto": "Ses entrailles étaient émues pour son frère, et il avait besoin de pleurer; il entra précipitamment dans une chambre, et il y pleura."}, {"numero": 31, "texto": "Après s''''être lavé le visage, il en sortit; et, faisant des efforts pour se contenir, il dit: Servez à manger."}, {"numero": 32, "texto": "On servit Joseph à part, et ses frères à part; les Egyptiens qui mangeaient avec lui furent aussi servis à part, car les Egyptiens ne pouvaient pas manger avec les Hébreux, parce que c''''est à leurs yeux une abomination."}, {"numero": 33, "texto": "Les frères de Joseph s''''assirent en sa présence, le premier-né selon son droit d''''aînesse, et le plus jeune selon son âge; et ils se regardaient les uns les autres avec étonnement."}, {"numero": 34, "texto": "Joseph leur fit porter des mets qui étaient devant lui, et Benjamin en eut cinq fois plus que les autres. Ils burent, et s''''égayèrent avec lui."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 43, 'es', '[{"numero": 1, "texto": "Y EL hambre era grande en la tierra."}, {"numero": 2, "texto": "Y aconteció que como acabaron de comer el trigo que trajeron de Egipto, díjoles su padre: Volved, y comprad para nosotros un poco de alimento."}, {"numero": 3, "texto": "Y respondió Judá, diciendo: Aquel varón nos protestó con ánimo resuelto, diciendo: No veréis mi rostro sin vuestro hermano con vosotros."}, {"numero": 4, "texto": "Si enviares á nuestro hermano con nosotros, descenderemos y te compraremos alimento:"}, {"numero": 5, "texto": "Pero si no le enviares, no descenderemos: porque aquel varón nos dijo: No veréis mi rostro sin vuestro hermano con vosotros."}, {"numero": 6, "texto": "Y dijo Israel: ¿Por qué me hicisteis tanto mal, declarando al varón que teníais más hermano?"}, {"numero": 7, "texto": "Y ellos respondieron: Aquel varón nos preguntó expresamente por nosotros, y por nuestra parentela, diciendo: ¿Vive aún vuestro padre? ¿tenéis otro hermano? y declarámosle conforme á estas palabras. ¿Podíamos nosotros saber que había de decir: Haced venir á vuestro hermano?"}, {"numero": 8, "texto": "Entonces Judá dijo á Israel su padre: Envía al mozo conmigo, y nos levantaremos é iremos, á fin que vivamos y no muramos nosotros, y tú, y nuestros niños."}, {"numero": 9, "texto": "Yo lo fío; á mí me pedirás cuenta de él: si yo no te lo volviere y lo pusiere delante de ti, seré para ti el culpante todos los días:"}, {"numero": 10, "texto": "Que si no nos hubiéramos detenido, cierto ahora hubiéramos ya vuelto dos veces."}, {"numero": 11, "texto": "Entonces Israel su padre les respondió: Pues que así es, hacedlo; tomad de lo mejor de la tierra en vuestros vasos, y llevad á aquel varón un presente, un poco de bálsamo, y un poco de miel, aromas y mirra, nueces y almendras."}, {"numero": 12, "texto": "Y tomad en vuestras manos doblado dinero, y llevad en vuestra mano el dinero vuelto en las bocas de vuestros costales; quizá fué yerro."}, {"numero": 13, "texto": "Tomad también á vuestro hermano, y levantaos, y volved á aquel varón."}, {"numero": 14, "texto": "Y el Dios Omnipotente os dé misericordias delante de aquel varón, y os suelte al otro vuestro hermano, y á este Benjamín. Y si he de ser privado de mis hijos, séalo."}, {"numero": 15, "texto": "Entonces tomaron aquellos varones el presente, y tomaron en su mano doblado dinero, y á Benjamín; y se levantaron, y descendieron á Egipto, y presentáronse delante de José."}, {"numero": 16, "texto": "Y vió José á Benjamín con ellos, y dijo al mayordomo de su casa: Mete en casa á esos hombres, y degüella víctima, y aderézala; porque estos hombres comerán conmigo al medio día."}, {"numero": 17, "texto": "E hizo el hombre como José dijo; y metió aquel hombre á los hombres en casa de José."}, {"numero": 18, "texto": "Y aquellos hombres tuvieron temor, cuando fueron metidos en casa de José, y decían: Por el dinero que fué vuelto en nuestros costales la primera vez nos han metido aquí, para revolver contra nosotros, y dar sobre nosotros, y tomarnos por siervos á nosotros, y á nuestros asnos."}, {"numero": 19, "texto": "Y llegáronse al mayordomo de la casa de José, y le hablaron á la entrada de la casa."}, {"numero": 20, "texto": "Y dijeron: Ay, señor mío, nosotros en realidad de verdad descendimos al principio á comprar alimentos:"}, {"numero": 21, "texto": "Y aconteció que como vinimos al mesón y abrimos nuestros costales, he aquí el dinero de cada uno estaba en la boca de su costal, nuestro dinero en su justo peso; y hémoslo vuelto en nuestras manos."}, {"numero": 22, "texto": "Hemos también traído en nuestras manos otro dinero para comprar alimentos: nosotros no sabemos quién haya puesto nuestro dinero en nuestros costales."}, {"numero": 23, "texto": "Y él respondió: Paz á vosotros, no temáis; vuestro Dios y el Dios de vuestro padre os dió el tesoro en vuestros costales: vuestro dinero vino á mí. Y sacó á Simeón á ellos."}, {"numero": 24, "texto": "Y metió aquel varón á aquellos hombres en casa de José: y dióles agua, y lavaron sus pies: y dió de comer á sus asnos."}, {"numero": 25, "texto": "Y ellos prepararon el presente entretanto que venía José al medio día, porque habían oído que allí habían de comer pan."}, {"numero": 26, "texto": "Y vino José á casa, y ellos le trajeron el presente que tenían en su mano dentro de casa, é inclináronse á él hasta tierra."}, {"numero": 27, "texto": "Entonces les preguntó él cómo estaban, y dijo: ¿Vuestro padre, el anciano que dijisteis, lo pasa bien? ¿vive todavía?"}, {"numero": 28, "texto": "Y ellos respondieron: Bien va á tu siervo nuestro padre; aun vive. Y se inclinaron, é hicieron reverencia."}, {"numero": 29, "texto": "Y alzando él sus ojos vió á Benjamín su hermano, hijo de su madre, y dijo: ¿Es éste vuestro hermano menor, de quien me hablasteis? Y dijo: Dios tenga misericordia de ti, hijo mío."}, {"numero": 30, "texto": "Entonces José se apresuró, porque se conmovieron sus entrañas á causa de su hermano, y procuró donde llorar: y entróse en su cámara, y lloró allí."}, {"numero": 31, "texto": "Y lavó su rostro, y salió fuera, y reprimióse, y dijo: Poned pan."}, {"numero": 32, "texto": "Y pusieron para él aparte, y separadamente para ellos, y aparte para los Egipcios que con él comían: porque los Egipcios no pueden comer pan con los Hebreos, lo cual es abominación á los Egipcios."}, {"numero": 33, "texto": "Y sentáronse delante de él, el mayor conforme á su mayoría, y el menor conforme á su menoría; y estaban aquellos hombres atónitos mirándose el uno al otro."}, {"numero": 34, "texto": "Y él tomó viandas de delante de sí para ellos; mas la porción de Benjamín era cinco veces como cualquiera de las de ellos. Y bebieron, y alegráronse con él."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 44, 'pt', '[{"numero": 1, "texto": "E mandou José ao mordomo de sua casa, dizendo: Enche os sacos destes homens de alimentos, quanto puderem levar, e põe o dinheiro de cada um na boca de seu saco:"}, {"numero": 2, "texto": "E porás meu copo, o copo de prata, na boca do saco do mais novo, com o dinheiro de seu trigo. E ele fez como disse José."}, {"numero": 3, "texto": "Vinda a manhã, os homens foram despedidos com seus asnos."}, {"numero": 4, "texto": "Havendo eles saído da cidade, da qual ainda não haviam se afastado, disse José a seu mordomo: Levanta-te, e segue a esses homens; e quando os alcançares, dize-lhes: Por que retribuístes com o mal pelo bem?"}, {"numero": 5, "texto": "Não é isto no que bebe meu senhor, e pelo que costuma adivinhar? Fizestes mal no que fizestes."}, {"numero": 6, "texto": "E quando ele os alcançou, disse-lhes estas palavras."}, {"numero": 7, "texto": "E eles lhe responderam: Por que diz meu senhor tais coisas? Nunca tal façam teus servos."}, {"numero": 8, "texto": "Eis que, o dinheiro que achamos na boca de nossos sacos, o voltamos a trazer a ti desde a terra de Canaã; como, pois, havíamos de furtar da casa de teu senhor prata nem ouro?"}, {"numero": 9, "texto": "Aquele de teus servos em quem for achado o copo, que morra, e ainda nós seremos servos de meu senhor."}, {"numero": 10, "texto": "E ele disse: Também agora seja conforme vossas palavras; aquele em quem se achar, será meu servo, e vós sereis sem culpa."}, {"numero": 11, "texto": "Eles então se deram pressa, e derrubando cada um seu saco em terra, abriu cada qual o seu saco."}, {"numero": 12, "texto": "E buscou; desde o mais velho começou, e acabou no mais novo; e o copo foi achado no saco de Benjamim."}, {"numero": 13, "texto": "Então eles rasgaram suas roupas, e carregou cada um seu asno, e voltaram à cidade."}, {"numero": 14, "texto": "E chegou Judá com seus irmãos à casa de José, que ainda estava ali, e prostraram-se diante dele em terra."}, {"numero": 15, "texto": "E disse-lhes José: Que obra é esta que fizestes? Não sabeis que um homem como eu sabe adivinhar?"}, {"numero": 16, "texto": "Então disse Judá: Que diremos a meu senhor? Que falaremos? Ou com que nos justificaremos? Deus achou a maldade de teus servos: eis que, nós somos servos de meu senhor, nós, e também aquele em cujo poder foi achado o copo."}, {"numero": 17, "texto": "E ele respondeu: Nunca eu tal faça: o homem em cujo poder foi achado o copo, ele será meu servo; vós ide em paz a vosso pai."}, {"numero": 18, "texto": "Então Judá se chegou a ele, e disse: Ai senhor meu, rogo-te que fale teu servo uma palavra aos ouvidos de meu senhor, e não se acenda tua ira contra teu servo, pois que tu és como Faraó."}, {"numero": 19, "texto": "Meu senhor perguntou a seus servos, dizendo: Tendes pai ou irmão?"}, {"numero": 20, "texto": "E nós respondemos a meu senhor: Temos um pai ancião, e um jovem que lhe nasceu em sua velhice, pequeno ainda; e um irmão seu morreu, e ele restou sozinho de sua mãe, e seu pai o ama."}, {"numero": 21, "texto": "E tu disseste a teus servos: Trazei-o a mim, e porei meus olhos sobre ele."}, {"numero": 22, "texto": "E nós dissemos a meu senhor: O jovem não pode deixar a seu pai, porque se o deixar, seu pai morrerá."}, {"numero": 23, "texto": "E disseste a teus servos: Se vosso irmão mais novo não descer convosco, não vejais mais meu rosto."}, {"numero": 24, "texto": "Aconteceu, pois, que quando chegamos a meu pai teu servo, nós lhe contamos as palavras de meu senhor."}, {"numero": 25, "texto": "E disse nosso pai: Voltai a comprar-nos um pouco de alimento."}, {"numero": 26, "texto": "E nós respondemos: Não podemos ir: se nosso irmão for conosco, iremos; porque não podemos ver o rosto do homem, não estando conosco nosso irmão o mais novo."}, {"numero": 27, "texto": "Então teu servo meu pai nos disse: Vós sabeis que dois me deu minha mulher;"}, {"numero": 28, "texto": "E um saiu de minha presença, e penso certamente que foi despedaçado, e até agora não o vi;"}, {"numero": 29, "texto": "E se tomardes também este de diante de mim, e lhe acontecer algum desastre, fareis descer meus cabelos grisalhos com tristeza ao Xeol."}, {"numero": 30, "texto": "Agora, pois, quando chegar eu a teu servo meu pai, e o jovem não for comigo, como sua alma está ligada à alma dele,"}, {"numero": 31, "texto": "Sucederá que quando perceber a ausência do jovem, morrerá; e teus servos farão descer os cabelos grisalhos de teu servo, nosso pai, com tristeza ao Xeol."}, {"numero": 32, "texto": "Como teu servo saiu por fiador do jovem com meu pai, dizendo: Se eu não o devolver a ti, então eu serei culpável para meu pai todos os dias;"}, {"numero": 33, "texto": "Rogo-te, portanto, que fique agora teu servo pelo jovem por servo de meu senhor, e que o jovem vá com seus irmãos."}, {"numero": 34, "texto": "Porque como irei eu a meu pai sem o jovem? Não poderei, por não ver o mal que sobrevirá a meu pai."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 44, 'en', '[{"numero": 1, "texto": "And he commanded the steward of his house, saying, Fill the men''s sacks with food, as much as they can carry, and put every man''s money in his sack''s mouth."}, {"numero": 2, "texto": "And put my cup, the silver cup, in the sack''s mouth of the youngest, and his corn money. And he did according to the word that Joseph had spoken."}, {"numero": 3, "texto": "As soon as the morning was light, the men were sent away, they and their asses."}, {"numero": 4, "texto": "And when they were gone out of the city, and not yet far off, Joseph said unto his steward, Up, follow after the men; and when thou dost overtake them, say unto them, Wherefore have ye rewarded evil for good?"}, {"numero": 5, "texto": "Is not this it in which my lord drinketh, and whereby indeed he divineth? ye have done evil in so doing."}, {"numero": 6, "texto": "And he overtook them, and he spake unto them these same words."}, {"numero": 7, "texto": "And they said unto him, Wherefore saith my lord these words? God forbid that thy servants should do according to this thing:"}, {"numero": 8, "texto": "Behold, the money, which we found in our sacks'' mouths, we brought again unto thee out of the land of Canaan: how then should we steal out of thy lord''s house silver or gold?"}, {"numero": 9, "texto": "With whomsoever of thy servants it be found, both let him die, and we also will be my lord''s bondmen."}, {"numero": 10, "texto": "And he said, Now also let it be according unto your words: he with whom it is found shall be my servant; and ye shall be blameless."}, {"numero": 11, "texto": "Then they speedily took down every man his sack to the ground, and opened every man his sack."}, {"numero": 12, "texto": "And he searched, and began at the eldest, and left at the youngest: and the cup was found in Benjamin''s sack."}, {"numero": 13, "texto": "Then they rent their clothes, and laded every man his ass, and returned to the city."}, {"numero": 14, "texto": "And Judah and his brethren came to Joseph''s house; for he was yet there: and they fell before him on the ground."}, {"numero": 15, "texto": "And Joseph said unto them, What deed is this that ye have done? wot ye not that such a man as I can certainly divine?"}, {"numero": 16, "texto": "And Judah said, What shall we say unto my lord? what shall we speak? or how shall we clear ourselves? God hath found out the iniquity of thy servants: behold, we are my lord''s servants, both we, and he also with whom the cup is found."}, {"numero": 17, "texto": "And he said, God forbid that I should do so: but the man in whose hand the cup is found, he shall be my servant; and as for you, get you up in peace unto your father."}, {"numero": 18, "texto": "Then Judah came near unto him, and said, Oh my lord, let thy servant, I pray thee, speak a word in my lord''s ears, and let not thine anger burn against thy servant: for thou art even as Pharaoh."}, {"numero": 19, "texto": "My lord asked his servants, saying, Have ye a father, or a brother?"}, {"numero": 20, "texto": "And we said unto my lord, We have a father, an old man, and a child of his old age, a little one; and his brother is dead, and he alone is left of his mother, and his father loveth him."}, {"numero": 21, "texto": "And thou saidst unto thy servants, Bring him down unto me, that I may set mine eyes upon him."}, {"numero": 22, "texto": "And we said unto my lord, The lad cannot leave his father: for if he should leave his father, his father would die."}, {"numero": 23, "texto": "And thou saidst unto thy servants, Except your youngest brother come down with you, ye shall see my face no more."}, {"numero": 24, "texto": "And it came to pass when we came up unto thy servant my father, we told him the words of my lord."}, {"numero": 25, "texto": "And our father said, Go again, and buy us a little food."}, {"numero": 26, "texto": "And we said, We cannot go down: if our youngest brother be with us, then will we go down: for we may not see the man''s face, except our youngest brother be with us."}, {"numero": 27, "texto": "And thy servant my father said unto us, Ye know that my wife bare me two sons:"}, {"numero": 28, "texto": "And the one went out from me, and I said, Surely he is torn in pieces; and I saw him not since:"}, {"numero": 29, "texto": "And if ye take this also from me, and mischief befall him, ye shall bring down my gray hairs with sorrow to the grave."}, {"numero": 30, "texto": "Now therefore when I come to thy servant my father, and the lad be not with us; seeing that his life is bound up in the lad''s life;"}, {"numero": 31, "texto": "It shall come to pass, when he seeth that the lad is not with us, that he will die: and thy servants shall bring down the gray hairs of thy servant our father with sorrow to the grave."}, {"numero": 32, "texto": "For thy servant became surety for the lad unto my father, saying, If I bring him not unto thee, then I shall bear the blame to my father for ever."}, {"numero": 33, "texto": "Now therefore, I pray thee, let thy servant abide instead of the lad a bondman to my lord; and let the lad go up with his brethren."}, {"numero": 34, "texto": "For how shall I go up to my father, and the lad be not with me? lest peradventure I see the evil that shall come on my father."}]'::jsonb, 'King James Version'),
  ('Gn', 44, 'fr', '[{"numero": 1, "texto": "Joseph donna cet ordre à l''''intendant de sa maison: Remplis de vivres les sacs de ces gens, autant qu''''ils en pourront porter, et mets l''''argent de chacun à l''''entrée de son sac."}, {"numero": 2, "texto": "Tu mettras aussi ma coupe, la coupe d''''argent, à l''''entrée du sac du plus jeune, avec l''''argent de son blé. L''''intendant fit ce que Joseph lui avait ordonné."}, {"numero": 3, "texto": "Le matin, dès qu''''il fit jour, on renvoya ces gens avec leurs ânes."}, {"numero": 4, "texto": "Ils étaient sortis de la ville, et ils n''''en étaient guère éloignés, lorsque Joseph dit à son intendant: Lève-toi, poursuis ces gens; et, quand tu les auras atteints, tu leur diras: Pourquoi avez-vous rendu le mal pour le bien?"}, {"numero": 5, "texto": "N''''avez-vous pas la coupe dans laquelle boit mon seigneur, et dont il se sert pour deviner? Vous avez mal fait d''''agir ainsi."}, {"numero": 6, "texto": "L''''intendant les atteignit, et leur dit ces mêmes paroles."}, {"numero": 7, "texto": "Ils lui répondirent: Pourquoi mon seigneur parle-t-il de la sorte? Dieu préserve tes serviteurs d''''avoir commis une telle action!"}, {"numero": 8, "texto": "Voici, nous t''''avons rapporté du pays de Canaan l''''argent que nous avons trouvé à l''''entrée de nos sacs; comment aurions-nous dérobé de l''''argent ou de l''''or dans la maison de ton seigneur?"}, {"numero": 9, "texto": "Que celui de tes serviteurs sur qui se trouvera la coupe meure, et que nous soyons nous-mêmes esclaves de mon seigneur!"}, {"numero": 10, "texto": "Il dit: Qu''''il en soit donc selon vos paroles! Celui sur qui se trouvera la coupe sera mon esclave; et vous, vous serez innocents."}, {"numero": 11, "texto": "Aussitôt, chacun descendit son sac à terre, et chacun ouvrit son sac."}, {"numero": 12, "texto": "L''''intendant les fouilla, commençant par le plus âgé et finissant par le plus jeune; et la coupe fut trouvée dans le sac de Benjamin."}, {"numero": 13, "texto": "Ils déchirèrent leurs vêtements, chacun rechargea son âne, et ils retournèrent à la ville."}, {"numero": 14, "texto": "Juda et ses frères arrivèrent à la maison de Joseph, où il était encore, et ils se prosternèrent en terre devant lui."}, {"numero": 15, "texto": "Joseph leur dit: Quelle action avez-vous faite? Ne savez-vous pas qu''''un homme comme moi a le pouvoir de deviner?"}, {"numero": 16, "texto": "Juda répondit: Que dirons-nous à mon seigneur? comment parlerons-nous? comment nous justifierons-nous? Dieu a trouvé l''''iniquité de tes serviteurs. Nous voici esclaves de mon seigneur, nous, et celui sur qui s''''est trouvée la coupe."}, {"numero": 17, "texto": "Et Joseph dit: Dieu me garde de faire cela! L''''homme sur qui la coupe a été trouvée sera mon esclave; mais vous, remontez en paix vers votre père."}, {"numero": 18, "texto": "Alors Juda s''''approcha de Joseph, et dit: De grâce, mon seigneur, que ton serviteur puisse faire entendre une parole à mon seigneur, et que sa colère ne s''''enflamme point contre ton serviteur! car tu es comme Pharaon."}, {"numero": 19, "texto": "Mon seigneur a interrogé ses serviteurs, en disant: Avez-vous un père, ou un frère?"}, {"numero": 20, "texto": "Nous avons répondu: Nous avons un vieux père, et un jeune frère, enfant de sa vieillesse; cet enfant avait un frère qui est mort, et qui était de la même mère; il reste seul, et son père l''''aime."}, {"numero": 21, "texto": "Tu as dit à tes serviteurs: Faites-le descendre vers moi, et que je le voie de mes propres yeux."}, {"numero": 22, "texto": "Nous avons répondu à mon seigneur: L''''enfant ne peut pas quitter son père; s''''il le quitte, son père mourra."}, {"numero": 23, "texto": "Tu as dit à tes serviteurs: Si votre jeune frère ne descend pas avec vous, vous ne reverrez pas ma face."}, {"numero": 24, "texto": "Lorsque nous sommes remontés auprès de ton serviteur, mon père, nous lui avons rapporté les paroles de mon seigneur."}, {"numero": 25, "texto": "Notre père a dit: Retournez, achetez-nous un peu de vivres."}, {"numero": 26, "texto": "Nous avons répondu: Nous ne pouvons pas descendre; mais, si notre jeune frère est avec nous, nous descendrons, car nous ne pouvons pas voir la face de cet homme, à moins que notre jeune frère ne soit avec nous."}, {"numero": 27, "texto": "Ton serviteur, notre père, nous a dit: Vous savez que ma femme m''''a enfanté deux fils."}, {"numero": 28, "texto": "L''''un étant sorti de chez moi, je pense qu''''il a été sans doute déchiré, car je ne l''''ai pas revu jusqu''''à présent."}, {"numero": 29, "texto": "Si vous me prenez encore celui-ci, et qu''''il lui arrive un malheur, vous ferez descendre mes cheveux blancs avec douleur dans le séjour des morts."}, {"numero": 30, "texto": "Maintenant, si je retourne auprès de ton serviteur, mon père, sans avoir avec nous l''''enfant à l''''âme duquel son âme est attachée,"}, {"numero": 31, "texto": "il mourra, en voyant que l''''enfant n''''y est pas; et tes serviteurs feront descendre avec douleur dans le séjour des morts les cheveux blancs de ton serviteur, notre père."}, {"numero": 32, "texto": "Car ton serviteur a répondu pour l''''enfant, en disant à mon père: Si je ne le ramène pas auprès de toi, je serai pour toujours coupable envers mon père."}, {"numero": 33, "texto": "Permets donc, je te prie, à ton serviteur de rester à la place de l''''enfant, comme esclave de mon seigneur; et que l''''enfant remonte avec ses frères."}, {"numero": 34, "texto": "Comment pourrai-je remonter vers mon père, si l''''enfant n''''est pas avec moi? Ah! que je ne voie point l''''affliction de mon père!"}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 44, 'es', '[{"numero": 1, "texto": "Y MANDÓ José al mayordomo de su casa, diciendo: Hinche los costales de aquestos varones de alimentos, cuanto pudieren llevar, y pon el dinero de cada uno en la boca de su costal:"}, {"numero": 2, "texto": "Y pondrás mi copa, la copa de plata, en la boca del costal del menor, con el dinero de su trigo. Y él hizo como dijo José."}, {"numero": 3, "texto": "Venida la mañana, los hombres fueron despedidos con sus asnos."}, {"numero": 4, "texto": "Habiendo ellos salido de la ciudad, de la que aun no se habían alejado, dijo José á su mayordomo: Levántate, y sigue á esos hombres; y cuando los alcanzares, diles: ¿Por qué habéis vuelto mal por bien?"}, {"numero": 5, "texto": "¿No es ésta en la que bebe mi señor, y por la que suele adivinar? habéis hecho mal en lo que hicisteis."}, {"numero": 6, "texto": "Y como él los alcanzó, díjoles estas palabras."}, {"numero": 7, "texto": "Y ellos le respondieron: ¿Por qué dice mi señor tales cosas? Nunca tal hagan tus siervos."}, {"numero": 8, "texto": "He aquí, el dinero que hallamos en la boca de nuestros costales, te lo volvimos á traer desde la tierra de Canaán; ¿cómo, pues, habíamos de hurtar de casa de tu señor plata ni oro?"}, {"numero": 9, "texto": "Aquel de tus siervos en quien fuere hallada la copa, que muera, y aun nosotros seremos siervos de mi señor."}, {"numero": 10, "texto": "Y él dijo: También ahora sea conforme á vuestras palabras; aquél en quien se hallare, será mi siervo, y vosotros seréis sin culpa."}, {"numero": 11, "texto": "Ellos entonces se dieron prisa, y derribando cada uno su costal en tierra, abrió cada cual el costal suyo."}, {"numero": 12, "texto": "Y buscó; desde el mayor comenzó, y acabó en el menor; y la copa fué hallada en el costal de Benjamín."}, {"numero": 13, "texto": "Entonces ellos rasgaron sus vestidos, y cargó cada uno su asno, y volvieron á la ciudad."}, {"numero": 14, "texto": "Y llegó Judá con sus hermanos á casa de José, que aun estaba allí, y postráronse delante de él en tierra."}, {"numero": 15, "texto": "Y díjoles José: ¿Qué obra es esta que habéis hecho? ¿no sabéis que un hombre como yo sabe adivinar?"}, {"numero": 16, "texto": "Entonces dijo Judá: ¿Qué diremos á mi señor? ¿qué hablaremos? ¿ó con qué nos justificaremos? Dios ha hallado la maldad de tus siervos: he aquí, nosotros somos siervos de mi señor, nosotros, y también aquél en cuyo poder fué hallada la copa."}, {"numero": 17, "texto": "Y él respondió: Nunca yo tal haga: el varón en cuyo poder fué hallada la copa, él será mi siervo; vosotros id en paz á vuestro padre."}, {"numero": 18, "texto": "Entonces Judá se llegó á él, y dijo: Ay señor mío, ruégote que hable tu siervo una palabra en oídos de mi señor, y no se encienda tu enojo contra tu siervo, pues que tú eres como Faraón."}, {"numero": 19, "texto": "Mi señor preguntó á sus siervos, diciendo: ¿Tenéis padre ó hermano?"}, {"numero": 20, "texto": "Y nosotros respondimos á mi señor: Tenemos un padre anciano, y un mozo que le nació en su vejez, pequeño aún; y un hermano suyo murió, y él quedó solo de su madre, y su padre lo ama."}, {"numero": 21, "texto": "Y tú dijiste á tus siervos: Traédmelo, y pondré mis ojos sobre él."}, {"numero": 22, "texto": "Y nosotros dijimos á mi señor: El mozo no puede dejar á su padre, porque si le dejare, su padre morirá."}, {"numero": 23, "texto": "Y dijiste á tus siervos: Si vuestro hermano menor no descendiere con vosotros, no veáis más mi rostro."}, {"numero": 24, "texto": "Aconteció pues, que como llegamos á mi padre tu siervo, contámosle las palabras de mi señor."}, {"numero": 25, "texto": "Y dijo nuestro padre: Volved á comprarnos un poco de alimento."}, {"numero": 26, "texto": "Y nosotros respondimos: No podemos ir: si nuestro hermano fuere con nosotros, iremos; porque no podemos ver el rostro del varón, no estando con nosotros nuestro hermano el menor."}, {"numero": 27, "texto": "Entonces tu siervo mi padre nos dijo: Vosotros sabéis que dos me parió mi mujer;"}, {"numero": 28, "texto": "Y el uno salió de conmigo, y pienso de cierto que fué despedazado, y hasta ahora no le he visto;"}, {"numero": 29, "texto": "Y si tomareis también éste de delante de mí, y le aconteciere algún desastre, haréis descender mis canas con dolor á la sepultura."}, {"numero": 30, "texto": "Ahora, pues, cuando llegare yo á tu siervo mi padre, y el mozo no fuere conmigo, como su alma está ligada al alma de él,"}, {"numero": 31, "texto": "Sucederá que cuando no vea al mozo, morirá: y tus siervos harán descender las canas de tu siervo nuestro padre con dolor á la sepultura."}, {"numero": 32, "texto": "Como tu siervo salió por fiador del mozo con mi padre, diciendo: Si no te lo volviere, entonces yo seré culpable para mi padre todos los días;"}, {"numero": 33, "texto": "Ruégote por tanto que quede ahora tu siervo por el mozo por siervo de mi señor, y que el mozo vaya con sus hermanos."}, {"numero": 34, "texto": "Porque ¿cómo iré yo á mi padre sin el mozo? No podré, por no ver el mal que sobrevendrá á mi padre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 45, 'pt', '[{"numero": 1, "texto": "Não podia já José se conter diante de todos os que estavam ao seu lado, e clamou: Fazei sair de minha presença a todos. E não ficou ninguém com ele, ao dar-se a conhecer José a seus irmãos."}, {"numero": 2, "texto": "Então se deu a chorar por voz em grito; e ouviram os egípcios, e ouviu também a casa de Faraó."}, {"numero": 3, "texto": "E disse José a seus irmãos: Eu sou José: vive ainda meu pai? E seus irmãos não puderam lhe responder, porque estavam perturbados diante dele."}, {"numero": 4, "texto": "Então disse José a seus irmãos: Achegai-vos agora a mim. E eles se achegaram. E ele disse: Eu sou José vosso irmão o que vendestes para o Egito."}, {"numero": 5, "texto": "Agora, pois, não vos entristeçais, nem vos pese de haver me vendido aqui; que para preservação de vida me enviou Deus diante de vós:"}, {"numero": 6, "texto": "Que já houve dois anos de fome em meio da terra, e ainda restam cinco anos em que nem haverá arada nem colheita."}, {"numero": 7, "texto": "E Deus me enviou adiante de vós, para que vós restásseis na terra, e para vos dar vida por meio de grande salvamento."}, {"numero": 8, "texto": "Assim, pois, não me enviastes vós aqui, mas sim Deus, que me pôs por pai de Faraó, e por senhor de toda sua casa, e por governador de toda a terra do Egito."}, {"numero": 9, "texto": "Apressai-vos, ide a meu pai e dizei-lhe: Assim diz teu filho José: Deus me pôs por senhor de todo Egito; vem a mim, não te detenhas:"}, {"numero": 10, "texto": "E habitarás na terra de Gósen, e estarás perto de mim, tu e teus filhos, e os filhos de teus filhos, teus gados e tuas vacas, e tudo o que tens."}, {"numero": 11, "texto": "E ali te alimentarei, pois ainda restam cinco anos de fome, para que não pereças de pobreza tu e tua casa, e tudo o que tens:"}, {"numero": 12, "texto": "E eis que, vossos olhos veem, e os olhos de meu irmão Benjamim, que meu boca vos fala."}, {"numero": 13, "texto": "Fareis pois saber a meu pai toda minha glória no Egito, e tudo o que vistes: e apressai-vos, e trazei a meu pai aqui."}, {"numero": 14, "texto": "E lançou-se sobre o pescoço de Benjamim seu irmão, e chorou; e também Benjamim chorou sobre seu pescoço."}, {"numero": 15, "texto": "E beijou a todos os seus irmãos, e chorou sobre eles: e depois seus irmãos falaram com ele."}, {"numero": 16, "texto": "E ouviu-se a notícia na casa de Faraó, dizendo: Os irmãos de José vieram. E pareceu bem aos olhos de Faraó e de seus servos."}, {"numero": 17, "texto": "E disse Faraó a José: Dize a teus irmãos: Fazei isto: carregai vossos animais, e ide, voltai à terra de Canaã;"}, {"numero": 18, "texto": "E tomai a vosso pai e vossas famílias, e vinde a mim, que eu vos darei o bom da terra do Egito e comereis a gordura da terra."}, {"numero": 19, "texto": "E tu manda: Fazei isto: tomai para vós da terra do Egito carros para vossos filhos e vossas mulheres; e tomai a vosso pai, e vinde."}, {"numero": 20, "texto": "E não se vos dê nada de vossos pertences, porque o bem da terra do Egito será vosso."}, {"numero": 21, "texto": "E fizeram-no assim os filhos de Israel: e deu-lhes José carros conforme a ordem de Faraó, e deu alimentos para o caminho."}, {"numero": 22, "texto": "A cada um de todos eles deu mudas de roupas, e a Benjamim deu trezentas peças de prata, e cinco mudas de roupas."}, {"numero": 23, "texto": "E a seu pai enviou isto: dez asnos carregados do melhor do Egito, e dez asnas carregadas de trigo, e pão e comida, para seu pai no caminho."}, {"numero": 24, "texto": "E despediu a seus irmãos, e foram-se. E ele lhes disse: Não brigais pelo caminho."}, {"numero": 25, "texto": "E subiram do Egito, e chegaram à terra de Canaã a Jacó seu pai."}, {"numero": 26, "texto": "E deram-lhe as novas, dizendo: José vive ainda; e ele é senhor toda a terra do Egito. E seu coração se desmaiou; pois não cria neles."}, {"numero": 27, "texto": "E eles lhe contaram todas as palavras de José, que ele lhes havia falado; e vendo ele os carros que José enviava para levá-lo, o espírito de Jacó seu pai reviveu."}, {"numero": 28, "texto": "Então disse Israel: Basta; José meu filho vive ainda: irei, e lhe verei antes que eu morra."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 45, 'en', '[{"numero": 1, "texto": "Then Joseph could not refrain himself before all them that stood by him; and he cried, Cause every man to go out from me. And there stood no man with him, while Joseph made himself known unto his brethren."}, {"numero": 2, "texto": "And he wept aloud: and the Egyptians and the house of Pharaoh heard."}, {"numero": 3, "texto": "And Joseph said unto his brethren, I am Joseph; doth my father yet live? And his brethren could not answer him; for they were troubled at his presence."}, {"numero": 4, "texto": "And Joseph said unto his brethren, Come near to me, I pray you. And they came near. And he said, I am Joseph your brother, whom ye sold into Egypt."}, {"numero": 5, "texto": "Now therefore be not grieved, nor angry with yourselves, that ye sold me hither: for God did send me before you to preserve life."}, {"numero": 6, "texto": "For these two years hath the famine been in the land: and yet there are five years, in the which there shall neither be earing nor harvest."}, {"numero": 7, "texto": "And God sent me before you to preserve you a posterity in the earth, and to save your lives by a great deliverance."}, {"numero": 8, "texto": "So now it was not you that sent me hither, but God: and he hath made me a father to Pharaoh, and lord of all his house, and a ruler throughout all the land of Egypt."}, {"numero": 9, "texto": "Haste ye, and go up to my father, and say unto him, Thus saith thy son Joseph, God hath made me lord of all Egypt: come down unto me, tarry not:"}, {"numero": 10, "texto": "And thou shalt dwell in the land of Goshen, and thou shalt be near unto me, thou, and thy children, and thy children''s children, and thy flocks, and thy herds, and all that thou hast:"}, {"numero": 11, "texto": "And there will I nourish thee; for yet there are five years of famine; lest thou, and thy household, and all that thou hast, come to poverty."}, {"numero": 12, "texto": "And, behold, your eyes see, and the eyes of my brother Benjamin, that it is my mouth that speaketh unto you."}, {"numero": 13, "texto": "And ye shall tell my father of all my glory in Egypt, and of all that ye have seen; and ye shall haste and bring down my father hither."}, {"numero": 14, "texto": "And he fell upon his brother Benjamin''s neck, and wept; and Benjamin wept upon his neck."}, {"numero": 15, "texto": "Moreover he kissed all his brethren, and wept upon them: and after that his brethren talked with him."}, {"numero": 16, "texto": "And the fame thereof was heard in Pharaoh''s house, saying, Joseph''s brethren are come: and it pleased Pharaoh well, and his servants."}, {"numero": 17, "texto": "And Pharaoh said unto Joseph, Say unto thy brethren, This do ye; lade your beasts, and go, get you unto the land of Canaan;"}, {"numero": 18, "texto": "And take your father and your households, and come unto me: and I will give you the good of the land of Egypt, and ye shall eat the fat of the land."}, {"numero": 19, "texto": "Now thou art commanded, this do ye; take you wagons out of the land of Egypt for your little ones, and for your wives, and bring your father, and come."}, {"numero": 20, "texto": "Also regard not your stuff; for the good of all the land of Egypt is your''s."}, {"numero": 21, "texto": "And the children of Israel did so: and Joseph gave them wagons, according to the commandment of Pharaoh, and gave them provision for the way."}, {"numero": 22, "texto": "To all of them he gave each man changes of raiment; but to Benjamin he gave three hundred pieces of silver, and five changes of raiment."}, {"numero": 23, "texto": "And to his father he sent after this manner; ten asses laden with the good things of Egypt, and ten she asses laden with corn and bread and meat for his father by the way."}, {"numero": 24, "texto": "So he sent his brethren away, and they departed: and he said unto them, See that ye fall not out by the way."}, {"numero": 25, "texto": "And they went up out of Egypt, and came into the land of Canaan unto Jacob their father,"}, {"numero": 26, "texto": "And told him, saying, Joseph is yet alive, and he is governor over all the land of Egypt. And Jacob''s heart fainted, for he believed them not."}, {"numero": 27, "texto": "And they told him all the words of Joseph, which he had said unto them: and when he saw the wagons which Joseph had sent to carry him, the spirit of Jacob their father revived:"}, {"numero": 28, "texto": "And Israel said, It is enough; Joseph my son is yet alive: I will go and see him before I die."}]'::jsonb, 'King James Version'),
  ('Gn', 45, 'fr', '[{"numero": 1, "texto": "Joseph ne pouvait plus se contenir devant tous ceux qui l''''entouraient. Il s''''écria: Faites sortir tout le monde. Et il ne resta personne avec Joseph, quand il se fit connaître à ses frères."}, {"numero": 2, "texto": "Il éleva la voix, en pleurant. Les Egyptiens l''''entendirent, et la maison de Pharaon l''''entendit."}, {"numero": 3, "texto": "Joseph dit à ses frères: Je suis Joseph! Mon père vit-il encore? Mais ses frères ne purent lui répondre, car ils étaient troublés en sa présence."}, {"numero": 4, "texto": "Joseph dit à ses frères: Approchez-vous de moi. Et ils s''''approchèrent. Il dit: Je suis Joseph, votre frère, que vous avez vendu pour être mené en Egypte."}, {"numero": 5, "texto": "Maintenant, ne vous affligez pas, et ne soyez pas fâchés de m''''avoir vendu pour être conduit ici, car c''''est pour vous sauver la vie que Dieu m''''a envoyé devant vous."}, {"numero": 6, "texto": "Voilà deux ans que la famine est dans le pays; et pendant cinq années encore, il n''''y aura ni labour, ni moisson."}, {"numero": 7, "texto": "Dieu m''''a envoyé devant vous pour vous faire subsister dans le pays, et pour vous faire vivre par une grande délivrance."}, {"numero": 8, "texto": "Ce n''''est donc pas vous qui m''''avez envoyé ici, mais c''''est Dieu; il m''''a établi père de Pharaon, maître de toute sa maison, et gouverneur de tout le pays d''''Egypte."}, {"numero": 9, "texto": "Hâtez-vous de remonter auprès de mon père, et vous lui direz: Ainsi a parlé ton fils Joseph: Dieu m''''a établi seigneur de toute l''''Egypte; descends vers moi, ne tarde pas!"}, {"numero": 10, "texto": "Tu habiteras dans le pays de Gosen, et tu seras près de moi, toi, tes fils, et les fils de tes fils, tes brebis et tes boeufs, et tout ce qui est à toi."}, {"numero": 11, "texto": "Là, je te nourrirai, car il y aura encore cinq années de famine; et ainsi tu ne périras point, toi, ta maison, et tout ce qui est à toi."}, {"numero": 12, "texto": "Vous voyez de vos yeux, et mon frère Benjamin voit de ses yeux que c''''est moi-même qui vous parle."}, {"numero": 13, "texto": "Racontez à mon père toute ma gloire en Egypte, et tout ce que vous avez vu; et vous ferez descendre ici mon père au plus tôt."}, {"numero": 14, "texto": "Il se jeta au cou de Benjamin, son frère, et pleura; et Benjamin pleura sur son cou."}, {"numero": 15, "texto": "Il embrassa aussi tous ses frères, en pleurant. Après quoi, ses frères s''''entretinrent avec lui."}, {"numero": 16, "texto": "Le bruit se répandit dans la maison de Pharaon que les frères de Joseph étaient arrivés: ce qui fut agréable à Pharaon et à ses serviteurs."}, {"numero": 17, "texto": "Pharaon dit à Joseph: Dis à tes frères: Faites ceci. Chargez vos bêtes, et partez pour le pays de Canaan;"}, {"numero": 18, "texto": "prenez votre père et vos familles, et venez auprès de moi. Je vous donnerai ce qu''''il y a de meilleur au pays d''''Egypte, et vous mangerez la graisse du pays."}, {"numero": 19, "texto": "Tu as ordre de leur dire: Faites ceci. Prenez dans le pays d''''Egypte des chars pour vos enfants et pour vos femmes; amenez votre père, et venez."}, {"numero": 20, "texto": "Ne regrettez point ce que vous laisserez, car ce qu''''il y a de meilleur dans tout le pays d''''Egypte sera pour vous."}, {"numero": 21, "texto": "Les fils d''''Israël firent ainsi. Joseph leur donna des chars, selon l''''ordre de Pharaon; il leur donna aussi des provisions pour la route."}, {"numero": 22, "texto": "Il leur donna à tous des vêtements de rechange, et il donna à Benjamin trois cents sicles d''''argent et cinq vêtements de rechange."}, {"numero": 23, "texto": "Il envoya à son père dix ânes chargés de ce qu''''il y avait de meilleur en Egypte, et dix ânesses chargées de blé, de pain et de vivres, pour son père pendant le voyage."}, {"numero": 24, "texto": "Puis il congédia ses frères, qui partirent; et il leur dit: Ne vous querellez pas en chemin."}, {"numero": 25, "texto": "Ils remontèrent de l''''Egypte, et ils arrivèrent dans le pays de Canaan, auprès de Jacob, leur père."}, {"numero": 26, "texto": "Ils lui dirent: Joseph vit encore, et même c''''est lui qui gouverne tout le pays d''''Egypte. Mais le coeur de Jacob resta froid, parce qu''''il ne les croyait pas."}, {"numero": 27, "texto": "Ils lui rapportèrent toutes les paroles que Joseph leur avait dites. Il vit les chars que Joseph avait envoyés pour le transporter. C''''est alors que l''''esprit de Jacob, leur père, se ranima;"}, {"numero": 28, "texto": "et Israël dit: C''''est assez! Joseph, mon fils, vit encore! J''''irai, et je le verrai avant que je meure."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 45, 'es', '[{"numero": 1, "texto": "NO podía ya José contenerse delante de todos los que estaban al lado suyo, y clamó: Haced salir de conmigo á todos. Y no quedó nadie con él, al darse á conocer José á sus hermanos."}, {"numero": 2, "texto": "Entonces se dió á llorar á voz en grito; y oyeron los Egipcios, y oyó también la casa de Faraón."}, {"numero": 3, "texto": "Y dijo José á sus hermanos: Yo soy José: ¿vive aún mi padre? Y sus hermanos no pudieron responderle, porque estaban turbados delante de él."}, {"numero": 4, "texto": "Entonces dijo José á sus hermanos: Llegaos ahora á mí. Y ellos se llegaron. Y él dijo: Yo soy José vuestro hermano el que vendisteis para Egipto."}, {"numero": 5, "texto": "Ahora pues, no os entristezcáis, ni os pese de haberme vendido acá; que para preservación de vida me envió Dios delante de vosotros:"}, {"numero": 6, "texto": "Que ya ha habido dos años de hambre en medio de la tierra, y aun quedan cinco años en que ni habrá arada ni siega."}, {"numero": 7, "texto": "Y Dios me envió delante de vosotros, para que vosotros quedaseis en la tierra, y para daros vida por medio de grande salvamento."}, {"numero": 8, "texto": "Así pues, no me enviasteis vosotros acá, sino Dios, que me ha puesto por padre de Faraón, y por señor de toda su casa, y por gobernador en toda la tierra de Egipto."}, {"numero": 9, "texto": "Daos priesa, id á mi padre y decidle: Así dice tu hijo José: Dios me ha puesto por señor de todo Egipto; ven á mí, no te detengas:"}, {"numero": 10, "texto": "Y habitarás en la tierra de Gosén, y estarás cerca de mí, tú y tus hijos, y los hijos de tus hijos, tus ganados y tus vacas, y todo lo que tienes."}, {"numero": 11, "texto": "Y allí te alimentaré, pues aun quedan cinco años de hambre, porque no perezcas de pobreza tú y tu casa, y todo lo que tienes:"}, {"numero": 12, "texto": "Y he aquí, vuestros ojos ven, y los ojos de mi hermano Benjamín, que mi boca os habla."}, {"numero": 13, "texto": "Haréis pues saber á mi padre toda mi gloria en Egipto, y todo lo que habéis visto: y daos priesa, y traed á mi padre acá."}, {"numero": 14, "texto": "Y echóse sobre el cuello de Benjamín su hermano, y lloró; y también Benjamín lloró sobre su cuello."}, {"numero": 15, "texto": "Y besó á todos sus hermanos, y lloró sobre ellos: y después sus hermanos hablaron con él."}, {"numero": 16, "texto": "Y oyóse la noticia en la casa de Faraón, diciendo: Los hermanos de José han venido. Y plugo en los ojos de Faraón y de sus siervos."}, {"numero": 17, "texto": "Y dijo Faraón á José: Di á tus hermanos: Haced esto: cargad vuestras bestias, é id, volved á la tierra de Canaán;"}, {"numero": 18, "texto": "Y tomad á vuestro padre y vuestras familias, y venid á mí, que yo os daré lo bueno de la tierra de Egipto y comeréis la grosura de la tierra."}, {"numero": 19, "texto": "Y tú manda: Haced esto: tomaos de la tierra de Egipto carros para vuestros niños y vuestras mujeres; y tomad á vuestro padre, y venid."}, {"numero": 20, "texto": "Y no se os dé nada de vuestras alhajas, porque el bien de la tierra de Egipto será vuestro."}, {"numero": 21, "texto": "E hiciéronlo así los hijos de Israel: y dióles José carros conforme á la orden de Faraón, y suministróles víveres para el camino."}, {"numero": 22, "texto": "A cada uno de todos ellos dió mudas de vestidos, y á Benjamín dió trescientas piezas de plata, y cinco mudas de vestidos."}, {"numero": 23, "texto": "Y á su padre envió esto: diez asnos cargados de lo mejor de Egipto, y diez asnas cargadas de trigo, y pan y comida, para su padre en el camino."}, {"numero": 24, "texto": "Y despidió á sus hermanos, y fuéronse. Y él les dijo: No riñáis por el camino."}, {"numero": 25, "texto": "Y subieron de Egipto, y llegaron á la tierra de Canaán á Jacob su padre."}, {"numero": 26, "texto": "Y diéronle las nuevas, diciendo: José vive aún; y él es señor en toda la tierra de Egipto. Y su corazón se desmayó; pues no los creía."}, {"numero": 27, "texto": "Y ellos le contaron todas las palabras de José, que él les había hablado; y viendo él los carros que José enviaba para llevarlo, el espíritu de Jacob su padre revivió."}, {"numero": 28, "texto": "Entonces dijo Israel: Basta; José mi hijo vive todavía: iré, y le veré antes que yo muera."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 46, 'pt', '[{"numero": 1, "texto": "E partiu-se Israel com tudo o que tinha, e veio a Berseba, e ofereceu sacrifícios ao Deus de seu pai Isaque."}, {"numero": 2, "texto": "E falou Deus a Israel em visões de noite, e disse: Jacó, Jacó. E ele respondeu: Eis-me aqui."}, {"numero": 3, "texto": "E disse: Eu sou Deus, o Deus de teu pai; não temas de descer ao Egito, porque eu te farei ali em grande nação."}, {"numero": 4, "texto": "Eu descerei contigo ao Egito, e eu também te farei voltar; e José porá sua mão sobre teus olhos."}, {"numero": 5, "texto": "E levantou-se Jacó de Berseba; e tomaram os filhos de Israel a seu pai Jacó, e a seus filhos, e a suas mulheres, nos carros que Faraó havia enviado para levá-lo."}, {"numero": 6, "texto": "E tomaram seus gados, e sua riqueza que havia adquirido na terra de Canaã, e vieram-se ao Egito, Jacó, e toda sua descendência consigo;"}, {"numero": 7, "texto": "Seus filhos, e os filhos de seus filhos consigo; suas filhas, e as filhas de seus filhos, e a toda sua descendência trouxe consigo ao Egito."}, {"numero": 8, "texto": "E estes são os nomes dos filhos de Israel, que entraram no Egito, Jacó e seus filhos: Rúben, o primogênito de Jacó."}, {"numero": 9, "texto": "E os filhos de Rúben: Enoque, e Palu, e Hezrom, e Carmi."}, {"numero": 10, "texto": "E os filhos de Simeão: Jemuel, e Jamim, e Oade, e Jaquim, e Zoar, e Saul, filho da cananeia."}, {"numero": 11, "texto": "E os filhos de Levi: Gérson, Coate, e Merari."}, {"numero": 12, "texto": "E os filhos de Judá: Er, e Onã, e Selá, e Perez, e Zerá: mas Er e Onã, morreram na terra de Canaã. E os filhos de Perez foram Hezrom e Hamul."}, {"numero": 13, "texto": "E os filhos de Issacar: Tola, e Puva, e Jó, e Sinrom."}, {"numero": 14, "texto": "E os filhos de Zebulom: Serede e Elom, e Jaleel."}, {"numero": 15, "texto": "Estes foram os filhos de Lia, os que deu a Jacó em Padã-Arã, e além de sua filha Diná: trinta e três as almas todas de seus filhos e filhas."}, {"numero": 16, "texto": "E os filhos de Gade: Zifiom, e Hagi, e Suni, e Ezbom, e Eri, e Arodi, e Areli."}, {"numero": 17, "texto": "E os filhos de Aser: Imna, e Isva, e Isvi y Berias, e Sera, irmã deles. Os filhos de Berias: Héber, e Malquiel."}, {"numero": 18, "texto": "Estes foram os filhos de Zilpa, a que Labão deu a sua filha Lia, e deu estes a Jacó; todas dezesseis almas."}, {"numero": 19, "texto": "E os filhos de Raquel, mulher de Jacó: José e Benjamim."}, {"numero": 20, "texto": "E nasceram a José na terra do Egito Manassés e Efraim, os que lhe deu Azenate, filha Potífera, sacerdote de Om."}, {"numero": 21, "texto": "E os filhos de Benjamim foram Belá, e Bequer e Asbel, e Gera, e Naamã, e Eí, e Rôs e Mupim, e Hupim, e Arde."}, {"numero": 22, "texto": "Estes foram os filhos de Raquel, que nasceram a Jacó: ao todo, catorze almas."}, {"numero": 23, "texto": "E os filhos de Dã: Husim."}, {"numero": 24, "texto": "E os filhos de Naftali: Jazeel, e Guni, e Jezer, e Silém."}, {"numero": 25, "texto": "Estes foram os filhos de Bila, a que deu Labão a Raquel sua filha, e ela deu à luz estes a Jacó; todas sete almas."}, {"numero": 26, "texto": "Todas as pessoas que vieram com Jacó ao Egito, procedentes de seus lombos, sem as mulheres dos filhos de Jacó, todas as pessoas foram sessenta e seis."}, {"numero": 27, "texto": "E os filhos de José, que lhe nasceram no Egito, duas pessoas. Todas as almas da casa de Jacó, que entraram no Egito, foram setenta."}, {"numero": 28, "texto": "E enviou a Judá adiante de si a José, para que lhe viesse a ver a Gósen; e chegaram à terra de Gósen."}, {"numero": 29, "texto": "E José preparou seu carro e veio a receber a Israel seu pai a Gósen; e se manifestou a ele, e lançou-se sobre seu pescoço, e chorou sobre seu pescoço bastante."}, {"numero": 30, "texto": "Então Israel disse a José: Morra eu agora, já que vi teu rosto, pois ainda vives."}, {"numero": 31, "texto": "E José disse a seus irmãos, e à casa de seu pai: Subirei e farei saber a Faraó, e lhe direi: Meus irmãos e a casa de meu pai, que estavam na terra de Canaã, vieram a mim;"}, {"numero": 32, "texto": "E os homens são pastores de ovelhas, porque são homens criadores de gado: e trouxeram suas ovelhas e suas vacas, e tudo o que tinham."}, {"numero": 33, "texto": "E quando Faraó vos chamar e disser: qual é vosso ofício?"}, {"numero": 34, "texto": "Então direis: Homens de criação de gado foram teus servos desde nossa juventude até agora, nós e nossos pais; a fim que moreis na terra de Gósen, porque os egípcios abominam todo pastor de ovelhas."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 46, 'en', '[{"numero": 1, "texto": "And Israel took his journey with all that he had, and came to Beersheba, and offered sacrifices unto the God of his father Isaac."}, {"numero": 2, "texto": "And God spake unto Israel in the visions of the night, and said, Jacob, Jacob. And he said, Here am I."}, {"numero": 3, "texto": "And he said, I am God, the God of thy father: fear not to go down into Egypt; for I will there make of thee a great nation:"}, {"numero": 4, "texto": "I will go down with thee into Egypt; and I will also surely bring thee up again: and Joseph shall put his hand upon thine eyes."}, {"numero": 5, "texto": "And Jacob rose up from Beersheba: and the sons of Israel carried Jacob their father, and their little ones, and their wives, in the wagons which Pharaoh had sent to carry him."}, {"numero": 6, "texto": "And they took their cattle, and their goods, which they had gotten in the land of Canaan, and came into Egypt, Jacob, and all his seed with him:"}, {"numero": 7, "texto": "His sons, and his sons'' sons with him, his daughters, and his sons'' daughters, and all his seed brought he with him into Egypt."}, {"numero": 8, "texto": "And these are the names of the children of Israel, which came into Egypt, Jacob and his sons: Reuben, Jacob''s firstborn."}, {"numero": 9, "texto": "And the sons of Reuben; Hanoch, and Phallu, and Hezron, and Carmi."}, {"numero": 10, "texto": "And the sons of Simeon; Jemuel, and Jamin, and Ohad, and Jachin, and Zohar, and Shaul the son of a Canaanitish woman."}, {"numero": 11, "texto": "And the sons of Levi; Gershon, Kohath, and Merari."}, {"numero": 12, "texto": "And the sons of Judah; Er, and Onan, and Shelah, and Pharez, and Zarah: but Er and Onan died in the land of Canaan. And the sons of Pharez were Hezron and Hamul."}, {"numero": 13, "texto": "And the sons of Issachar; Tola, and Phuvah, and Job, and Shimron."}, {"numero": 14, "texto": "And the sons of Zebulun; Sered, and Elon, and Jahleel."}, {"numero": 15, "texto": "These be the sons of Leah, which she bare unto Jacob in Padanaram, with his daughter Dinah: all the souls of his sons and his daughters were thirty and three."}, {"numero": 16, "texto": "And the sons of Gad; Ziphion, and Haggi, Shuni, and Ezbon, Eri, and Arodi, and Areli."}, {"numero": 17, "texto": "And the sons of Asher; Jimnah, and Ishuah, and Isui, and Beriah, and Serah their sister: and the sons of Beriah; Heber, and Malchiel."}, {"numero": 18, "texto": "These are the sons of Zilpah, whom Laban gave to Leah his daughter, and these she bare unto Jacob, even sixteen souls."}, {"numero": 19, "texto": "The sons of Rachel Jacob''s wife; Joseph, and Benjamin."}, {"numero": 20, "texto": "And unto Joseph in the land of Egypt were born Manasseh and Ephraim, which Asenath the daughter of Potipherah priest of On bare unto him."}, {"numero": 21, "texto": "And the sons of Benjamin were Belah, and Becher, and Ashbel, Gera, and Naaman, Ehi, and Rosh, Muppim, and Huppim, and Ard."}, {"numero": 22, "texto": "These are the sons of Rachel, which were born to Jacob: all the souls were fourteen."}, {"numero": 23, "texto": "And the sons of Dan; Hushim."}, {"numero": 24, "texto": "And the sons of Naphtali; Jahzeel, and Guni, and Jezer, and Shillem."}, {"numero": 25, "texto": "These are the sons of Bilhah, which Laban gave unto Rachel his daughter, and she bare these unto Jacob: all the souls were seven."}, {"numero": 26, "texto": "All the souls that came with Jacob into Egypt, which came out of his loins, besides Jacob''s sons'' wives, all the souls were threescore and six;"}, {"numero": 27, "texto": "And the sons of Joseph, which were born him in Egypt, were two souls: all the souls of the house of Jacob, which came into Egypt, were threescore and ten."}, {"numero": 28, "texto": "And he sent Judah before him unto Joseph, to direct his face unto Goshen; and they came into the land of Goshen."}, {"numero": 29, "texto": "And Joseph made ready his chariot, and went up to meet Israel his father, to Goshen, and presented himself unto him; and he fell on his neck, and wept on his neck a good while."}, {"numero": 30, "texto": "And Israel said unto Joseph, Now let me die, since I have seen thy face, because thou art yet alive."}, {"numero": 31, "texto": "And Joseph said unto his brethren, and unto his father''s house, I will go up, and shew Pharaoh, and say unto him, My brethren, and my father''s house, which were in the land of Canaan, are come unto me;"}, {"numero": 32, "texto": "And the men are shepherds, for their trade hath been to feed cattle; and they have brought their flocks, and their herds, and all that they have."}, {"numero": 33, "texto": "And it shall come to pass, when Pharaoh shall call you, and shall say, What is your occupation?"}, {"numero": 34, "texto": "That ye shall say, Thy servants'' trade hath been about cattle from our youth even until now, both we, and also our fathers: that ye may dwell in the land of Goshen; for every shepherd is an abomination unto the Egyptians."}]'::jsonb, 'King James Version'),
  ('Gn', 46, 'fr', '[{"numero": 1, "texto": "Israël partit, avec tout ce qui lui appartenait. Il arriva à Beer-Schéba, et il offrit des sacrifices au Dieu de son père Isaac."}, {"numero": 2, "texto": "Dieu parla à Israël dans une vision pendant la nuit, et il dit: Jacob! Jacob! Israël répondit: Me voici!"}, {"numero": 3, "texto": "Et Dieu dit: Je suis le Dieu, le Dieu de ton père. Ne crains point de descendre en Egypte, car là je te ferai devenir une grande nation."}, {"numero": 4, "texto": "Moi-même je descendrai avec toi en Egypte, et moi-même je t''''en ferai remonter; et Joseph te fermera les yeux."}, {"numero": 5, "texto": "Jacob quitta Beer-Schéba; et les fils d''''Israël mirent Jacob, leur père, avec leurs enfants et leurs femmes, sur les chars que Pharaon avait envoyés pour les transporter."}, {"numero": 6, "texto": "Ils prirent aussi leurs troupeaux et les biens qu''''ils avaient acquis dans le pays de Canaan. Et Jacob se rendit en Egypte, avec toute sa famille."}, {"numero": 7, "texto": "Il emmena avec lui en Egypte ses fils et les fils de ses fils, ses filles et les filles de ses fils, et toute sa famille."}, {"numero": 8, "texto": "Voici les noms des fils d''''Israël, qui vinrent en Egypte. Jacob et ses fils. Premier-né de Jacob: Ruben."}, {"numero": 9, "texto": "Fils de Ruben: Hénoc, Pallu, Hetsron et Carmi."}, {"numero": 10, "texto": "Fils de Siméon: Jemuel, Jamin, Ohad, Jakin et Tsochar; et Saul, fils de la Cananéenne."}, {"numero": 11, "texto": "Fils de Lévi: Guerschon, Kehath et Merari."}, {"numero": 12, "texto": "Fils de Juda: Er, Onan, Schéla, Pérets et Zarach; mais Er et Onan moururent au pays de Canaan. Les fils de Pérets furent Hetsron et Hamul."}, {"numero": 13, "texto": "Fils d''''Issacar: Thola, Puva, Job et Schimron."}, {"numero": 14, "texto": "Fils de Zabulon: Séred, Elon et Jahleel."}, {"numero": 15, "texto": "Ce sont là les fils que Léa enfanta à Jacob à Paddan-Aram, avec sa fille Dina. Ses fils et ses filles formaient en tout trente-trois personnes."}, {"numero": 16, "texto": "Fils de Gad: Tsiphjon, Haggi, Schuni, Etsbon, Eri, Arodi et Areéli."}, {"numero": 17, "texto": "Fils d''''Aser: Jimna, Jischva, Jischvi et Beria; et Sérach, leur soeur. Et les fils de Beria: Héber et Malkiel."}, {"numero": 18, "texto": "Ce sont là les fils de Zilpa, que Laban avait donnée à Léa, sa fille; et elle les enfanta à Jacob. En tout, seize personnes."}, {"numero": 19, "texto": "Fils de Rachel, femme de Jacob: Joseph et Benjamin."}, {"numero": 20, "texto": "Il naquit à Joseph, au pays d''''Egypte, Manassé et Ephraïm, que lui enfanta Asnath, fille de Poti-Phéra, prêtre d''''On."}, {"numero": 21, "texto": "Fils de Benjamin: Béla, Béker, Aschbel, Guéra, Naaman, Ehi, Rosch, Muppim, Huppim et Ard."}, {"numero": 22, "texto": "Ce sont là les fils de Rachel, qui naquirent à Jacob. En tout, quatorze personnes."}, {"numero": 23, "texto": "Fils de Dan: Huschim."}, {"numero": 24, "texto": "Fils de Nephthali: Jathtseel, Guni, Jetser et Schillem."}, {"numero": 25, "texto": "Ce sont là les fils de Bilha, que Laban avait donnée à Rachel, sa fille; et elle les enfanta à Jacob. En tout, sept personnes."}, {"numero": 26, "texto": "Les personnes qui vinrent avec Jacob en Egypte, et qui étaient issues de lui, étaient au nombre de soixante-six en tout, sans compter les femmes des fils de Jacob."}, {"numero": 27, "texto": "Et Joseph avait deux fils qui lui étaient nés en Egypte. Le total des personnes de la famille de Jacob qui vinrent en Egypte était de soixante-dix."}, {"numero": 28, "texto": "Jacob envoya Juda devant lui vers Joseph, pour l''''informer qu''''il se rendait en Gosen."}, {"numero": 29, "texto": "Joseph attela son char et y monta, pour aller en Gosen, à la rencontre d''''Israël, son père. Dès qu''''il le vit, il se jeta à son cou, et pleura longtemps sur son cou."}, {"numero": 30, "texto": "Israël dit à Joseph: Que je meure maintenant, puisque j''''ai vu ton visage et que tu vis encore!"}, {"numero": 31, "texto": "Joseph dit à ses frères et à la famille de son père: Je vais avertir Pharaon, et je lui dirai: Mes frères et la famille de mon père, qui étaient au pays de Canaan, sont arrivés auprès de moi."}, {"numero": 32, "texto": "Ces hommes sont bergers, car ils élèvent des troupeaux; ils ont amené leurs brebis et leurs boeufs, et tout ce qui leur appartient."}, {"numero": 33, "texto": "Et quand Pharaon vous appellera, et dira: Quelle est votre occupation?"}, {"numero": 34, "texto": "vous répondrez: Tes serviteurs ont élevé des troupeaux, depuis notre jeunesse jusqu''''à présent, nous et nos pères. De cette manière, vous habiterez dans le pays de Gosen, car tous les bergers sont en abomination aux Egyptiens."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 46, 'es', '[{"numero": 1, "texto": "Y PARTIÓSE Israel con todo lo que tenía, y vino á Beer-seba, y ofreció sacrificios al Dios de su padre Isaac."}, {"numero": 2, "texto": "Y habló Dios á Israel en visiones de noche, y dijo: Jacob, Jacob. Y él respondió: Heme aquí."}, {"numero": 3, "texto": "Y dijo: Yo soy Dios, el Dios de tu padre; no temas de descender á Egipto, porque yo te pondré allí en gran gente."}, {"numero": 4, "texto": "Yo descenderé contigo á Egipto, y yo también te haré volver: y José pondrá su mano sobre tus ojos."}, {"numero": 5, "texto": "Y levantóse Jacob de Beer-seba; y tomaron los hijos de Israel á su padre Jacob, y á sus niños, y á sus mujeres, en los carros que Faraón había enviado para llevarlo."}, {"numero": 6, "texto": "Y tomaron sus ganados, y su hacienda que había adquirido en la tierra de Canaán, y viniéronse á Egipto, Jacob, y toda su simiente consigo;"}, {"numero": 7, "texto": "Sus hijos, y los hijos de sus hijos consigo; sus hijas, y las hijas de sus hijos, y á toda su simiente trajo consigo á Egipto."}, {"numero": 8, "texto": "Y estos son los nombres de los hijos de Israel, que entraron en Egipto, Jacob y sus hijos: Rubén, el primogénito de Jacob."}, {"numero": 9, "texto": "Y los hijos de Rubén: Hanoch, y Phallu, y Hezrón, y Carmi."}, {"numero": 10, "texto": "Y los hijos de Simeón: Jemuel, y Jamín, y Ohad, y Jachîn, y Zohar, y Saúl, hijo de la Cananea."}, {"numero": 11, "texto": "Y los hijos de Leví: Gersón, y Coath, y Merari."}, {"numero": 12, "texto": "Y los hijos de Judá: Er, y Onán, y Sela, y Phares, y Zara: mas Er y Onán, murieron en la tierra de Canaán. Y los hijos de Phares fueron Hezrón y Hamul."}, {"numero": 13, "texto": "Y los hijos de Issachâr: Thola, y Phua, y Job, y Simrón."}, {"numero": 14, "texto": "Y los hijos de Zabulón: Sered, y Elón, y Jahleel."}, {"numero": 15, "texto": "Estos fueron los hijos de Lea, los que parió á Jacob en Padan-aram, y además su hija Dina: treinta y tres las almas todas de sus hijos é hijas."}, {"numero": 16, "texto": "Y los hijos de Gad: Ziphión, y Aggi, y Ezbón, y Suni, y Heri, y Arodi, y Areli."}, {"numero": 17, "texto": "Y los hijos de Aser: Jimna, é Ishua, é Isui, y Beria, y Sera, hermana de ellos. Los hijos de Beria: Heber, y Malchîel."}, {"numero": 18, "texto": "Estos fueron los hijos de Zilpa, la que Labán dió á su hija Lea, y parió estos á Jacob; todas diez y seis almas."}, {"numero": 19, "texto": "Y los hijos de Rachêl, mujer de Jacob: José y Benjamín."}, {"numero": 20, "texto": "Y nacieron á José en la tierra de Egipto Manasés y Ephraim, los que le parió Asenath, hija de Potipherah, sacerdote de On."}, {"numero": 21, "texto": "Y los hijos de Benjamín fueron Bela, y Bechêr y Asbel, y Gera, y Naamán, y Ehi, y Ros y Muppim, y Huppim, y Ard."}, {"numero": 22, "texto": "Estos fueron los hijos de Rachêl, que nacieron á Jacob: en todas, catorce almas."}, {"numero": 23, "texto": "Y los hijos de Dan: Husim."}, {"numero": 24, "texto": "Y los hijos de Nephtalí: Jahzeel, y Guni, y Jezer, y Shillem."}, {"numero": 25, "texto": "Estos fueron los hijos de Bilha, la que dió Labán á Rachêl su hija, y parió estos á Jacob; todas siete almas."}, {"numero": 26, "texto": "Todas las personas que vinieron con Jacob á Egipto, procedentes de sus lomos, sin las mujeres de los hijos de Jacob, todas las personas fueron sesenta y seis."}, {"numero": 27, "texto": "Y los hijos de José, que le nacieron en Egipto, dos personas. Todas las almas de la casa de Jacob, que entraron en Egipto, fueron setenta."}, {"numero": 28, "texto": "Y envió á Judá delante de sí á José, para que le viniese á ver á Gosén; y llegaron á la tierra de Gosén."}, {"numero": 29, "texto": "Y José unció su carro y vino á recibir á Israel su padre á Gosén; y se manifestó á él, y echóse sobre su cuello, y lloró sobre su cuello bastante."}, {"numero": 30, "texto": "Entonces Israel dijo á José: Muera yo ahora, ya que he visto tu rostro, pues aun vives."}, {"numero": 31, "texto": "Y José dijo á sus hermanos, y á la casa de su padre: Subiré y haré saber á Faraón, y diréle: Mis hermanos y la casa de mi padre, que estaban en la tierra de Canaán, han venido á mí;"}, {"numero": 32, "texto": "Y los hombres son pastores de ovejas, porque son hombres ganaderos: y han traído sus ovejas y sus vacas, y todo lo que tenían."}, {"numero": 33, "texto": "Y cuando Faraón os llamare y dijere: ¿cuál es vuestro oficio?"}, {"numero": 34, "texto": "Entonces diréis: Hombres de ganadería han sido tus siervos desde nuestra mocedad hasta ahora, nosotros y nuestros padres; á fin que moréis en la tierra de Gosén, porque los Egipcios abominan todo pastor de ovejas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 47, 'pt', '[{"numero": 1, "texto": "E José veio, e fez saber a Faraó, e disse: Meu pai e meus irmãos, e suas ovelhas e suas vacas, com tudo o que têm, vieram da terra de Canaã, e eis que, estão na terra de Gósen."}, {"numero": 2, "texto": "E dentre seus irmãos tomou cinco homens, e os apresentou diante de Faraó."}, {"numero": 3, "texto": "E Faraó disse a seus irmãos: Qual é vosso ofício? E eles responderam a Faraó: Pastores de ovelhas são teus servos, tanto nós como nossos pais."}, {"numero": 4, "texto": "Disseram ademais a Faraó: Por morar nesta terra viemos; porque não há pasto para as ovelhas de teus servos, pois a fome é grave na terra de Canaã: portanto, te rogamos agora que habitem teus servos na terra de Gósen."}, {"numero": 5, "texto": "Então Faraó falou a José, dizendo: Teu pai e teus irmãos vieram a ti;"}, {"numero": 6, "texto": "A terra do Egito diante de ti está; no melhor da terra faze habitar a teu pai e a teus irmãos; habitem na terra de Gósen; e se entendes que há entre eles homens competentes, põe-os por administradores do meu gado."}, {"numero": 7, "texto": "E José introduziu a seu pai, e apresentou-o diante de Faraó; e Jacó abençoou a Faraó."}, {"numero": 8, "texto": "E disse Faraó a Jacó: Quantos são os dias dos anos de tua vida?"}, {"numero": 9, "texto": "E Jacó respondeu a Faraó: Os dias dos anos de minha peregrinação são cento e trinta anos; poucos e maus foram os dias dos anos de minha vida, e não chegaram aos dias dos anos da vida de meus pais nos dias de sua peregrinação."}, {"numero": 10, "texto": "E Jacó abençoou a Faraó, e saiu-se de diante de Faraó."}, {"numero": 11, "texto": "Assim José fez habitar a seu pai e a seus irmãos, e deu-lhes possessão na terra do Egito, no melhor da terra, na terra de Ramessés como mandou Faraó."}, {"numero": 12, "texto": "E alimentava José a seu pai e a seus irmãos, e a toda a casa de seu pai, de pão, segundo o número de seus filhos."}, {"numero": 13, "texto": "E não havia pão toda a terra, e a fome era muito grave; pelo que desfaleceu de fome a terra do Egito e a terra de Canaã."}, {"numero": 14, "texto": "E recolheu José todo o dinheiro que se achou na terra do Egito e na terra de Canaã, pelos alimentos que dele compravam; e meteu José o dinheiro na casa de Faraó."}, {"numero": 15, "texto": "E acabado o dinheiro da terra do Egito e da terra de Canaã, veio todo Egito a José dizendo: Dá-nos pão: por que morreremos diante de ti, por haver-se acabado o dinheiro?"}, {"numero": 16, "texto": "E José disse: Dai vossos gados, e eu vos darei por vossos gados, se se acabou o dinheiro."}, {"numero": 17, "texto": "E eles trouxeram seus gados a José; e José lhes deu alimentos por cavalos, e pelo rebanho das ovelhas, e pelo rebanho das vacas, e por asnos: e sustentou-os de pão por todos os seus gados aquele ano."}, {"numero": 18, "texto": "E acabado aquele ano, vieram a ele o segundo ano, e lhe disseram: Não encobriremos a nosso senhor que o dinheiro certamente se acabou; também o gado é já de nosso senhor; nada restou diante de nosso senhor a não ser nossos corpos e nossa terra."}, {"numero": 19, "texto": "Por que morreremos diante de teus olhos, tanto nós como nossa terra? Compra a nós e a nossa terra por pão, e seremos nós e nossa terra servos de Faraó; e dá-nos semente para que vivamos e não morramos, e não seja assolada a terra."}, {"numero": 20, "texto": "Então comprou José toda a terra do Egito para Faraó; pois os egípcios venderam cada um suas terras, porque se agravou a fome sobre eles: e a terra veio a ser de Faraó."}, {"numero": 21, "texto": "E ao povo o fez passar às cidades desde um fim do termo do Egito até o outro fim."}, {"numero": 22, "texto": "Somente a terra dos sacerdotes não comprou, porquanto os sacerdotes tinham ração de Faraó, e eles comiam sua ração que Faraó lhes dava: por isso não venderam sua terra."}, {"numero": 23, "texto": "E José disse ao povo: Eis que comprei hoje vós e vossa terra para Faraó: vede aqui semente, e semeareis a terra."}, {"numero": 24, "texto": "E será que dos frutos dareis o quinto a Faraó, e as quatro partes serão vossas para semear as terras, e para vosso mantimento, e dos que estão em vossas casas, e para que comam vossos meninos."}, {"numero": 25, "texto": "E eles responderam: A vida nos deste: achemos favor aos olhos de meu senhor, e sejamos servos de Faraó."}, {"numero": 26, "texto": "Então José o pôs por estatuto até hoje sobre a terra do Egito, assinalando para Faraó o quinto; exceto somente a terra dos sacerdotes, que não foi de Faraó."}, {"numero": 27, "texto": "Assim habitou Israel na terra do Egito, na terra de Gósen; e apossaram-se nela, y se aumentaram, e multiplicaram em grande maneira."}, {"numero": 28, "texto": "E viveu Jacó na terra do Egito dezessete anos: e foram os dias de Jacó, os anos de sua vida, cento quarenta e sete anos."}, {"numero": 29, "texto": "E achegaram-se os dias de Israel para morrer, e chamou a José seu filho, e lhe disse: Se achei agora favor em teus olhos, rogo-te que ponhas tua mão debaixo de minha coxa, e farás comigo misericórdia e verdade; rogo-te que não me enterres no Egito;"}, {"numero": 30, "texto": "Mas quando dormir com meus pais, me levarás de Egito, e me sepultarás no sepulcro deles. E ele respondeu: Eu farei como tu dizes."}, {"numero": 31, "texto": "E ele disse: Jura-me isso. E ele lhe jurou. Então Israel se inclinou sobre a cabeceira da cama."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 47, 'en', '[{"numero": 1, "texto": "Then Joseph came and told Pharaoh, and said, My father and my brethren, and their flocks, and their herds, and all that they have, are come out of the land of Canaan; and, behold, they are in the land of Goshen."}, {"numero": 2, "texto": "And he took some of his brethren, even five men, and presented them unto Pharaoh."}, {"numero": 3, "texto": "And Pharaoh said unto his brethren, What is your occupation? And they said unto Pharaoh, Thy servants are shepherds, both we, and also our fathers."}, {"numero": 4, "texto": "They said morever unto Pharaoh, For to sojourn in the land are we come; for thy servants have no pasture for their flocks; for the famine is sore in the land of Canaan: now therefore, we pray thee, let thy servants dwell in the land of Goshen."}, {"numero": 5, "texto": "And Pharaoh spake unto Joseph, saying, Thy father and thy brethren are come unto thee:"}, {"numero": 6, "texto": "The land of Egypt is before thee; in the best of the land make thy father and brethren to dwell; in the land of Goshen let them dwell: and if thou knowest any men of activity among them, then make them rulers over my cattle."}, {"numero": 7, "texto": "And Joseph brought in Jacob his father, and set him before Pharaoh: and Jacob blessed Pharaoh."}, {"numero": 8, "texto": "And Pharaoh said unto Jacob, How old art thou?"}, {"numero": 9, "texto": "And Jacob said unto Pharaoh, The days of the years of my pilgrimage are an hundred and thirty years: few and evil have the days of the years of my life been, and have not attained unto the days of the years of the life of my fathers in the days of their pilgrimage."}, {"numero": 10, "texto": "And Jacob blessed Pharaoh, and went out from before Pharaoh."}, {"numero": 11, "texto": "And Joseph placed his father and his brethren, and gave them a possession in the land of Egypt, in the best of the land, in the land of Rameses, as Pharaoh had commanded."}, {"numero": 12, "texto": "And Joseph nourished his father, and his brethren, and all his father''s household, with bread, according to their families."}, {"numero": 13, "texto": "And there was no bread in all the land; for the famine was very sore, so that the land of Egypt and all the land of Canaan fainted by reason of the famine."}, {"numero": 14, "texto": "And Joseph gathered up all the money that was found in the land of Egypt, and in the land of Canaan, for the corn which they bought: and Joseph brought the money into Pharaoh''s house."}, {"numero": 15, "texto": "And when money failed in the land of Egypt, and in the land of Canaan, all the Egyptians came unto Joseph, and said, Give us bread: for why should we die in thy presence? for the money faileth."}, {"numero": 16, "texto": "And Joseph said, Give your cattle; and I will give you for your cattle, if money fail."}, {"numero": 17, "texto": "And they brought their cattle unto Joseph: and Joseph gave them bread in exchange for horses, and for the flocks, and for the cattle of the herds, and for the asses: and he fed them with bread for all their cattle for that year."}, {"numero": 18, "texto": "When that year was ended, they came unto him the second year, and said unto him, We will not hide it from my lord, how that our money is spent; my lord also hath our herds of cattle; there is not ought left in the sight of my lord, but our bodies, and our lands:"}, {"numero": 19, "texto": "Wherefore shall we die before thine eyes, both we and our land? buy us and our land for bread, and we and our land will be servants unto Pharaoh: and give us seed, that we may live, and not die, that the land be not desolate."}, {"numero": 20, "texto": "And Joseph bought all the land of Egypt for Pharaoh; for the Egyptians sold every man his field, because the famine prevailed over them: so the land became Pharaoh''s."}, {"numero": 21, "texto": "And as for the people, he removed them to cities from one end of the borders of Egypt even to the other end thereof."}, {"numero": 22, "texto": "Only the land of the priests bought he not; for the priests had a portion assigned them of Pharaoh, and did eat their portion which Pharaoh gave them: wherefore they sold not their lands."}, {"numero": 23, "texto": "Then Joseph said unto the people, Behold, I have bought you this day and your land for Pharaoh: lo, here is seed for you, and ye shall sow the land."}, {"numero": 24, "texto": "And it shall come to pass in the increase, that ye shall give the fifth part unto Pharaoh, and four parts shall be your own, for seed of the field, and for your food, and for them of your households, and for food for your little ones."}, {"numero": 25, "texto": "And they said, Thou hast saved our lives: let us find grace in the sight of my lord, and we will be Pharaoh''s servants."}, {"numero": 26, "texto": "And Joseph made it a law over the land of Egypt unto this day, that Pharaoh should have the fifth part, except the land of the priests only, which became not Pharaoh''s."}, {"numero": 27, "texto": "And Israel dwelt in the land of Egypt, in the country of Goshen; and they had possessions therein, and grew, and multiplied exceedingly."}, {"numero": 28, "texto": "And Jacob lived in the land of Egypt seventeen years: so the whole age of Jacob was an hundred forty and seven years."}, {"numero": 29, "texto": "And the time drew nigh that Israel must die: and he called his son Joseph, and said unto him, If now I have found grace in thy sight, put, I pray thee, thy hand under my thigh, and deal kindly and truly with me; bury me not, I pray thee, in Egypt:"}, {"numero": 30, "texto": "But I will lie with my fathers, and thou shalt carry me out of Egypt, and bury me in their buryingplace. And he said, I will do as thou hast said."}, {"numero": 31, "texto": "And he said, Swear unto me. And he sware unto him. And Israel bowed himself upon the bed''s head."}]'::jsonb, 'King James Version'),
  ('Gn', 47, 'fr', '[{"numero": 1, "texto": "Joseph alla avertir Pharaon, et lui dit: Mes frères et mon père sont arrivés du pays de Canaan, avec leurs brebis et leurs boeufs, et tout ce qui leur appartient; et les voici dans le pays de Gosen."}, {"numero": 2, "texto": "Il prit cinq de ses frères, et les présenta à Pharaon."}, {"numero": 3, "texto": "Pharaon leur dit: Quelle est votre occupation? Ils répondirent à Pharaon: Tes serviteurs sont bergers, comme l''''étaient nos pères."}, {"numero": 4, "texto": "Ils dirent encore à Pharaon: Nous sommes venus pour séjourner dans le pays, parce qu''''il n''''y a plus de pâturage pour les brebis de tes serviteurs, car la famine s''''appesantit sur le pays de Canaan; permets donc à tes serviteurs d''''habiter au pays de Gosen."}, {"numero": 5, "texto": "Pharaon dit à Joseph: Ton père et tes frères sont venus auprès de toi."}, {"numero": 6, "texto": "Le pays d''''Egypte est devant toi; établis ton père et tes frères dans la meilleure partie du pays. Qu''''ils habitent dans le pays de Gosen; et, si tu trouves parmi eux des hommes capables, mets-les à la tête de mes troupeaux."}, {"numero": 7, "texto": "Joseph fit venir Jacob, son père, et le présenta à Pharaon. Et Jacob bénit Pharaon."}, {"numero": 8, "texto": "Pharaon dit à Jacob: Quel est le nombre de jours des années de ta vie?"}, {"numero": 9, "texto": "Jacob répondit à Pharaon: Les jours des années de mon pèlerinage sont de cent trente ans. Les jours des années de ma vie ont été peu nombreux et mauvais, et ils n''''ont point atteint les jours des années de la vie de mes pères durant leur pèlerinage."}, {"numero": 10, "texto": "Jacob bénit encore Pharaon, et se retira de devant Pharaon."}, {"numero": 11, "texto": "Joseph établit son père et ses frères, et leur donna une propriété dans le pays d''''Egypte, dans la meilleure partie du pays, dans la contrée de Ramsès, comme Pharaon l''''avait ordonné."}, {"numero": 12, "texto": "Joseph fournit du pain à son père et à ses frères, et à toute la famille de son père, selon le nombre des enfants."}, {"numero": 13, "texto": "Il n''''y avait plus de pain dans tout le pays, car la famine était très grande; le pays d''''Egypte et le pays de Canaan languissaient, à cause de la famine."}, {"numero": 14, "texto": "Joseph recueillit tout l''''argent qui se trouvait dans le pays d''''Egypte et dans le pays de Canaan, contre le blé qu''''on achetait; et il fit entrer cet argent dans la maison de Pharaon."}, {"numero": 15, "texto": "Quand l''''argent du pays d''''Egypte et du pays de Canaan fut épuisé, tous les Egyptiens vinrent à Joseph, en disant: Donne-nous du pain! Pourquoi mourrions-nous en ta présence? car l''''argent manque."}, {"numero": 16, "texto": "Joseph dit: Donnez vos troupeaux, et je vous donnerai du pain contre vos troupeaux, si l''''argent manque."}, {"numero": 17, "texto": "Ils amenèrent leurs troupeaux à Joseph, et Joseph leur donna du pain contre les chevaux, contre les troupeaux de brebis et de boeufs, et contre les ânes. Il leur fournit ainsi du pain cette année-là contre tous leurs troupeaux."}, {"numero": 18, "texto": "Lorsque cette année fut écoulée, ils vinrent à Joseph l''''année suivante, et lui dirent: Nous ne cacherons point à mon seigneur que l''''argent est épuisé, et que les troupeaux de bétail ont été amenés à mon seigneur; il ne reste devant mon seigneur que nos corps et nos terres."}, {"numero": 19, "texto": "Pourquoi mourrions-nous sous tes yeux, nous et nos terres? Achète-nous avec nos terres contre du pain, et nous appartiendrons à mon seigneur, nous et nos terres. Donne-nous de quoi semer, afin que nous vivions et que nous ne mourions pas, et que nos terres ne soient pas désolées."}, {"numero": 20, "texto": "Joseph acheta toutes les terres de l''''Egypte pour Pharaon; car les Egyptiens vendirent chacun leur champ, parce que la famine les pressait. Et le pays devint la propriété de Pharaon."}, {"numero": 21, "texto": "Il fit passer le peuple dans les villes, d''''un bout à l''''autre des frontières de l''''Egypte."}, {"numero": 22, "texto": "Seulement, il n''''acheta point les terres des prêtres, parce qu''''il y avait une loi de Pharaon en faveur des prêtres, qui vivaient du revenu que leur assurait Pharaon: c''''est pourquoi ils ne vendirent point leurs terres."}, {"numero": 23, "texto": "Joseph dit au peuple: Je vous ai achetés aujourd''''hui avec vos terres, pour Pharaon; voici pour vous de la semence, et vous pourrez ensemencer le sol."}, {"numero": 24, "texto": "A la récolte, vous donnerez un cinquième à Pharaon, et vous aurez les quatre autres parties, pour ensemencer les champs, et pour vous nourrir avec vos enfants et ceux qui sont dans vos maisons."}, {"numero": 25, "texto": "Ils dirent: Tu nous sauves la vie! que nous trouvions grâce aux yeux de mon seigneur, et nous serons esclaves de Pharaon."}, {"numero": 26, "texto": "Joseph fit de cela une loi, qui a subsisté jusqu''''à ce jour, et d''''après laquelle un cinquième du revenu des terres de l''''Egypte appartient à Pharaon; il n''''y a que les terres des prêtres qui ne soient point à Pharaon."}, {"numero": 27, "texto": "Israël habita dans le pays d''''Egypte, dans le pays de Gosen. Ils eurent des possessions, ils furent féconds et multiplièrent beaucoup."}, {"numero": 28, "texto": "Jacob vécut dix-sept ans dans le pays d''''Egypte; et les jours des années de la vie de Jacob furent de cent quarante-sept ans."}, {"numero": 29, "texto": "Lorsqu''''Israël approcha du moment de sa mort, il appela son fils Joseph, et lui dit: Si j''''ai trouvé grâce à tes yeux, mets, je te prie, ta main sous ma cuisse, et use envers moi de bonté et de fidélité: ne m''''enterre pas en Egypte!"}, {"numero": 30, "texto": "Quand je serai couché avec mes pères, tu me transporteras hors de l''''Egypte, et tu m''''enterreras dans leur sépulcre. Joseph répondit: Je ferai selon ta parole."}, {"numero": 31, "texto": "Jacob dit: Jure-le-moi. Et Joseph le lui jura. Puis Israël se prosterna sur le chevet de son lit."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 47, 'es', '[{"numero": 1, "texto": "Y JOSÉ vino, é hizo saber á Faraón, y dijo: Mi padre y mis hermanos, y sus ovejas y sus vacas, con todo lo que tienen, han venido de la tierra de Canaán, y he aquí, están en la tierra de Gosén."}, {"numero": 2, "texto": "Y de los postreros de sus hermanos tomó cinco varones, y presentólos delante de Faraón."}, {"numero": 3, "texto": "Y Faraón dijo á sus hermanos: ¿Cuál es vuestro oficio? Y ellos respondieron á Faraón: Pastores de ovejas son tus siervos, así nosotros como nuestros padres."}, {"numero": 4, "texto": "Dijeron además á Faraón: Por morar en esta tierra hemos venido; porque no hay pasto para las ovejas de tus siervos, pues el hambre es grave en la tierra de Canaán: por tanto, te rogamos ahora que habiten tus siervos en la tierra de Gosén."}, {"numero": 5, "texto": "Entonces Faraón habló á José, diciendo: Tu padre y tus hermanos han venido á ti;"}, {"numero": 6, "texto": "La tierra de Egipto delante de ti está; en lo mejor de la tierra haz habitar á tu padre y á tus hermanos; habiten en la tierra de Gosén; y si entiendes que hay entre ellos hombres eficaces, ponlos por mayorales del ganado mío."}, {"numero": 7, "texto": "Y José introdujo á su padre, y presentólo delante de Faraón; y Jacob bendijo á Faraón."}, {"numero": 8, "texto": "Y dijo Faraón á Jacob: ¿Cuántos son los días de los años de tu vida?"}, {"numero": 9, "texto": "Y Jacob respondió á Faraón: Los días de los años de mi peregrinación son ciento treinta años; pocos y malos han sido los días de los años de mi vida, y no han llegado á los días de los años de la vida de mis padres en los días de su peregrinación."}, {"numero": 10, "texto": "Y Jacob bendijo á Faraón, y salióse de delante de Faraón."}, {"numero": 11, "texto": "Así José hizo habitar á su padre y á sus hermanos, y dióles posesión en la tierra de Egipto, en lo mejor de la tierra, en la tierra de Rameses como mandó Faraón."}, {"numero": 12, "texto": "Y alimentaba José á su padre y á sus hermanos, y á toda la casa de su padre, de pan, hasta la boca del niño."}, {"numero": 13, "texto": "Y no había pan en toda la tierra, y el hambre era muy grave; por lo que desfalleció de hambre la tierra de Egipto y la tierra de Canaán."}, {"numero": 14, "texto": "Y recogió José todo el dinero que se halló en la tierra de Egipto y en la tierra de Canaán, por los alimentos que de él compraban; y metió José el dinero en casa de Faraón."}, {"numero": 15, "texto": "Y acabado el dinero de la tierra de Egipto y de la tierra de Canaán, vino todo Egipto á José diciendo: Danos pan: ¿por qué moriremos delante de ti, por haberse acabado el dinero?"}, {"numero": 16, "texto": "Y José dijo: Dad vuestros ganados, y yo os daré por vuestros ganados, si se ha acabado el dinero."}, {"numero": 17, "texto": "Y ellos trajeron sus ganados á José; y José les dió alimentos por caballos, y por el ganado de las ovejas, y por el ganado de las vacas, y por asnos: y sustentólos de pan por todos sus ganados aquel año."}, {"numero": 18, "texto": "Y acabado aquel año, vinieron á él el segundo año, y le dijeron: No encubriremos á nuestro señor que el dinero ciertamente se ha acabado; también el ganado es ya de nuestro señor; nada ha quedado delante de nuestro señor sino nuestros cuerpos y nuestra tierra."}, {"numero": 19, "texto": "¿Por qué moriremos delante de tus ojos, así nosotros como nuestra tierra? Cómpranos á nosotros y á nuestra tierra por pan, y seremos nosotros y nuestra tierra siervos de Faraón: y danos simiente para que vivamos y no muramos, y no sea asolada la tierra."}, {"numero": 20, "texto": "Entonces compró José toda la tierra de Egipto para Faraón; pues los Egipcios vendieron cada uno sus tierras, porque se agravó el hambre sobre ellos: y la tierra vino á ser de Faraón."}, {"numero": 21, "texto": "Y al pueblo hízolo pasar á las ciudades desde el un cabo del término de Egipto hasta el otro cabo."}, {"numero": 22, "texto": "Solamente la tierra de los sacerdotes no compró, por cuanto los sacerdotes tenían ración de Faraón, y ellos comían su ración que Faraón les daba: por eso no vendieron su tierra."}, {"numero": 23, "texto": "Y José dijo al pueblo: He aquí os he hoy comprado y á vuestra tierra para Faraón: ved aquí simiente, y sembraréis la tierra."}, {"numero": 24, "texto": "Y será que de los frutos daréis el quinto á Faraón, y las cuatro partes serán vuestras para sembrar las tierras, y para vuestro mantenimiento, y de los que están en vuestras casas, y para que coman vuestros niños."}, {"numero": 25, "texto": "Y ellos respondieron: La vida nos has dado: hallemos gracia en ojos de mi señor, y seamos siervos de Faraón."}, {"numero": 26, "texto": "Entonces José lo puso por fuero hasta hoy sobre la tierra de Egipto, señalando para Faraón el quinto; excepto sólo la tierra de los sacerdotes, que no fué de Faraón."}, {"numero": 27, "texto": "Así habitó Israel en la tierra de Egipto, en la tierra de Gosén; y aposesionáronse en ella, y se aumentaron, y multiplicaron en gran manera."}, {"numero": 28, "texto": "Y vivió Jacob en la tierra de Egipto diecisiete años: y fueron los días de Jacob, los años de su vida, ciento cuarenta y siete años."}, {"numero": 29, "texto": "Y llegáronse los días de Israel para morir, y llamó á José su hijo, y le dijo: Si he hallado ahora gracia en tus ojos, ruégote que pongas tu mano debajo de mi muslo, y harás conmigo misericordia y verdad; ruégote que no me entierres en Egipto;"}, {"numero": 30, "texto": "Mas cuando durmiere con mis padres, llevarme has de Egipto, y me sepultarás en el sepulcro de ellos. Y él respondió: Yo haré como tú dices."}, {"numero": 31, "texto": "Y él dijo: Júramelo. Y él le juró. Entonces Israel se inclinó sobre la cabecera de la cama."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 48, 'pt', '[{"numero": 1, "texto": "E sucedeu depois destas coisas que foi dito a José: Eis que teu pai está enfermo. E ele tomou consigo seus dois filhos Manassés e Efraim."}, {"numero": 2, "texto": "E se fez saber a Jacó, dizendo: Eis que teu filho José vem a ti. Então se esforçou Israel, e sentou-se sobre a cama;"}, {"numero": 3, "texto": "E disse a José: O Deus Todo-Poderoso me apareceu em Luz na terra de Canaã, e me abençoou,"}, {"numero": 4, "texto": "E disse-me: Eis que, eu te farei crescer, e te multiplicarei, e te porei por conjunto de povos: e darei esta terra à tua descendência depois de ti por herança perpétua."}, {"numero": 5, "texto": "E agora teus dois filhos Efraim e Manassés, que te nasceram na terra do Egito, antes que viesse a ti à terra do Egito, meus são; como Rúben e Simeão, serão meus:"}, {"numero": 6, "texto": "E os que depois deles geraste, serão teus; pelo nome de seus irmãos serão chamados em suas propriedades."}, {"numero": 7, "texto": "Porque quando eu vinha de Padã-Arã, se me morreu Raquel na terra de Canaã, no caminho, como certa distância vindo a Efrata; e sepultei-a ali no caminho de Efrata, que é Belém."}, {"numero": 8, "texto": "E viu Israel os filhos de José, e disse: Quem são estes?"}, {"numero": 9, "texto": "E respondeu José a seu pai: São meus filhos, que Deus me deu aqui. E ele disse: Achegai-os agora a mim, e os abençoarei."}, {"numero": 10, "texto": "E os olhos de Israel estavam tão agravados da velhice, que não podia ver. Fez-lhes, pois, chegar a ele, e ele os beijou e abraçou."}, {"numero": 11, "texto": "E disse Israel a José: Não pensava eu ver teu rosto, e eis que Deus me fez ver também tua descendência."}, {"numero": 12, "texto": "Então José os tirou dentre seus joelhos, e inclinou-se à terra."}, {"numero": 13, "texto": "E tomou-os José a ambos, Efraim à sua direita, à esquerda de Israel; e a Manassés à sua esquerda, à direita de Israel; e fez-lhes chegar a ele."}, {"numero": 14, "texto": "Então Israel estendeu sua mão direita, e a pôs sobre a cabeça de Efraim, que era o mais novo, e sua esquerda sobre a cabeça de Manassés, colocando assim suas mãos propositadamente, ainda que Manassés era o primogênito."}, {"numero": 15, "texto": "E abençoou a José, e disse: O Deus em cuja presença andaram meus pais Abraão e Isaque, o Deus que me mantém desde que eu sou até hoje,"}, {"numero": 16, "texto": "O Anjo que me liberta de todo mal abençoe a estes moços: e meu nome seja chamado neles, e o nome de meus pais Abraão e Isaque: e multipliquem em grande maneira em meio da terra."}, {"numero": 17, "texto": "Então vendo José que seu pai punha a direita sobre a cabeça de Efraim, causou-lhe isto desgosto; e pegou a mão de seu pai, para mudá-la de sobre a cabeça de Efraim à cabeça de Manassés."}, {"numero": 18, "texto": "E disse José a seu pai: Não assim, meu pai, porque este é o primogênito; põe tua mão direita sobre sua cabeça."}, {"numero": 19, "texto": "Mas seu pai não quis, e disse: Eu sei, meu filho, eu sei: também ele virá a ser um povo, e será também acrescentado; porém seu irmão mais novo será maior que ele, e sua descendência será plenitude de povos."}, {"numero": 20, "texto": "E abençoou-os aquele dia, dizendo: Em ti Israel abençoará, dizendo: Deus faça de ti Deus como a Efraim e como a Manassés. E pôs a Efraim diante de Manassés."}, {"numero": 21, "texto": "E disse Israel a José: Eis que eu morro, mas Deus será convosco, e vos fará voltar à terra de vossos pais."}, {"numero": 22, "texto": "E eu dei a ti uma parte sobre teus irmãos, a qual tomei eu da mão dos amorreus com minha espada e com meu arco."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 48, 'en', '[{"numero": 1, "texto": "And it came to pass after these things, that one told Joseph, Behold, thy father is sick: and he took with him his two sons, Manasseh and Ephraim."}, {"numero": 2, "texto": "And one told Jacob, and said, Behold, thy son Joseph cometh unto thee: and Israel strengthened himself, and sat upon the bed."}, {"numero": 3, "texto": "And Jacob said unto Joseph, God Almighty appeared unto me at Luz in the land of Canaan, and blessed me,"}, {"numero": 4, "texto": "And said unto me, Behold, I will make thee fruitful, and multiply thee, and I will make of thee a multitude of people; and will give this land to thy seed after thee for an everlasting possession."}, {"numero": 5, "texto": "And now thy two sons, Ephraim and Manasseh, which were born unto thee in the land of Egypt before I came unto thee into Egypt, are mine; as Reuben and Simeon, they shall be mine."}, {"numero": 6, "texto": "And thy issue, which thou begettest after them, shall be thine, and shall be called after the name of their brethren in their inheritance."}, {"numero": 7, "texto": "And as for me, when I came from Padan, Rachel died by me in the land of Canaan in the way, when yet there was but a little way to come unto Ephrath: and I buried her there in the way of Ephrath; the same is Bethlehem."}, {"numero": 8, "texto": "And Israel beheld Joseph''s sons, and said, Who are these?"}, {"numero": 9, "texto": "And Joseph said unto his father, They are my sons, whom God hath given me in this place. And he said, Bring them, I pray thee, unto me, and I will bless them."}, {"numero": 10, "texto": "Now the eyes of Israel were dim for age, so that he could not see. And he brought them near unto him; and he kissed them, and embraced them."}, {"numero": 11, "texto": "And Israel said unto Joseph, I had not thought to see thy face: and, lo, God hath shewed me also thy seed."}, {"numero": 12, "texto": "And Joseph brought them out from between his knees, and he bowed himself with his face to the earth."}, {"numero": 13, "texto": "And Joseph took them both, Ephraim in his right hand toward Israel''s left hand, and Manasseh in his left hand toward Israel''s right hand, and brought them near unto him."}, {"numero": 14, "texto": "And Israel stretched out his right hand, and laid it upon Ephraim''s head, who was the younger, and his left hand upon Manasseh''s head, guiding his hands wittingly; for Manasseh was the firstborn."}, {"numero": 15, "texto": "And he blessed Joseph, and said, God, before whom my fathers Abraham and Isaac did walk, the God which fed me all my life long unto this day,"}, {"numero": 16, "texto": "The Angel which redeemed me from all evil, bless the lads; and let my name be named on them, and the name of my fathers Abraham and Isaac; and let them grow into a multitude in the midst of the earth."}, {"numero": 17, "texto": "And when Joseph saw that his father laid his right hand upon the head of Ephraim, it displeased him: and he held up his father''s hand, to remove it from Ephraim''s head unto Manasseh''s head."}, {"numero": 18, "texto": "And Joseph said unto his father, Not so, my father: for this is the firstborn; put thy right hand upon his head."}, {"numero": 19, "texto": "And his father refused, and said, I know it, my son, I know it: he also shall become a people, and he also shall be great: but truly his younger brother shall be greater than he, and his seed shall become a multitude of nations."}, {"numero": 20, "texto": "And he blessed them that day, saying, In thee shall Israel bless, saying, God make thee as Ephraim and as Manasseh: and he set Ephraim before Manasseh."}, {"numero": 21, "texto": "And Israel said unto Joseph, Behold, I die: but God shall be with you, and bring you again unto the land of your fathers."}, {"numero": 22, "texto": "Moreover I have given to thee one portion above thy brethren, which I took out of the hand of the Amorite with my sword and with my bow."}]'::jsonb, 'King James Version'),
  ('Gn', 48, 'fr', '[{"numero": 1, "texto": "Après ces choses, l''''on vint dire à Joseph: Voici, ton père est malade. Et il prit avec lui ses deux fils, Manassé et Ephraïm."}, {"numero": 2, "texto": "On avertit Jacob, et on lui dit: Voici ton fils Joseph qui vient vers toi. Et Israël rassembla ses forces, et s''''assit sur son lit."}, {"numero": 3, "texto": "Jacob dit à Joseph: Le Dieu tout-puissant m''''est apparu à Luz, dans le pays de Canaan, et il m''''a béni."}, {"numero": 4, "texto": "Il m''''a dit: Je te rendrai fécond, je te multiplierai, et je ferai de toi une multitude de peuples; je donnerai ce pays à ta postérité après toi, pour qu''''elle le possède à toujours."}, {"numero": 5, "texto": "Maintenant, les deux fils qui te sont nés au pays d''''Egypte, avant mon arrivée vers toi en Egypte, seront à moi; Ephraïm et Manassé seront à moi, comme Ruben et Siméon."}, {"numero": 6, "texto": "Mais les enfants que tu as engendrés après eux seront à toi; ils seront appelés du nom de leurs frères dans leur héritage."}, {"numero": 7, "texto": "A mon retour de Paddan, Rachel mourut en route auprès de moi, dans le pays de Canaan, à quelque distance d''''Ephrata; et c''''est là que je l''''ai enterrée, sur le chemin d''''Ephrata, qui est Bethléhem."}, {"numero": 8, "texto": "Israël regarda les fils de Joseph, et dit: Qui sont ceux-ci?"}, {"numero": 9, "texto": "Joseph répondit à son père: Ce sont mes fils, que Dieu m''''a donnés ici. Israël dit: Fais-les, je te prie, approcher de moi, pour que je les bénisse."}, {"numero": 10, "texto": "Les yeux d''''Israël étaient appesantis par la vieillesse; il ne pouvait plus voir. Joseph les fit approcher de lui; et Israël leur donna un baiser, et les embrassa."}, {"numero": 11, "texto": "Israël dit à Joseph: Je ne pensais pas revoir ton visage, et voici que Dieu me fait voir même ta postérité."}, {"numero": 12, "texto": "Joseph les retira des genoux de son père, et il se prosterna en terre devant lui."}, {"numero": 13, "texto": "Puis Joseph les prit tous deux, Ephraïm de sa main droite à la gauche d''''Israël, et Manassé de sa main gauche à la droite d''''Israël, et il les fit approcher de lui."}, {"numero": 14, "texto": "Israël étendit sa main droite et la posa sur la tête d''''Ephraïm qui était le plus jeune, et il posa sa main gauche sur la tête de Manassé: ce fut avec intention qu''''il posa ses mains ainsi, car Manassé était le premier-né."}, {"numero": 15, "texto": "Il bénit Joseph, et dit: Que le Dieu en présence duquel ont marché mes pères, Abraham et Isaac, que le Dieu qui m''''a conduit depuis que j''''existe jusqu''''à ce jour,"}, {"numero": 16, "texto": "que l''''ange qui m''''a délivré de tout mal, bénisse ces enfants! Qu''''ils soient appelés de mon nom et du nom de mes pères, Abraham et Isaac, et qu''''ils multiplient en abondance au milieu du pays!"}, {"numero": 17, "texto": "Joseph vit avec déplaisir que son père posait sa main droite sur la tête d''''Ephraïm; il saisit la main de son père, pour la détourner de dessus la tête d''''Ephraïm, et la diriger sur celle de Manassé."}, {"numero": 18, "texto": "Et Joseph dit à son père: Pas ainsi, mon père, car celui-ci est le premier-né; pose ta main droite sur sa tête."}, {"numero": 19, "texto": "Son père refusa, et dit: Je le sais, mon fils, je le sais; lui aussi deviendra un peuple, lui aussi sera grand; mais son frère cadet sera plus grand que lui, et sa postérité deviendra une multitude de nations."}, {"numero": 20, "texto": "Il les bénit ce jour-là, et dit: C''''est par toi qu''''Israël bénira, en disant: Que Dieu te traite comme Ephraïm et comme Manassé! Et il mit Ephraïm avant Manassé."}, {"numero": 21, "texto": "Israël dit à Joseph: Voici, je vais mourir! Mais Dieu sera avec vous, et il vous fera retourner dans le pays de vos pères."}, {"numero": 22, "texto": "Je te donne, de plus qu''''à tes frères, une part que j''''ai prise de la main des Amoréens avec mon épée et avec mon arc."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 48, 'es', '[{"numero": 1, "texto": "Y SUCEDIÓ después de estas cosas el haberse dicho á José: He aquí tu padre está enfermo. Y él tomó consigo sus dos hijos Manasés y Ephraim."}, {"numero": 2, "texto": "Y se hizo saber á Jacob, diciendo: He aquí tu hijo José viene á ti. Entonces se esforzó Israel, y sentóse sobre la cama;"}, {"numero": 3, "texto": "Y dijo á José: El Dios Omnipotente me apareció en Luz en la tierra de Canaán, y me bendijo,"}, {"numero": 4, "texto": "Y díjome: He aquí, yo te haré crecer, y te multiplicaré, y te pondré por estirpe de pueblos: y daré esta tierra á tu simiente después de ti por heredad perpetua."}, {"numero": 5, "texto": "Y ahora tus dos hijos Ephraim y Manasés, que te nacieron en la tierra de Egipto, antes que viniese á ti á la tierra de Egipto, míos son; como Rubén y Simeón, serán míos:"}, {"numero": 6, "texto": "Y los que después de ellos has engendrado, serán tuyos; por el nombre de sus hermanos serán llamados en sus heredades."}, {"numero": 7, "texto": "Porque cuando yo venía de Padan-aram, se me murió Rachêl en la tierra de Canaán, en el camino, como media legua de tierra viniendo á Ephrata; y sepultéla allí en el camino de Ephrata, que es Bethlehem."}, {"numero": 8, "texto": "Y vió Israel los hijos de José, y dijo: ¿Quiénes son éstos?"}, {"numero": 9, "texto": "Y respondió José á su padre: Son mis hijos, que Dios me ha dado aquí. Y él dijo: Allégalos ahora á mí, y los bendeciré."}, {"numero": 10, "texto": "Y los ojos de Israel estaban tan agravados de la vejez, que no podía ver. Hízoles, pues, llegar á él, y él los besó y abrazó."}, {"numero": 11, "texto": "Y dijo Israel á José: No pensaba yo ver tu rostro, y he aquí Dios me ha hecho ver también tu simiente."}, {"numero": 12, "texto": "Entonces José los sacó de entre sus rodillas, é inclinóse á tierra."}, {"numero": 13, "texto": "Y tomólos José á ambos, Ephraim á su diestra, á la siniestra de Israel; y á Manasés á su izquierda, á la derecha de Israel; é hízoles llegar á él."}, {"numero": 14, "texto": "Entonces Israel extendió su diestra, y púsola sobre la cabeza de Ephraim, que era el menor, y su siniestra sobre la cabeza de Manasés, colocando así sus manos adrede, aunque Manasés era el primogénito."}, {"numero": 15, "texto": "Y bendijo á José, y dijo: El Dios en cuya presencia anduvieron mis padres Abraham é Isaac, el Dios que me mantiene desde que yo soy hasta este día,"}, {"numero": 16, "texto": "El Angel que me liberta de todo mal, bendiga á estos mozos: y mi nombre sea llamado en ellos, y el nombre de mis padres Abraham é Isaac: y multipliquen en gran manera en medio de la tierra."}, {"numero": 17, "texto": "Entonces viendo José que su padre ponía la mano derecha sobre la cabeza de Ephraim, causóle esto disgusto; y asió la mano de su padre, para mudarla de sobre la cabeza de Ephraim á la cabeza de Manasés."}, {"numero": 18, "texto": "Y dijo José á su padre: No así, padre mío, porque éste es el primogénito; pon tu diestra sobre su cabeza."}, {"numero": 19, "texto": "Mas su padre no quiso, y dijo: Lo sé, hijo mío, lo sé: también él vendrá á ser un pueblo, y será también acrecentado; pero su hermano menor será más grande que él, y su simiente será plenitud de gentes."}, {"numero": 20, "texto": "Y bendíjolos aquel día, diciendo: En ti bendecirá Israel, diciendo: Póngate Dios como á Ephraim y como á Manasés. Y puso á Ephraim delante de Manasés."}, {"numero": 21, "texto": "Y dijo Israel á José: He aquí, yo muero, mas Dios será con vosotros, y os hará volver á la tierra de vuestros padres."}, {"numero": 22, "texto": "Y yo te he dado á ti una parte sobre tus hermanos, la cual tomé yo de mano del Amorrheo con mi espada y con mi arco."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 49, 'pt', '[{"numero": 1, "texto": "E chamou Jacó a seus filhos, e disse: Juntai-vos, e vos declararei o que vos há de acontecer nos últimos dias."}, {"numero": 2, "texto": "Juntai-vos e ouvi, filhos de Jacó; E escutai a vosso pai Israel."}, {"numero": 3, "texto": "Rúben, tu és meu primogênito, minha força, e o princípio do meu vigor; Principal em dignidade, principal em poder."}, {"numero": 4, "texto": "Corrente como as águas, não sejas o principal; Porquanto subiste ao leito de teu pai: Então te contaminaste, subindo a meu estrado."}, {"numero": 5, "texto": "Simeão e Levi, irmãos: Armas de violência são suas armas."}, {"numero": 6, "texto": "Em seu secreto não entre minha alma, nem minha honra se junte em sua companhia; Que em seu furor mataram homem, E em sua vontade aleijaram bois."}, {"numero": 7, "texto": "Maldito seu furor, que foi bravio; E sua ira, que foi dura: Eu os dividirei em Jacó, E os espalharei em Israel."}, {"numero": 8, "texto": "Judá, teus irmãos te louvarão: Tua mão esterá sobre o pescoço de teus inimigos: Os filhos de teu pai se inclinarão a ti."}, {"numero": 9, "texto": "Jovem leão é Judá: Da presa subiste, filho meu: Encurvou-se, lançou-se como leão, Assim como leão velho; quem o despertará?"}, {"numero": 10, "texto": "Não será tirado o cetro de Judá, E o legislador dentre seus pés, Até que venha Siló; E a ele se congregarão os povos."}, {"numero": 11, "texto": "Atando à vide seu jumentinho, E à videira o filho de sua jumenta, Lavou no veio sua roupa, E no sangue de uvas seu manto:"}, {"numero": 12, "texto": "Seus olhos mais vermelhos que o vinho, E os dentes mais brancos que o leite."}, {"numero": 13, "texto": "Zebulom em portos de mar habitará, E será para porto de navios; E seu termo até Sidom."}, {"numero": 14, "texto": "Issacar, asno de forte estrutura deitado entre dois apriscos:"}, {"numero": 15, "texto": "E viu que o descanso era bom, E que a terra era deleitosa; E baixou seu ombro para levar, E serviu em tributo."}, {"numero": 16, "texto": "Dã julgará a seu povo, Como uma das tribos de Israel."}, {"numero": 17, "texto": "Será Dã serpente junto ao caminho, víbora junto à vereda, que morde os calcanhares dos cavalos, e faz cair por detrás ao cavaleiro deles."}, {"numero": 18, "texto": "Tua salvação espero, ó SENHOR."}, {"numero": 19, "texto": "Gade, exército o atacará; mas ele contra-atacará ao fim."}, {"numero": 20, "texto": "O pão de Aser será espesso, E ele dará deleites ao rei."}, {"numero": 21, "texto": "Naftali, serva solta, que diz belas coisas."}, {"numero": 22, "texto": "Ramo frutífero é José, ramo frutífero é junto à fonte, cujos ramos se estendem sobre o muro;"}, {"numero": 23, "texto": "E causaram-lhe amargura, e flecharam-lhe, e os arqueiros o odiaram;"}, {"numero": 24, "texto": "Mas seu arco manteve-se forte, E os braços de suas mãos se fortaleceram pelas mãos do Forte de Jacó, (Dali é o Pastor, e a Pedra de Israel,)"}, {"numero": 25, "texto": "Do Deus de teu pai, o qual te ajudará, E do Todo-Poderoso, o qual te abençoará com bênçãos dos céus de acima, com bênçãos do abismo que está abaixo, Com bênçãos do seio e da madre."}, {"numero": 26, "texto": "As bênçãos de teu pai Foram maiores que as bênçãos de meus progenitores: Até o termo das colinas eternas serão sobre a cabeça de José, E sobre o topo da cabeça do que foi separado de seus irmãos."}, {"numero": 27, "texto": "Benjamim, lobo arrebatador; de manhã comerá a presa, e à tarde repartirá os despojos."}, {"numero": 28, "texto": "Todos estes foram as doze tribos de Israel: e isto foi o que seu pai lhes disse, e os abençoou; a cada um por sua bênção os abençoou."}, {"numero": 29, "texto": "Mandou-lhes logo, e disse-lhes: Eu vou a ser reunido com meu povo: sepultai-me com meus pais na caverna que está no campo de Efrom os heteus;"}, {"numero": 30, "texto": "Na caverna que está no campo de Macpela, que está diante de Manre na terra de Canaã, a qual comprou Abraão com o mesmo campo de Efrom os heteus, para herança de sepultura."}, {"numero": 31, "texto": "Ali sepultaram a Abraão e a Sara sua mulher; ali sepultaram a Isaque e a Rebeca sua mulher; ali também sepultei Lia."}, {"numero": 32, "texto": "O campo e a cova que nele está foram comprados dos filhos de Hete."}, {"numero": 33, "texto": "E quando acabou Jacó de dar ordens a seus filhos, encolheu seus pés na cama, e expirou; e foi reunido com seus pais."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 49, 'en', '[{"numero": 1, "texto": "And Jacob called unto his sons, and said, Gather yourselves together, that I may tell you that which shall befall you in the last days."}, {"numero": 2, "texto": "Gather yourselves together, and hear, ye sons of Jacob; and hearken unto Israel your father."}, {"numero": 3, "texto": "Reuben, thou art my firstborn, my might, and the beginning of my strength, the excellency of dignity, and the excellency of power:"}, {"numero": 4, "texto": "Unstable as water, thou shalt not excel; because thou wentest up to thy father''s bed; then defiledst thou it: he went up to my couch."}, {"numero": 5, "texto": "Simeon and Levi are brethren; instruments of cruelty are in their habitations."}, {"numero": 6, "texto": "O my soul, come not thou into their secret; unto their assembly, mine honour, be not thou united: for in their anger they slew a man, and in their selfwill they digged down a wall."}, {"numero": 7, "texto": "Cursed be their anger, for it was fierce; and their wrath, for it was cruel: I will divide them in Jacob, and scatter them in Israel."}, {"numero": 8, "texto": "Judah, thou art he whom thy brethren shall praise: thy hand shall be in the neck of thine enemies; thy father''s children shall bow down before thee."}, {"numero": 9, "texto": "Judah is a lion''s whelp: from the prey, my son, thou art gone up: he stooped down, he couched as a lion, and as an old lion; who shall rouse him up?"}, {"numero": 10, "texto": "The sceptre shall not depart from Judah, nor a lawgiver from between his feet, until Shiloh come; and unto him shall the gathering of the people be."}, {"numero": 11, "texto": "Binding his foal unto the vine, and his ass''s colt unto the choice vine; he washed his garments in wine, and his clothes in the blood of grapes:"}, {"numero": 12, "texto": "His eyes shall be red with wine, and his teeth white with milk."}, {"numero": 13, "texto": "Zebulun shall dwell at the haven of the sea; and he shall be for an haven of ships; and his border shall be unto Zidon."}, {"numero": 14, "texto": "Issachar is a strong ass couching down between two burdens:"}, {"numero": 15, "texto": "And he saw that rest was good, and the land that it was pleasant; and bowed his shoulder to bear, and became a servant unto tribute."}, {"numero": 16, "texto": "Dan shall judge his people, as one of the tribes of Israel."}, {"numero": 17, "texto": "Dan shall be a serpent by the way, an adder in the path, that biteth the horse heels, so that his rider shall fall backward."}, {"numero": 18, "texto": "I have waited for thy salvation, O Lord."}, {"numero": 19, "texto": "Gad, a troop shall overcome him: but he shall overcome at the last."}, {"numero": 20, "texto": "Out of Asher his bread shall be fat, and he shall yield royal dainties."}, {"numero": 21, "texto": "Naphtali is a hind let loose: he giveth goodly words."}, {"numero": 22, "texto": "Joseph is a fruitful bough, even a fruitful bough by a well; whose branches run over the wall:"}, {"numero": 23, "texto": "The archers have sorely grieved him, and shot at him, and hated him:"}, {"numero": 24, "texto": "But his bow abode in strength, and the arms of his hands were made strong by the hands of the mighty God of Jacob; (from thence is the shepherd, the stone of Israel:)"}, {"numero": 25, "texto": "Even by the God of thy father, who shall help thee; and by the Almighty, who shall bless thee with blessings of heaven above, blessings of the deep that lieth under, blessings of the breasts, and of the womb:"}, {"numero": 26, "texto": "The blessings of thy father have prevailed above the blessings of my progenitors unto the utmost bound of the everlasting hills: they shall be on the head of Joseph, and on the crown of the head of him that was separate from his brethren."}, {"numero": 27, "texto": "Benjamin shall ravin as a wolf: in the morning he shall devour the prey, and at night he shall divide the spoil."}, {"numero": 28, "texto": "All these are the twelve tribes of Israel: and this is it that their father spake unto them, and blessed them; every one according to his blessing he blessed them."}, {"numero": 29, "texto": "And he charged them, and said unto them, I am to be gathered unto my people: bury me with my fathers in the cave that is in the field of Ephron the Hittite,"}, {"numero": 30, "texto": "In the cave that is in the field of Machpelah, which is before Mamre, in the land of Canaan, which Abraham bought with the field of Ephron the Hittite for a possession of a buryingplace."}, {"numero": 31, "texto": "There they buried Abraham and Sarah his wife; there they buried Isaac and Rebekah his wife; and there I buried Leah."}, {"numero": 32, "texto": "The purchase of the field and of the cave that is therein was from the children of Heth."}, {"numero": 33, "texto": "And when Jacob had made an end of commanding his sons, he gathered up his feet into the bed, and yielded up the ghost, and was gathered unto his people."}]'::jsonb, 'King James Version'),
  ('Gn', 49, 'fr', '[{"numero": 1, "texto": "Jacob appela ses fils, et dit: Assemblez-vous, et je vous annoncerai ce qui vous arrivera dans la suite des temps."}, {"numero": 2, "texto": "Rassemblez-vous, et écoutez, fils de Jacob! Ecoutez Israël, votre père!"}, {"numero": 3, "texto": "Ruben, toi, mon premier-né, Ma force et les prémices de ma vigueur, Supérieur en dignité et supérieur en puissance,"}, {"numero": 4, "texto": "Impétueux comme les eaux, tu n''''auras pas la prééminence! Car tu es monté sur la couche de ton père, Tu as souillé ma couche en y montant."}, {"numero": 5, "texto": "Siméon et Lévi sont frères; Leurs glaives sont des instruments de violence."}, {"numero": 6, "texto": "Que mon âme n''''entre point dans leur conciliabule, Que mon esprit ne s''''unisse point à leur assemblée! Car, dans leur colère, ils ont tué des hommes, Et, dans leur méchanceté, ils ont coupé les jarrets des taureaux."}, {"numero": 7, "texto": "Maudite soit leur colère, car elle est violente, Et leur fureur, car elle est cruelle! Je les séparerai dans Jacob, Et je les disperserai dans Israël."}, {"numero": 8, "texto": "Juda, tu recevras les hommages de tes frères; Ta main sera sur la nuque de tes ennemis. Les fils de ton père se prosterneront devant toi."}, {"numero": 9, "texto": "Juda est un jeune lion. Tu reviens du carnage, mon fils! Il ploie les genoux, il se couche comme un lion, Comme une lionne: qui le fera lever?"}, {"numero": 10, "texto": "Le sceptre ne s''''éloignera point de Juda, Ni le bâton souverain d''''entre ses pieds, Jusqu''''à ce que vienne le Schilo, Et que les peuples lui obéissent."}, {"numero": 11, "texto": "Il attache à la vigne son âne, Et au meilleur cep le petit de son ânesse; Il lave dans le vin son vêtement, Et dans le sang des raisins son manteau."}, {"numero": 12, "texto": "Il a les yeux rouges de vin, Et les dents blanches de lait."}, {"numero": 13, "texto": "Zabulon habitera sur la côte des mers, Il sera sur la côte des navires, Et sa limite s''''étendra du côté de Sidon."}, {"numero": 14, "texto": "Issacar est un âne robuste, Qui se couche dans les étables."}, {"numero": 15, "texto": "Il voit que le lieu où il repose est agréable, Et que la contrée est magnifique; Et il courbe son épaule sous le fardeau, Il s''''assujettit à un tribut."}, {"numero": 16, "texto": "Dan jugera son peuple, Comme l''''une des tribus d''''Israël."}, {"numero": 17, "texto": "Dan sera un serpent sur le chemin, Une vipère sur le sentier, Mordant les talons du cheval, Pour que le cavalier tombe à la renverse."}, {"numero": 18, "texto": "J''''espère en ton secours, ô Eternel!"}, {"numero": 19, "texto": "Gad sera assailli par des bandes armées, Mais il les assaillira et les poursuivra."}, {"numero": 20, "texto": "Aser produit une nourriture excellente; Il fournira les mets délicats des rois."}, {"numero": 21, "texto": "Nephthali est une biche en liberté; Il profère de belles paroles."}, {"numero": 22, "texto": "Joseph est le rejeton d''''un arbre fertile, Le rejeton d''''un arbre fertile près d''''une source; Les branches s''''élèvent au-dessus de la muraille."}, {"numero": 23, "texto": "Ils l''''ont provoqué, ils ont lancé des traits; Les archers l''''ont poursuivi de leur haine."}, {"numero": 24, "texto": "Mais son arc est demeuré ferme, Et ses mains ont été fortifiées Par les mains du Puissant de Jacob: Il est ainsi devenu le berger, le rocher d''''Israël."}, {"numero": 25, "texto": "C''''est l''''oeuvre du Dieu de ton père, qui t''''aidera; C''''est l''''oeuvre du Tout-Puissant, qui te bénira Des bénédictions des cieux en haut, Des bénédictions des eaux en bas, Des bénédictions des mamelles et du sein maternel."}, {"numero": 26, "texto": "Les bénédictions de ton père s''''élèvent Au-dessus des bénédictions de mes pères Jusqu''''à la cime des collines éternelles: Qu''''elles soient sur la tête de Joseph, Sur le sommet de la tête du prince de ses frères!"}, {"numero": 27, "texto": "Benjamin est un loup qui déchire; Le matin, il dévore la proie, Et le soir, il partage le butin."}, {"numero": 28, "texto": "Ce sont là tous ceux qui forment les douze tribus d''''Israël. Et c''''est là ce que leur dit leur père, en les bénissant. Il les bénit, chacun selon sa bénédiction."}, {"numero": 29, "texto": "Puis il leur donna cet ordre: Je vais être recueilli auprès de mon peuple; enterrez-moi avec mes pères, dans la caverne qui est au champ d''''Ephron, le Héthien,"}, {"numero": 30, "texto": "dans la caverne du champ de Macpéla, vis-à-vis de Mamré, dans le pays de Canaan. C''''est le champ qu''''Abraham a acheté d''''Ephron, le Héthien, comme propriété sépulcrale."}, {"numero": 31, "texto": "Là on a enterré Abraham et Sara, sa femme; là on a enterré Isaac et Rebecca, sa femme; et là j''''ai enterré Léa."}, {"numero": 32, "texto": "Le champ et la caverne qui s''''y trouve ont été achetés des fils de Heth."}, {"numero": 33, "texto": "Lorsque Jacob eut achevé de donner ses ordres à ses fils, il retira ses pieds dans le lit, il expira, et fut recueilli auprès de son peuple."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 49, 'es', '[{"numero": 1, "texto": "Y LLAMÓ Jacob á sus hijos, y dijo: Juntaos, y os declararé lo que os ha de acontecer en los postreros días."}, {"numero": 2, "texto": "Juntaos y oid, hijos de Jacob; y escuchad á vuestro padre Israel."}, {"numero": 3, "texto": "Rubén, tú eres mi primogénito, mi fortaleza, y el principio de mi vigor; principal en dignidad, principal en poder."}, {"numero": 4, "texto": "Corriente como las aguas, no seas el principal; por cuanto subiste al lecho de tu padre: entonces te envileciste, subiendo á mi estrado."}, {"numero": 5, "texto": "Simeón y Leví, hermanos: armas de iniquidad sus armas."}, {"numero": 6, "texto": "En su secreto no entre mi alma, ni mi honra se junte en su compañía; que en su furor mataron varón, y en su voluntad arrancaron muro."}, {"numero": 7, "texto": "Maldito su furor, que fué fiero; y su ira, que fué dura: yo los apartaré en Jacob, y los esparciré en Israel."}, {"numero": 8, "texto": "Judá, alabarte han tus hermanos: tu mano en la cerviz de tus enemigos: los hijos de tu padre se inclinarán á ti."}, {"numero": 9, "texto": "Cachorro de león Judá: de la presa subiste, hijo mío: encorvóse, echóse como león, así como león viejo; ¿quién lo despertará?"}, {"numero": 10, "texto": "No será quitado el cetro de Judá, y el legislador de entre sus piés, hasta que venga Shiloh; y á él se congregarán los pueblos."}, {"numero": 11, "texto": "Atando á la vid su pollino, y á la cepa el hijo de su asna, lavó en el vino su vestido, y en la sangre de uvas su manto:"}, {"numero": 12, "texto": "Sus ojos bermejos del vino, y los dientes blancos de la leche."}, {"numero": 13, "texto": "Zabulón en puertos de mar habitará, y será para puerto de navíos; y su término hasta Sidón."}, {"numero": 14, "texto": "Issachâr, asno huesudo echado entre dos tercios:"}, {"numero": 15, "texto": "Y vió que el descanso era bueno, y que la tierra era deleitosa; y bajó su hombro para llevar, y sirvió en tributo."}, {"numero": 16, "texto": "Dan juzgará á su pueblo, como una de las tribus de Israel."}, {"numero": 17, "texto": "Será Dan serpiente junto al camino, cerasta junto á la senda, que muerde los talones de los caballos, y hace caer por detrás al cabalgador de ellos."}, {"numero": 18, "texto": "Tu salud esperé, oh Jehová."}, {"numero": 19, "texto": "Gad, ejército lo acometerá; mas él acometerá al fin."}, {"numero": 20, "texto": "El pan de Aser será grueso, y él dará deleites al rey."}, {"numero": 21, "texto": "Nephtalí, sierva dejada, que dará dichos hermosos."}, {"numero": 22, "texto": "Ramo fructífero José, ramo fructífero junto á fuente, cuyos vástagos se extienden sobre el muro."}, {"numero": 23, "texto": "Y causáronle amargura, y asaeteáronle, y aborreciéronle los archeros:"}, {"numero": 24, "texto": "Mas su arco quedó en fortaleza, y los brazos de sus manos se corroboraron por las manos del Fuerte de Jacob, (de allí el pastor, y la piedra de Israel,)"}, {"numero": 25, "texto": "Del Dios de tu padre, el cual te ayudará, y del Omnipotente, el cual te bendecirá con bendiciones de los cielos de arriba, con bendiciones del abismo que está abajo, con bendiciones del seno y de la matriz."}, {"numero": 26, "texto": "Las bendiciones de tu padre fueron mayores que las bendiciones de mis progenitores: hasta el término de los collados eternos serán sobre la cabeza de José, y sobre la mollera del Nazareo de sus hermanos."}, {"numero": 27, "texto": "Benjamín, lobo arrebatador: á la mañana comerá la presa, y á la tarde repartirá los despojos."}, {"numero": 28, "texto": "Todos estos fueron las doce tribus de Israel: y esto fué lo que su padre les dijo, y bendíjolos; á cada uno por su bendición los bendijo."}, {"numero": 29, "texto": "Mandóles luego, y díjoles: Yo voy á ser reunido con mi pueblo: sepultadme con mis padres en la cueva que está en el campo de Ephrón el Hetheo;"}, {"numero": 30, "texto": "En la cueva que está en el campo de Macpela, que está delante de Mamre en la tierra de Canaán, la cual compró Abraham con el mismo campo de Ephrón el Hetheo, para heredad de sepultura."}, {"numero": 31, "texto": "Allí sepultaron á Abraham y á Sara su mujer; allí sepultaron á Isaac y á Rebeca su mujer; allí también sepulté yo á Lea."}, {"numero": 32, "texto": "La compra del campo y de la cueva que está en él, fué de los hijos de Heth."}, {"numero": 33, "texto": "Y como acabó Jacob de dar órdenes á sus hijos, encogió sus pies en la cama, y espiró: y fué reunido con sus padres."}]'::jsonb, 'Reina-Valera 1909'),
  ('Gn', 50, 'pt', '[{"numero": 1, "texto": "Então se lançou José sobre o rosto de seu pai, e chorou sobre ele, e o beijou."}, {"numero": 2, "texto": "E mandou José a seus servos médicos que embalsamassem a seu pai; e os médicos embalsamaram a Israel."}, {"numero": 3, "texto": "E cumpriam-lhe quarenta dias, porque assim cumpriam os dias dos embalsamados, e choraram-no os egípcios setenta dias."}, {"numero": 4, "texto": "E passados os dias de seu luto, falou José aos da casa de Faraó, dizendo: Se achei agora favor em vossos olhos, vos rogo que faleis aos ouvidos de Faraó, dizendo:"}, {"numero": 5, "texto": "Meu pai me fez jurar dizendo: Eis que eu morro; em meu sepulcro que eu cavei para mim na terra de Canaã, ali me sepultarás; rogo, pois, que vá eu agora, e sepultarei a meu pai, e voltarei."}, {"numero": 6, "texto": "E Faraó disse: Vai, e sepulta a teu pai, como ele te fez jurar."}, {"numero": 7, "texto": "Então José subiu a sepultar a seu pai; e subiram com ele todos os servos de Faraó, os anciãos de sua casa, e todos os anciãos da terra do Egito."}, {"numero": 8, "texto": "E toda a casa de José, e seus irmãos, e a casa de seu pai: somente deixaram na terra de Gósen seus filhos, e suas ovelhas e suas vacas."}, {"numero": 9, "texto": "E subiram também com ele carros e cavaleiros, e fez-se um esquadrão muito grande."}, {"numero": 10, "texto": "E chegaram até a eira de Atade, que está à outra parte do Jordão, e lamentaram ali com grande e muito grave lamentação: e José fez a seu pai luto por sete dias."}, {"numero": 11, "texto": "E vendo os moradores da terra, os cananeus, o pranto na eira de Atade, disseram: Pranto grande é este dos egípcios: por isso foi chamado seu nome Abel-Mizraim, que está à outra parte do Jordão."}, {"numero": 12, "texto": "Fizeram, pois, seus filhos com ele, segundo lhes havia mandado:"}, {"numero": 13, "texto": "Pois seus filhos o levaram à terra de Canaã, e o sepultaram na caverna do campo de Macpela, a que havia comprado Abraão com o mesmo campo, para herança de sepultura, de Efrom o heteu, diante de Manre."}, {"numero": 14, "texto": "E voltou José ao Egito, ele e seus irmãos, e todos os que subiram com ele a sepultar a seu pai, depois que o sepultou."}, {"numero": 15, "texto": "E vendo os irmãos de José que seu pai era morto, disseram: Talvez José nos odeie, e nos retribua de todo o mal que lhe fizemos."}, {"numero": 16, "texto": "E enviaram a dizer a José: Teu pai mandou antes de sua morte, dizendo:"}, {"numero": 17, "texto": "Assim direis a José: Rogo-te que perdoes agora a maldade de teus irmãos e seu pecado, porque mal te trataram: portanto agora te rogamos que perdoes a maldade dos servos do Deus de teu pai. E José chorou enquanto falavam."}, {"numero": 18, "texto": "E vieram também seus irmãos, e prostraram-se diante dele, e disseram: Eis-nos aqui por teus servos."}, {"numero": 19, "texto": "E respondeu-lhes José: Não temais: estou eu em lugar de Deus?"}, {"numero": 20, "texto": "Vós pensastes mal sobre mim, mas Deus o encaminhou para o bem, para fazer o que vemos hoje, para manter em vida muito povo."}, {"numero": 21, "texto": "Agora, pois, não tenhais medo; eu sustentarei a vós e a vossos filhos. Assim os consolou, e lhes falou ao coração."}, {"numero": 22, "texto": "E esteve José no Egito, ele e a casa de seu pai; e viveu José cento dez anos."}, {"numero": 23, "texto": "E viu José os filhos de Efraim até a terceira geração: também os filhos de Maquir, filho de Manassés, foram criados sobre os joelhos de José."}, {"numero": 24, "texto": "E José disse a seus irmãos: Eu me morro; mas Deus certamente vos visitará, e vos fará subir desta terra à terra que jurou a Abraão, a Isaque, e a Jacó."}, {"numero": 25, "texto": "E fez jurar José aos filhos de Israel, dizendo: Deus certamente vos visitará, e fareis levar daqui meus ossos."}, {"numero": 26, "texto": "E morreu José da idade de cento e dez anos; e embalsamaram-no, e foi posto num caixão no Egito."}]'::jsonb, 'Almeida Livre'),
  ('Gn', 50, 'en', '[{"numero": 1, "texto": "And Joseph fell upon his father''s face, and wept upon him, and kissed him."}, {"numero": 2, "texto": "And Joseph commanded his servants the physicians to embalm his father: and the physicians embalmed Israel."}, {"numero": 3, "texto": "And forty days were fulfilled for him; for so are fulfilled the days of those which are embalmed: and the Egyptians mourned for him threescore and ten days."}, {"numero": 4, "texto": "And when the days of his mourning were past, Joseph spake unto the house of Pharaoh, saying, If now I have found grace in your eyes, speak, I pray you, in the ears of Pharaoh, saying,"}, {"numero": 5, "texto": "My father made me swear, saying, Lo, I die: in my grave which I have digged for me in the land of Canaan, there shalt thou bury me. Now therefore let me go up, I pray thee, and bury my father, and I will come again."}, {"numero": 6, "texto": "And Pharaoh said, Go up, and bury thy father, according as he made thee swear."}, {"numero": 7, "texto": "And Joseph went up to bury his father: and with him went up all the servants of Pharaoh, the elders of his house, and all the elders of the land of Egypt,"}, {"numero": 8, "texto": "And all the house of Joseph, and his brethren, and his father''s house: only their little ones, and their flocks, and their herds, they left in the land of Goshen."}, {"numero": 9, "texto": "And there went up with him both chariots and horsemen: and it was a very great company."}, {"numero": 10, "texto": "And they came to the threshingfloor of Atad, which is beyond Jordan, and there they mourned with a great and very sore lamentation: and he made a mourning for his father seven days."}, {"numero": 11, "texto": "And when the inhabitants of the land, the Canaanites, saw the mourning in the floor of Atad, they said, This is a grievous mourning to the Egyptians: wherefore the name of it was called Abelmizraim, which is beyond Jordan."}, {"numero": 12, "texto": "And his sons did unto him according as he commanded them:"}, {"numero": 13, "texto": "For his sons carried him into the land of Canaan, and buried him in the cave of the field of Machpelah, which Abraham bought with the field for a possession of a buryingplace of Ephron the Hittite, before Mamre."}, {"numero": 14, "texto": "And Joseph returned into Egypt, he, and his brethren, and all that went up with him to bury his father, after he had buried his father."}, {"numero": 15, "texto": "And when Joseph''s brethren saw that their father was dead, they said, Joseph will peradventure hate us, and will certainly requite us all the evil which we did unto him."}, {"numero": 16, "texto": "And they sent a messenger unto Joseph, saying, Thy father did command before he died, saying,"}, {"numero": 17, "texto": "So shall ye say unto Joseph, Forgive, I pray thee now, the trespass of thy brethren, and their sin; for they did unto thee evil: and now, we pray thee, forgive the trespass of the servants of the God of thy father. And Joseph wept when they spake unto him."}, {"numero": 18, "texto": "And his brethren also went and fell down before his face; and they said, Behold, we be thy servants."}, {"numero": 19, "texto": "And Joseph said unto them, Fear not: for am I in the place of God?"}, {"numero": 20, "texto": "But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive."}, {"numero": 21, "texto": "Now therefore fear ye not: I will nourish you, and your little ones. And he comforted them, and spake kindly unto them."}, {"numero": 22, "texto": "And Joseph dwelt in Egypt, he, and his father''s house: and Joseph lived an hundred and ten years."}, {"numero": 23, "texto": "And Joseph saw Ephraim''s children of the third generation: the children also of Machir the son of Manasseh were brought up upon Joseph''s knees."}, {"numero": 24, "texto": "And Joseph said unto his brethren, I die: and God will surely visit you, and bring you out of this land unto the land which he sware to Abraham, to Isaac, and to Jacob."}, {"numero": 25, "texto": "And Joseph took an oath of the children of Israel, saying, God will surely visit you, and ye shall carry up my bones from hence."}, {"numero": 26, "texto": "So Joseph died, being an hundred and ten years old: and they embalmed him, and he was put in a coffin in Egypt."}]'::jsonb, 'King James Version'),
  ('Gn', 50, 'fr', '[{"numero": 1, "texto": "Joseph se jeta sur le visage de son père, pleura sur lui, et le baisa."}, {"numero": 2, "texto": "Il ordonna aux médecins à son service d''''embaumer son père, et les médecins embaumèrent Israël."}, {"numero": 3, "texto": "Quarante jours s''''écoulèrent ainsi, et furent employés à l''''embaumer. Et les Egyptiens le pleurèrent soixante-dix jours."}, {"numero": 4, "texto": "Quand les jours du deuil furent passés, Joseph s''''adressa aux gens de la maison de Pharaon, et leur dit: Si j''''ai trouvé grâce à vos yeux, rapportez, je vous prie, à Pharaon ce que je vous dis."}, {"numero": 5, "texto": "Mon père m''''a fait jurer, en disant: Voici, je vais mourir! Tu m''''enterreras dans le sépulcre que je me suis acheté au pays de Canaan. Je voudrais donc y monter, pour enterrer mon père; et je reviendrai."}, {"numero": 6, "texto": "Pharaon répondit: Monte, et enterre ton père, comme il te l''''a fait jurer."}, {"numero": 7, "texto": "Joseph monta, pour enterrer son père. Avec lui montèrent tous les serviteurs de Pharaon, anciens de sa maison, tous les anciens du pays d''''Egypte,"}, {"numero": 8, "texto": "toute la maison de Joseph, ses frères, et la maison de son père: on ne laissa dans le pays de Gosen que les enfants, les brebis et les boeufs."}, {"numero": 9, "texto": "Il y avait encore avec Joseph des chars et des cavaliers, en sorte que le cortège était très nombreux."}, {"numero": 10, "texto": "Arrivés à l''''aire d''''Athad, qui est au delà du Jourdain, ils firent entendre de grandes et profondes lamentations; et Joseph fit en l''''honneur de son père un deuil de sept jours."}, {"numero": 11, "texto": "Les habitants du pays, les Cananéens, furent témoins de ce deuil dans l''''aire d''''Athad, et ils dirent: Voilà un grand deuil parmi les Egyptiens! C''''est pourquoi l''''on a donné le nom d''''Abel-Mitsraïm à cette aire qui est au delà du Jourdain."}, {"numero": 12, "texto": "C''''est ainsi que les fils de Jacob exécutèrent les ordres de leur père."}, {"numero": 13, "texto": "Ils le transportèrent au pays de Canaan, et l''''enterrèrent dans la caverne du champ de Macpéla, qu''''Abraham avait achetée d''''Ephron, le Héthien, comme propriété sépulcrale, et qui est vis-à-vis de Mamré."}, {"numero": 14, "texto": "Joseph, après avoir enterré son père, retourna en Egypte, avec ses frères et tous ceux qui étaient montés avec lui pour enterrer son père."}, {"numero": 15, "texto": "Quand les frères de Joseph virent que leur père était mort, ils dirent: Si Joseph nous prenait en haine, et nous rendait tout le mal que nous lui avons fait!"}, {"numero": 16, "texto": "Et ils firent dire à Joseph: Ton père a donné cet ordre avant de mourir:"}, {"numero": 17, "texto": "Vous parlerez ainsi à Joseph: Oh! pardonne le crime de tes frères et leur péché, car ils t''''ont fait du mal! Pardonne maintenant le péché des serviteurs du Dieu de ton père! Joseph pleura, en entendant ces paroles."}, {"numero": 18, "texto": "Ses frères vinrent eux-mêmes se prosterner devant lui, et ils dirent: Nous sommes tes serviteurs."}, {"numero": 19, "texto": "Joseph leur dit: Soyez sans crainte; car suis-je à la place de Dieu?"}, {"numero": 20, "texto": "Vous aviez médité de me faire du mal: Dieu l''''a changé en bien, pour accomplir ce qui arrive aujourd''''hui, pour sauver la vie à un peuple nombreux."}, {"numero": 21, "texto": "Soyez donc sans crainte; je vous entretiendrai, vous et vos enfants. Et il les consola, en parlant à leur coeur."}, {"numero": 22, "texto": "Joseph demeura en Egypte, lui et la maison de son père. Il vécut cent dix ans."}, {"numero": 23, "texto": "Joseph vit les fils d''''Ephraïm jusqu''''à la troisième génération; et les fils de Makir, fils de Manassé, naquirent sur ses genoux."}, {"numero": 24, "texto": "Joseph dit à ses frères: Je vais mourir! Mais Dieu vous visitera, et il vous fera remonter de ce pays-ci dans le pays qu''''il a juré de donner à Abraham, à Isaac et à Jacob."}, {"numero": 25, "texto": "Joseph fit jurer les fils d''''Israël, en disant: Dieu vous visitera; et vous ferez remonter mes os loin d''''ici."}, {"numero": 26, "texto": "Joseph mourut, âgé de cent dix ans. On l''''embauma, et on le mit dans un cercueil en Egypte."}]'::jsonb, 'Louis Segond 1910'),
  ('Gn', 50, 'es', '[{"numero": 1, "texto": "ENTONCES se echó José sobre el rostro de su padre, y lloró sobre él, y besólo."}, {"numero": 2, "texto": "Y mandó José á sus médicos familiares que embalsamasen á su padre: y los médicos embalsamaron á Israel."}, {"numero": 3, "texto": "Y cumpliéronle cuarenta días, porque así cumplían los días de los embalsamados, y lloráronlo los Egipcios setenta días."}, {"numero": 4, "texto": "Y pasados los días de su luto, habló José á los de la casa de Faraón, diciendo: Si he hallado ahora gracia en vuestros ojos, os ruego que habléis en oídos de Faraón, diciendo:"}, {"numero": 5, "texto": "Mi padre me conjuró diciendo: He aquí yo muero; en mi sepulcro que yo cavé para mí en la tierra de Canaán, allí me sepultarás; ruego pues que vaya yo ahora, y sepultaré á mi padre, y volveré."}, {"numero": 6, "texto": "Y Faraón dijo: Ve, y sepulta á tu padre, como él te conjuró."}, {"numero": 7, "texto": "Entonces José subió á sepultar á su padre; y subieron con él todos los siervos de Faraón, los ancianos de su casa, y todos los ancianos de la tierra de Egipto,"}, {"numero": 8, "texto": "Y toda la casa de José, y sus hermanos, y la casa de su padre: solamente dejaron en la tierra de Gosén sus niños, y sus ovejas y sus vacas."}, {"numero": 9, "texto": "Y subieron también con él carros y gente de á caballo, é hízose un escuadrón muy grande."}, {"numero": 10, "texto": "Y llegaron hasta la era de Atad, que está á la otra parte del Jordán, y endecharon allí con grande y muy grave lamentación: y José hizo á su padre duelo por siete días."}, {"numero": 11, "texto": "Y viendo los moradores de la tierra, los Cananeos, el llanto en la era de Atad, dijeron: Llanto grande es este de los Egipcios: por eso fué llamado su nombre Abelmizraim, que está á la otra parte del Jordán."}, {"numero": 12, "texto": "Hicieron, pues, sus hijos con él, según les había mandado:"}, {"numero": 13, "texto": "Pues lleváronlo sus hijos á la tierra de Canaán, y le sepultaron en la cueva del campo de Macpela, la que había comprado Abraham con el mismo campo, para heredad de sepultura, de Ephrón el Hetheo, delante de Mamre."}, {"numero": 14, "texto": "Y tornóse José á Egipto, él y sus hermanos, y todos los que subieron con él á sepultar á su padre, después que le hubo sepultado."}, {"numero": 15, "texto": "Y viendo los hermanos de José que su padre era muerto, dijeron: Quizá nos aborrecerá José, y nos dará el pago de todo el mal que le hicimos."}, {"numero": 16, "texto": "Y enviaron á decir á José: Tu padre mandó antes de su muerte, diciendo:"}, {"numero": 17, "texto": "Así diréis á José: Ruégote que perdones ahora la maldad de tus hermanos y su pecado, porque mal te trataron: por tanto ahora te rogamos que perdones la maldad de los siervos del Dios de tu padre. Y José lloró mientras hablaban."}, {"numero": 18, "texto": "Y vinieron también sus hermanos, y postráronse delante de él, y dijeron: Henos aquí por tus siervos."}, {"numero": 19, "texto": "Y respondióles José: No temáis: ¿estoy yo en lugar de Dios?"}, {"numero": 20, "texto": "Vosotros pensasteis mal sobre mí, mas Dios lo encaminó á bien, para hacer lo que vemos hoy, para mantener en vida á mucho pueblo."}, {"numero": 21, "texto": "Ahora, pues, no tengáis miedo; yo os sustentaré á vosotros y á vuestros hijos. Así los consoló, y les habló al corazón."}, {"numero": 22, "texto": "Y estuvo José en Egipto, él y la casa de su padre: y vivió José ciento diez años."}, {"numero": 23, "texto": "Y vió José los hijos de Ephraim hasta la tercera generación: también los hijos de Machîr, hijo de Manasés, fueron criados sobre las rodillas de José."}, {"numero": 24, "texto": "Y José dijo á sus hermanos: Yo me muero; mas Dios ciertamente os visitará, y os hará subir de aquesta tierra á la tierra que juró á Abraham, á Isaac, y á Jacob."}, {"numero": 25, "texto": "Y conjuró José á los hijos de Israel, diciendo: Dios ciertamente os visitará, y haréis llevar de aquí mis huesos."}, {"numero": 26, "texto": "Y murió José de edad de ciento diez años; y embalsamáronlo, y fué puesto en un ataúd en Egipto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Hb', 11, 'pt', '[{"numero": 1, "texto": "Ora, a fé é a certeza das coisas que se esperam, e a prova das coisas que não se veem."}, {"numero": 2, "texto": "Pois por ela os antigos obtiveram testemunho."}, {"numero": 3, "texto": "Pela fé entendemos que o universo foi aprontado pela palavra de Deus, de maneira que as coisas que se veem não foram feitas de algo visível."}, {"numero": 4, "texto": "Pela fé, Abel ofereceu a Deus melhor sacrifício do que Caim; por isso obteve testemunho de que era justo, pois Deus testemunhou de suas ofertas; e mesmo estando morto, ainda fala por meio dela."}, {"numero": 5, "texto": "Pela fé, Enoque foi transportado para não experimentar a morte; e não foi achado, porque Deus havia o transportado; pois antes da sua transportação ele obteve testemunho de ter agradado a Deus."}, {"numero": 6, "texto": "Ora, sem fé é impossível agradar [a Deus] . Pois é necessário que aquele que se aproxima de Deus creia que ele existe, e que ele é recompensador dos que o buscam."}, {"numero": 7, "texto": "Pela fé, Noé, divinamente advertido das coisas que ainda se não viam, temeu; e, para salvamento de sua família construiu a arca. Por meio da fé ele condenou o mundo, e foi feito herdeiro da justiça segundo a fé."}, {"numero": 8, "texto": "Pela fé, Abraão, quando foi chamado para ir ao lugar que havia de receber por herança, obedeceu, e saiu sem que soubesse aonde ia."}, {"numero": 9, "texto": "Pela fé, ele habitou na terra de promessa, como em [terra] que não fosse sua, morando em tendas com Isaque e com Jacó, herdeiros com ele da mesma promessa."}, {"numero": 10, "texto": "Pois ele esperava a cidade que tem fundamentos firmes, da qual o arquiteto e construtor é Deus."}, {"numero": 11, "texto": "Pela fé, também, a própria Sara recebeu a capacidade de conceber descendência, e já na idade avançada ela deu à luz, pois considerou fiel aquele que havia prometido."}, {"numero": 12, "texto": "Assim, de um que estava à beira da morte, nasceu [uma descendência] numerosa como as estrelas do céu, e incontável como a areia na praia do mar."}, {"numero": 13, "texto": "[Permanecendo] na fé, todos esses morreram sem receberem as promessas. Mas as viram de longe, creram, e felicitaram-se nelas, declarando que eram estrangeiros e peregrinos na terra."}, {"numero": 14, "texto": "Pois os que dizem tais coisas mostram claramente que estão buscando a [sua] própria pátria."}, {"numero": 15, "texto": "Ora, se estivessem pensando naquela de onde saíram, eles tinham oportunidade de voltar."}, {"numero": 16, "texto": "Mas agora desejam uma melhor, isto é, a celestial. Por isso Deus não se envergonha deles, de ser chamado o Deus deles, porque já lhes preparou uma cidade."}, {"numero": 17, "texto": "Pela fé, Abraão, quando foi provado, ofereceu Isaque; aquele que havia recebido as promessas ofereceu o [seu] único filho,"}, {"numero": 18, "texto": "do qual foi dito: Em Isaque será chamada a tua descendência."}, {"numero": 19, "texto": "[Abraão] considerou que Deus era poderoso até para ressuscitar [Isaque] dos mortos; de onde também, de forma figurada, ele o recuperou."}, {"numero": 20, "texto": "Pela fé, Isaque abençoou Jacó e Esaú quanto às coisas futuras."}, {"numero": 21, "texto": "Pela fé, Jacó, enquanto morria, abençoou a cada um dos filhos de José, e adorou [apoiado] sobre a ponta do seu cajado."}, {"numero": 22, "texto": "Pela fé, José, no fim de sua vida, mencionou a saída dos filhos de Israel, e deu ordem acerca dos seus ossos."}, {"numero": 23, "texto": "Pela fé, Moisés, quando nasceu, foi escondido três meses pelos seus pais, pois viram que o menino era belo, e não se intimidaram com o mandamento do rei."}, {"numero": 24, "texto": "Pela fé, Moisés, sendo já crescido, recusou ser chamado filho da filha de faraó;"}, {"numero": 25, "texto": "pois preferiu ser maltratado com o povo de Deus a ter por um tempo o prazer do pecado."}, {"numero": 26, "texto": "Ele considerou que as humilhações por causa de Cristo eram riquezas maiores que os tesouros no Egito; pois sua atenção estava fixada na recompensa."}, {"numero": 27, "texto": "Pela fé, ele deixou o Egito sem temer a ira do rei, pois perseverou como que vendo aquele que é invisível."}, {"numero": 28, "texto": "Pela fé, ele celebrou a Páscoa e o derramamento do sangue, para que o destruidor dos primogênitos não os tocasse."}, {"numero": 29, "texto": "Pela fé, atravessaram o mar Vermelho, como que por [ terra ] seca, o que, quando os Egípcios tentaram, afogaram-se."}, {"numero": 30, "texto": "Pela fé, os muros de Jericó caíram, depois de serem rodeados por sete dias."}, {"numero": 31, "texto": "Pela fé, Raabe, a prostituta, não pereceu com os incrédulos, pois acolheu em paz os espias."}, {"numero": 32, "texto": "E que mais direi? Pois me faltará tempo se eu contar a respeito de Gideão, Baraque, e também de Sansão, Jefté, Davi, e também de Samuel e dos profetas."}, {"numero": 33, "texto": "Pela fé, esses venceram reinos, exercitaram justiça, alcançaram promessas, fecharam bocas de leões,"}, {"numero": 34, "texto": "apagaram o poder do fogo, escaparam do fio de espada, da fraqueza tiraram forças, tonaram-se fortes na batalha, puseram em fuga os exércitos dos estrangeiros;"}, {"numero": 35, "texto": "As mulheres receberam de volta os seus mortos pela ressurreição; e outros foram torturados, não aceitando a soltura, para alcançarem uma melhor ressurreição;"}, {"numero": 36, "texto": "e outros experimentaram provação de insultos e açoites, e até correntes e prisões;"}, {"numero": 37, "texto": "foram apedrejados, serrados, tentados, morreram pela espada; andaram [vestidos] de peles de ovelhas e de cabras; necessitados, afligidos, maltratados;"}, {"numero": 38, "texto": "(o mundo não era digno deles) andando sem rumo em desertos, montanhas, covas, e nas cavernas da terra."}, {"numero": 39, "texto": "E todos esses, [mesmo] tendo testemunho pela fé, não alcançaram a promessa,"}, {"numero": 40, "texto": "pois Deus havia preparado algo melhor para nós, para que, sem nós, eles não fossem aperfeiçoados."}]'::jsonb, 'Almeida Livre'),
  ('Hb', 11, 'en', '[{"numero": 1, "texto": "Now faith is the substance of things hoped for, the evidence of things not seen."}, {"numero": 2, "texto": "For by it the elders obtained a good report."}, {"numero": 3, "texto": "Through faith we understand that the worlds were framed by the word of God, so that things which are seen were not made of things which do appear."}, {"numero": 4, "texto": "By faith Abel offered unto God a more excellent sacrifice than Cain, by which he obtained witness that he was righteous, God testifying of his gifts: and by it he being dead yet speaketh."}, {"numero": 5, "texto": "By faith Enoch was translated that he should not see death; and was not found, because God had translated him: for before his translation he had this testimony, that he pleased God."}, {"numero": 6, "texto": "But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him."}, {"numero": 7, "texto": "By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house; by the which he condemned the world, and became heir of the righteousness which is by faith."}, {"numero": 8, "texto": "By faith Abraham, when he was called to go out into a place which he should after receive for an inheritance, obeyed; and he went out, not knowing whither he went."}, {"numero": 9, "texto": "By faith he sojourned in the land of promise, as in a strange country, dwelling in tabernacles with Isaac and Jacob, the heirs with him of the same promise:"}, {"numero": 10, "texto": "For he looked for a city which hath foundations, whose builder and maker is God."}, {"numero": 11, "texto": "Through faith also Sara herself received strength to conceive seed, and was delivered of a child when she was past age, because she judged him faithful who had promised."}, {"numero": 12, "texto": "Therefore sprang there even of one, and him as good as dead, so many as the stars of the sky in multitude, and as the sand which is by the sea shore innumerable."}, {"numero": 13, "texto": "These all died in faith, not having received the promises, but having seen them afar off, and were persuaded of them, and embraced them, and confessed that they were strangers and pilgrims on the earth."}, {"numero": 14, "texto": "For they that say such things declare plainly that they seek a country."}, {"numero": 15, "texto": "And truly, if they had been mindful of that country from whence they came out, they might have had opportunity to have returned."}, {"numero": 16, "texto": "But now they desire a better country, that is, an heavenly: wherefore God is not ashamed to be called their God: for he hath prepared for them a city."}, {"numero": 17, "texto": "By faith Abraham, when he was tried, offered up Isaac: and he that had received the promises offered up his only begotten son,"}, {"numero": 18, "texto": "Of whom it was said, That in Isaac shall thy seed be called:"}, {"numero": 19, "texto": "Accounting that God was able to raise him up, even from the dead; from whence also he received him in a figure."}, {"numero": 20, "texto": "By faith Isaac blessed Jacob and Esau concerning things to come."}, {"numero": 21, "texto": "By faith Jacob, when he was a dying, blessed both the sons of Joseph; and worshipped, leaning upon the top of his staff."}, {"numero": 22, "texto": "By faith Joseph, when he died, made mention of the departing of the children of Israel; and gave commandment concerning his bones."}, {"numero": 23, "texto": "By faith Moses, when he was born, was hid three months of his parents, because they saw he was a proper child; and they were not afraid of the king''s commandment."}, {"numero": 24, "texto": "By faith Moses, when he was come to years, refused to be called the son of Pharaoh''s daughter;"}, {"numero": 25, "texto": "Choosing rather to suffer affliction with the people of God, than to enjoy the pleasures of sin for a season;"}, {"numero": 26, "texto": "Esteeming the reproach of Christ greater riches than the treasures in Egypt: for he had respect unto the recompence of the reward."}, {"numero": 27, "texto": "By faith he forsook Egypt, not fearing the wrath of the king: for he endured, as seeing him who is invisible."}, {"numero": 28, "texto": "Through faith he kept the passover, and the sprinkling of blood, lest he that destroyed the firstborn should touch them."}, {"numero": 29, "texto": "By faith they passed through the Red sea as by dry land: which the Egyptians assaying to do were drowned."}, {"numero": 30, "texto": "By faith the walls of Jericho fell down, after they were compassed about seven days."}, {"numero": 31, "texto": "By faith the harlot Rahab perished not with them that believed not, when she had received the spies with peace."}, {"numero": 32, "texto": "And what shall I more say? for the time would fail me to tell of Gedeon, and of Barak, and of Samson, and of Jephthae; of David also, and Samuel, and of the prophets:"}, {"numero": 33, "texto": "Who through faith subdued kingdoms, wrought righteousness, obtained promises, stopped the mouths of lions."}, {"numero": 34, "texto": "Quenched the violence of fire, escaped the edge of the sword, out of weakness were made strong, waxed valiant in fight, turned to flight the armies of the aliens."}, {"numero": 35, "texto": "Women received their dead raised to life again: and others were tortured, not accepting deliverance; that they might obtain a better resurrection:"}, {"numero": 36, "texto": "And others had trial of cruel mockings and scourgings, yea, moreover of bonds and imprisonment:"}, {"numero": 37, "texto": "They were stoned, they were sawn asunder, were tempted, were slain with the sword: they wandered about in sheepskins and goatskins; being destitute, afflicted, tormented;"}, {"numero": 38, "texto": "(Of whom the world was not worthy:) they wandered in deserts, and in mountains, and in dens and caves of the earth."}, {"numero": 39, "texto": "And these all, having obtained a good report through faith, received not the promise:"}, {"numero": 40, "texto": "God having provided some better thing for us, that they without us should not be made perfect."}]'::jsonb, 'King James Version'),
  ('Hb', 11, 'fr', '[{"numero": 1, "texto": "Or la foi est une ferme assurance des choses qu''''on espère, une démonstration de celles qu''''on ne voit pas."}, {"numero": 2, "texto": "Pour l''''avoir possédée, les anciens ont obtenu un témoignage favorable."}, {"numero": 3, "texto": "C''''est par la foi que nous reconnaissons que le monde a été formé par la parole de Dieu, en sorte que ce qu''''on voit n''''a pas été fait de choses visibles."}, {"numero": 4, "texto": "C''''est par la foi qu''''Abel offrit à Dieu un sacrifice plus excellent que celui de Caïn; c''''est par elle qu''''il fut déclaré juste, Dieu approuvant ses offrandes; et c''''est par elle qu''''il parle encore, quoique mort."}, {"numero": 5, "texto": "C''''est par la foi qu''''Enoch fut enlevé pour qu''''il ne vît point la mort, et qu''''il ne parut plus parce que Dieu l''''avait enlevé; car, avant son enlèvement, il avait reçu le témoignage qu''''il était agréable à Dieu."}, {"numero": 6, "texto": "Or sans la foi il est impossible de lui être agréable; car il faut que celui qui s''''approche de Dieu croie que Dieu existe, et qu''''il est le rémunérateur de ceux qui le cherchent."}, {"numero": 7, "texto": "C''''est par la foi que Noé, divinement averti des choses qu''''on ne voyait pas encore, et saisi d''''une crainte respectueuse, construisit une arche pour sauver sa famille; c''''est par elle qu''''il condamna le monde, et devint héritier de la justice qui s''''obtient par la foi."}, {"numero": 8, "texto": "C''''est par la foi qu''''Abraham, lors de sa vocation, obéit et partit pour un lieu qu''''il devait recevoir en héritage, et qu''''il partit sans savoir où il allait."}, {"numero": 9, "texto": "C''''est par la foi qu''''il vint s''''établir dans la terre promise comme dans une terre étrangère, habitant sous des tentes, ainsi qu''''Isaac et Jacob, les cohéritiers de la même promesse."}, {"numero": 10, "texto": "Car il attendait la cité qui a de solides fondements, celle dont Dieu est l''''architecte et le constructeur."}, {"numero": 11, "texto": "C''''est par la foi que Sara elle-même, malgré son âge avancé, fut rendue capable d''''avoir une postérité, parce qu''''elle crut à la fidélité de celui qui avait fait la promesse."}, {"numero": 12, "texto": "C''''est pourquoi d''''un seul homme, déjà usé de corps, naquit une postérité nombreuse comme les étoiles du ciel, comme le sable qui est sur le bord de la mer et qu''''on ne peut compter."}, {"numero": 13, "texto": "C''''est dans la foi qu''''ils sont tous morts, sans avoir obtenu les choses promises; mais ils les ont vues et saluées de loin, reconnaissant qu''''ils étaient étrangers et voyageurs sur la terre."}, {"numero": 14, "texto": "Ceux qui parlent ainsi montrent qu''''ils cherchent une patrie."}, {"numero": 15, "texto": "S''''ils avaient eu en vue celle d''''où ils étaient sortis, ils auraient eu le temps d''''y retourner."}, {"numero": 16, "texto": "Mais maintenant ils en désirent une meilleure, c''''est-à-dire une céleste. C''''est pourquoi Dieu n''''a pas honte d''''être appelé leur Dieu, car il leur a préparé une cité."}, {"numero": 17, "texto": "C''''est par la foi qu''''Abraham offrit Isaac, lorsqu''''il fut mis à l''''épreuve, et qu''''il offrit son fils unique, lui qui avait reçu les promesses,"}, {"numero": 18, "texto": "et à qui il avait été dit: En Isaac sera nommée pour toi une postérité."}, {"numero": 19, "texto": "Il pensait que Dieu est puissant, même pour ressusciter les morts; aussi le recouvra-t-il par une sorte de résurrection."}, {"numero": 20, "texto": "C''''est par la foi qu''''Isaac bénit Jacob et Esaü, en vue des choses à venir."}, {"numero": 21, "texto": "C''''est par la foi que Jacob mourant bénit chacun des fils de Joseph, et qu''''il adora, appuyé sur l''''extrémité de son bâton."}, {"numero": 22, "texto": "C''''est par la foi que Joseph mourant fit mention de la sortie des fils d''''Israël, et qu''''il donna des ordres au sujet de ses os."}, {"numero": 23, "texto": "C''''est par la foi que Moïse, à sa naissance, fut caché pendant trois mois par ses parents, parce qu''''ils virent que l''''enfant était beau, et qu''''ils ne craignirent pas l''''ordre du roi."}, {"numero": 24, "texto": "C''''est par la foi que Moïse, devenu grand, refusa d''''être appelé fils de la fille de Pharaon,"}, {"numero": 25, "texto": "aimant mieux être maltraité avec le peuple de Dieu que d''''avoir pour un temps la jouissance du péché,"}, {"numero": 26, "texto": "regardant l''''opprobre de Christ comme une richesse plus grande que les trésors de l''''Egypte, car il avait les yeux fixés sur la rémunération."}, {"numero": 27, "texto": "C''''est par la foi qu''''il quitta l''''Egypte, sans être effrayé de la colère du roi; car il se montra ferme, comme voyant celui qui est invisible."}, {"numero": 28, "texto": "C''''est par la foi qu''''il fit la Pâque et l''''aspersion du sang, afin que l''''exterminateur ne touchât pas aux premiers-nés des Israélites."}, {"numero": 29, "texto": "C''''est par la foi qu''''ils traversèrent la mer Rouge comme un lieu sec, tandis que les Egyptiens qui en firent la tentative furent engloutis."}, {"numero": 30, "texto": "C''''est par la foi que les murailles de Jéricho tombèrent, après qu''''on en eut fait le tour pendant sept jours."}, {"numero": 31, "texto": "C''''est par la foi que Rahab la prostituée ne périt pas avec les rebelles, parce qu''''elle avait reçu les espions avec bienveillance."}, {"numero": 32, "texto": "Et que dirai-je encore? Car le temps me manquerait pour parler de Gédéon, de Barak, de Samson, de Jephthé, de David, de Samuel, et des prophètes,"}, {"numero": 33, "texto": "qui, par la foi, vainquirent des royaumes, exercèrent la justice, obtinrent des promesses, fermèrent la gueule des lions,"}, {"numero": 34, "texto": "teignirent la puissance du feu, échappèrent au tranchant de l''''épée, guérirent de leurs maladies, furent vaillants à la guerre, mirent en fuite des armées étrangères."}, {"numero": 35, "texto": "Des femmes recouvrèrent leurs morts par la résurrection; d''''autres furent livrés aux tourments, et n''''acceptèrent point de délivrance, afin d''''obtenir une meilleure résurrection;"}, {"numero": 36, "texto": "d''''autres subirent les moqueries et le fouet, les chaînes et la prison;"}, {"numero": 37, "texto": "ils furent lapidés, sciés, torturés, ils moururent tués par l''''épée, ils allèrent çà et là vêtus de peaux de brebis et de peaux de chèvres, dénués de tout, persécutés, maltraités,"}, {"numero": 38, "texto": "eux dont le monde n''''était pas digne, errants dans les déserts et les montagnes, dans les cavernes et les antres de la terre."}, {"numero": 39, "texto": "Tous ceux-là, à la foi desquels il a été rendu témoignage, n''''ont pas obtenu ce qui leur était promis,"}, {"numero": 40, "texto": "Dieu ayant en vue quelque chose de meilleur pour nous, afin qu''''ils ne parvinssent pas sans nous à la perfection."}]'::jsonb, 'Louis Segond 1910'),
  ('Hb', 11, 'es', '[{"numero": 1, "texto": "ES pues la fe la sustancia de las cosas que se esperan, la demostración de las cosas que no se ven."}, {"numero": 2, "texto": "Porque por ella alcanzaron testimonio los antiguos."}, {"numero": 3, "texto": "Por la fe entendemos haber sido compuestos los siglos por la palabra de Dios, siendo hecho lo que se ve, de lo que no se veía."}, {"numero": 4, "texto": "Por la fe Abel ofreció á Dios mayor sacrificio que Caín, por la cual alcanzó testimonio de que era justo, dando Dios testimonio á sus presentes; y difunto, aun habla por ella."}, {"numero": 5, "texto": "Por la fe Enoc fué traspuesto para no ver muerte, y no fué hallado, porque lo traspuso Dios. Y antes que fuese traspuesto, tuvo testimonio de haber agradado á Dios."}, {"numero": 6, "texto": "Empero sin fe es imposible agradar á Dios; porque es menester que el que á Dios se allega, crea que le hay, y que es galardonador de los que le buscan."}, {"numero": 7, "texto": "Por la fe Noé, habiendo recibido respuesta de cosas que aun no se veían, con temor aparejó el arca en que su casa se salvase: por la cual fe condenó al mundo, y fué hecho heredero de la justicia que es por la fe."}, {"numero": 8, "texto": "Por la fe Abraham, siendo llamado, obedeció para salir al lugar que había de recibir por heredad; y salió sin saber dónde iba."}, {"numero": 9, "texto": "Por fe habitó en la tierra prometida como en tierra ajena, morando en cabañas con Isaac y Jacob, herederos juntamente de la misma promesa:"}, {"numero": 10, "texto": "Porque esperaba ciudad con fundamentos, el artífice y hacedor de la cual es Dios."}, {"numero": 11, "texto": "Por la fe también la misma Sara, siendo estéril, recibió fuerza para concebir simiente; y parió aun fuera del tiempo de la edad, porque creyó ser fiel el que lo había prometido."}, {"numero": 12, "texto": "Por lo cual también, de uno, y ése ya amortecido, salieron como las estrellas del cielo en multitud, y como la arena innumerable que está á la orilla de la mar."}, {"numero": 13, "texto": "Conforme á la fe murieron todos éstos sin haber recibido las promesas, sino mirándolas de lejos, y creyéndolas, y saludándolas, y confesando que eran peregrinos y advenedizos sobre la tierra."}, {"numero": 14, "texto": "Porque los que esto dicen, claramente dan á entender que buscan una patria."}, {"numero": 15, "texto": "Que si se acordaran de aquella de donde salieron, cierto tenían tiempo para volverse:"}, {"numero": 16, "texto": "Empero deseaban la mejor, es á saber, la celestial; por lo cual Dios no se avergüenza de llamarse Dios de ellos: porque les había aparejado ciudad."}, {"numero": 17, "texto": "Por fe ofreció Abraham á Isaac cuando fué probado, y ofrecía al unigénito el que había recibido las promesas,"}, {"numero": 18, "texto": "Habiéndole sido dicho: En Isaac te será llamada simiente:"}, {"numero": 19, "texto": "Pensando que aun de los muertos es Dios poderoso para levantar; de donde también le volvió á recibir por figura."}, {"numero": 20, "texto": "Por fe bendijo Isaac á Jacob y á Esaú respecto á cosas que habían de ser."}, {"numero": 21, "texto": "Por fe Jacob, muriéndose, bendijo á cada uno de los hijos de José, y adoró estribando sobre la punta de su bordón."}, {"numero": 22, "texto": "Por fe José, muriéndose, se acordó de la partida de los hijos de Israel; y dió mandamiento acerca de sus huesos."}, {"numero": 23, "texto": "Por fe Moisés, nacido, fué escondido de sus padres por tres meses, porque le vieron hermoso niño; y no temieron el mandamiento del rey."}, {"numero": 24, "texto": "Por fe Moisés, hecho ya grande, rehusó ser llamado hijo de la hija de Faraón;"}, {"numero": 25, "texto": "Escogiendo antes ser afligido con el pueblo de Dios, que gozar de comodidades temporales de pecado."}, {"numero": 26, "texto": "Teniendo por mayores riquezas el vituperio de Cristo que los tesoros de los Egipcios; porque miraba á la remuneración."}, {"numero": 27, "texto": "Por fe dejó á Egipto, no temiendo la ira del rey; porque se sostuvo como viendo al Invisible."}, {"numero": 28, "texto": "Por fe celebró la pascua y el derramamiento de la sangre, para que el que mataba los primogénitos no los tocase."}, {"numero": 29, "texto": "Por fe pasaron el mar Bermejo como por tierra seca: lo cual probando los Egipcios, fueron sumergidos."}, {"numero": 30, "texto": "Por fe cayeron los muros de Jericó con rodearlos siete días."}, {"numero": 31, "texto": "Por fe Rahab la ramera no pereció juntamente con los incrédulos, habiendo recibido á los espías con paz."}, {"numero": 32, "texto": "¿Y qué más digo? porque el tiempo me faltará contando de Gedeón, de Barac, de Samsón, de Jephté, de David, de Samuel, y de los profetas:"}, {"numero": 33, "texto": "Que por fe ganaron reinos, obraron justicia, alcanzaron promesas, taparon las bocas de leones,"}, {"numero": 34, "texto": "Apagaron fuegos impetuosos, evitaron filo de cuchillo, convalecieron de enfermedades, fueron hechos fuertes en batallas, trastornaron campos de extraños."}, {"numero": 35, "texto": "Las mujeres recibieron sus muertos por resurrección; unos fueron estirados, no aceptando el rescate, para ganar mejor resurrección;"}, {"numero": 36, "texto": "Otros experimentaron vituperios y azotes; y á más de esto prisiones y cárceles;"}, {"numero": 37, "texto": "Fueron apedreados, aserrados, tentados, muertos á cuchillo; anduvieron de acá para allá cubiertos de pieles de ovejas y de cabras, pobres, angustiados, maltratados;"}, {"numero": 38, "texto": "De los cuales el mundo no era digno; perdidos por los desiertos, por los montes, por las cuevas y por las cavernas de la tierra."}, {"numero": 39, "texto": "Y todos éstos, aprobados por testimonio de la fe, no recibieron la promesa;"}, {"numero": 40, "texto": "Proveyendo Dios alguna cosa mejor para nosotros, para que no fuesen perfeccionados sin nosotros."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 5, 'pt', '[{"numero": 1, "texto": "Agora cantarei a meu amado o cântico de meu querido de sua vinha: meu amado tem uma vinha, em um morro fértil;"}, {"numero": 2, "texto": "E a cercou, e limpou das pedras, e a plantou de excelentes videiras, e edificou no meio dela uma torre; e também fundou nela uma prensa de uvas; e esperava que desse uvas boas, porém deu uvas imprestáveis."}, {"numero": 3, "texto": "E agora, ó moradores de Jerusalém, e vós homens de Judá? Julgai, eu vos peço, entre mim e minha vinha."}, {"numero": 4, "texto": "O que mais podia ser feito à minha vinha, que eu não tenha já feito? Se eu esperava uvas boas, como, pois, veio dar uvas imprestáveis?"}, {"numero": 5, "texto": "Por isso agora eu vos farei saber o que farei à minha vinha: tirarei sua cerca, para que sirva de pastagem; derrubarei seu muro, para que seja pisada;"}, {"numero": 6, "texto": "E eu a tornarei uma [terra] abandonada; não será podada, nem cavada; mas crescerão [nela] cardos e espinhos; e darei ordens às nuvens, para que não chovam chuva sobre ela."}, {"numero": 7, "texto": "Porque a vinha do SENHOR dos exércitos é a casa de Israel, e os homens de Judá são suas plantas agradáveis; porém ele esperava juízo, e eis aqui opressão; [ele esperava] justiça, e eis aqui clamor."}, {"numero": 8, "texto": "Ai dos que juntam uma casas, [e] acumulam propriedades de terra, até que não tenha sobrado mais lugar, para que somente vós fiqueis como moradores no meio da terra."}, {"numero": 9, "texto": "O SENHOR dos exércitos [disse] aos meus ouvidos: Verdadeiramente muitas casas se tornarão desertas, [até] as grandes e valiosas ficarão sem moradores!"}, {"numero": 10, "texto": "E dez jeiras de vinha darão [apenas] um bato; e um ômer de semente dará [apenas] um efa."}, {"numero": 11, "texto": "Ai dos que se levantam cedo pela manhã, para buscarem bebida alcoólica, e continuam até a noite, [até que] o vinho os esquente."}, {"numero": 12, "texto": "E harpas, liras, tamborins, gaitas e vinho há em seus banquetes; porém não olham para a obra do SENHOR, nem veem a obra de suas próprias mãos."}, {"numero": 13, "texto": "Por isso meu povo será levado cativo, porque não tem conhecimento; seus nobres terão fome, e sua multidão se secará de sede."}, {"numero": 14, "texto": "Por isso o Xeol alargou seu avidez, e sua boca se abriu tanto que não se pode medir, e [ali] descerão a nobreza e também a multidão, em meio a barulhos e com os que festejam."}, {"numero": 15, "texto": "Então as pessoas serão rebaixadas, e os homens serão humilhados; e os olhos dos arrogantes se humilharão."}, {"numero": 16, "texto": "Mas o SENHOR dos exércitos será exaltado com juízo; e Deus, o Santo, será santificado com justiça."}, {"numero": 17, "texto": "E os cordeiros pastarão como se fosse seus próprios pastos, e os estranhos comerão [do alimento proveniente] dos lugares abandonados dos ricos."}, {"numero": 18, "texto": "Ai dos que puxam perversidade com cordas de futilidade, e pelo pecado como que [com] cordas de carruagens!"}, {"numero": 19, "texto": "E dizem: Que ele se apresse, acelere sua obra, para que a vejamos; e aproxime-se e venha o conselho do Santo de Israel, para que possamos saber."}, {"numero": 20, "texto": "Ai dos que chamam o mal de bem, e o bem de mal; que trocam as trevas pela luz, e a luz pelas trevas; e trocam o amargo pelo doce, e o doce pelo amargo!"}, {"numero": 21, "texto": "Ai dos [que se acham] sábios aos seus próprios olhos, e prudentes para si mesmos!"}, {"numero": 22, "texto": "Ai dos [que se acham] corajosos para beberem vinho, e homens fortes para misturarem bebida alcoólica!"}, {"numero": 23, "texto": "[Ai d] os que inocentam o perverso por causa de suborno, e se desviam da justiça dos justos!"}, {"numero": 24, "texto": "Por isso, como a língua de fogo consome a estopa, e a chama queima a palha, [assim] sua raiz será como podridão, e sua flor se desfará como o pó; pois rejeitaram a Lei do SENHOR dos exércitos, e desprezaram a palavra do Santo de Israel."}, {"numero": 25, "texto": "Por isso se acendeu a ira do SENHOR contra seu povo, e estendeu sua mão contra ele, e o feriu; e as montanhas tremeram, e seus cadáveres foram como lixo no meio das ruas; com tudo isto ele não retrocedeu sua ira; ao contrário, sua mão ainda está estendida."}, {"numero": 26, "texto": "E ele levantará uma bandeira para as nações distantes, e lhes assoviará desde os confins da terra; e eis que virão com rapidez apressadamente."}, {"numero": 27, "texto": "Não haverá entre eles cansado ou quem tropece; ninguém cochilará, nem dormirá; nem se desatará o cinto de seus lombos, nem será arrebentada a tira de seus calçados."}, {"numero": 28, "texto": "Suas flechas estarão afiadas, e todos os seus arcos prontos para atirar; os cascos de seus cavalos serão comparáveis a rochas, e as rodas [de suas carruagens] como redemoinhos de vento."}, {"numero": 29, "texto": "O rugido deles será como o de um leão feroz, e bramarão como filhotes de leão; e rugirão, e tomarão a presa, e a levarão, e não haverá quem [a] resgate."}, {"numero": 30, "texto": "E bramarão contra ela naquele dia como o bramido do mar; então olharão para a terra, e eis que há trevas [e] aflição; e a luz se escurecerá em suas nuvens."}]'::jsonb, 'Almeida Livre'),
  ('Is', 5, 'en', '[{"numero": 1, "texto": "Now will I sing to my wellbeloved a song of my beloved touching his vineyard. My wellbeloved hath a vineyard in a very fruitful hill:"}, {"numero": 2, "texto": "And he fenced it, and gathered out the stones thereof, and planted it with the choicest vine, and built a tower in the midst of it, and also made a winepress therein: and he looked that it should bring forth grapes, and it brought forth wild grapes."}, {"numero": 3, "texto": "And now, O inhabitants of Jerusalem, and men of Judah, judge, I pray you, betwixt me and my vineyard."}, {"numero": 4, "texto": "What could have been done more to my vineyard, that I have not done in it? wherefore, when I looked that it should bring forth grapes, brought it forth wild grapes?"}, {"numero": 5, "texto": "And now go to; I will tell you what I will do to my vineyard: I will take away the hedge thereof, and it shall be eaten up; and break down the wall thereof, and it shall be trodden down:"}, {"numero": 6, "texto": "And I will lay it waste: it shall not be pruned, nor digged; but there shall come up briers and thorns: I will also command the clouds that they rain no rain upon it."}, {"numero": 7, "texto": "For the vineyard of the Lord of hosts is the house of Israel, and the men of Judah his pleasant plant: and he looked for judgment, but behold oppression; for righteousness, but behold a cry."}, {"numero": 8, "texto": "Woe unto them that join house to house, that lay field to field, till there be no place, that they may be placed alone in the midst of the earth!"}, {"numero": 9, "texto": "In mine ears said the Lord of hosts, Of a truth many houses shall be desolate, even great and fair, without inhabitant."}, {"numero": 10, "texto": "Yea, ten acres of vineyard shall yield one bath, and the seed of an homer shall yield an ephah."}, {"numero": 11, "texto": "Woe unto them that rise up early in the morning, that they may follow strong drink; that continue until night, till wine inflame them!"}, {"numero": 12, "texto": "And the harp, and the viol, the tabret, and pipe, and wine, are in their feasts: but they regard not the work of the Lord, neither consider the operation of his hands."}, {"numero": 13, "texto": "Therefore my people are gone into captivity, because they have no knowledge: and their honourable men are famished, and their multitude dried up with thirst."}, {"numero": 14, "texto": "Therefore hell hath enlarged herself, and opened her mouth without measure: and their glory, and their multitude, and their pomp, and he that rejoiceth, shall descend into it."}, {"numero": 15, "texto": "And the mean man shall be brought down, and the mighty man shall be humbled, and the eyes of the lofty shall be humbled:"}, {"numero": 16, "texto": "But the Lord of hosts shall be exalted in judgment, and God that is holy shall be sanctified in righteousness."}, {"numero": 17, "texto": "Then shall the lambs feed after their manner, and the waste places of the fat ones shall strangers eat."}, {"numero": 18, "texto": "Woe unto them that draw iniquity with cords of vanity, and sin as it were with a cart rope:"}, {"numero": 19, "texto": "That say, Let him make speed, and hasten his work, that we may see it: and let the counsel of the Holy One of Israel draw nigh and come, that we may know it!"}, {"numero": 20, "texto": "Woe unto them that call evil good, and good evil; that put darkness for light, and light for darkness; that put bitter for sweet, and sweet for bitter!"}, {"numero": 21, "texto": "Woe unto them that are wise in their own eyes, and prudent in their own sight!"}, {"numero": 22, "texto": "Woe unto them that are mighty to drink wine, and men of strength to mingle strong drink:"}, {"numero": 23, "texto": "Which justify the wicked for reward, and take away the righteousness of the righteous from him!"}, {"numero": 24, "texto": "Therefore as the fire devoureth the stubble, and the flame consumeth the chaff, so their root shall be as rottenness, and their blossom shall go up as dust: because they have cast away the law of the Lord of hosts, and despised the word of the Holy One of Israel."}, {"numero": 25, "texto": "Therefore is the anger of the Lord kindled against his people, and he hath stretched forth his hand against them, and hath smitten them: and the hills did tremble, and their carcases were torn in the midst of the streets. For all this his anger is not turned away, but his hand is stretched out still."}, {"numero": 26, "texto": "And he will lift up an ensign to the nations from far, and will hiss unto them from the end of the earth: and, behold, they shall come with speed swiftly:"}, {"numero": 27, "texto": "None shall be weary nor stumble among them; none shall slumber nor sleep; neither shall the girdle of their loins be loosed, nor the latchet of their shoes be broken:"}, {"numero": 28, "texto": "Whose arrows are sharp, and all their bows bent, their horses'' hoofs shall be counted like flint, and their wheels like a whirlwind:"}, {"numero": 29, "texto": "Their roaring shall be like a lion, they shall roar like young lions: yea, they shall roar, and lay hold of the prey, and shall carry it away safe, and none shall deliver it."}, {"numero": 30, "texto": "And in that day they shall roar against them like the roaring of the sea: and if one look unto the land, behold darkness and sorrow, and the light is darkened in the heavens thereof."}]'::jsonb, 'King James Version'),
  ('Is', 5, 'fr', '[{"numero": 1, "texto": "Je chanterai à mon bien-aimé Le cantique de mon bien-aimé sur sa vigne. Mon bien-aimé avait une vigne, Sur un coteau fertile."}, {"numero": 2, "texto": "Il en remua le sol, ôta les pierres, et y mit un plant délicieux; Il bâtit une tour au milieu d''''elle, Et il y creusa aussi une cuve. Puis il espéra qu''''elle produirait de bons raisins, Mais elle en a produit de mauvais."}, {"numero": 3, "texto": "Maintenant donc, habitants de Jérusalem et hommes de Juda, Soyez juges entre moi et ma vigne!"}, {"numero": 4, "texto": "Qu''''y avait-il encore à faire à ma vigne, Que je n''''aie pas fait pour elle? Pourquoi, quand j''''ai espéré qu''''elle produirait de bons raisins, En a-t-elle produit de mauvais?"}, {"numero": 5, "texto": "Je vous dirai maintenant Ce que je vais faire à ma vigne. J''''en arracherai la haie, pour qu''''elle soit broutée; J''''en abattrai la clôture, pour qu''''elle soit foulée aux pieds."}, {"numero": 6, "texto": "Je la réduirai en ruine; elle ne sera plus taillée, ni cultivée; Les ronces et les épines y croîtront; Et je donnerai mes ordres aux nuées, Afin qu''''elles ne laissent plus tomber la pluie sur elle."}, {"numero": 7, "texto": "La vigne de l''''Eternel des armées, c''''est la maison d''''Israël, Et les hommes de Juda, c''''est le plant qu''''il chérissait. Il avait espéré de la droiture, et voici du sang versé! De la justice, et voici des cris de détresse!"}, {"numero": 8, "texto": "Malheur à ceux qui ajoutent maison à maison, Et qui joignent champ à champ, Jusqu''''à ce qu''''il n''''y ait plus d''''espace, Et qu''''ils habitent seuls au milieu du pays!"}, {"numero": 9, "texto": "Voici ce que m''''a révélé l''''Eternel des armées: Certainement, ces maisons nombreuses seront dévastées, Ces grandes et belles maisons n''''auront plus d''''habitants."}, {"numero": 10, "texto": "Même dix arpents de vigne ne produiront qu''''un bath, Et un homer de semence ne produira qu''''un épha."}, {"numero": 11, "texto": "Malheur à ceux qui de bon matin Courent après les boissons enivrantes, Et qui bien avant dans la nuit Sont échauffés par le vin!"}, {"numero": 12, "texto": "La harpe et le luth, le tambourin, la flûte et le vin, animent leurs festins; Mais ils ne prennent point garde à l''''oeuvre de l''''Eternel, Et ils ne voient point le travail de ses mains."}, {"numero": 13, "texto": "C''''est pourquoi mon peuple sera soudain emmené captif; Sa noblesse mourra de faim, Et sa multitude sera desséchée par la soif."}, {"numero": 14, "texto": "C''''est pourquoi le séjour des morts ouvre sa bouche, Elargit sa gueule outre mesure; Alors descendent la magnificence et la richesse de Sion, Et sa foule bruyante et joyeuse."}, {"numero": 15, "texto": "Les petits seront abattus, les grands seront humiliés, Et les regards des hautains seront abaissés."}, {"numero": 16, "texto": "L''''Eternel des armées sera élevé par le jugement, Et le Dieu saint sera sanctifié par la justice."}, {"numero": 17, "texto": "Des brebis paîtront comme sur leur pâturage, Et des étrangers dévoreront les possessions ruinées des riches."}, {"numero": 18, "texto": "Malheur à ceux qui tirent l''''iniquité avec les cordes du vice, Et le péché comme avec les traits d''''un char,"}, {"numero": 19, "texto": "Et qui disent: Qu''''il hâte, qu''''il accélère son oeuvre, Afin que nous la voyions! Que le décret du Saint d''''Israël arrive et s''''exécute, Afin que nous le connaissions!"}, {"numero": 20, "texto": "Malheur à ceux qui appellent le mal bien, et le bien mal, Qui changent les ténèbres en lumière, et la lumière en ténèbres, Qui changent l''''amertume en douceur, et la douceur en amertume!"}, {"numero": 21, "texto": "Malheur à ceux qui sont sages à leurs yeux, Et qui se croient intelligents!"}, {"numero": 22, "texto": "Malheur à ceux qui ont de la bravoure pour boire du vin, Et de la vaillance pour mêler des liqueurs fortes;"}, {"numero": 23, "texto": "Qui justifient le coupable pour un présent, Et enlèvent aux innocents leurs droits!"}, {"numero": 24, "texto": "C''''est pourquoi, comme une langue de feu dévore le chaume, Et comme la flamme consume l''''herbe sèche, Ainsi leur racine sera comme de la pourriture, Et leur fleur se dissipera comme de la poussière; Car ils ont dédaigné la loi de l''''Eternel des armées, Et ils ont méprisé la parole du Saint d''''Israël."}, {"numero": 25, "texto": "C''''est pourquoi la colère de l''''Eternel s''''enflamme contre son peuple, Il étend sa main sur lui, et il le frappe; Les montagnes s''''ébranlent; Et les cadavres sont comme des balayures au milieu des rues. Malgré tout cela, sa colère ne s''''apaise point, Et sa main est encore étendue."}, {"numero": 26, "texto": "Il élève une bannière pour les peuples lointains, Et il en siffle un des extrémités de la terre: Et voici, il arrive avec promptitude et légèreté."}, {"numero": 27, "texto": "Nul n''''est fatigué, nul ne chancelle de lassitude, Personne ne sommeille, ni ne dort; Aucun n''''a la ceinture de ses reins détachée, Ni la courroie de ses souliers rompue."}, {"numero": 28, "texto": "Ses flèches sont aiguës, Et tous ses arcs tendus; Les sabots de ses chevaux ressemblent à des cailloux, Et les roues de ses chars à un tourbillon."}, {"numero": 29, "texto": "Son rugissement est comme celui d''''une lionne; Il rugit comme des lionceaux, il gronde, et saisit la proie, Il l''''emporte, et personne ne vient au secours."}, {"numero": 30, "texto": "En ce jour, il y aura près de lui un mugissement, Comme celui d''''une tempête sur mer; En regardant la terre, on ne verra que ténèbres, Avec des alternatives d''''angoisse et d''''espérance; Au ciel, l''''obscurité régnera."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 5, 'es', '[{"numero": 1, "texto": "AHORA cantaré por mi amado el cantar de mi amado á su viña. Tenía mi amado una viña en un recuesto, lugar fértil."}, {"numero": 2, "texto": "Habíala cercado, y despedregádola, y plantádola de vides escogidas: había edificado en medio de ella una torre, y también asentado un lagar en ella: y esperaba que llevase uvas, y llevó uvas silvestres."}, {"numero": 3, "texto": "Ahora pues, vecinos de Jerusalem y varones de Judá, juzgad ahora entre mí y mi viña."}, {"numero": 4, "texto": "¿Qué más se había de hacer á mi viña, que yo no haya hecho en ella? ¿Cómo, esperando yo que llevase uvas, ha llevado uvas silvestres?"}, {"numero": 5, "texto": "Os mostraré pues ahora lo que haré yo á mi viña: Quitaréle su vallado, y será para ser consumida; aportillaré su cerca, y será para ser hollada;"}, {"numero": 6, "texto": "Haré que quede desierta; no será podada ni cavada, y crecerá el cardo y las espinas: y aun á las nubes mandaré que no derramen lluvia sobre ella."}, {"numero": 7, "texto": "Ciertamente la viña de Jehová de los ejércitos es la casa de Israel, y los hombres de Judá planta suya deleitosa. Esperaba juicio, y he aquí vileza; justicia, y he aquí clamor."}, {"numero": 8, "texto": "¡Ay de los que juntan casa con casa, y allegan heredad á heredad hasta acabar el término! ¿Habitaréis vosotros solos en medio de la tierra?"}, {"numero": 9, "texto": "Ha llegado á mis oídos de parte de Jehová de los ejércitos, que las muchas casas han de quedar asoladas, sin morador las grandes y hermosas."}, {"numero": 10, "texto": "Y diez huebras de viña producirán un zaque, y treinta modios de simiente darán tres modios."}, {"numero": 11, "texto": "¡Ay de los que se levantan de mañana para seguir la embriaguez; que se están hasta la noche, hasta que el vino los enciende!"}, {"numero": 12, "texto": "Y en sus banquetes hay arpas, vihuelas, tamboriles, flautas, y vino; y no miran la obra de Jehová, ni consideran la obra de sus manos."}, {"numero": 13, "texto": "Por tanto mi pueblo fué llevado cautivo, porque no tuvo ciencia: y su gloria pereció de hambre, y su multitud se secó de sed."}, {"numero": 14, "texto": "Por eso ensanchó su interior el sepulcro, y sin medida extendió su boca; y allá descenderá la gloria de ellos, y su multitud, y su fausto, y el que en él se holgaba."}, {"numero": 15, "texto": "Y el hombre será humillado, y el varón será abatido, y bajados serán los ojos de los altivos."}, {"numero": 16, "texto": "Mas Jehová de los ejércitos será ensalzado en juicio, y el Dios Santo será santificado con justicia."}, {"numero": 17, "texto": "Y los corderos serán apacentados según su costumbre; y extraños comerán las gruesas desamparadas."}, {"numero": 18, "texto": "¡Ay de los que traen la iniquidad con cuerdas de vanidad, y el pecado como con coyundas de carreta,"}, {"numero": 19, "texto": "Los cuales dicen: Venga ya, apresúrese su obra, y veamos: acérquese, y venga el consejo del Santo de Israel, para que lo sepamos!"}, {"numero": 20, "texto": "¡Ay de los que á lo malo dicen bueno, y á lo bueno malo; que hacen de la luz tinieblas, y de las tinieblas luz; que ponen lo amargo por dulce, y lo dulce por amargo!"}, {"numero": 21, "texto": "¡Ay de los sabios en sus ojos, y de los que son prudentes delante de sí mismos!"}, {"numero": 22, "texto": "¡Ay de los que son valientes para beber vino, y hombres fuertes para mezclar bebida;"}, {"numero": 23, "texto": "Los que dan por justo al impío por cohechos, y al justo quitan su justicia!"}, {"numero": 24, "texto": "Por tanto, como la lengua del fuego consume las aristas, y la llama devora la paja, así será su raíz como pudrimiento, y su flor se desvanecerá como polvo: porque desecharon la ley de Jehová de los ejércitos, y abominaron la palabra del Santo de Israel."}, {"numero": 25, "texto": "Por esta causa se encendió el furor de Jehová contra su pueblo, y extendió contra él su mano, é hirióle; y se estremecieron los montes, y sus cadáveres fueron arrojados en medio de las calles. Con todo esto no ha cesado su furor, antes está su mano todavía extendida."}, {"numero": 26, "texto": "Y alzará pendón á gentes de lejos, y silbará al que está en el cabo de la tierra; y he aquí que vendrá pronto y velozmente."}, {"numero": 27, "texto": "No habrá entre ellos cansado, ni que vacile; ninguno se dormirá ni le tomará sueño; á ninguno se le desatará el cinto de los lomos, ni se le romperá la correa de sus zapatos."}, {"numero": 28, "texto": "Sus saetas amoladas, y todos sus arcos entesados; las uñas de sus caballos parecerán como de pedernal, y las ruedas de sus carros como torbellino."}, {"numero": 29, "texto": "Su bramido como de león; rugirá á manera de leoncillos, rechinará los dientes, y arrebatará la presa; la apañara, y nadie se la quitará."}, {"numero": 30, "texto": "Y bramará sobre él en aquel día como bramido de la mar: entonces mirará hacia la tierra, y he aquí tinieblas de tribulación, y en sus cielos se oscurecerá la luz."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 11, 'pt', '[{"numero": 1, "texto": "E uma vara brotará do tronco cortado de Jessé; e um ramo crescerá de suas raízes."}, {"numero": 2, "texto": "E repousará sobre ele o Espírito do SENHOR: o Espírito de sabedoria e de entendimento, o Espírito de conselho e força, o Espírito de conhecimento e temor ao SENHOR."}, {"numero": 3, "texto": "E seu prazer será no temor ao SENHOR; e não julgará segundo a vista de seus olhos, nem repreenderá segundo o ouvir de seus ouvidos."}, {"numero": 4, "texto": "Mas julgará com justiça aos pobres, e repreenderá com equidade aos humildes da terra; porém ferirá a terra com a vara de sua boca, e com o espírito de seus lábios matará ao perverso."}, {"numero": 5, "texto": "E a justiça será o cinto de sua cintura; a fidelidade o cinto de seus lombos."}, {"numero": 6, "texto": "E o lobo morará com o cordeiro, e o leopardo se deitará com o cabrito; e o bezerro, o filhote de leão, e o animal cevado [andarão] juntos, e um menino pequeno os guiará."}, {"numero": 7, "texto": "A vaca e a ursa se alimentarão juntas, seus filhos [juntos] se deitarão; e o leão comerá palha como o boi."}, {"numero": 8, "texto": "A criança que ainda mama brincará sobre a toca da serpente, e a que for desmamada porá sua mão na cova da víbora."}, {"numero": 9, "texto": "Não se fará mal nem dano algum em todo o meu santo monte, porque a terra se encherá do conhecimento do SENHOR, como as águas cobrem o mar."}, {"numero": 10, "texto": "E acontecerá naquele dia, que as nações buscarão a raiz de Jessé, posta como bandeira dos povos; e seu repouso será glorioso."}, {"numero": 11, "texto": "E acontecerá naquele dia, que o Senhor voltará a pôr sua mão para adquirir de novo aos restantes de seus povo, que restarem da Assíria, do Egito, Patros, Cuxe, Elão, Sinear, Hamate, e das ilhas do mar."}, {"numero": 12, "texto": "E levantará uma bandeira entre as nações, e juntará aos desterrados de Israel, e reunirá aos dispersos de Judá desde os quatro confins da terra."}, {"numero": 13, "texto": "E a inveja de Efraim terminará, e os adversários de Judá serão cortados; Efraim não invejará a Judá, e Judá não oprimirá a Efraim."}, {"numero": 14, "texto": "Em vez disso, voarão sobre os ombros dos filisteus ao ocidente, e juntos despojarão aos do oriente; porão suas mãos [sobre] Edom e Moabe, e os filhos de Amom lhes obedecerão."}, {"numero": 15, "texto": "E o SENHOR dividirá a porção de mar do Egito, e moverá sua mão contra o rio com a força de seu vento; e o ferirá em sete correntes, e fará com que se possa atravessá-lo com sandálias."}, {"numero": 16, "texto": "E haverá um caminho para os restantes de seu povo, que restarem da Assíria, assim como aconteceu a Israel, no dia em que subiu da terra do Egito."}]'::jsonb, 'Almeida Livre'),
  ('Is', 11, 'en', '[{"numero": 1, "texto": "And there shall come forth a rod out of the stem of Jesse, and a Branch shall grow out of his roots:"}, {"numero": 2, "texto": "And the spirit of the Lord shall rest upon him, the spirit of wisdom and understanding, the spirit of counsel and might, the spirit of knowledge and of the fear of the Lord;"}, {"numero": 3, "texto": "And shall make him of quick understanding in the fear of the Lord: and he shall not judge after the sight of his eyes, neither reprove after the hearing of his ears:"}, {"numero": 4, "texto": "But with righteousness shall he judge the poor, and reprove with equity for the meek of the earth: and he shall smite the earth: with the rod of his mouth, and with the breath of his lips shall he slay the wicked."}, {"numero": 5, "texto": "And righteousness shall be the girdle of his loins, and faithfulness the girdle of his reins."}, {"numero": 6, "texto": "The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them."}, {"numero": 7, "texto": "And the cow and the bear shall feed; their young ones shall lie down together: and the lion shall eat straw like the ox."}, {"numero": 8, "texto": "And the sucking child shall play on the hole of the asp, and the weaned child shall put his hand on the cockatrice'' den."}, {"numero": 9, "texto": "They shall not hurt nor destroy in all my holy mountain: for the earth shall be full of the knowledge of the Lord, as the waters cover the sea."}, {"numero": 10, "texto": "And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek: and his rest shall be glorious."}, {"numero": 11, "texto": "And it shall come to pass in that day, that the Lord shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea."}, {"numero": 12, "texto": "And he shall set up an ensign for the nations, and shall assemble the outcasts of Israel, and gather together the dispersed of Judah from the four corners of the earth."}, {"numero": 13, "texto": "The envy also of Ephraim shall depart, and the adversaries of Judah shall be cut off: Ephraim shall not envy Judah, and Judah shall not vex Ephraim."}, {"numero": 14, "texto": "But they shall fly upon the shoulders of the Philistines toward the west; they shall spoil them of the east together: they shall lay their hand upon Edom and Moab; and the children of Ammon shall obey them."}, {"numero": 15, "texto": "And the Lord shall utterly destroy the tongue of the Egyptian sea; and with his mighty wind shall he shake his hand over the river, and shall smite it in the seven streams, and make men go over dryshod."}, {"numero": 16, "texto": "And there shall be an highway for the remnant of his people, which shall be left, from Assyria; like as it was to Israel in the day that he came up out of the land of Egypt."}]'::jsonb, 'King James Version'),
  ('Is', 11, 'fr', '[{"numero": 1, "texto": "Puis un rameau sortira du tronc d''''Isaï, Et un rejeton naîtra de ses racines."}, {"numero": 2, "texto": "L''''Esprit de l''''Eternel reposera sur lui: Esprit de sagesse et d''''intelligence, Esprit de conseil et de force, Esprit de connaissance et de crainte de l''''Eternel."}, {"numero": 3, "texto": "Il respirera la crainte de l''''Eternel; Il ne jugera point sur l''''apparence, Il ne prononcera point sur un ouï-dire."}, {"numero": 4, "texto": "Mais il jugera les pauvres avec équité, Et il prononcera avec droiture sur les malheureux de la terre; Il frappera la terre de sa parole comme d''''une verge, Et du souffle de ses lèvres il fera mourir le méchant."}, {"numero": 5, "texto": "La justice sera la ceinture de ses flancs, Et la fidélité la ceinture de ses reins."}, {"numero": 6, "texto": "Le loup habitera avec l''''agneau, Et la panthère se couchera avec le chevreau; Le veau, le lionceau, et le bétail qu''''on engraisse, seront ensemble, Et un petit enfant les conduira."}, {"numero": 7, "texto": "La vache et l''''ourse auront un même pâturage, Leurs petits un même gîte; Et le lion, comme le boeuf, mangera de la paille."}, {"numero": 8, "texto": "Le nourrisson s''''ébattra sur l''''antre de la vipère, Et l''''enfant sevré mettra sa main dans la caverne du basilic."}, {"numero": 9, "texto": "Il ne se fera ni tort ni dommage Sur toute ma montagne sainte; Car la terre sera remplie de la connaissance de l''''Eternel, Comme le fond de la mer par les eaux qui le couvrent."}, {"numero": 10, "texto": "En ce jour, le rejeton d''''Isaï Sera là comme une bannière pour les peuples; Les nations se tourneront vers lui, Et la gloire sera sa demeure."}, {"numero": 11, "texto": "Dans ce même temps, le Seigneur étendra une seconde fois sa main, Pour racheter le reste de son peuple, Dispersé en Assyrie et en Egypte, A Pathros et en Ethiopie, A Elam, à Schinear et à Hamath, Et dans les îles de la mer."}, {"numero": 12, "texto": "Il élèvera une bannière pour les nations, Il rassemblera les exilés d''''Israël, Et il recueillera les dispersés de Juda, Des quatre extrémités de la terre."}, {"numero": 13, "texto": "La jalousie d''''Ephraïm disparaîtra, Et ses ennemis en Juda seront anéantis; Ephraïm ne sera plus jaloux de Juda, Et Juda ne sera plus hostile à Ephraïm."}, {"numero": 14, "texto": "Ils voleront sur l''''épaule des Philistins à l''''occident, Ils pilleront ensemble les fils de l''''Orient; Edom et Moab seront la proie de leurs mains, Et les fils d''''Ammon leur seront assujettis."}, {"numero": 15, "texto": "L''''Eternel desséchera la langue de la mer d''''Egypte, Et il lèvera sa main sur le fleuve, en soufflant avec violence: Il le partagera en sept canaux, Et on le traversera avec des souliers."}, {"numero": 16, "texto": "Et il y aura une route pour le reste de son peuple, Qui sera échappé de l''''Assyrie, Comme il y en eut une pour Israël, Le jour où il sortit du pays d''''Egypte."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 11, 'es', '[{"numero": 1, "texto": "Y SALDRÁ una vara del tronco de Isaí, y un vástago retoñará de sus raíces."}, {"numero": 2, "texto": "Y reposará sobre él el espíritu de Jehová; espíritu de sabiduría y de inteligencia, espíritu de consejo y de fortaleza, espíritu de conocimiento y de temor de Jehová."}, {"numero": 3, "texto": "Y harále entender diligente en el temor de Jehová. No juzgará según la vista de sus ojos, ni argüirá por lo que oyeren sus oídos;"}, {"numero": 4, "texto": "Sino que juzgará con justicia á los pobres, y argüirá con equidad por los mansos de la tierra: y herirá la tierra con la vara de su boca, y con el espíritu de sus labios matará al impío."}, {"numero": 5, "texto": "Y será la justicia cinto de sus lomos, y la fidelidad ceñidor de sus riñones."}, {"numero": 6, "texto": "Morará el lobo con el cordero, y el tigre con el cabrito se acostará: el becerro y el león y la bestia doméstica andarán juntos, y un niño los pastoreará."}, {"numero": 7, "texto": "La vaca y la osa pacerán, sus crías se echarán juntas; y el león como el buey comerá paja."}, {"numero": 8, "texto": "Y el niño de teta se entretendrá sobre la cueva del áspid, y el recién destetado extenderá su mano sobre la caverna del basilisco."}, {"numero": 9, "texto": "No harán mal ni dañarán en todo mi santo monte; porque la tierra será llena del conocimiento de Jehová, como cubren la mar las aguas."}, {"numero": 10, "texto": "Y acontecerá en aquel tiempo que la raíz de Isaí, la cual estará puesta por pendón á los pueblos, será buscada de las gentes; y su holganza será gloria."}, {"numero": 11, "texto": "Asimismo acontecerá en aquel tiempo, que Jehová tornará á poner otra vez su mano para poseer las reliquias de su pueblo que fueron dejadas de Assur, y de Egipto, y de Parthia, y de Etiopía, y de Persia, y de Caldea, y de Amath, y de las Islas de la mar."}, {"numero": 12, "texto": "Y levantará pendón á las gentes, y juntará los desterrados de Israel, y reunirá los esparcidos de Judá de los cuatro cantones de la tierra."}, {"numero": 13, "texto": "Y se disipará la envidia de Ephraim, y los enemigos de Judá serán talados. Ephraim no tendrá envidia contra Judá, ni Judá afligirá á Ephraim;"}, {"numero": 14, "texto": "Mas volarán sobre los hombros de los Filisteos al occidente, meterán también á saco á los de oriente: Edom y Moab les servirán, y los hijos de Ammón les darán obediencia."}, {"numero": 15, "texto": "Y secará Jehová la lengua de la mar de Egipto; y levantará su mano con fortaleza de su espíritu sobre el río, y herirálo en sus siete brazos, y hará que pasen por él con zapatos."}, {"numero": 16, "texto": "Y habrá camino para las reliquias de su pueblo, las que quedaron de Assur, de la manera que lo hubo para Israel el día que subió de la tierra de Egipto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 26, 'pt', '[{"numero": 1, "texto": "Naquele dia, se cantará este cântico na terra de Judá: Temos uma cidade forte! [Deus lhe] pôs a salvação por muros e antemuros."}, {"numero": 2, "texto": "Abri as portas, para que por elas entre a nação justa, que guarda fidelidades."}, {"numero": 3, "texto": "Tu guardarás em completa paz aquele que tem firme entendimento, pois ele confia em ti."}, {"numero": 4, "texto": "Confiai no SENHOR para sempre, pois no SENHOR DEUS está a rocha eterna."}, {"numero": 5, "texto": "Pois ele abate aos que habitam em lugares altos, a cidade elevada; certamente ele a abaixará até o chão, e a derrubará até o pó."}, {"numero": 6, "texto": "Pés a pisotearão; os pés dos afligidos, os passos dos pobres."}, {"numero": 7, "texto": "O caminho do justo é todo plano; tu [que és] reto nivelas o andar do justo."}, {"numero": 8, "texto": "Também no caminho dos teus juízos esperamos em ti; em teu nome e em tua lembrança está o desejo de [nossa] alma."}, {"numero": 9, "texto": "Com minha alma te desejei de noite, e [com] meu espírito dentro de mim te busquei de madrugada; pois quando teus juízos [estão] sobre a terra, os moradores do mundo aprendem a justiça."}, {"numero": 10, "texto": "[Ainda] que se faça favor ao perverso, nem assim ele aprende a justiça; [até] na terra dos corretos ele pratica maldade, e não dá atenção à majestade do SENHOR."}, {"numero": 11, "texto": "Ó SENHOR, tua mão está levantada, mas eles não [a] veem; [porém] eles verão e serão envergonhados pelo zelo [que tens] do [teu] povo; e o fogo consumirá a teus adversários."}, {"numero": 12, "texto": "Ó SENHOR, tu nos fornecerá paz; pois todos os nossos feitos tu fizeste por nós."}, {"numero": 13, "texto": "Ó SENHOR nosso Deus, outros senhores fora de ti nos dominaram; mas somente em ti, em teu nome, mantínhamos nossos pensamentos."}, {"numero": 14, "texto": "Eles estão mortos, não [voltarão] a viver; fantasmas não ressuscitarão; por isso tu os visitaste e os destruíste, e eliminaste toda a memória deles."}, {"numero": 15, "texto": "Tu, SENHOR, engrandeceste esta nação; engrandeceste esta nação, [e] te fizeste glorioso; alargaste os limites da terra."}, {"numero": 16, "texto": "Ó SENHOR, na aflição eles te buscaram; [quando] tu os castigaste, uma oração eles sussurraram."}, {"numero": 17, "texto": "Tal como a grávida quando chega a hora do parto, sofre e dá gritos por suas dores, assim fomos nós diante de tua presença, SENHOR."}, {"numero": 18, "texto": "Concebemos e tivemos dores, porém geramos [nada além] de vento. Não trouxemos libertação à terra, nem os moradores do mundo caíram."}, {"numero": 19, "texto": "Os teus mortos viverão, [junto com] meu cadáver, [assim] ressuscitarão; festejai e sede alegres, vós que habitais no pó! Pois o teu orvalho [é] orvalho de luz, e a terra gerará de si [seus] mortos."}, {"numero": 20, "texto": "Vai, ó povo meu; entra em teus quartos, e fecha tuas portas ao redor de ti; esconde-te por um momento, até que a ira tenha passado."}, {"numero": 21, "texto": "Porque eis que o SENHOR sairá de seu lugar para punir a maldade dos moradores da terra sobre eles; e a terra mostrará seus sangues, e não mais cobrirá seus mortos."}]'::jsonb, 'Almeida Livre'),
  ('Is', 26, 'en', '[{"numero": 1, "texto": "In that day shall this song be sung in the land of Judah; We have a strong city; salvation will God appoint for walls and bulwarks."}, {"numero": 2, "texto": "Open ye the gates, that the righteous nation which keepeth the truth may enter in."}, {"numero": 3, "texto": "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee."}, {"numero": 4, "texto": "Trust ye in the Lord for ever: for in the Lord Jehovah is everlasting strength:"}, {"numero": 5, "texto": "For he bringeth down them that dwell on high; the lofty city, he layeth it low; he layeth it low, even to the ground; he bringeth it even to the dust."}, {"numero": 6, "texto": "The foot shall tread it down, even the feet of the poor, and the steps of the needy."}, {"numero": 7, "texto": "The way of the just is uprightness: thou, most upright, dost weigh the path of the just."}, {"numero": 8, "texto": "Yea, in the way of thy judgments, O Lord, have we waited for thee; the desire of our soul is to thy name, and to the remembrance of thee."}, {"numero": 9, "texto": "With my soul have I desired thee in the night; yea, with my spirit within me will I seek thee early: for when thy judgments are in the earth, the inhabitants of the world will learn righteousness."}, {"numero": 10, "texto": "Let favour be shewed to the wicked, yet will he not learn righteousness: in the land of uprightness will he deal unjustly, and will not behold the majesty of the Lord."}, {"numero": 11, "texto": "Lord, when thy hand is lifted up, they will not see: but they shall see, and be ashamed for their envy at the people; yea, the fire of thine enemies shall devour them."}, {"numero": 12, "texto": "Lord, thou wilt ordain peace for us: for thou also hast wrought all our works in us."}, {"numero": 13, "texto": "O Lord our God, other lords beside thee have had dominion over us: but by thee only will we make mention of thy name."}, {"numero": 14, "texto": "They are dead, they shall not live; they are deceased, they shall not rise: therefore hast thou visited and destroyed them, and made all their memory to perish."}, {"numero": 15, "texto": "Thou hast increased the nation, O Lord, thou hast increased the nation: thou art glorified: thou hadst removed it far unto all the ends of the earth."}, {"numero": 16, "texto": "Lord, in trouble have they visited thee, they poured out a prayer when thy chastening was upon them."}, {"numero": 17, "texto": "Like as a woman with child, that draweth near the time of her delivery, is in pain, and crieth out in her pangs; so have we been in thy sight, O Lord."}, {"numero": 18, "texto": "We have been with child, we have been in pain, we have as it were brought forth wind; we have not wrought any deliverance in the earth; neither have the inhabitants of the world fallen."}, {"numero": 19, "texto": "Thy dead men shall live, together with my dead body shall they arise. Awake and sing, ye that dwell in dust: for thy dew is as the dew of herbs, and the earth shall cast out the dead."}, {"numero": 20, "texto": "Come, my people, enter thou into thy chambers, and shut thy doors about thee: hide thyself as it were for a little moment, until the indignation be overpast."}, {"numero": 21, "texto": "For, behold, the Lord cometh out of his place to punish the inhabitants of the earth for their iniquity: the earth also shall disclose her blood, and shall no more cover her slain."}]'::jsonb, 'King James Version'),
  ('Is', 26, 'fr', '[{"numero": 1, "texto": "En ce jour, on chantera ce cantique dans le pays de Juda: Nous avons une ville forte; Il nous donne le salut pour murailles et pour rempart."}, {"numero": 2, "texto": "Ouvrez les portes, Laissez entrer la nation juste et fidèle."}, {"numero": 3, "texto": "A celui qui est ferme dans ses sentiments Tu assures la paix, la paix, Parce qu''''il se confie en toi."}, {"numero": 4, "texto": "Confiez-vous en l''''Eternel à perpétuité, Car l''''Eternel, l''''Eternel est le rocher des siècles."}, {"numero": 5, "texto": "Il a renversé ceux qui habitaient les hauteurs, Il a abaissé la ville superbe; Il l''''a abaissée jusqu''''à terre, Il lui a fait toucher la poussière."}, {"numero": 6, "texto": "Elle est foulée aux pieds, Aux pieds des pauvres, sous les pas des misérables."}, {"numero": 7, "texto": "Le chemin du juste est la droiture; Toi qui es juste, tu aplanis le sentier du juste."}, {"numero": 8, "texto": "Aussi nous t''''attendons, ô Eternel! sur la voie de tes jugements; Notre âme soupire après ton nom et après ton souvenir."}, {"numero": 9, "texto": "Mon âme te désire pendant la nuit, Et mon esprit te cherche au dedans de moi; Car, lorsque tes jugements s''''exercent sur la terre, Les habitants du monde apprennent la justice."}, {"numero": 10, "texto": "Si l''''on fait grâce au méchant, il n''''apprend pas la justice, Il se livre au mal dans le pays de la droiture, Et il n''''a point égard à la majesté de Dieu."}, {"numero": 11, "texto": "Eternel, ta main est puissante: Ils ne l''''aperçoivent pas. Ils verront ton zèle pour le peuple, et ils en seront confus; Le feu consumera tes ennemis."}, {"numero": 12, "texto": "Eternel, tu nous donnes la paix; Car tout ce que nous faisons, C''''est toi qui l''''accomplis pour nous."}, {"numero": 13, "texto": "Eternel, notre Dieu, d''''autres maîtres que toi ont dominé sur nous; Mais c''''est grâce à toi seul que nous invoquons ton nom."}, {"numero": 14, "texto": "Ceux qui sont morts ne revivront pas, Des ombres ne se relèveront pas; Car tu les as châtiés, tu les as anéantis, Et tu en as détruit tout souvenir."}, {"numero": 15, "texto": "Multiplie le peuple, ô Eternel! Multiplie le peuple, manifeste ta gloire; Recule toutes les limites du pays."}, {"numero": 16, "texto": "Eternel, ils t''''ont cherché, quand ils étaient dans la détresse; Ils se sont répandus en prières, quand tu les as châtiés."}, {"numero": 17, "texto": "Comme une femme enceinte, sur le point d''''accoucher, Se tord et crie au milieu de ses douleurs, Ainsi avons-nous été, loin de ta face, ô Eternel!"}, {"numero": 18, "texto": "Nous avons conçu, nous avons éprouvé des douleurs, Et, quand nous enfantons, ce n''''est que du vent: Le pays n''''est pas sauvé, Et ses habitants ne sont pas nés."}, {"numero": 19, "texto": "Que tes morts revivent! Que mes cadavres se relèvent! -Réveillez-vous et tressaillez de joie, habitants de la poussière! Car ta rosée est une rosée vivifiante, Et la terre redonnera le jour aux ombres."}, {"numero": 20, "texto": "Va, mon peuple, entre dans ta chambre, Et ferme la porte derrière toi; Cache-toi pour quelques instants, Jusqu''''à ce que la colère soit passée."}, {"numero": 21, "texto": "Car voici, l''''Eternel sort de sa demeure, Pour punir les crimes des habitants de la terre; Et la terre mettra le sang à nu, Elle ne couvrira plus les meurtres."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 26, 'es', '[{"numero": 1, "texto": "EN aquel día cantarán este cantar en tierra de Judá: Fuerte ciudad tenemos: salud puso Dios por muros y antemuro."}, {"numero": 2, "texto": "Abrid las puertas, y entrará la gente justa, guardadora de verdades."}, {"numero": 3, "texto": "Tú le guardarás en completa paz, cuyo pensamiento en ti persevera; porque en ti se ha confiado."}, {"numero": 4, "texto": "Confiad en Jehová perpetuamente: porque en el Señor Jehová está la fortaleza de los siglos."}, {"numero": 5, "texto": "Porque derribó los que moraban en lugar sublime: humilló la ciudad ensalzada, humillóla hasta la tierra, derribóla hasta el polvo."}, {"numero": 6, "texto": "Hollarála pie, los pies del afligido, los pasos de los menesterosos."}, {"numero": 7, "texto": "El camino del justo es rectitud: Tú, Recto, pesas el camino del justo."}, {"numero": 8, "texto": "También en el camino de tus juicios, oh Jehová, te hemos esperado: á tu nombre y á tu memoria es el deseo del alma."}, {"numero": 9, "texto": "Con mi alma te he deseado en la noche; y en tanto que me durare el espíritu en medio de mí, madrugaré á buscarte: porque luego que hay juicios tuyos en la tierra, los moradores del mundo aprenden justicia."}, {"numero": 10, "texto": "Alcanzará piedad el impío, y no aprenderá justicia; en tierra de rectitud hará iniquidad, y no mirará á la majestad de Jehová."}, {"numero": 11, "texto": "Jehová, bien que se levante tu mano, no ven: verán al cabo, y se avergonzarán los que envidian á tu pueblo; y á tus enemigos fuego los consumirá."}, {"numero": 12, "texto": "Jehová, tú nos depararás paz; porque también obraste en nosotros todas nuestras obras."}, {"numero": 13, "texto": "Jehová Dios nuestro, señores se han enseñoreado de nosotros fuera de ti; mas en ti solamente nos acordaremos de tu nombre."}, {"numero": 14, "texto": "Muertos son, no vivirán: han fallecido, no resucitarán: porque los visitaste, y destruiste, y deshiciste toda su memoria."}, {"numero": 15, "texto": "Añadiste al pueblo, oh Jehová, añadiste al pueblo: hicístete glorioso: extendístelo hasta todos los términos de la tierra."}, {"numero": 16, "texto": "Jehová, en la tribulación te buscaron: derramaron oración cuando los castigaste."}, {"numero": 17, "texto": "Como la preñada cuando se acerca el parto gime, y da gritos con sus dolores, así hemos sido delante de ti, oh Jehová."}, {"numero": 18, "texto": "Concebimos, tuvimos dolores de parto, parimos como viento: salud ninguna hicimos en la tierra, ni cayeron los moradores del mundo."}, {"numero": 19, "texto": "Tus muertos vivirán; junto con mi cuerpo muerto resucitarán. ¡Despertad y cantad, moradores del polvo! porque tu rocío, cual rocío de hortalizas; y la tierra echará los muertos."}, {"numero": 20, "texto": "Anda, pueblo mío, éntrate en tus aposentos, cierra tras ti tus puertas; escóndete un poquito, por un momento, en tanto que pasa la ira."}, {"numero": 21, "texto": "Porque he aquí que Jehová sale de su lugar, para visitar la maldad del morador de la tierra contra él; y la tierra descubrirá sus sangres, y no más encubrirá sus muertos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 35, 'pt', '[{"numero": 1, "texto": "O deserto e o lugar seco terão prazer disto; e o lugar desabitado se alegrará e florescerá como a rosa."}, {"numero": 2, "texto": "Abundantemente florescerá, e também se encherá de alegria e júbilo; a glória do Líbano lhe será dada, a honra do Carmelo e de Sarom; eles verão a glória do SENHOR, a honra de nosso Deus."}, {"numero": 3, "texto": "Fortalecei as mãos fracas, e firmai os joelhos que tremem."}, {"numero": 4, "texto": "Dizei aos perturbados de coração: Fortalecei-vos! Não temais! Eis que nosso Deus virá para a vingança, aos pagamentos de Deus; ele virá e vos salvará."}, {"numero": 5, "texto": "Então os olhos dos cegos serão abertos, e os ouvidos dos surdos se abrirão."}, {"numero": 6, "texto": "Então os aleijados saltarão como cervos, e a língua dos mudos falará alegremente; porque águas arrebentarão no deserto, e ribeiros no lugar desabitado."}, {"numero": 7, "texto": "E a terra seca se tornará em lagoas, e a terra sedenta em mananciais de águas; nas habitações em que repousavam os chacais, haverá erva com canas e juncos."}, {"numero": 8, "texto": "E ali haverá uma estrada, e um caminho que se chamará caminho da santidade; o impuro não passará por ele, mas será para os [que podem] andar pelo caminho; até mesmo os tolos [que por ele passarem] não errarão."}, {"numero": 9, "texto": "Ali não haverá leão, nem animal selvagem subirá a ele, nem se achará nele; porém os redimidos [por ele] andarão."}, {"numero": 10, "texto": "E os resgatados do SENHOR voltarão, e virão a Sião com júbilo, e alegria eterna haverá sobre suas cabeças; eles terão prazer e alegria, e a tristeza e o gemido [deles] fugirão."}]'::jsonb, 'Almeida Livre'),
  ('Is', 35, 'en', '[{"numero": 1, "texto": "The wilderness and the solitary place shall be glad for them; and the desert shall rejoice, and blossom as the rose."}, {"numero": 2, "texto": "It shall blossom abundantly, and rejoice even with joy and singing: the glory of Lebanon shall be given unto it, the excellency of Carmel and Sharon, they shall see the glory of the Lord, and the excellency of our God."}, {"numero": 3, "texto": "Strengthen ye the weak hands, and confirm the feeble knees."}, {"numero": 4, "texto": "Say to them that are of a fearful heart, Be strong, fear not: behold, your God will come with vengeance, even God with a recompence; he will come and save you."}, {"numero": 5, "texto": "Then the eyes of the blind shall be opened, and the ears of the deaf shall be unstopped."}, {"numero": 6, "texto": "Then shall the lame man leap as an hart, and the tongue of the dumb sing: for in the wilderness shall waters break out, and streams in the desert."}, {"numero": 7, "texto": "And the parched ground shall become a pool, and the thirsty land springs of water: in the habitation of dragons, where each lay, shall be grass with reeds and rushes."}, {"numero": 8, "texto": "And an highway shall be there, and a way, and it shall be called The way of holiness; the unclean shall not pass over it; but it shall be for those: the wayfaring men, though fools, shall not err therein."}, {"numero": 9, "texto": "No lion shall be there, nor any ravenous beast shall go up thereon, it shall not be found there; but the redeemed shall walk there:"}, {"numero": 10, "texto": "And the ransomed of the Lord shall return, and come to Zion with songs and everlasting joy upon their heads: they shall obtain joy and gladness, and sorrow and sighing shall flee away."}]'::jsonb, 'King James Version'),
  ('Is', 35, 'fr', '[{"numero": 1, "texto": "Le désert et le pays aride se réjouiront; La solitude s''''égaiera, et fleurira comme un narcisse;"}, {"numero": 2, "texto": "Elle se couvrira de fleurs, et tressaillira de joie, Avec chants d''''allégresse et cris de triomphe; La gloire du Liban lui sera donnée, La magnificence du Carmel et de Saron. Ils verront la gloire de l''''Eternel, la magnificence de notre Dieu."}, {"numero": 3, "texto": "Fortifiez les mains languissantes, Et affermissez les genoux qui chancellent;"}, {"numero": 4, "texto": "Dites à ceux qui ont le coeur troublé: Prenez courage, ne craignez point; Voici votre Dieu, la vengeance viendra, La rétribution de Dieu; Il viendra lui-même, et vous sauvera."}, {"numero": 5, "texto": "Alors s''''ouvriront les yeux des aveugles, S''''ouvriront les oreilles des sourds;"}, {"numero": 6, "texto": "Alors le boiteux sautera comme un cerf, Et la langue du muet éclatera de joie. Car des eaux jailliront dans le désert, Et des ruisseaux dans la solitude;"}, {"numero": 7, "texto": "Le mirage se changera en étang Et la terre desséchée en sources d''''eaux; Dans le repaire qui servait de gîte aux chacals, Croîtront des roseaux et des joncs."}, {"numero": 8, "texto": "Il y aura là un chemin frayé, une route, Qu''''on appellera la voie sainte; Nul impur n''''y passera; elle sera pour eux seuls; Ceux qui la suivront, même les insensés, ne pourront s''''égarer."}, {"numero": 9, "texto": "Sur cette route, point de lion; Nulle bête féroce ne la prendra, Nulle ne s''''y rencontrera; Les délivrés y marcheront."}, {"numero": 10, "texto": "Les rachetés de l''''Eternel retourneront, Ils iront à Sion avec chants de triomphe, Et une joie éternelle couronnera leur tête; L''''allégresse et la joie s''''approcheront, La douleur et les gémissements s''''enfuiront."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 35, 'es', '[{"numero": 1, "texto": "ALEGRARSE han el desierto y la soledad: el yermo se gozará, y florecerá como la rosa."}, {"numero": 2, "texto": "Florecerá profusamente, y también se alegrará y cantará con júbilo: la gloria del Líbano le será dada, la hermosura de Carmel y de Sarón. Ellos verán la gloria de Jehová, la hermosura del Dios nuestro."}, {"numero": 3, "texto": "Confortad á las manos cansadas, roborad las vacilantes rodillas."}, {"numero": 4, "texto": "Decid á los de corazón apocado: Confortaos, no temáis: he aquí que vuestro Dios viene con venganza, con pago; el mismo Dios vendrá, y os salvará."}, {"numero": 5, "texto": "Entonces los ojos de los ciegos serán abiertos, y los oídos de los sordos se abrirán."}, {"numero": 6, "texto": "Entonces el cojo saltará como un ciervo, y cantará la lengua del mudo; porque aguas serán cavadas en el desierto, y torrentes en la soledad."}, {"numero": 7, "texto": "El lugar seco será tornado en estanque, y el secadal en manaderos de aguas; en la habitación de chacales, en su cama, será lugar de cañas y de juncos."}, {"numero": 8, "texto": "Y habrá allí calzada y camino, y será llamado Camino de Santidad; no pasará por él inmundo; y habrá para ellos en él quien los acompañe, de tal manera que los insensatos no yerren."}, {"numero": 9, "texto": "No habrá allí león, ni bestia fiera subirá por él, ni allí se hallará, para que caminen los redimidos."}, {"numero": 10, "texto": "Y los redimidos de Jehová volverán, y vendrán á Sión con alegría; y gozo perpetuo será sobre sus cabezas: y retendrán el gozo y alegría, y huirá la tristeza y el gemido."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 40, 'pt', '[{"numero": 1, "texto": "Consolai, consolai a meu povo, diz vosso Deus."}, {"numero": 2, "texto": "Falai ao coração de Jerusalém, e proclamai a ela, que seu esforço de guerra está terminado, que sua perversidade está perdoada; porque já recebeu [punição] em dobro da mão do SENHOR por todo os seus pecados."}, {"numero": 3, "texto": "Voz do que clama no deserto: Preparai o caminho do SENHOR; endireitai na terra estéril vereda ao nosso Deus."}, {"numero": 4, "texto": "Todo vale será levantado, e todo monte e morro serão abaixados; e o torto se endireitará, e o [terreno] acidentado se tornará plano."}, {"numero": 5, "texto": "E a glória do SENHOR se manifestará; e toda carne juntamente verá; pois [assim] falou a boca do SENHOR."}, {"numero": 6, "texto": "Uma voz: Clama!E ele disse: O que clamarei? Que toda carne é erva, e toda a sua bondade como as flores do campo."}, {"numero": 7, "texto": "A erva se seca, as flores caem, porque o Espírito do SENHOR nelas sopra; verdadeiramente o povo é erva."}, {"numero": 8, "texto": "A erva se seca, as flores caem; porém a palavra do nosso Deus continua firme para sempre."}, {"numero": 9, "texto": "Ó Sião, que anuncias boas novas, sobe até um monte alto! Ó Jerusalém, que anuncias boas novas, levanta tua voz com força; levanta-a, não temas; dize as cidades de Judá: Eis [aqui] o vosso Deus!"}, {"numero": 10, "texto": "Eis que o Senhor DEUS virá com poder; e seu braço governará por ele; eis que sua retribuição [virá] com ele, e seu pagamento diante de si."}, {"numero": 11, "texto": "Como pastor ele apascentará seu rebanho; em seus braços recolherá aos cordeirinhos, e os levará em seu colo; ele guiará mansamente as que tiveram filhotes."}, {"numero": 12, "texto": "Quem mediu com seu punho as águas, e tomou a medida dos céus aos palmos? E [quem] recolheu numa caixa de medida o pó da terra, e pesou os montes com pesos, e os morros com balanças?"}, {"numero": 13, "texto": "Quem guiou o Espírito do SENHOR? E que conselheiro o ensinou?"}, {"numero": 14, "texto": "Com quem ele tomou conselho? [Quem] lhe deu entendimento, e lhe ensinou o caminho do juízo, e lhe ensinou conhecimento, e lhe mostrou o caminho do entendimento?"}, {"numero": 15, "texto": "Eis que as nações [lhe] são consideradas como uma gota de balde, e como o pó miúdo das balanças; eis que ele levanta as ilhas como poeira."}, {"numero": 16, "texto": "Nem [todo] o Líbano seria suficiente para o fogo, nem seus animais bastam para um holocausto."}, {"numero": 17, "texto": "Todas as nações são como nada perante ele; menos que nada e vazio ele as considera."}, {"numero": 18, "texto": "A quem, pois, comparareis a Deus? Ou que semelhança atribuireis a ele?"}, {"numero": 19, "texto": "O artífice funde a imagem, e o ourives a cobre de ouro, e cadeias de prata [lhe] funde."}, {"numero": 20, "texto": "O empobrecido, que não tem o que oferecer, escolhe madeira que não se estraga, [e] busca um artífice habilidoso, para preparar uma imagem que não se mova."}, {"numero": 21, "texto": "Por acaso não sabeis? Por acaso não ouvis? Ou desde o princípio não vos disseram? Por acaso não tendes entendido desde os fundamentos da terra?"}, {"numero": 22, "texto": "Ele é o que está sentado sobre o globo da terra, cujos moradores são [para ele] como gafanhotos; ele é o que estende os céus como uma cortina, e os estica como uma tenda, para [neles] habitar."}, {"numero": 23, "texto": "Ele é o que torna os príncipes em nada, [e] faz juízes da terra serem como o vazio."}, {"numero": 24, "texto": "Mal foram plantados, mal foram semeados, mal seu caule forma raízes na terra; e [logo] ele sopra neles, e se secam, e um vento forte os leva como palha fina."}, {"numero": 25, "texto": "A quem, pois, me comparareis, que eu lhe seja semelhante?,diz o Santo."}, {"numero": 26, "texto": "Levantai vossos olhos ao alto, e vede quem criou estas coisas, que faz sair numerado seu exército; e chama a todos eles pelos nomes, pela grandeza de [suas] forças, e por ser forte em poder, nenhuma [delas] faltará."}, {"numero": 27, "texto": "Por que dizes, ó Jacó, e falas, ó Israel: Meu caminho está escondido do SENHOR, e meu juízo passa longe de meu Deus?"}, {"numero": 28, "texto": "Por acaso não sabes, nem ouviste, que o eterno Deus, o SENHOR, o criador dos confins da terra, não se cansa, nem se fatiga, e que seu entendimento é incompreensível?"}, {"numero": 29, "texto": "Ele dá força ao cansado, e multiplica as forças daquele que não tem vigor."}, {"numero": 30, "texto": "Até os jovens se cansam e se fatigam; e os rapazes caem;"}, {"numero": 31, "texto": "Mas os que confiam no SENHOR renovarão as forças, subirão com asas como águias; correrão, e não se cansarão; caminharão, e não se fatigarão."}]'::jsonb, 'Almeida Livre'),
  ('Is', 40, 'en', '[{"numero": 1, "texto": "Comfort ye, comfort ye my people, saith your God."}, {"numero": 2, "texto": "Speak ye comfortably to Jerusalem, and cry unto her, that her warfare is accomplished, that her iniquity is pardoned: for she hath received of the Lord''s hand double for all her sins."}, {"numero": 3, "texto": "The voice of him that crieth in the wilderness, Prepare ye the way of the Lord, make straight in the desert a highway for our God."}, {"numero": 4, "texto": "Every valley shall be exalted, and every mountain and hill shall be made low: and the crooked shall be made straight, and the rough places plain:"}, {"numero": 5, "texto": "And the glory of the Lord shall be revealed, and all flesh shall see it together: for the mouth of the Lord hath spoken it."}, {"numero": 6, "texto": "The voice said, Cry. And he said, What shall I cry? All flesh is grass, and all the goodliness thereof is as the flower of the field:"}, {"numero": 7, "texto": "The grass withereth, the flower fadeth: because the spirit of the Lord bloweth upon it: surely the people is grass."}, {"numero": 8, "texto": "The grass withereth, the flower fadeth: but the word of our God shall stand for ever."}, {"numero": 9, "texto": "O Zion, that bringest good tidings, get thee up into the high mountain; O Jerusalem, that bringest good tidings, lift up thy voice with strength; lift it up, be not afraid; say unto the cities of Judah, Behold your God!"}, {"numero": 10, "texto": "Behold, the Lord God will come with strong hand, and his arm shall rule for him: behold, his reward is with him, and his work before him."}, {"numero": 11, "texto": "He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom, and shall gently lead those that are with young."}, {"numero": 12, "texto": "Who hath measured the waters in the hollow of his hand, and meted out heaven with the span, and comprehended the dust of the earth in a measure, and weighed the mountains in scales, and the hills in a balance?"}, {"numero": 13, "texto": "Who hath directed the Spirit of the Lord, or being his counsellor hath taught him?"}, {"numero": 14, "texto": "With whom took he counsel, and who instructed him, and taught him in the path of judgment, and taught him knowledge, and shewed to him the way of understanding?"}, {"numero": 15, "texto": "Behold, the nations are as a drop of a bucket, and are counted as the small dust of the balance: behold, he taketh up the isles as a very little thing."}, {"numero": 16, "texto": "And Lebanon is not sufficient to burn, nor the beasts thereof sufficient for a burnt offering."}, {"numero": 17, "texto": "All nations before him are as nothing; and they are counted to him less than nothing, and vanity."}, {"numero": 18, "texto": "To whom then will ye liken God? or what likeness will ye compare unto him?"}, {"numero": 19, "texto": "The workman melteth a graven image, and the goldsmith spreadeth it over with gold, and casteth silver chains."}, {"numero": 20, "texto": "He that is so impoverished that he hath no oblation chooseth a tree that will not rot; he seeketh unto him a cunning workman to prepare a graven image, that shall not be moved."}, {"numero": 21, "texto": "Have ye not known? have ye not heard? hath it not been told you from the beginning? have ye not understood from the foundations of the earth?"}, {"numero": 22, "texto": "It is he that sitteth upon the circle of the earth, and the inhabitants thereof are as grasshoppers; that stretcheth out the heavens as a curtain, and spreadeth them out as a tent to dwell in:"}, {"numero": 23, "texto": "That bringeth the princes to nothing; he maketh the judges of the earth as vanity."}, {"numero": 24, "texto": "Yea, they shall not be planted; yea, they shall not be sown: yea, their stock shall not take root in the earth: and he shall also blow upon them, and they shall wither, and the whirlwind shall take them away as stubble."}, {"numero": 25, "texto": "To whom then will ye liken me, or shall I be equal? saith the Holy One."}, {"numero": 26, "texto": "Lift up your eyes on high, and behold who hath created these things, that bringeth out their host by number: he calleth them all by names by the greatness of his might, for that he is strong in power; not one faileth."}, {"numero": 27, "texto": "Why sayest thou, O Jacob, and speakest, O Israel, My way is hid from the Lord, and my judgment is passed over from my God?"}, {"numero": 28, "texto": "Hast thou not known? hast thou not heard, that the everlasting God, the Lord, the Creator of the ends of the earth, fainteth not, neither is weary? there is no searching of his understanding."}, {"numero": 29, "texto": "He giveth power to the faint; and to them that have no might he increaseth strength."}, {"numero": 30, "texto": "Even the youths shall faint and be weary, and the young men shall utterly fall:"}, {"numero": 31, "texto": "But they that wait upon the Lord shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint."}]'::jsonb, 'King James Version'),
  ('Is', 40, 'fr', '[{"numero": 1, "texto": "Consolez, consolez mon peuple, Dit votre Dieu."}, {"numero": 2, "texto": "Parlez au coeur de Jérusalem, et criez lui Que sa servitude est finie, Que son iniquité est expiée, Qu''''elle a reçu de la main de l''''Eternel Au double de tous ses péchés."}, {"numero": 3, "texto": "Une voix crie: Préparez au désert le chemin de l''''Eternel, Aplanissez dans les lieux arides Une route pour notre Dieu."}, {"numero": 4, "texto": "Que toute vallée soit exhaussée, Que toute montagne et toute colline soient abaissées! Que les coteaux se changent en plaines, Et les défilés étroits en vallons!"}, {"numero": 5, "texto": "Alors la gloire de l''''Eternel sera révélée, Et au même instant toute chair la verra; Car la bouche de l''''Eternel a parlé."}, {"numero": 6, "texto": "Une voix dit: Crie! -Et il répond: Que crierai-je? Toute chair est comme l''''herbe, Et tout son éclat comme la fleur des champs."}, {"numero": 7, "texto": "L''''herbe sèche, la fleur tombe, Quand le vent de l''''Eternel souffle dessus. -Certainement le peuple est comme l''''herbe:"}, {"numero": 8, "texto": "L''''herbe sèche, la fleur tombe; Mais la parole de notre Dieu subsiste éternellement."}, {"numero": 9, "texto": "Monte sur une haute montagne, Sion, pour publier la bonne nouvelle; Elève avec force ta voix, Jérusalem, pour publier la bonne nouvelle; Elève ta voix, ne crains point, Dis aux villes de Juda: Voici votre Dieu!"}, {"numero": 10, "texto": "Voici, le Seigneur, l''''Eternel vient avec puissance, Et de son bras il commande; Voici, le salaire est avec lui, Et les rétributions le précèdent."}, {"numero": 11, "texto": "Comme un berger, il paîtra son troupeau, Il prendra les agneaux dans ses bras, Et les portera dans son sein; Il conduira les brebis qui allaitent."}, {"numero": 12, "texto": "Qui a mesuré les eaux dans le creux de sa main, Pris les dimensions des cieux avec la paume, Et ramassé la poussière de la terre dans un tiers de mesure? Qui a pesé les montagnes au crochet, Et les collines à la balance?"}, {"numero": 13, "texto": "Qui a sondé l''''esprit de l''''Eternel, Et qui l''''a éclairé de ses conseils?"}, {"numero": 14, "texto": "Avec qui a-t-il délibéré pour en recevoir de l''''instruction? Qui lui a appris le sentier de la justice? Qui lui a enseigné la sagesse, Et fait connaître le chemin de l''''intelligence?"}, {"numero": 15, "texto": "Voici, les nations sont comme une goutte d''''un seau, Elles sont comme de la poussière sur une balance; Voici, les îles sont comme une fine poussière qui s''''envole."}, {"numero": 16, "texto": "Le Liban ne suffit pas pour le feu, Et ses animaux ne suffisent pas pour l''''holocauste."}, {"numero": 17, "texto": "Toutes les nations sont devant lui comme un rien, Elles ne sont pour lui que néant et vanité."}, {"numero": 18, "texto": "A qui voulez-vous comparer Dieu? Et quelle image ferez-vous son égale?"}, {"numero": 19, "texto": "C''''est un ouvrier qui fond l''''idole, Et c''''est un orfèvre qui la couvre d''''or, Et y soude des chaînettes d''''argent."}, {"numero": 20, "texto": "Celui que la pauvreté oblige à donner peu Choisit un bois qui résiste à la vermoulure; Il se procure un ouvrier capable, Pour faire une idole qui ne branle pas."}, {"numero": 21, "texto": "Ne le savez-vous pas? ne l''''avez-vous pas appris? Ne vous l''''a-t-on pas fait connaître dès le commencement? N''''avez-vous jamais réfléchi à la fondation de la terre?"}, {"numero": 22, "texto": "C''''est lui qui est assis au-dessus du cercle de la terre, Et ceux qui l''''habitent sont comme des sauterelles; Il étend les cieux comme une étoffe légère, Il les déploie comme une tente, pour en faire sa demeure."}, {"numero": 23, "texto": "C''''est lui qui réduit les princes au néant, Et qui fait des juges de la terre une vanité;"}, {"numero": 24, "texto": "Ils ne sont pas même plantés, pas même semés, Leur tronc n''''a pas même de racine en terre: Il souffle sur eux, et ils se dessèchent, Et un tourbillon les emporte comme le chaume."}, {"numero": 25, "texto": "A qui me comparerez-vous, pour que je lui ressemble? Dit le Saint."}, {"numero": 26, "texto": "Levez vos yeux en haut, et regardez! Qui a créé ces choses? Qui fait marcher en ordre leur armée? Il les appelle toutes par leur nom; Par son grand pouvoir et par sa force puissante, Il n''''en est pas une qui fasse défaut."}, {"numero": 27, "texto": "Pourquoi dis-tu, Jacob, Pourquoi dis-tu, Israël: Ma destinée est cachée devant l''''Eternel, Mon droit passe inaperçu devant mon Dieu?"}, {"numero": 28, "texto": "Ne le sais-tu pas? ne l''''as-tu pas appris? C''''est le Dieu d''''éternité, l''''Eternel, Qui a créé les extrémités de la terre; Il ne se fatigue point, il ne se lasse point; On ne peut sonder son intelligence."}, {"numero": 29, "texto": "Il donne de la force à celui qui est fatigué, Et il augmente la vigueur de celui qui tombe en défaillance."}, {"numero": 30, "texto": "Les adolescents se fatiguent et se lassent, Et les jeunes hommes chancellent;"}, {"numero": 31, "texto": "Mais ceux qui se confient en l''''Eternel renouvellent leur force. Ils prennent le vol comme les aigles; Ils courent, et ne se lassent point, Ils marchent, et ne se fatiguent point."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 40, 'es', '[{"numero": 1, "texto": "CONSOLAOS, consolaos, pueblo mío, dice vuestro Dios."}, {"numero": 2, "texto": "Hablad al corazón de Jerusalem: decidle á voces que su tiempo es ya cumplido, que su pecado es perdonado; que doble ha recibido de la mano de Jehová por todos sus pecados."}, {"numero": 3, "texto": "Voz que clama en el desierto: Barred camino á Jehová: enderezad calzada en la soledad á nuestro Dios."}, {"numero": 4, "texto": "Todo valle sea alzado, y bájese todo monte y collado; y lo torcido se enderece, y lo áspero se allane."}, {"numero": 5, "texto": "Y manifestaráse la gloria de Jehová, y toda carne juntamente la verá; que la boca de Jehová habló."}, {"numero": 6, "texto": "Voz que decía: Da voces. Y yo respondí: ¿Qué tengo de decir á voces? Toda carne es hierba, y toda su gloria como flor del campo:"}, {"numero": 7, "texto": "La hierba se seca, y la flor se cae; porque el viento de Jehová sopló en ella: ciertamente hierba es el pueblo."}, {"numero": 8, "texto": "Sécase la hierba, cáese la flor: mas la palabra del Dios nuestro permanece para siempre."}, {"numero": 9, "texto": "Súbete sobre un monte alto, anunciadora de Sión; levanta fuertemente tu voz, anunciadora de Jerusalem; levántala, no temas; di á las ciudades de Judá: ¡Veis aquí el Dios vuestro!"}, {"numero": 10, "texto": "He aquí que el Señor Jehová vendrá con fortaleza, y su brazo se enseñoreará: he aquí que su salario viene con él, y su obra delante de su rostro."}, {"numero": 11, "texto": "Como pastor apacentará su rebaño; en su brazo cogerá los corderos, y en su seno los llevará; pastoreará suavemente las paridas."}, {"numero": 12, "texto": "¿Quién midió las aguas con su puño, y aderezó los cielos con su palmo, y con tres dedos allegó el polvo de la tierra, y pesó los montes con balanza, y con peso los collados?"}, {"numero": 13, "texto": "¿Quién enseñó al espíritu de Jehová, ó le aconsejo enseñándole?"}, {"numero": 14, "texto": "¿A quién demandó consejo para ser avisado? ¿Quién le enseñó el camino del juicio, ó le enseñó ciencia, ó le mostró la senda de la prudencia?"}, {"numero": 15, "texto": "He aquí que las naciones son reputadas como la gota de un acetre, y como el orín del peso: he aquí que hace desaparecer las islas como polvo."}, {"numero": 16, "texto": "Ni el Líbano bastará para el fuego, ni todos sus animales para el sacrificio."}, {"numero": 17, "texto": "Como nada son todas las gentes delante de él; y en su comparación serán estimadas en menos que nada, y que lo que no es."}, {"numero": 18, "texto": "¿A qué pues haréis semejante á Dios, ó qué imagen le compondréis?"}, {"numero": 19, "texto": "El artífice apareja la imagen de talla, el platero le extiende el oro, y le funde cadenas de plata."}, {"numero": 20, "texto": "El pobre escoge, para ofrecerle, madera que no se corrompa; búscase un maestro sabio, que le haga una imagen de talla que no se mueva."}, {"numero": 21, "texto": "¿No sabéis? ¿no habéis oído? ¿nunca os lo han dicho desde el principio? ¿no habéis sido enseñados desde que la tierra se fundó?"}, {"numero": 22, "texto": "El está asentado sobre el globo de la tierra, cuyos moradores son como langostas: él extiende los cielos como una cortina, tiéndelos como una tienda para morar:"}, {"numero": 23, "texto": "El torna en nada los poderosos, y á los que gobiernan la tierra hace como cosa vana."}, {"numero": 24, "texto": "Como si nunca fueran plantados, como si nunca fueran sembrados, como si nunca su tronco hubiera tenido raíz en la tierra; así que sopla en ellos se secan, y el torbellino los lleva como hojarascas."}, {"numero": 25, "texto": "¿A qué pues me haréis semejante, ó seré asimilado? dice el Santo."}, {"numero": 26, "texto": "Levantad en alto vuestros ojos, y mirad quién crió estas cosas: él saca por cuenta su ejército: á todas llama por sus nombres; ninguna faltará: tal es la grandeza de su fuerza, y su poder y virtud."}, {"numero": 27, "texto": "¿Por qué dices, oh Jacob, y hablas tú, Israel: Mi camino es escondido de Jehová, y de mi Dios pasó mi juicio?"}, {"numero": 28, "texto": "¿No has sabido, no has oído que el Dios del siglo es Jehová, el cual crió los términos de la tierra? No se trabaja, ni se fatiga con cansancio, y su entendimiento no hay quien lo alcance."}, {"numero": 29, "texto": "El da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas."}, {"numero": 30, "texto": "Los mancebos se fatigan y se cansan, los mozos flaquean y caen:"}, {"numero": 31, "texto": "Mas los que esperan á Jehová tendrán nuevas fuerzas; levantarán las alas como águilas; correrán, y no se cansarán; caminarán, y no se fatigarán."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 42, 'pt', '[{"numero": 1, "texto": "Eis aqui meu servo, a quem sustento; meu escolhido, [em quem] minha alma se agrada. Sobre ele eu pus o meu Espírito; ele trará justiça às nações."}, {"numero": 2, "texto": "Ele não gritará, nem levantará [seu clamor] ; ele não fará ouvir sua voz nas ruas."}, {"numero": 3, "texto": "A cana rachada ele não quebrará, nem apagará o pavio que fumega; com a verdade ele trará justiça."}, {"numero": 4, "texto": "Ele não fraquejará, nem será esmagado, até que ponha a justiça na terra; e os litorais esperarão a sua doutrina."}, {"numero": 5, "texto": "Assim diz Deus, o SENHOR, que criou os céus, e os esticou; estendeu a terra, e a tudo quanto ela produz; que dá respiração ao povo que nela [habita] ,e espírito aos que nela andam."}, {"numero": 6, "texto": "Eu, o SENHOR, te chamei em justiça, e te tomarei pela mão. E eu te guardarei, e te darei como pacto para o povo e luz para as nações;"}, {"numero": 7, "texto": "Para abrir os olhos cegos, para tirar da prisão os presos, [tirar] do cárcere os que habitam em trevas."}, {"numero": 8, "texto": "Eu, EU-SOU; este é o meu nome! Não darei a minha glória a outro, nem o meu louvor às imagens de escultura."}, {"numero": 9, "texto": "Eis que as coisas anteriores já aconteceram; e as novas eu [vos] anuncio; e antes que surjam, [delas] eu vos informo."}, {"numero": 10, "texto": "Cantai ao SENHOR um cântico novo, um louvor a ele desde o limite da terra; vós que navegais pelo mar, e tudo quanto nele há; vós terras do litoral e seus moradores."}, {"numero": 11, "texto": "Levantem [a voz] o deserto e suas cidades, com as aldeias que Quedar habita; cantem os que habitam nas rochas, [e] gritem de alegria do cume dos montes."}, {"numero": 12, "texto": "Deem glória ao SENHOR, e anunciem louvor a ele nas terras do litoral."}, {"numero": 13, "texto": "O SENHOR sairá como guerreiro, como homem de guerra despertará o [seu] zelo; ele gritará, e fará grade ruído; e dominará a seus inimigos."}, {"numero": 14, "texto": "Por muito tempo fiquei calado, quieto estive, [e] me retive; [mas agora] darei gritos como a que está de parto, suspirando e juntamente ofegando."}, {"numero": 15, "texto": "Aos montes e morros tornarei em deserto, e toda sua erva farei secar; e tornarei aos rios em ilhas, e as lagoas secarei."}, {"numero": 16, "texto": "E guiarei aos cegos por um caminho que nunca conheceram; eu os farei caminhar pelas veredas que não conheciam; tornarei as trevas em luz perante eles, e as coisas tortas [farei] direitas; estas coisas lhes farei, e nunca os desampararei."}, {"numero": 17, "texto": "[Mas] serão conduzidos para trás e se envergonharão os que confiam em imagens de escultura, [e] dizem às imagens de fundição: Vós sois nossos deuses."}, {"numero": 18, "texto": "Surdos, ouvi; e vós cegos, olhai para que possais ver."}, {"numero": 19, "texto": "Quem é cego, senão o meu servo? Ou surdo, como o meu mensageiro, a quem envio? Quem é cego como o aliançado, e cego como o servo do SENHOR?"}, {"numero": 20, "texto": "Tu vês muitas coisas, porém não as guardas; mesmo abrindo os ouvidos, contudo nada ouve."}, {"numero": 21, "texto": "O SENHOR se agradou, por causa de sua justiça, em engrandecer [sua] lei, e em fazê [-la] gloriosa."}, {"numero": 22, "texto": "Mas [este] é um povo roubado e saqueado; todos estão enlaçados em covas, e escondidos em cárceres; são postos como despojos, e ninguém há que os resgate; estão como [objetos] de roubo, e ninguém diz “Restitui [-os] ”."}, {"numero": 23, "texto": "Quem dentre vós dá ouvidos a isto? [Quem] presta atenção e ouve o que há de ser no futuro?"}, {"numero": 24, "texto": "Quem entregou a Jacó como roubo, e a Israel a ladrões? Por acaso não foi o SENHOR, aquele contra quem pecamos? Pois não queriam andar em seus caminhos, e não deram ouvidos à sua lei."}, {"numero": 25, "texto": "Por isso ele derramou sobre eles o furor de sua ira, e a força da guerra; e os pôs em labaredas ao redor; porém [ainda assim] não entenderam; e ele os pôs para queimar, porém [ainda assim] não puseram [nisso] o coração."}]'::jsonb, 'Almeida Livre'),
  ('Is', 42, 'en', '[{"numero": 1, "texto": "Behold my servant, whom I uphold; mine elect, in whom my soul delighteth; I have put my spirit upon him: he shall bring forth judgment to the Gentiles."}, {"numero": 2, "texto": "He shall not cry, nor lift up, nor cause his voice to be heard in the street."}, {"numero": 3, "texto": "A bruised reed shall he not break, and the smoking flax shall he not quench: he shall bring forth judgment unto truth."}, {"numero": 4, "texto": "He shall not fail nor be discouraged, till he have set judgment in the earth: and the isles shall wait for his law."}, {"numero": 5, "texto": "Thus saith God the Lord, he that created the heavens, and stretched them out; he that spread forth the earth, and that which cometh out of it; he that giveth breath unto the people upon it, and spirit to them that walk therein:"}, {"numero": 6, "texto": "I the Lord have called thee in righteousness, and will hold thine hand, and will keep thee, and give thee for a covenant of the people, for a light of the Gentiles;"}, {"numero": 7, "texto": "To open the blind eyes, to bring out the prisoners from the prison, and them that sit in darkness out of the prison house."}, {"numero": 8, "texto": "I am the Lord: that is my name: and my glory will I not give to another, neither my praise to graven images."}, {"numero": 9, "texto": "Behold, the former things are come to pass, and new things do I declare: before they spring forth I tell you of them."}, {"numero": 10, "texto": "Sing unto the Lord a new song, and his praise from the end of the earth, ye that go down to the sea, and all that is therein; the isles, and the inhabitants thereof."}, {"numero": 11, "texto": "Let the wilderness and the cities thereof lift up their voice, the villages that Kedar doth inhabit: let the inhabitants of the rock sing, let them shout from the top of the mountains."}, {"numero": 12, "texto": "Let them give glory unto the Lord, and declare his praise in the islands."}, {"numero": 13, "texto": "The Lord shall go forth as a mighty man, he shall stir up jealousy like a man of war: he shall cry, yea, roar; he shall prevail against his enemies."}, {"numero": 14, "texto": "I have long time holden my peace; I have been still, and refrained myself: now will I cry like a travailing woman; I will destroy and devour at once."}, {"numero": 15, "texto": "I will make waste mountains and hills, and dry up all their herbs; and I will make the rivers islands, and I will dry up the pools."}, {"numero": 16, "texto": "And I will bring the blind by a way that they knew not; I will lead them in paths that they have not known: I will make darkness light before them, and crooked things straight. These things will I do unto them, and not forsake them."}, {"numero": 17, "texto": "They shall be turned back, they shall be greatly ashamed, that trust in graven images, that say to the molten images, Ye are our gods."}, {"numero": 18, "texto": "Hear, ye deaf; and look, ye blind, that ye may see."}, {"numero": 19, "texto": "Who is blind, but my servant? or deaf, as my messenger that I sent? who is blind as he that is perfect, and blind as the Lord''s servant?"}, {"numero": 20, "texto": "Seeing many things, but thou observest not; opening the ears, but he heareth not."}, {"numero": 21, "texto": "The Lord is well pleased for his righteousness'' sake; he will magnify the law, and make it honourable."}, {"numero": 22, "texto": "But this is a people robbed and spoiled; they are all of them snared in holes, and they are hid in prison houses: they are for a prey, and none delivereth; for a spoil, and none saith, Restore."}, {"numero": 23, "texto": "Who among you will give ear to this? who will hearken and hear for the time to come?"}, {"numero": 24, "texto": "Who gave Jacob for a spoil, and Israel to the robbers? did not the Lord, he against whom we have sinned? for they would not walk in his ways, neither were they obedient unto his law."}, {"numero": 25, "texto": "Therefore he hath poured upon him the fury of his anger, and the strength of battle: and it hath set him on fire round about, yet he knew not; and it burned him, yet he laid it not to heart."}]'::jsonb, 'King James Version'),
  ('Is', 42, 'fr', '[{"numero": 1, "texto": "Voici mon serviteur, que je soutiendrai, Mon élu, en qui mon âme prend plaisir. J''''ai mis mon esprit sur lui; Il annoncera la justice aux nations."}, {"numero": 2, "texto": "Il ne criera point, il n''''élèvera point la voix, Et ne la fera point entendre dans les rues."}, {"numero": 3, "texto": "Il ne brisera point le roseau cassé, Et il n''''éteindra point la mèche qui brûle encore; Il annoncera la justice selon la vérité."}, {"numero": 4, "texto": "Il ne se découragera point et ne se relâchera point, Jusqu''''à ce qu''''il ait établi la justice sur la terre, Et que les îles espèrent en sa loi."}, {"numero": 5, "texto": "Ainsi parle Dieu, l''''Eternel, Qui a créé les cieux et qui les a déployés, Qui a étendu la terre et ses productions, Qui a donné la respiration à ceux qui la peuplent, Et le souffle à ceux qui y marchent."}, {"numero": 6, "texto": "Moi, l''''Eternel, je t''''ai appelé pour le salut, Et je te prendrai par la main, Je te garderai, et je t''''établirai pour traiter alliance avec le peuple, Pour être la lumière des nations,"}, {"numero": 7, "texto": "Pour ouvrir les yeux des aveugles, Pour faire sortir de prison le captif, Et de leur cachot ceux qui habitent dans les ténèbres."}, {"numero": 8, "texto": "Je suis l''''Eternel, c''''est là mon nom; Et je ne donnerai pas ma gloire à un autre, Ni mon honneur aux idoles."}, {"numero": 9, "texto": "Voici, les premières choses se sont accomplies, Et je vous en annonce de nouvelles; Avant qu''''elles arrivent, je vous les prédis."}, {"numero": 10, "texto": "Chantez à l''''Eternel un cantique nouveau, Chantez ses louanges aux extrémités de la terre, Vous qui voguez sur la mer et vous qui la peuplez, Iles et habitants des îles!"}, {"numero": 11, "texto": "Que le désert et ses villes élèvent la voix! Que les villages occupés par Kédar élèvent la voix! Que les habitants des rochers tressaillent d''''allégresse! Que du sommet des montagnes retentissent des cris de joie!"}, {"numero": 12, "texto": "Qu''''on rende gloire à l''''Eternel, Et que dans les îles on publie ses louanges!"}, {"numero": 13, "texto": "L''''Eternel s''''avance comme un héros, Il excite son ardeur comme un homme de guerre; Il élève la voix, il jette des cris, Il manifeste sa force contre ses ennemis."}, {"numero": 14, "texto": "J''''ai longtemps gardé le silence, je me suis tu, je me suis contenu; Je crierai comme une femme en travail, Je serai haletant et je soufflerai tout à la fois."}, {"numero": 15, "texto": "Je ravagerai montagnes et collines, Et j''''en dessécherai toute la verdure; Je changerai les fleuves en terre ferme, Et je mettrai les étangs à sec."}, {"numero": 16, "texto": "Je ferai marcher les aveugles sur un chemin qu''''ils ne connaissent pas, Je les conduirai par des sentiers qu''''ils ignorent; Je changerai devant eux les ténèbres en lumière, Et les endroits tortueux en plaine: Voilà ce que je ferai, et je ne les abandonnerai point."}, {"numero": 17, "texto": "Ils reculeront, ils seront confus, Ceux qui se confient aux idoles taillées, Ceux qui disent aux idoles de fonte: Vous êtes nos dieux!"}, {"numero": 18, "texto": "Sourds, écoutez! Aveugles, regardez et voyez!"}, {"numero": 19, "texto": "Qui est aveugle, sinon mon serviteur, Et sourd comme mon messager que j''''envoie? Qui est aveugle, comme l''''ami de Dieu, Aveugle comme le serviteur de l''''Eternel?"}, {"numero": 20, "texto": "Tu as vu beaucoup de choses, mais tu n''''y as point pris garde; On a ouvert les oreilles, mais on n''''a point entendu."}, {"numero": 21, "texto": "L''''Eternel a voulu, pour le bonheur d''''Israël, Publier une loi grande et magnifique."}, {"numero": 22, "texto": "Et c''''est un peuple pillé et dépouillé! On les a tous enchaînés dans des cavernes, Plongés dans des cachots; Ils ont été mis au pillage, et personne qui les délivre! Dépouillés, et personne qui dise: Restitue!"}, {"numero": 23, "texto": "Qui parmi vous prêtera l''''oreille à ces choses? Qui voudra s''''y rendre attentif et écouter à l''''avenir?"}, {"numero": 24, "texto": "Qui a livré Jacob au pillage, Et Israël aux pillards? N''''est-ce pas l''''Eternel? Nous avons péché contre lui. Ils n''''ont point voulu marcher dans ses voies, Et ils n''''ont point écouté sa loi."}, {"numero": 25, "texto": "Aussi a-t-il versé sur Israël l''''ardeur de sa colère Et la violence de la guerre; La guerre l''''a embrasé de toutes parts, et il n''''a point compris; Elle l''''a consumé, et il n''''y a point pris garde."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 42, 'es', '[{"numero": 1, "texto": "HE aquí mi siervo, yo le sostendré; mi escogido, en quien mi alma toma contentamiento: he puesto sobre él mi espíritu, dará juicio á las gentes."}, {"numero": 2, "texto": "No clamará, ni alzará, ni hará oir su voz en las plazas."}, {"numero": 3, "texto": "No quebrará la caña cascada, ni apagará el pábilo que humeare: sacará el juicio á verdad."}, {"numero": 4, "texto": "No se cansará, ni desmayará, hasta que ponga en la tierra juicio; y las islas esperarán su ley."}, {"numero": 5, "texto": "Así dice el Dios Jehová, el Criador de los cielos, y el que los extiende; el que extiende la tierra y sus verduras; el que da respiración al pueblo que mora sobre ella, y espíritu á los que por ella andan:"}, {"numero": 6, "texto": "Yo Jehová te he llamado en justicia, y te tendré por la mano; te guardaré y te pondré por alianza del pueblo, por luz de las gentes;"}, {"numero": 7, "texto": "Para que abras ojos de ciegos, para que saques de la cárcel á los presos, y de casas de prisión á los que están de asiento en tinieblas."}, {"numero": 8, "texto": "Yo Jehová: este es mi nombre; y á otro no daré mi gloria, ni mi alabanza á esculturas."}, {"numero": 9, "texto": "Las cosas primeras he aquí vinieron, y yo anuncio nuevas cosas: antes que salgan á luz, yo os las haré notorias."}, {"numero": 10, "texto": "Cantad á Jehová un nuevo cántico, su alabanza desde el fin de la tierra; los que descendéis á la mar, y lo que la hinche, las islas y los moradores de ellas."}, {"numero": 11, "texto": "Alcen la voz el desierto y sus ciudades, las aldeas donde habita Cedar: canten los moradores de la Piedra, y desde la cumbre de los montes den voces de júbilo."}, {"numero": 12, "texto": "Den gloria á Jehová, y prediquen sus loores en las islas."}, {"numero": 13, "texto": "Jehová saldrá como gigante, y como hombre de guerra despertará celo: gritará, voceará, esforzaráse sobre sus enemigos."}, {"numero": 14, "texto": "Desde el siglo he callado, tenido he silencio, y heme detenido: daré voces como la que está de parto; asolaré y devoraré juntamente."}, {"numero": 15, "texto": "Tornaré en soledad montes y collados, haré secar toda su hierba; los ríos tornaré en islas, y secaré los estanques."}, {"numero": 16, "texto": "Y guiaré los ciegos por camino que no sabían, haréles pisar por las sendas que no habían conocido; delante de ellos tornaré las tinieblas en luz, y los rodeos en llanura. Estas cosas les haré, y no los desampararé."}, {"numero": 17, "texto": "Serán vueltos atrás, y en extremo confundidos, los que confían en las esculturas, y dicen á las estatuas de fundición: Vosotros sois nuestros dioses."}, {"numero": 18, "texto": "Sordos, oid; y vosotros ciegos, mirad para ver."}, {"numero": 19, "texto": "¿Quién ciego, sino mi siervo? ¿quién sordo, como mi mensajero que envié? ¿quién ciego como el perfecto, y ciego como el siervo de Jehová,"}, {"numero": 20, "texto": "Que ve muchas cosas y no advierte, que abre los oídos y no oye?"}, {"numero": 21, "texto": "Jehová se complació por amor de su justicia en magnificar la ley y engrandecerla."}, {"numero": 22, "texto": "Mas este es pueblo saqueado y hollado, todos ellos enlazados en cavernas y escondidos en cárceles: son puestos á saco, y no hay quien libre; hollados, y no hay quien diga, Restituid."}, {"numero": 23, "texto": "¿Quién de vosotros oirá esto? ¿quién atenderá y escuchará en orden al porvernir?"}, {"numero": 24, "texto": "¿Quién dió á Jacob en presa, y entregó á Israel á saqueadores? ¿No fué Jehová, contra quien pecamos? y no quisieron andar en sus caminos, ni oyeron su ley."}, {"numero": 25, "texto": "Por tanto derramó sobre él el furor de su ira, y fuerza de guerra; púsole fuego de todas partes, empero no entendió; y encendióle, mas no ha parado mientes."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 43, 'pt', '[{"numero": 1, "texto": "Porém agora assim diz o SENHOR, o teu Criador, ó Jacó, e o teu Formador, ó Israel: Não temas, porque eu te resgatei; chamei a ti por teu nome; tu és meu."}, {"numero": 2, "texto": "Quando passares pelas águas, estarei contigo; e [ao passares] pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem a chamas arderão em ti."}, {"numero": 3, "texto": "Porque eu sou o SENHOR teu Deus, o Santo de Israel, teu Salvador; dei ao Egito, a Cuxe, e a Seba como teu resgate, em teu lugar."}, {"numero": 4, "texto": "Visto que foste precioso em meus olhos, [assim] foste glorificado, e eu te amei; por isso dei homens em troca de ti, e povos em troca de tua alma."}, {"numero": 5, "texto": "Não temas, pois estou contigo; eu trarei tua semente desde o oriente, e te ajuntarei desde o ocidente."}, {"numero": 6, "texto": "Direi ao norte: Dá!, E ao sul: Não retenhas! Trazei meus filhos de longe, e minhas filhas desde os confins da terra;"}, {"numero": 7, "texto": "Todos os chamados do meu nome, e os que criei para minha gloria; eu os formei; sim, eu os fiz."}, {"numero": 8, "texto": "Trazei ao povo cego, que tem olhos; e aos surdos, que tem ouvidos."}, {"numero": 9, "texto": "Todas as nações se reúnam, e os povos se ajuntem. Quem deles isto isto anuncia, e nos faz ouvir as coisas do passado? Mostrem suas testemunhas, para que se justifiquem, e se ouça, e se diga: É verdade."}, {"numero": 10, "texto": "Vós sois minhas testemunhas (diz o SENHOR); e meu servo, a quem escolhi; para que saibais, e creiais em mim, e entendais que eu sou o próprio, e [que] antes de mim nenhum Deus se formou, e depois de minha nenhum haverá."}, {"numero": 11, "texto": "Eu, eu sou o SENHOR; e fora de mim não há salvador."}, {"numero": 12, "texto": "Eu anunciei, eu salvei, e eu fiz ouvir, e deus estrangeiro não houve entre vós, e vós sois minhas testemunhas, (diz o SENHOR), que eu sou Deus."}, {"numero": 13, "texto": "E desde antes de haver dia, eu o sou; e ninguém há que possa livrar das minhas mãos. Eu estou agindo, quem pode impedir?"}, {"numero": 14, "texto": "Assim diz o SENHOR o teu Redentor, o Santo de Israel: Por causa de vós eu enviei [inimigos] a Babilônia, e a todos eu os fiz descerem [como] fugitivos, inclusive os Caldeus, nos navios em que se orgulhavam."}, {"numero": 15, "texto": "Eu sou o SENHOR, vosso Santo; o Criador de Israel, o vosso Rei."}, {"numero": 16, "texto": "Assim diz o SENHOR, aquele que preparou no mar um caminho, e nas águas impetuosas uma vereda;"}, {"numero": 17, "texto": "Aquele que trouxe carruagens e cavalos, exército e forças; [todos] juntamente caíram, e não mais se levantaram; estão extintos, foram apagados como um pavio:"}, {"numero": 18, "texto": "Não vos lembreis das coisas passadas, nem considereis as antigas;"}, {"numero": 19, "texto": "Eis que farei uma coisa nova, agora surgirá; por acaso não a reconhecereis? Pois porei um caminho no deserto, [e] rios na terra vazia."}, {"numero": 20, "texto": "Os animais do campo me honrarão; os chacais e os filhotes de avestruz; porque porei águas no deserto, rios na terra vazia, para dar de beber a meu povo, meu escolhido."}, {"numero": 21, "texto": "Este povo formei para mim, eles declararão louvor a mim."}, {"numero": 22, "texto": "Porém tu não me invocaste, ó Jacó; pois te cansaste de mim, ó Israel."}, {"numero": 23, "texto": "Não me trouxeste o gado miúdo de teus holocaustos, nem me honraste [com] teus sacrifícios; eu não vos oprimi com ofertas, nem te cansei com incenso."}, {"numero": 24, "texto": "Não me compraste com dinheiro cana aromática, nem me saciaste com a gordura de teus sacrifícios; mas me oprimiste com teus pecados, [e] me cansaste com tuas maldades."}, {"numero": 25, "texto": "Eu, eu sou o que anulo tuas transgressões por causa de mim; e te teus pecados eu não me lembro."}, {"numero": 26, "texto": "Faze-me lembrar, entremos em juízo juntos; mostra [teus argumentos] ,para que possas te justificar."}, {"numero": 27, "texto": "Teu primeiro pai pecou; e teus intérpretes transgrediram contra mim."}, {"numero": 28, "texto": "Por isso profanei os líderes do santuário, e entreguei Jacó à desgraça, e Israel à humilhação."}]'::jsonb, 'Almeida Livre'),
  ('Is', 43, 'en', '[{"numero": 1, "texto": "But now thus saith the Lord that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine."}, {"numero": 2, "texto": "When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee."}, {"numero": 3, "texto": "For I am the Lord thy God, the Holy One of Israel, thy Saviour: I gave Egypt for thy ransom, Ethiopia and Seba for thee."}, {"numero": 4, "texto": "Since thou wast precious in my sight, thou hast been honourable, and I have loved thee: therefore will I give men for thee, and people for thy life."}, {"numero": 5, "texto": "Fear not: for I am with thee: I will bring thy seed from the east, and gather thee from the west;"}, {"numero": 6, "texto": "I will say to the north, Give up; and to the south, Keep not back: bring my sons from far, and my daughters from the ends of the earth;"}, {"numero": 7, "texto": "Even every one that is called by my name: for I have created him for my glory, I have formed him; yea, I have made him."}, {"numero": 8, "texto": "Bring forth the blind people that have eyes, and the deaf that have ears."}, {"numero": 9, "texto": "Let all the nations be gathered together, and let the people be assembled: who among them can declare this, and shew us former things? let them bring forth their witnesses, that they may be justified: or let them hear, and say, It is truth."}, {"numero": 10, "texto": "Ye are my witnesses, saith the Lord, and my servant whom I have chosen: that ye may know and believe me, and understand that I am he: before me there was no God formed, neither shall there be after me."}, {"numero": 11, "texto": "I, even I, am the Lord; and beside me there is no saviour."}, {"numero": 12, "texto": "I have declared, and have saved, and I have shewed, when there was no strange god among you: therefore ye are my witnesses, saith the Lord, that I am God."}, {"numero": 13, "texto": "Yea, before the day was I am he; and there is none that can deliver out of my hand: I will work, and who shall let it?"}, {"numero": 14, "texto": "Thus saith the Lord, your redeemer, the Holy One of Israel; For your sake I have sent to Babylon, and have brought down all their nobles, and the Chaldeans, whose cry is in the ships."}, {"numero": 15, "texto": "I am the Lord, your Holy One, the creator of Israel, your King."}, {"numero": 16, "texto": "Thus saith the Lord, which maketh a way in the sea, and a path in the mighty waters;"}, {"numero": 17, "texto": "Which bringeth forth the chariot and horse, the army and the power; they shall lie down together, they shall not rise: they are extinct, they are quenched as tow."}, {"numero": 18, "texto": "Remember ye not the former things, neither consider the things of old."}, {"numero": 19, "texto": "Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert."}, {"numero": 20, "texto": "The beast of the field shall honour me, the dragons and the owls: because I give waters in the wilderness, and rivers in the desert, to give drink to my people, my chosen."}, {"numero": 21, "texto": "This people have I formed for myself; they shall shew forth my praise."}, {"numero": 22, "texto": "But thou hast not called upon me, O Jacob; but thou hast been weary of me, O Israel."}, {"numero": 23, "texto": "Thou hast not brought me the small cattle of thy burnt offerings; neither hast thou honoured me with thy sacrifices. I have not caused thee to serve with an offering, nor wearied thee with incense."}, {"numero": 24, "texto": "Thou hast bought me no sweet cane with money, neither hast thou filled me with the fat of thy sacrifices: but thou hast made me to serve with thy sins, thou hast wearied me with thine iniquities."}, {"numero": 25, "texto": "I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins."}, {"numero": 26, "texto": "Put me in remembrance: let us plead together: declare thou, that thou mayest be justified."}, {"numero": 27, "texto": "Thy first father hath sinned, and thy teachers have transgressed against me."}, {"numero": 28, "texto": "Therefore I have profaned the princes of the sanctuary, and have given Jacob to the curse, and Israel to reproaches."}]'::jsonb, 'King James Version'),
  ('Is', 43, 'fr', '[{"numero": 1, "texto": "Ainsi parle maintenant l''''Eternel, qui t''''a créé, ô Jacob! Celui qui t''''a formé, ô Israël! Ne crains rien, car je te rachète, Je t''''appelle par ton nom: tu es à moi!"}, {"numero": 2, "texto": "Si tu traverses les eaux, je serai avec toi; Et les fleuves, ils ne te submergeront point; Si tu marches dans le feu, tu ne te brûleras pas, Et la flamme ne t''''embrasera pas."}, {"numero": 3, "texto": "Car je suis l''''Eternel, ton Dieu, Le Saint d''''Israël, ton sauveur; Je donne l''''Egypte pour ta rançon, L''''Ethiopie et Saba à ta place."}, {"numero": 4, "texto": "Parce que tu as du prix à mes yeux, Parce que tu es honoré et que je t''''aime, Je donne des hommes à ta place, Et des peuples pour ta vie."}, {"numero": 5, "texto": "Ne crains rien, car je suis avec toi; Je ramènerai de l''''orient ta race, Et je te rassemblerai de l''''occident."}, {"numero": 6, "texto": "Je dirai au septentrion: Donne! Et au midi: Ne retiens point! Fais venir mes fils des pays lointains, Et mes filles de l''''extrémité de la terre,"}, {"numero": 7, "texto": "Tous ceux qui s''''appellent de mon nom, Et que j''''ai créés pour ma gloire, Que j''''ai formés et que j''''ai faits."}, {"numero": 8, "texto": "Qu''''on fasse sortir le peuple aveugle, qui a des yeux, Et les sourds, qui ont des oreilles."}, {"numero": 9, "texto": "Que toutes les nations se rassemblent, Et que les peuples se réunissent. Qui d''''entre eux a annoncé ces choses? Lesquels nous ont fait entendre les premières prédictions? Qu''''ils produisent leurs témoins et établissent leur droit; Qu''''on écoute et qu''''on dise: C''''est vrai!"}, {"numero": 10, "texto": "Vous êtes mes témoins, dit l''''Eternel, Vous, et mon serviteur que j''''ai choisi, Afin que vous le sachiez, Que vous me croyiez et compreniez que c''''est moi: Avant moi il n''''a point été formé de Dieu, Et après moi il n''''y en aura point."}, {"numero": 11, "texto": "C''''est moi, moi qui suis l''''Eternel, Et hors moi il n''''y a point de sauveur."}, {"numero": 12, "texto": "C''''est moi qui ai annoncé, sauvé, prédit, Ce n''''est point parmi vous un dieu étranger; Vous êtes mes témoins, dit l''''Eternel, C''''est moi qui suis Dieu."}, {"numero": 13, "texto": "Je le suis dès le commencement, Et nul ne délivre de ma main; J''''agirai: qui s''''y opposera?"}, {"numero": 14, "texto": "Ainsi parle l''''Eternel, Votre rédempteur, le Saint d''''Israël: A cause de vous, j''''envoie l''''ennemi contre Babylone, Et je fais descendre tous les fuyards, Même les Chaldéens, sur les navires dont ils tiraient gloire."}, {"numero": 15, "texto": "Je suis l''''Eternel, votre Saint, Le créateur d''''Israël, votre roi."}, {"numero": 16, "texto": "Ainsi parle l''''Eternel, Qui fraya dans la mer un chemin, Et dans les eaux puissantes un sentier,"}, {"numero": 17, "texto": "Qui mit en campagne des chars et des chevaux, Une armée et de vaillants guerriers, Soudain couchés ensemble, pour ne plus se relever, Anéantis, éteints comme une mèche:"}, {"numero": 18, "texto": "Ne pensez plus aux événements passés, Et ne considérez plus ce qui est ancien."}, {"numero": 19, "texto": "Voici, je vais faire une chose nouvelle, sur le point d''''arriver: Ne la connaîtrez-vous pas? Je mettrai un chemin dans le désert, Et des fleuves dans la solitude."}, {"numero": 20, "texto": "Les bêtes des champs me glorifieront, Les chacals et les autruches, Parce que j''''aurai mis des eaux dans le désert, Des fleuves dans la solitude, Pour abreuver mon peuple, mon élu."}, {"numero": 21, "texto": "Le peuple que je me suis formé Publiera mes louanges."}, {"numero": 22, "texto": "Et tu ne m''''as pas invoqué, ô Jacob! Car tu t''''es lassé de moi, ô Israël!"}, {"numero": 23, "texto": "Tu ne m''''as pas offert tes brebis en holocauste, Et tu ne m''''as pas honoré par tes sacrifices; Je ne t''''ai point tourmenté pour des offrandes, Et je ne t''''ai point fatigué pour de l''''encens."}, {"numero": 24, "texto": "Tu n''''as pas à prix d''''argent acheté pour moi des aromates, Et tu ne m''''as pas rassasié de la graisse de tes sacrifices; Mais tu m''''as tourmenté par tes péchés, Tu m''''as fatigué par tes iniquités."}, {"numero": 25, "texto": "C''''est moi, moi qui efface tes transgressions pour l''''amour de moi, Et je ne me souviendrai plus de tes péchés."}, {"numero": 26, "texto": "Réveille ma mémoire, plaidons ensemble, Parle toi-même, pour te justifier."}, {"numero": 27, "texto": "Ton premier père a péché, Et tes interprètes se sont rebellés contre moi."}, {"numero": 28, "texto": "C''''est pourquoi j''''ai traité en profanes les chefs du sanctuaire, J''''ai livré Jacob à la destruction, Et Israël aux outrages."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 43, 'es', '[{"numero": 1, "texto": "Y AHORA, así dice Jehová Criador tuyo, oh Jacob, y Formador tuyo, oh Israel: No temas, porque yo te redimí; te puse nombre, mío eres tú."}, {"numero": 2, "texto": "Cuando pasares por las aguas, yo seré contigo; y por los ríos, no te anegarán. Cuando pasares por el fuego, no te quemarás, ni la llama arderá en ti."}, {"numero": 3, "texto": "Porque yo Jehová Dios tuyo, el Santo de Israel, soy tu Salvador: á Egipto he dado por tu rescate, á Etiopía y á Seba por ti."}, {"numero": 4, "texto": "Porque en mis ojos fuiste de grande estima, fuiste honorable, y yo te amé: daré pues hombres por ti, y naciones por tu alma."}, {"numero": 5, "texto": "No temas, porque yo soy contigo; del oriente traeré tu generación, y del occidente te recogeré."}, {"numero": 6, "texto": "Diré al aquilón: Da acá; y al mediodía: No detengas: trae de lejos mis hijos, y mis hijas de los términos de la tierra,"}, {"numero": 7, "texto": "Todos los llamados de mi nombre; para gloria mía los críe, los formé y los hice."}, {"numero": 8, "texto": "Sacad al pueblo ciego que tiene ojos, y á los sordos que tienen oídos."}, {"numero": 9, "texto": "Congréguense á una todas las gentes, y júntense todos los pueblos: ¿quién de ellos hay que nos dé nuevas de esto, y que nos haga oir las cosas primeras? Presenten sus testigos, y justifíquense; oigan, y digan: Verdad."}, {"numero": 10, "texto": "Vosotros sois mis testigos, dice Jehová, y mi siervo que yo escogí; para que me conozcáis y creáis, y entendáis que yo mismo soy; antes de mí no fué formado Dios, ni lo será después de mí."}, {"numero": 11, "texto": "Yo, yo Jehová; y fuera de mí no hay quien salve."}, {"numero": 12, "texto": "Yo anuncié, y salvé, é hice oir, y no hubo entre vosotros extraño. Vosotros pues sois mis testigos, dice Jehová, que yo soy Dios."}, {"numero": 13, "texto": "Aun antes que hubiera día, yo era; y no hay quien de mi mano libre: si yo hiciere, ¿quién lo estorbará?"}, {"numero": 14, "texto": "Así dice Jehová, Redentor vuestro, el Santo de Israel: Por vosotros envié á Babilonia, é hice descender fugitivos todos ellos, y clamor de Caldeos en las naves."}, {"numero": 15, "texto": "Yo Jehová, Santo vuestro, Criador de Israel, vuestro Rey."}, {"numero": 16, "texto": "Así dice Jehová, el que da camino en la mar, y senda en las aguas impetuosas;"}, {"numero": 17, "texto": "El que saca carro y caballo, ejército y fuerza; caen juntamente para no levantarse; quedan extinguidos, como pábilo quedan apagados."}, {"numero": 18, "texto": "No os acordéis de las cosas pasadas, ni traigáis á memoria las cosas antiguas."}, {"numero": 19, "texto": "He aquí que yo hago cosa nueva: presto saldrá á luz: ¿no la sabréis? Otra vez pondré camino en el desierto, y ríos en la soledad."}, {"numero": 20, "texto": "La bestia del campo me honrará, los chacales, y los pollos del avestruz: porque daré aguas en el desierto, ríos en la soledad, para que beba mi pueblo, mi escogido."}, {"numero": 21, "texto": "Este pueblo crié para mí; mis alabanzas publicará."}, {"numero": 22, "texto": "Y no me invocaste á mí, oh Jacob; antes, de mí te cansaste, oh Israel."}, {"numero": 23, "texto": "No me trajiste á mí los animales de tus holocaustos, ni á mí me honraste con tus sacrificios: no te hice servir con presente, ni te hice fatigar con perfume."}, {"numero": 24, "texto": "No compraste para mí caña aromática por dinero, ni me saciaste con la grosura de tus sacrificios; antes me hiciste servir en tus pecados, me has fatigado con tus maldades."}, {"numero": 25, "texto": "Yo, yo soy el que borro tus rebeliones por amor de mí; y no me acordaré de tus pecados."}, {"numero": 26, "texto": "Hazme acordar, entremos en juicio juntamente; relata tú para abonarte."}, {"numero": 27, "texto": "Tu primer padre pecó, y tus enseñadores prevaricaron contra mí."}, {"numero": 28, "texto": "Por tanto, yo profané los príncipes del santuario, y puse por anatema á Jacob, y por oprobio á Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 53, 'pt', '[{"numero": 1, "texto": "Quem creu em nossa pregação? E a quem se manifestou o braço do SENHOR?"}, {"numero": 2, "texto": "Pois foi crescendo como renovo perante ele, e como raiz de terra seca; não tinha boa aparência nem formosura; e quando olhávamos para ele, não havia [nele] boa aparência, para que o desejássemos."}, {"numero": 3, "texto": "Ele era desprezado e rejeitado entre os homens, era homem de dores, e experiente em enfermidade; ele era como alguém de quem [os outros] escondiam o rosto; era desprezado, e não lhe estimávamos."}, {"numero": 4, "texto": "Verdadeiramente ele tomou sobre si nossas enfermidades, e nossas dores levou sobre si; e nós o considerávamos como afligido, ferido por Deus, e oprimido."}, {"numero": 5, "texto": "Porém ele foi ferido por nossas transgressões, [e] esmagado por nossas perversidades; o castigo que nos traz a paz estava sobre ele, e por suas feridas fomos curados."}, {"numero": 6, "texto": "Todos nós andávamos sem rumo como ovelhas; cada um se desviava por seu caminho; porém o SENHOR fez vir sobre ele a perversidade de todos nós."}, {"numero": 7, "texto": "Ele foi oprimido e afligido, porém não abriu sua boca; tal como cordeiro ele foi levado ao matadouro, e como ovelha muda perante seus tosquiadores, assim ele não abriu sua boca."}, {"numero": 8, "texto": "Com opressão e julgamento ele foi removido; e quem falará de sua geração? Porque ele foi cortado da terra dos viventes; pela transgressão do meu povo ele foi ferido."}, {"numero": 9, "texto": "E puseram sua sepultura com perversos, e com um rico em sua morte; pois ele nunca fez injustiça, nem houve engano em sua boca."}, {"numero": 10, "texto": "Porém agradou ao SENHOR esmagá-lo, fazendo-o ficar enfermo; quando sua alma for posta como expiação do pecado, ele verá semente, [e] prolongará os dias; e o bom prazer do SENHOR prosperará em sua mão."}, {"numero": 11, "texto": "A [consequência] do trabalho de sua alma ele verá [e] se fartará; com seu conhecimento o meu servo, o justo, justificará a muitos, pois levará sobre si as perversidades deles."}, {"numero": 12, "texto": "Por isso lhe darei a porção de muitos, e e com os poderosos ele repartirá despojo, pois derramou sua alma na morte, e foi contado com os transgressores; e levou sobre si o pecado de muitos, e intercedeu pelos transgressores."}]'::jsonb, 'Almeida Livre'),
  ('Is', 53, 'en', '[{"numero": 1, "texto": "Who hath believed our report? and to whom is the arm of the Lord revealed?"}, {"numero": 2, "texto": "For he shall grow up before him as a tender plant, and as a root out of a dry ground: he hath no form nor comeliness; and when we shall see him, there is no beauty that we should desire him."}, {"numero": 3, "texto": "He is despised and rejected of men; a man of sorrows, and acquainted with grief: and we hid as it were our faces from him; he was despised, and we esteemed him not."}, {"numero": 4, "texto": "Surely he hath borne our griefs, and carried our sorrows: yet we did esteem him stricken, smitten of God, and afflicted."}, {"numero": 5, "texto": "But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed."}, {"numero": 6, "texto": "All we like sheep have gone astray; we have turned every one to his own way; and the Lord hath laid on him the iniquity of us all."}, {"numero": 7, "texto": "He was oppressed, and he was afflicted, yet he opened not his mouth: he is brought as a lamb to the slaughter, and as a sheep before her shearers is dumb, so he openeth not his mouth."}, {"numero": 8, "texto": "He was taken from prison and from judgment: and who shall declare his generation? for he was cut off out of the land of the living: for the transgression of my people was he stricken."}, {"numero": 9, "texto": "And he made his grave with the wicked, and with the rich in his death; because he had done no violence, neither was any deceit in his mouth."}, {"numero": 10, "texto": "Yet it pleased the Lord to bruise him; he hath put him to grief: when thou shalt make his soul an offering for sin, he shall see his seed, he shall prolong his days, and the pleasure of the Lord shall prosper in his hand."}, {"numero": 11, "texto": "He shall see of the travail of his soul, and shall be satisfied: by his knowledge shall my righteous servant justify many; for he shall bear their iniquities."}, {"numero": 12, "texto": "Therefore will I divide him a portion with the great, and he shall divide the spoil with the strong; because he hath poured out his soul unto death: and he was numbered with the transgressors; and he bare the sin of many, and made intercession for the transgressors."}]'::jsonb, 'King James Version'),
  ('Is', 53, 'fr', '[{"numero": 1, "texto": "Qui a cru à ce qui nous était annoncé? Qui a reconnu le bras de l''''Eternel?"}, {"numero": 2, "texto": "Il s''''est élevé devant lui comme une faible plante, Comme un rejeton qui sort d''''une terre desséchée; Il n''''avait ni beauté, ni éclat pour attirer nos regards, Et son aspect n''''avait rien pour nous plaire."}, {"numero": 3, "texto": "Méprisé et abandonné des hommes, Homme de douleur et habitué à la souffrance, Semblable à celui dont on détourne le visage, Nous l''''avons dédaigné, nous n''''avons fait de lui aucun cas."}, {"numero": 4, "texto": "Cependant, ce sont nos souffrances qu''''il a portées, C''''est de nos douleurs qu''''il s''''est chargé; Et nous l''''avons considéré comme puni, Frappé de Dieu, et humilié."}, {"numero": 5, "texto": "Mais il était blessé pour nos péchés, Brisé pour nos iniquités; Le châtiment qui nous donne la paix est tombé sur lui, Et c''''est par ses meurtrissures que nous sommes guéris."}, {"numero": 6, "texto": "Nous étions tous errants comme des brebis, Chacun suivait sa propre voie; Et l''''Eternel a fait retomber sur lui l''''iniquité de nous tous."}, {"numero": 7, "texto": "Il a été maltraité et opprimé, Et il n''''a point ouvert la bouche, Semblable à un agneau qu''''on mène à la boucherie, A une brebis muette devant ceux qui la tondent; Il n''''a point ouvert la bouche."}, {"numero": 8, "texto": "Il a été enlevé par l''''angoisse et le châtiment; Et parmi ceux de sa génération, qui a cru Qu''''il était retranché de la terre des vivants Et frappé pour les péchés de mon peuple?"}, {"numero": 9, "texto": "On a mis son sépulcre parmi les méchants, Son tombeau avec le riche, Quoiqu''''il n''''eût point commis de violence Et qu''''il n''''y eût point de fraude dans sa bouche."}, {"numero": 10, "texto": "Il a plu à l''''Eternel de le briser par la souffrance... Après avoir livré sa vie en sacrifice pour le péché, Il verra une postérité et prolongera ses jours; Et l''''oeuvre de l''''Eternel prospérera entre ses mains."}, {"numero": 11, "texto": "A cause du travail de son âme, il rassasiera ses regards; Par sa connaissance mon serviteur juste justifiera beaucoup d''''hommes, Et il se chargera de leurs iniquités."}, {"numero": 12, "texto": "C''''est pourquoi je lui donnerai sa part avec les grands; Il partagera le butin avec les puissants, Parce qu''''il s''''est livré lui-même à la mort, Et qu''''il a été mis au nombre des malfaiteurs, Parce qu''''il a porté les péchés de beaucoup d''''hommes, Et qu''''il a intercédé pour les coupables."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 53, 'es', '[{"numero": 1, "texto": "¿QUIÉN ha creído á nuestro anuncio? ¿y sobre quién se ha manifestado el brazo de Jehová?"}, {"numero": 2, "texto": "Y subirá cual renuevo delante de él, y como raíz de tierra seca: no hay parecer en él, ni hermosura: verlo hemos, mas sin atractivo para que le deseemos."}, {"numero": 3, "texto": "Despreciado y desechado entre los hombres, varón de dolores, experimentado en quebranto: y como que escondimos de él el rostro, fué menospreciado, y no lo estimamos."}, {"numero": 4, "texto": "Ciertamente llevó él nuestras enfermedades, y sufrió nuestros dolores; y nosotros le tuvimos por azotado, por herido de Dios y abatido."}, {"numero": 5, "texto": "Mas él herido fué por nuestras rebeliones, molido por nuestros pecados: el castigo de nuestra paz sobre él; y por su llaga fuimos nosotros curados."}, {"numero": 6, "texto": "Todos nosotros nos descarriamos como ovejas, cada cual se apartó por su camino: mas Jehová cargó en él el pecado de todos nosotros."}, {"numero": 7, "texto": "Angustiado él, y afligido, no abrió su boca: como cordero fué llevado al matadero; y como oveja delante de sus trasquiladores, enmudeció, y no abrió su boca."}, {"numero": 8, "texto": "De la cárcel y del juicio fué quitado; y su generación ¿quién la contará? Porque cortado fué de la tierra de los vivientes; por la rebelión de mi pueblo fué herido."}, {"numero": 9, "texto": "Y dispúsose con los impíos su sepultura, mas con los ricos fué en su muerte; porque nunca hizo él maldad, ni hubo engaño en su boca."}, {"numero": 10, "texto": "Con todo eso Jehová quiso quebrantarlo, sujetándole á padecimiento. Cuando hubiere puesto su vida en expiación por el pecado, verá linaje, vivirá por largos días, y la voluntad de Jehová será en su mano prosperada."}, {"numero": 11, "texto": "Del trabajo de su alma verá y será saciado; con su conocimiento justificará mi siervo justo á muchos, y él llevará las iniquidades de ellos."}, {"numero": 12, "texto": "Por tanto yo le daré parte con los grandes, y con los fuertes repartirá despojos; por cuanto derramó su vida hasta la muerte, y fué contado con los perversos, habiendo él llevado el pecado de muchos, y orado por los transgresores."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 54, 'pt', '[{"numero": 1, "texto": "Canta alegremente, ó estéril, [que] não geravas; grita de prazer com alegre canto, e jubila tu que não tiveste dores de parto; pois mais são os filhos da solitária do que os filhos da casada, diz o SENHOR."}, {"numero": 2, "texto": "Aumenta o espaço de tua tenda, e as cortinas de tuas habitações sejam estendidas; não o impeças; alonga tuas cordas, e fixa bem tuas estacas;"}, {"numero": 3, "texto": "Porque transbordarás à direita e à esquerda; e tua semente tomará posse das nações, e farão habitar as cidades assoladas."}, {"numero": 4, "texto": "Não temas, pois não serás envergonhada; e não te envergonhes, pois não serás humilhada; ao contrário, te esquecerás da vergonha da tua juventude, e não te lembrarás mais da desonra de tua viuvez."}, {"numero": 5, "texto": "Porque teu marido é o Criador; EU-SOU dos exércitos é o seu nome; e o Santo de Israel é o teu Redentor; ele será chamado: o Deus de toda a terra."}, {"numero": 6, "texto": "Pois o SENHOR te chamou como mulher abandonada, e triste de espírito; como uma mulher da juventude que havia sido rejeitada, diz o teu Deus."}, {"numero": 7, "texto": "Por um curto momento te deixei; porém com grandes misericórdias te recolherei."}, {"numero": 8, "texto": "Num acesso de ira escondi minha face de ti por um momento; porém com bondade eterna terei compaixão de ti, diz o SENHOR teu Redentor."}, {"numero": 9, "texto": "Porque isto será para mim [como] as águas de Noé, quando jurei que as águas de Noé não mais passaria sobre a terra; assim jurei, que não me irarei contra ti, nem te repreenderei."}, {"numero": 10, "texto": "Porque montes se removerão e morros se retirarão, porém minha bondade não se removerá de ti, nem o pacto de minha paz se retirará, diz o SENHOR, que tem compaixão de ti."}, {"numero": 11, "texto": "Tu, oprimida, afligida por tempestade, [e] desconsolada: eis que eu porei tuas pedras com ornamentos, e te fundarei sobre safiras."}, {"numero": 12, "texto": "E farei de rubis as tuas torres; e tuas portas de carbúnculos, e todos os teus limites com pedras preciosas."}, {"numero": 13, "texto": "E todos os teus filhos serão ensinados pelo SENHOR; e a paz de teus filhos será abundante."}, {"numero": 14, "texto": "Com justiça serás firmada; afasta-te da opressão, porque já não temerás; assim como também do assombro, porque este não se aproximará de ti."}, {"numero": 15, "texto": "Se alguém lutar [contra ti] ,não será por mim; quem lutar contra ti cairá por causa de ti."}, {"numero": 16, "texto": "Eis que fui eu que criei ao ferreiro que assopra as brasas no fogo, e que produz a ferramenta para sua obra; também fui eu que criei ao destruidor, para causar ruína."}, {"numero": 17, "texto": "Nenhuma ferramenta preparada contra ti terá sucesso; e toda língua que se levantar contra ti em juízo, tu a condenarás; esta é a herança dos servos do SENHOR; e a justiça deles [provém] de mim, diz o SENHOR."}]'::jsonb, 'Almeida Livre'),
  ('Is', 54, 'en', '[{"numero": 1, "texto": "Sing, O barren, thou that didst not bear; break forth into singing, and cry aloud, thou that didst not travail with child: for more are the children of the desolate than the children of the married wife, saith the Lord."}, {"numero": 2, "texto": "Enlarge the place of thy tent, and let them stretch forth the curtains of thine habitations: spare not, lengthen thy cords, and strengthen thy stakes;"}, {"numero": 3, "texto": "For thou shalt break forth on the right hand and on the left; and thy seed shall inherit the Gentiles, and make the desolate cities to be inhabited."}, {"numero": 4, "texto": "Fear not; for thou shalt not be ashamed: neither be thou confounded; for thou shalt not be put to shame: for thou shalt forget the shame of thy youth, and shalt not remember the reproach of thy widowhood any more."}, {"numero": 5, "texto": "For thy Maker is thine husband; the Lord of hosts is his name; and thy Redeemer the Holy One of Israel; The God of the whole earth shall he be called."}, {"numero": 6, "texto": "For the Lord hath called thee as a woman forsaken and grieved in spirit, and a wife of youth, when thou wast refused, saith thy God."}, {"numero": 7, "texto": "For a small moment have I forsaken thee; but with great mercies will I gather thee."}, {"numero": 8, "texto": "In a little wrath I hid my face from thee for a moment; but with everlasting kindness will I have mercy on thee, saith the Lord thy Redeemer."}, {"numero": 9, "texto": "For this is as the waters of Noah unto me: for as I have sworn that the waters of Noah should no more go over the earth; so have I sworn that I would not be wroth with thee, nor rebuke thee."}, {"numero": 10, "texto": "For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the Lord that hath mercy on thee."}, {"numero": 11, "texto": "O thou afflicted, tossed with tempest, and not comforted, behold, I will lay thy stones with fair colours, and lay thy foundations with sapphires."}, {"numero": 12, "texto": "And I will make thy windows of agates, and thy gates of carbuncles, and all thy borders of pleasant stones."}, {"numero": 13, "texto": "And all thy children shall be taught of the Lord; and great shall be the peace of thy children."}, {"numero": 14, "texto": "In righteousness shalt thou be established: thou shalt be far from oppression; for thou shalt not fear: and from terror; for it shall not come near thee."}, {"numero": 15, "texto": "Behold, they shall surely gather together, but not by me: whosoever shall gather together against thee shall fall for thy sake."}, {"numero": 16, "texto": "Behold, I have created the smith that bloweth the coals in the fire, and that bringeth forth an instrument for his work; and I have created the waster to destroy."}, {"numero": 17, "texto": "No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the Lord, and their righteousness is of me, saith the Lord."}]'::jsonb, 'King James Version'),
  ('Is', 54, 'fr', '[{"numero": 1, "texto": "Réjouis-toi, stérile, toi qui n''''enfantes plus! Fais éclater ton allégresse et ta joie, toi qui n''''as plus de douleurs! Car les fils de la délaissée seront plus nombreux Que les fils de celle qui est mariée, dit l''''Eternel."}, {"numero": 2, "texto": "Elargis l''''espace de ta tente; Qu''''on déploie les couvertures de ta demeure: Ne retiens pas! Allonge tes cordages, Et affermis tes pieux!"}, {"numero": 3, "texto": "Car tu te répandras à droite et à gauche; Ta postérité envahira des nations, Et peuplera des villes désertes."}, {"numero": 4, "texto": "Ne crains pas, car tu ne seras point confondue; Ne rougis pas, car tu ne seras pas déshonorée; Mais tu oublieras la honte de ta jeunesse, Et tu ne te souviendras plus de l''''opprobre de ton veuvage."}, {"numero": 5, "texto": "Car ton créateur est ton époux: L''''Eternel des armées est son nom; Et ton rédempteur est le Saint d''''Israël: Il se nomme Dieu de toute la terre;"}, {"numero": 6, "texto": "Car l''''Eternel te rappelle comme une femme délaissée et au coeur attristé, Comme une épouse de la jeunesse qui a été répudiée, dit ton Dieu."}, {"numero": 7, "texto": "Quelques instants je t''''avais abandonnée, Mais avec une grande affection je t''''accueillerai;"}, {"numero": 8, "texto": "Dans un instant de colère, je t''''avais un moment dérobé ma face, Mais avec un amour éternel j''''aurai compassion de toi, Dit ton rédempteur, l''''Eternel."}, {"numero": 9, "texto": "Il en sera pour moi comme des eaux de Noé: J''''avais juré que les eaux de Noé ne se répandraient plus sur la terre; Je jure de même de ne plus m''''irriter contre toi Et de ne plus te menacer."}, {"numero": 10, "texto": "Quand les montagnes s''''éloigneraient, Quand les collines chancelleraient, Mon amour ne s''''éloignera point de toi, Et mon alliance de paix ne chancellera point, Dit l''''Eternel, qui a compassion de toi."}, {"numero": 11, "texto": "Malheureuse, battue de la tempête, et que nul ne console! Voici, je garnirai tes pierres d''''antimoine, Et je te donnerai des fondements de saphir;"}, {"numero": 12, "texto": "Je ferai tes créneaux de rubis, Tes portes d''''escarboucles, Et toute ton enceinte de pierres précieuses."}, {"numero": 13, "texto": "Tous tes fils seront disciples de l''''Eternel, Et grande sera la prospérité de tes fils."}, {"numero": 14, "texto": "Tu seras affermie par la justice; Bannis l''''inquiétude, car tu n''''as rien à craindre, Et la frayeur, car elle n''''approchera pas de toi."}, {"numero": 15, "texto": "Si l''''on forme des complots, cela ne viendra pas de moi; Quiconque se liguera contre toi tombera sous ton pouvoir."}, {"numero": 16, "texto": "Voici, j''''ai créé l''''ouvrier qui souffle le charbon au feu, Et qui fabrique une arme par son travail; Mais j''''ai créé aussi le destructeur pour la briser."}, {"numero": 17, "texto": "Toute arme forgée contre toi sera sans effet; Et toute langue qui s''''élèvera en justice contre toi, Tu la condamneras. Tel est l''''héritage des serviteurs de l''''Eternel, Tel est le salut qui leur viendra de moi, Dit l''''Eternel."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 54, 'es', '[{"numero": 1, "texto": "ALÉGRATE, oh estéril, la que no paría; levanta canción, y da voces de júbilo, la que nunca estuvo de parto: porque más son los hijos de la dejada que los de la casada, ha dicho Jehová."}, {"numero": 2, "texto": "Ensancha el sitio de tu cabaña, y las cortinas de tus tiendas sean extendidas; no seas escasa; alarga tus cuerdas, y fortifica tus estacas."}, {"numero": 3, "texto": "Porque á la mano derecha y á la mano izquierda has de crecer; y tu simiente heredará gentes, y habitarán las ciudades asoladas."}, {"numero": 4, "texto": "No temas, que no serás avergonzada; y no te avergüences, que no serás afrentada: antes, te olvidarás de la vergüenza de tu mocedad, y de la afrenta de tu viudez no tendrás más memoria."}, {"numero": 5, "texto": "Porque tu marido es tu Hacedor; Jehová de los ejércitos es su nombre: y tu redentor, el Santo de Israel; Dios de toda la tierra será llamado."}, {"numero": 6, "texto": "Porque como á mujer dejada y triste de espíritu te llamó Jehová, y como á mujer moza que es repudiada, dijo el Dios tuyo."}, {"numero": 7, "texto": "Por un pequeño momento te dejé; mas te recogeré con grandes misericordias."}, {"numero": 8, "texto": "Con un poco de ira escondí mi rostro de ti por un momento; mas con misericordia eterna tendré compasión de ti, dijo tu Redentor Jehová."}, {"numero": 9, "texto": "Porque esto me será como las aguas de Noé; que juré que nunca más las aguas de Noé pasarían sobre la tierra; así he jurado que no me enojaré contra ti, ni te reñiré."}, {"numero": 10, "texto": "Porque los montes se moverán, y los collados temblarán; mas no se apartará de ti mi misericordia, ni el pacto de mi paz vacilará, dijo Jehová, el que tiene misericordia de ti."}, {"numero": 11, "texto": "Pobrecita, fatigada con tempestad, sin consuelo; he aquí que yo cimentaré tus piedras sobre carbunclo, y sobre zafiros te fundaré."}, {"numero": 12, "texto": "Tus ventanas pondré de piedras preciosas, tus puertas de piedras de carbunclo, y todo tu término de piedras de buen gusto."}, {"numero": 13, "texto": "Y todos tus hijos serán enseñados de Jehová; y multiplicará la paz de tus hijos."}, {"numero": 14, "texto": "Con justicia serás adornada; estarás lejos de opresión, porque no temerás; y de temor, porque no se acercará á ti."}, {"numero": 15, "texto": "Si alguno conspirare contra ti, será sin mí: el que contra ti conspirare, delante de ti caerá."}, {"numero": 16, "texto": "He aquí que yo crié al herrero que sopla las ascuas en el fuego, y que saca la herramienta para su obra; y yo he criado al destruidor para destruir."}, {"numero": 17, "texto": "Toda herramienta que fuere fabricada contra ti, no prosperará; y tú condenarás toda lengua que se levantare contra ti en juicio. Esta es la heredad de los siervos de Jehová, y su justicia de por mí, dijo Jehová."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 60, 'pt', '[{"numero": 1, "texto": "Levanta-te! Brilha! Porque já chegou a tua luz; e a glória do SENHOR já está raiando sobre ti."}, {"numero": 2, "texto": "Porque eis que as trevas cobrirão a terra, e a escuridão aos povos; porém sobre ti o SENHOR virá raiando, e sua glória será vista sobre ti."}, {"numero": 3, "texto": "E as nações virão à tua luz, e os reis ao brilho que raiou a ti."}, {"numero": 4, "texto": "Levanta teus olhos ao redor, e vê; todos estes se ajuntaram, [e] vem a ti; teus filhos virão de longe, e tuas filhas serão criadas ao teu lado."}, {"numero": 5, "texto": "Então verás, e te alegrarás; teu coração palpitará e se encherá de alegria, porque a abundância do mar a ti se voltará, as riquezas das nações a ti chegarão."}, {"numero": 6, "texto": "Multidão de camelos te cobrirá; dromedários de Midiã e Efá, todos virão de Sabá; trarão ouro e incenso, e declararão louvores ao SENHOR."}, {"numero": 7, "texto": "Todas as ovelhas de Quedar se ajuntarão a ti; os carneiros de Nebaiote te servirão; com agrado subirão ao meu altar, e eu glorificarei a casa de minha glória."}, {"numero": 8, "texto": "Quem são estes que vêm voando como nuvens, e como pombas às suas janelas?"}, {"numero": 9, "texto": "Pois as ilhas me esperarão, e primeiro os navios de Társis, para trazer teus filhos de longe, sua prata e seu ouro com eles; para o nome do SENHOR teu Deus, e para o Santo de Israel, porque ele te glorificou."}, {"numero": 10, "texto": "E filhos de estrangeiros edificarão teus muros, e seus reis te servirão; porque em minha ira eu te feri, porém em meu favor tive misericórdia de ti."}, {"numero": 11, "texto": "E tuas portas estarão continuamente abertas, nem de dia nem de noite se fecharão; para que tragam a ti as riquezas das nações, e seus reis [a ti] sejam trazidos."}, {"numero": 12, "texto": "Pois a nação e reino que não te servirem perecerão; e tais nações serão assoladas por completo."}, {"numero": 13, "texto": "A glória do Líbano virá a ti, a faia, o pinheiro, e o cipreste juntamente, para ornamentarem o lugar do meu santuário, e glorificarei o lugar de meus pés."}, {"numero": 14, "texto": "Também virão a ti inclinados os filhos dos que te oprimiram, e se prostrarão às pisadas de teus pés todos os que blasfemaram de ti; e te chamarão a cidade do SENHOR, a Sião do Santo de Israel."}, {"numero": 15, "texto": "Em vez de abandonada e odiada, [de tal modo] que ninguém passava [por ti] ,eu farei de ti uma excelência eterna, alegria de geração após geração."}, {"numero": 16, "texto": "E mamarás o leite das nações, e mamarás os peitos dos reis; e saberás que eu sou o SENHOR, teu Salvador e teu Redentor, o Poderoso de Jacó."}, {"numero": 17, "texto": "Em vez de bronze trarei ouro, e em vez de ferro trarei prata, e em vez de madeira bronze, e em vez de pedras ferro; e farei pacíficos teus oficiais, e justos aqueles que cobram de ti."}, {"numero": 18, "texto": "Nunca mais se ouvirá falar de violência em tua terra; [nem] ruína, nem destruição dentro de tuas fronteiras; em vez disso, a teus muros chamarás Salvação, e a tuas portas Louvor."}, {"numero": 19, "texto": "Nunca mais o sol te servirá para luz do dia, nem com [seu] brilho a lua te iluminará; mas o SENHOR será tua luz eterna, e teu Deus o teu ornamento."}, {"numero": 20, "texto": "Nunca mais o teu sol irá se por, nem tua lua minguará; porque o SENHOR será tua luz eterna, e os dias de teu luto se acabarão."}, {"numero": 21, "texto": "E todos os de teu povo serão justos; para sempre terão posse da terra; serão renovo de minha plantação, obra de minhas mãos, para que eu seja glorificado."}, {"numero": 22, "texto": "O menor será mil, e o de menor tamanho será um povo forte; eu, o SENHOR, o farei depressa em seu [devido] tempo."}]'::jsonb, 'Almeida Livre'),
  ('Is', 60, 'en', '[{"numero": 1, "texto": "Arise, shine; for thy light is come, and the glory of the Lord is risen upon thee."}, {"numero": 2, "texto": "For, behold, the darkness shall cover the earth, and gross darkness the people: but the Lord shall arise upon thee, and his glory shall be seen upon thee."}, {"numero": 3, "texto": "And the Gentiles shall come to thy light, and kings to the brightness of thy rising."}, {"numero": 4, "texto": "Lift up thine eyes round about, and see: all they gather themselves together, they come to thee: thy sons shall come from far, and thy daughters shall be nursed at thy side."}, {"numero": 5, "texto": "Then thou shalt see, and flow together, and thine heart shall fear, and be enlarged; because the abundance of the sea shall be converted unto thee, the forces of the Gentiles shall come unto thee."}, {"numero": 6, "texto": "The multitude of camels shall cover thee, the dromedaries of Midian and Ephah; all they from Sheba shall come: they shall bring gold and incense; and they shall shew forth the praises of the Lord."}, {"numero": 7, "texto": "All the flocks of Kedar shall be gathered together unto thee, the rams of Nebaioth shall minister unto thee: they shall come up with acceptance on mine altar, and I will glorify the house of my glory."}, {"numero": 8, "texto": "Who are these that fly as a cloud, and as the doves to their windows?"}, {"numero": 9, "texto": "Surely the isles shall wait for me, and the ships of Tarshish first, to bring thy sons from far, their silver and their gold with them, unto the name of the Lord thy God, and to the Holy One of Israel, because he hath glorified thee."}, {"numero": 10, "texto": "And the sons of strangers shall build up thy walls, and their kings shall minister unto thee: for in my wrath I smote thee, but in my favour have I had mercy on thee."}, {"numero": 11, "texto": "Therefore thy gates shall be open continually; they shall not be shut day nor night; that men may bring unto thee the forces of the Gentiles, and that their kings may be brought."}, {"numero": 12, "texto": "For the nation and kingdom that will not serve thee shall perish; yea, those nations shall be utterly wasted."}, {"numero": 13, "texto": "The glory of Lebanon shall come unto thee, the fir tree, the pine tree, and the box together, to beautify the place of my sanctuary; and I will make the place of my feet glorious."}, {"numero": 14, "texto": "The sons also of them that afflicted thee shall come bending unto thee; and all they that despised thee shall bow themselves down at the soles of thy feet; and they shall call thee; The city of the Lord, The Zion of the Holy One of Israel."}, {"numero": 15, "texto": "Whereas thou has been forsaken and hated, so that no man went through thee, I will make thee an eternal excellency, a joy of many generations."}, {"numero": 16, "texto": "Thou shalt also suck the milk of the Gentiles, and shalt suck the breast of kings: and thou shalt know that I the Lord am thy Saviour and thy Redeemer, the mighty One of Jacob."}, {"numero": 17, "texto": "For brass I will bring gold, and for iron I will bring silver, and for wood brass, and for stones iron: I will also make thy officers peace, and thine exactors righteousness."}, {"numero": 18, "texto": "Violence shall no more be heard in thy land, wasting nor destruction within thy borders; but thou shalt call thy walls Salvation, and thy gates Praise."}, {"numero": 19, "texto": "The sun shall be no more thy light by day; neither for brightness shall the moon give light unto thee: but the Lord shall be unto thee an everlasting light, and thy God thy glory."}, {"numero": 20, "texto": "Thy sun shall no more go down; neither shall thy moon withdraw itself: for the Lord shall be thine everlasting light, and the days of thy mourning shall be ended."}, {"numero": 21, "texto": "Thy people also shall be all righteous: they shall inherit the land for ever, the branch of my planting, the work of my hands, that I may be glorified."}, {"numero": 22, "texto": "A little one shall become a thousand, and a small one a strong nation: I the Lord will hasten it in his time."}]'::jsonb, 'King James Version'),
  ('Is', 60, 'fr', '[{"numero": 1, "texto": "Lève-toi, sois éclairée, car ta lumière arrive, Et la gloire de l''''Eternel se lève sur toi."}, {"numero": 2, "texto": "Voici, les ténèbres couvrent la terre, Et l''''obscurité les peuples; Mais sur toi l''''Eternel se lève, Sur toi sa gloire apparaît."}, {"numero": 3, "texto": "Des nations marchent à ta lumière, Et des rois à la clarté de tes rayons."}, {"numero": 4, "texto": "Porte tes yeux alentour, et regarde: Tous ils s''''assemblent, ils viennent vers toi; Tes fils arrivent de loin, Et tes filles sont portées sur les bras."}, {"numero": 5, "texto": "Tu tressailliras alors et tu te réjouiras, Et ton coeur bondira et se dilatera, Quand les richesses de la mer se tourneront vers toi, Quand les trésors des nations viendront à toi."}, {"numero": 6, "texto": "Tu seras couverte d''''une foule de chameaux, De dromadaires de Madian et d''''Epha; Ils viendront tous de Séba; Ils porteront de l''''or et de l''''encens, Et publieront les louanges de l''''Eternel."}, {"numero": 7, "texto": "Les troupeaux de Kédar se réuniront tous chez toi; Les béliers de Nebajoth seront à ton service; Ils monteront sur mon autel et me seront agréables, Et je glorifierai la maison de ma gloire."}, {"numero": 8, "texto": "Qui sont ceux-là qui volent comme des nuées, Comme des colombes vers leur colombier?"}, {"numero": 9, "texto": "Car les îles espèrent en moi, Et les navires de Tarsis sont en tête, Pour ramener de loin tes enfants, Avec leur argent et leur or, A cause du nom de l''''Eternel, ton Dieu, Du Saint d''''Israël qui te glorifie."}, {"numero": 10, "texto": "Les fils de l''''étranger rebâtiront tes murs, Et leurs rois seront tes serviteurs; Car je t''''ai frappée dans ma colère, Mais dans ma miséricorde j''''ai pitié de toi."}, {"numero": 11, "texto": "Tes portes seront toujours ouvertes, Elles ne seront fermées ni jour ni nuit, Afin de laisser entrer chez toi les trésors des nations, Et leurs rois avec leur suite."}, {"numero": 12, "texto": "Car la nation et le royaume qui ne te serviront pas périront, Ces nations-là seront exterminées."}, {"numero": 13, "texto": "La gloire du Liban viendra chez toi, Le cyprès, l''''orme et le buis, tous ensemble, Pour orner le lieu de mon sanctuaire, Et je glorifierai la place où reposent mes pieds."}, {"numero": 14, "texto": "Les fils de tes oppresseurs viendront s''''humilier devant toi, Et tous ceux qui te méprisaient se prosterneront à tes pieds; Ils t''''appelleront ville de l''''Eternel, Sion du Saint d''''Israël."}, {"numero": 15, "texto": "Au lieu que tu étais délaissée et haïe, Et que personne ne te parcourait, Je ferai de toi un ornement pour toujours, Un sujet de joie de génération en génération."}, {"numero": 16, "texto": "Tu suceras le lait des nations, Tu suceras la mamelle des rois; Et tu sauras que je suis l''''Eternel, ton sauveur, Ton rédempteur, le puissant de Jacob."}, {"numero": 17, "texto": "Au lieu de l''''airain je ferai venir de l''''or, Au lieu du fer je ferai venir de l''''argent, Au lieu du bois, de l''''airain, Et au lieu des pierres, du fer; Je ferai régner sur toi la paix, Et dominer la justice."}, {"numero": 18, "texto": "On n''''entendra plus parler de violence dans ton pays, Ni de ravage et de ruine dans ton territoire; Tu donneras à tes murs le nom de salut, Et à tes portes celui de gloire."}, {"numero": 19, "texto": "Ce ne sera plus le soleil qui te servira de lumière pendant le jour, Ni la lune qui t''''éclairera de sa lueur; Mais l''''Eternel sera ta lumière à toujours, Ton Dieu sera ta gloire."}, {"numero": 20, "texto": "Ton soleil ne se couchera plus, Et ta lune ne s''''obscurcira plus; Car l''''Eternel sera ta lumière à toujours, Et les jours de ton deuil seront passés."}, {"numero": 21, "texto": "Il n''''y aura plus que des justes parmi ton peuple, Ils posséderont à toujours le pays; C''''est le rejeton que j''''ai planté, l''''oeuvre de mes mains, Pour servir à ma gloire."}, {"numero": 22, "texto": "Le plus petit deviendra un millier, Et le moindre une nation puissante. Moi, l''''Eternel, je hâterai ces choses en leur temps."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 60, 'es', '[{"numero": 1, "texto": "LEVÁNTATE, resplandece; que ha venido tu lumbre, y la gloria de Jehová ha nacido sobre ti."}, {"numero": 2, "texto": "Porque he aquí que tinieblas cubrirán la tierra, y oscuridad los pueblos: mas sobre ti nacerá Jehová, y sobre ti será vista su gloria."}, {"numero": 3, "texto": "Y andarán las gentes á tu luz, y los reyes al resplandor de tu nacimiento."}, {"numero": 4, "texto": "Alza tus ojos en derredor, y mira: todos estos se han juntado, vinieron á ti: tus hijos vendrán de lejos, y tus hijas sobre el lado serán criadas."}, {"numero": 5, "texto": "Entonces verás y resplandecerás; y se maravillará y ensanchará tu corazón, que se haya vuelto á ti la multitud de la mar, y la fortaleza de las gentes haya venido á ti."}, {"numero": 6, "texto": "Multitud de camellos te cubrirá, dromedarios de Madián y de Epha; vendrán todos los de Seba; traerán oro é incienso, y publicarán alabanzas de Jehová."}, {"numero": 7, "texto": "Todo el ganado de Cedar será juntado para ti: carneros de Nebayoth te serán servidos: serán ofrecidos con agrado sobre mi altar, y glorificaré la casa de mi gloria."}, {"numero": 8, "texto": "¿Quiénes son estos que vuelan como nubes, y como palomas á sus ventanas?"}, {"numero": 9, "texto": "Ciertamente á mí esperarán las islas, y las naves de Tarsis desde el principio, para traer tus hijos de lejos, su plata y su oro con ellos, al nombre de Jehová tu Dios, y al Santo de Israel, que te ha glorificado."}, {"numero": 10, "texto": "Y los hijos de los extranjeros edificarán tus muros, y sus reyes te servirán; porque en mi ira te herí, mas en mi buena voluntad tendré de ti misericordia."}, {"numero": 11, "texto": "Tus puertas estarán de continuo abiertas; no se cerrarán de día ni de noche; para que sea traída á ti fortaleza de gentes, y sus reyes conducidos."}, {"numero": 12, "texto": "Porque la gente ó el reino que no te sirviere, perecerá; y del todo serán asoladas."}, {"numero": 13, "texto": "La gloria del Líbano vendrá á ti, hayas, pinos, y bojes juntamente, para decorar el lugar de mi santuario; y yo honraré el lugar de mis pies."}, {"numero": 14, "texto": "Y vendrán á ti humillados los hijos de los que te afligieron, y á las pisadas de tus pies se encorvarán todos los que te escarnecían, y llamarte han Ciudad de Jehová, Sión del Santo de Israel."}, {"numero": 15, "texto": "En lugar de que has sido desechada y aborrecida, y que no había quien por ti pasase, ponerte he en gloria perpetua, gozo de generación y generación."}, {"numero": 16, "texto": "Y mamarás la leche de las gentes, el pecho de los reyes mamarás; y conocerás que yo Jehová soy el Salvador tuyo, y Redentor tuyo, el Fuerte de Jacob."}, {"numero": 17, "texto": "En vez de cobre traeré oro, y por hierro plata, y por madera metal, y en lugar de piedras hierro; y pondré paz por tu tributo, y justicia por tus exactores."}, {"numero": 18, "texto": "Nunca más se oirá en tu tierra violencia, destrucción ni quebrantamiento en tus términos; mas á tus muros llamarás Salud, y á tus puertas Alabanza."}, {"numero": 19, "texto": "El sol nunca más te servirá de luz para el día, ni el resplandor de la luna te alumbrará; sino que Jehová te será por luz perpetua, y el Dios tuyo por tu gloria."}, {"numero": 20, "texto": "No se pondrá jamás tu sol, ni menguará tu luna: porque te será Jehová por luz perpetua, y los días de tu luto serán acabados."}, {"numero": 21, "texto": "Y tu pueblo, todos ellos serán justos, para siempre heredarán la tierra; renuevos de mi plantío, obra de mis manos, para glorificarme."}, {"numero": 22, "texto": "El pequeño será por mil, el menor, por gente fuerte. Yo Jehová á su tiempo haré que esto sea presto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Is', 61, 'pt', '[{"numero": 1, "texto": "O Espírito do Senhor DEUS está sobre mim; pois o SENHOR me ungiu, para dar boas novas aos mansos; ele me enviou para sarar aos feridos de coração, para anunciar liberdade aos cativos, e libertação aos prisioneiros."}, {"numero": 2, "texto": "Para anunciar o ano do favor do SENHOR, e o dia da vingança de nosso Deus; para consolar todos os tristes."}, {"numero": 3, "texto": "Para ordenar aos tristes de Sião, que lhes seja dado ornamento no lugar de cinza, óleo de alegria no lugar de tristeza, vestes de louvor no lugar de espírito angustiado; para que sejam chamados de carvalhos da justiça, plantação do SENHOR; para que ele seja glorificado."}, {"numero": 4, "texto": "E edificarão os lugares arruinados desde os tempos antigos, restaurarão os desde antes destruídos, e renovarão as cidades arruinadas, destruídas desde muitas gerações."}, {"numero": 5, "texto": "E estrangeiros apascentarão vossos rebanhos, e filhos de outras nações serão vossos lavradores e vossos trabalhadores nas vinhas."}, {"numero": 6, "texto": "Porém vós sereis chamados sacerdotes do SENHOR; chamarão a vós de trabalhadores a serviço de nosso Deus; comereis dos bens das nações, e da riqueza deles vós vos orgulhareis."}, {"numero": 7, "texto": "Em vez de vossa vergonha, [tereis] porção dobrada; e [em vez] de humilhação, terão alegria sobre sua parte; pois em sua terra terão posse do dobro, [e] terão alegria eterna."}, {"numero": 8, "texto": "Porque eu, o SENHOR, amo a justiça, e odeio o roubo com sacrifício de queima; e farei que sua obra seja em verdade, e farei um pacto eterno com eles."}, {"numero": 9, "texto": "E sua descendência será conhecida entre as nações, e seus descendentes em meio aos povos; todos quantos os virem, os reconhecerão, que são descendência abençoada pelo SENHOR."}, {"numero": 10, "texto": "Eu estou muito jubilante no SENHOR, minha alma se alegra em meu Deus; porque ele me vestiu de roupas de salvação; ele me cobriu com a capa da justiça, tal como o noivo [quando] se veste da roupa sacerdotal, e como a noiva se enfeita com suas joias."}, {"numero": 11, "texto": "Porque tal como a terra produz seus renovos, e como o jardim faz brotar o que nele se semeia, assim também o Senhor DEUS fará brotar justiça e louvor diante de todas as nações."}]'::jsonb, 'Almeida Livre'),
  ('Is', 61, 'en', '[{"numero": 1, "texto": "The Spirit of the Lord God is upon me; because the Lord hath anointed me to preach good tidings unto the meek; he hath sent me to bind up the brokenhearted, to proclaim liberty to the captives, and the opening of the prison to them that are bound;"}, {"numero": 2, "texto": "To proclaim the acceptable year of the Lord, and the day of vengeance of our God; to comfort all that mourn;"}, {"numero": 3, "texto": "To appoint unto them that mourn in Zion, to give unto them beauty for ashes, the oil of joy for mourning, the garment of praise for the spirit of heaviness; that they might be called trees of righteousness, the planting of the Lord, that he might be glorified."}, {"numero": 4, "texto": "And they shall build the old wastes, they shall raise up the former desolations, and they shall repair the waste cities, the desolations of many generations."}, {"numero": 5, "texto": "And strangers shall stand and feed your flocks, and the sons of the alien shall be your plowmen and your vinedressers."}, {"numero": 6, "texto": "But ye shall be named the Priests of the Lord: men shall call you the Ministers of our God: ye shall eat the riches of the Gentiles, and in their glory shall ye boast yourselves."}, {"numero": 7, "texto": "For your shame ye shall have double; and for confusion they shall rejoice in their portion: therefore in their land they shall possess the double: everlasting joy shall be unto them."}, {"numero": 8, "texto": "For I the Lord love judgment, I hate robbery for burnt offering; and I will direct their work in truth, and I will make an everlasting covenant with them."}, {"numero": 9, "texto": "And their seed shall be known among the Gentiles, and their offspring among the people: all that see them shall acknowledge them, that they are the seed which the Lord hath blessed."}, {"numero": 10, "texto": "I will greatly rejoice in the Lord, my soul shall be joyful in my God; for he hath clothed me with the garments of salvation, he hath covered me with the robe of righteousness, as a bridegroom decketh himself with ornaments, and as a bride adorneth herself with her jewels."}, {"numero": 11, "texto": "For as the earth bringeth forth her bud, and as the garden causeth the things that are sown in it to spring forth; so the Lord God will cause righteousness and praise to spring forth before all the nations."}]'::jsonb, 'King James Version'),
  ('Is', 61, 'fr', '[{"numero": 1, "texto": "L''''esprit du Seigneur, l''''Eternel, est sur moi, Car l''''Eternel m''''a oint pour porter de bonnes nouvelles aux malheureux; Il m''''a envoyé pour guérir ceux qui ont le coeur brisé, Pour proclamer aux captifs la liberté, Et aux prisonniers la délivrance;"}, {"numero": 2, "texto": "Pour publier une année de grâce de l''''Eternel, Et un jour de vengeance de notre Dieu; Pour consoler tous les affligés;"}, {"numero": 3, "texto": "Pour accorder aux affligés de Sion, Pour leur donner un diadème au lieu de la cendre, Une huile de joie au lieu du deuil, Un vêtement de louange au lieu d''''un esprit abattu, Afin qu''''on les appelle des térébinthes de la justice, Une plantation de l''''Eternel, pour servir à sa gloire."}, {"numero": 4, "texto": "Ils rebâtiront sur d''''anciennes ruines, Ils relèveront d''''antiques décombres, Ils renouvelleront des villes ravagées, Dévastées depuis longtemps."}, {"numero": 5, "texto": "Des étrangers seront là et feront paître vos troupeaux, Des fils de l''''étranger seront vos laboureurs et vos vignerons."}, {"numero": 6, "texto": "Mais vous, on vous appellera sacrificateurs de l''''Eternel, On vous nommera serviteurs de notre Dieu; Vous mangerez les richesses des nations, Et vous vous glorifierez de leur gloire."}, {"numero": 7, "texto": "Au lieu de votre opprobre, vous aurez une portion double; Au lieu de l''''ignominie, ils seront joyeux de leur part; Ils posséderont ainsi le double dans leur pays, Et leur joie sera éternelle."}, {"numero": 8, "texto": "Car moi, l''''Eternel, j''''aime la justice, Je hais la rapine avec l''''iniquité; Je leur donnerai fidèlement leur récompense, Et je traiterai avec eux une alliance éternelle."}, {"numero": 9, "texto": "Leur race sera connue parmi les nations, Et leur postérité parmi les peuples; Tous ceux qui les verront reconnaîtront Qu''''ils sont une race bénie de l''''Eternel."}, {"numero": 10, "texto": "Je me réjouirai en l''''Eternel, Mon âme sera ravie d''''allégresse en mon Dieu; Car il m''''a revêtu des vêtements du salut, Il m''''a couvert du manteau de la délivrance, Comme le fiancé s''''orne d''''un diadème, Comme la fiancée se pare de ses joyaux."}, {"numero": 11, "texto": "Car, comme la terre fait éclore son germe, Et comme un jardin fait pousser ses semences, Ainsi le Seigneur, l''''Eternel, fera germer le salut et la louange, En présence de toutes les nations."}]'::jsonb, 'Louis Segond 1910'),
  ('Is', 61, 'es', '[{"numero": 1, "texto": "EL espíritu del Señor Jehová es sobre mí, porque me ungió Jehová; hame enviado á predicar buenas nuevas á los abatidos, á vendar á los quebrantados de corazón, á publicar libertad á los cautivos, y á los presos abertura de la cárcel;"}, {"numero": 2, "texto": "A promulgar año de la buena voluntad de Jehová, y día de venganza del Dios nuestro; á consolar á todos los enlutados;"}, {"numero": 3, "texto": "A ordenar á Sión á los enlutados, para darles gloria en lugar de ceniza, óleo de gozo en lugar del luto, manto de alegría en lugar del espíritu angustiado; y serán llamados árboles de justicia, plantío de Jehová, para gloria suya."}, {"numero": 4, "texto": "Y edificarán los desiertos antiguos, y levantarán los asolamientos primeros, y restaurarán las ciudades asoladas, los asolamientos de muchas generaciones."}, {"numero": 5, "texto": "Y estarán extranjeros, y apacentarán vuestras ovejas, y los extraños serán vuestros labradores y vuestros viñadores."}, {"numero": 6, "texto": "Y vosotros seréis llamados sacerdotes de Jehová, ministros del Dios nuestro seréis dichos: comeréis las riquezas de las gentes, y con su gloria seréis sublimes."}, {"numero": 7, "texto": "En lugar de vuestra doble confusión, y de vuestra deshonra, os alabarán en sus heredades; por lo cual en sus tierras poseerán doblado, y tendrán perpetuo gozo."}, {"numero": 8, "texto": "Porque yo Jehová soy amador del derecho, aborrecedor del latrocinio para holocausto; por tanto afirmaré en verdad su obra, y haré con ellos pacto perpetuo."}, {"numero": 9, "texto": "Y la simiente de ellos será conocida entre las gentes, y sus renuevos en medio de los pueblos; todos los que los vieren, los conocerán, que son simiente bendita de Jehová."}, {"numero": 10, "texto": "En gran manera me gozaré en Jehová, mi alma se alegrará en mi Dios; porque me vistió de vestidos de salud, rodeóme de manto de justicia, como á novio me atavió, y como á novia compuesta de sus joyas."}, {"numero": 11, "texto": "Porque como la tierra produce su renuevo, y como el huerto hace brotar su simiente, así el Señor Jehová hará brotar justicia y alabanza delante de todas las gentes."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jl', 2, 'pt', '[{"numero": 1, "texto": "Tocai a trombeta em Sião, e alertai em alta voz no meu santo monte; perturbem-se todos os moradores desta terra; porque o dia do SENHOR vem, porque perto está."}, {"numero": 2, "texto": "Dia de trevas e de escuridão, dia de nuvens e densas trevas, como a madrugada espalhada sobre os montes; um povo grande e poderoso, como nunca houve desde a antiguidade, nem depois dele jamais haverá, de geração em geração."}, {"numero": 3, "texto": "Diante dele o fogo consome, e atrás dele a chama arde; a terra adiante dele é como o jardim do Éden, mas atrás dele como deserto devastado; nada há que dele possa escapar."}, {"numero": 4, "texto": "Sua aparência é como a aparência de cavalos, e correrão como cavaleiros."}, {"numero": 5, "texto": "Saltarão como estrondo de carruagens sobre as topos dos montes, como som de chama de fogo que consome a palha, como povo poderoso, em posição de combate."}, {"numero": 6, "texto": "Diante dele os povos se angustiarão, todos os rostos se afligirão."}, {"numero": 7, "texto": "Como guerreiros correrão, como homens de guerra subirão a muralha; e cada um irá em seus caminhos, e não torcerão suas veredas."}, {"numero": 8, "texto": "Nenhum apertará ao outro; irão cada um em seu percurso; irrompem sem desfazerem suas fileiras."}, {"numero": 9, "texto": "Irão pela cidade, correrão pela muralha, subirão nas casas, entrarão pelas janelas como ladrão."}, {"numero": 10, "texto": "A terra se abala diante deles, o céu se estremece; o sol e a lua se escurecem, e as estrelas retiram seu brilho."}, {"numero": 11, "texto": "E o SENHOR levanta sua voz diante de seu exército; porque suas tropas são muito grandes; porque forte é aquele que cumpre sua palavra; porque o dia do SENHOR é grande, e muito terrível; quem poderá o suportar?"}, {"numero": 12, "texto": "Por isso agora o SENHOR diz: Convertei-vos a mim com todo o vosso coração, com jejum, choro e pranto."}, {"numero": 13, "texto": "Rasgai vosso coração, e não vossas vestes.Convertei-vos ao SENHOR vosso Deus, porque ele é piedoso e misericordioso, que demora para se irar, e é grande em bondade, e que se arrepende de castigar."}, {"numero": 14, "texto": "Quem sabe talvez ele volte atrás e se arrependa, e deixe após si uma bênção, uma oferta de alimento de de bebida ao SENHOR vosso Deus?"}, {"numero": 15, "texto": "Tocai a trombeta em Sião, santificai um jejum, convocai uma reunião solene."}, {"numero": 16, "texto": "Reuni o povo, santificai a congregação, juntai os anciãos, reuni as crianças e os que mamam; saia o noivo de seu cômodo, e a noiva de seu quarto."}, {"numero": 17, "texto": "Os sacerdotes, trabalhadores do SENHOR, chorem entre o pórtico e o altar, e digam: Poupa a teu povo, SENHOR, e não entregues tua herança à humilhação, para que as nações a dominem. Por que entre os povos diriam: Onde está o Deus deles?"}, {"numero": 18, "texto": "Então o SENHOR terá zelo por sua terra, e poupará a seu povo."}, {"numero": 19, "texto": "E o SENHOR responderá e dirá a seu povo: Eis que eu vos envio pão, suco de uva, e azeite, e deles sereis saciados; e nunca mais vos entregarei à humilhação entre as nações."}, {"numero": 20, "texto": "E afastarei de vós o [exército] do norte, e o lançarei na terra seca e deserta; sua frente será para o mar oriental, e sua retaguarda para o mar ocidental, e exalará seu mau cheiro; subirá sua podridão, porque fez grandes coisas."}, {"numero": 21, "texto": "Não temas, ó terra; alegra-te e encha-te de alegria, porque o SENHOR tem feito grandes coisas."}, {"numero": 22, "texto": "Não temais, vós animais do campo; porque os pastos do deserto voltarão a ficar verdes, porque as árvores darão seu fruto, a figueira e a videira mostrarão seu vigor."}, {"numero": 23, "texto": "E vós, filhos de Sião, alegrai-vos e enchei-vos de alegria no SENHOR vosso Deus; porque ele vos dará a primeira chuva com justiça, e fará descer sobre vós as primeiras e últimas chuvas do ano, assim como era antes."}, {"numero": 24, "texto": "E as eiras se encherão de trigo, e as prensas transbordarão de suco de uva e azeite."}, {"numero": 25, "texto": "Assim vos restituirei dos anos em que comeram o cortador, o comedor, o devorador e o destruidor, o meu grande exército que enviei contra vós."}, {"numero": 26, "texto": "E comereis abundantemente até vos saciar; e louvareis o nome do SENHOR vosso Deus, que fez maravilhas convosco; e nunca mais meu povo será envergonhado."}, {"numero": 27, "texto": "E sabereis que eu estou no meio de Israel, e que eu sou o SENHOR vosso Deus, e não há outro; e meu povo nunca mais será envergonhado."}, {"numero": 28, "texto": "E será depois que derramarei meu Espírito sobre toda carne; e vossos filhos e vossas filhas profetizarão; vossos velhos terão sonhos, e vossos jovens terão visões."}, {"numero": 29, "texto": "E também sobre os servos e sobre as servas, naqueles dias derramarei o meu Espírito."}, {"numero": 30, "texto": "E mostrarei maravilhas no céu e na terra; sangue, fogo, e colunas de fumaça."}, {"numero": 31, "texto": "O sol se tornará em trevas, e a lua em sangue, antes que venha o grande e temível dia do SENHOR."}, {"numero": 32, "texto": "E será que todo aquele que invocar o nome do SENHOR será salvo; porque no monte de Sião e em Jerusalém haverá livramento, assim como o SENHOR disse, entre os que restarem, aos quais o SENHOR chamar."}]'::jsonb, 'Almeida Livre'),
  ('Jl', 2, 'en', '[{"numero": 1, "texto": "Blow ye the trumpet in Zion, and sound an alarm in my holy mountain: let all the inhabitants of the land tremble: for the day of the Lord cometh, for it is nigh at hand;"}, {"numero": 2, "texto": "A day of darkness and of gloominess, a day of clouds and of thick darkness, as the morning spread upon the mountains: a great people and a strong; there hath not been ever the like, neither shall be any more after it, even to the years of many generations."}, {"numero": 3, "texto": "A fire devoureth before them; and behind them a flame burneth: the land is as the garden of Eden before them, and behind them a desolate wilderness; yea, and nothing shall escape them."}, {"numero": 4, "texto": "The appearance of them is as the appearance of horses; and as horsemen, so shall they run."}, {"numero": 5, "texto": "Like the noise of chariots on the tops of mountains shall they leap, like the noise of a flame of fire that devoureth the stubble, as a strong people set in battle array."}, {"numero": 6, "texto": "Before their face the people shall be much pained: all faces shall gather blackness."}, {"numero": 7, "texto": "They shall run like mighty men; they shall climb the wall like men of war; and they shall march every one on his ways, and they shall not break their ranks:"}, {"numero": 8, "texto": "Neither shall one thrust another; they shall walk every one in his path: and when they fall upon the sword, they shall not be wounded."}, {"numero": 9, "texto": "They shall run to and fro in the city; they shall run upon the wall, they shall climb up upon the houses; they shall enter in at the windows like a thief."}, {"numero": 10, "texto": "The earth shall quake before them; the heavens shall tremble: the sun and the moon shall be dark, and the stars shall withdraw their shining:"}, {"numero": 11, "texto": "And the Lord shall utter his voice before his army: for his camp is very great: for he is strong that executeth his word: for the day of the Lord is great and very terrible; and who can abide it?"}, {"numero": 12, "texto": "Therefore also now, saith the Lord, turn ye even to me with all your heart, and with fasting, and with weeping, and with mourning:"}, {"numero": 13, "texto": "And rend your heart, and not your garments, and turn unto the Lord your God: for he is gracious and merciful, slow to anger, and of great kindness, and repenteth him of the evil."}, {"numero": 14, "texto": "Who knoweth if he will return and repent, and leave a blessing behind him; even a meat offering and a drink offering unto the Lord your God?"}, {"numero": 15, "texto": "Blow the trumpet in Zion, sanctify a fast, call a solemn assembly:"}, {"numero": 16, "texto": "Gather the people, sanctify the congregation, assemble the elders, gather the children, and those that suck the breasts: let the bridegroom go forth of his chamber, and the bride out of her closet."}, {"numero": 17, "texto": "Let the priests, the ministers of the Lord, weep between the porch and the altar, and let them say, Spare thy people, O Lord, and give not thine heritage to reproach, that the heathen should rule over them: wherefore should they say among the people, Where is their God?"}, {"numero": 18, "texto": "Then will the Lord be jealous for his land, and pity his people."}, {"numero": 19, "texto": "Yea, the Lord will answer and say unto his people, Behold, I will send you corn, and wine, and oil, and ye shall be satisfied therewith: and I will no more make you a reproach among the heathen:"}, {"numero": 20, "texto": "But I will remove far off from you the northern army, and will drive him into a land barren and desolate, with his face toward the east sea, and his hinder part toward the utmost sea, and his stink shall come up, and his ill savour shall come up, because he hath done great things."}, {"numero": 21, "texto": "Fear not, O land; be glad and rejoice: for the Lord will do great things."}, {"numero": 22, "texto": "Be not afraid, ye beasts of the field: for the pastures of the wilderness do spring, for the tree beareth her fruit, the fig tree and the vine do yield their strength."}, {"numero": 23, "texto": "Be glad then, ye children of Zion, and rejoice in the Lord your God: for he hath given you the former rain moderately, and he will cause to come down for you the rain, the former rain, and the latter rain in the first month."}, {"numero": 24, "texto": "And the floors shall be full of wheat, and the vats shall overflow with wine and oil."}, {"numero": 25, "texto": "And I will restore to you the years that the locust hath eaten, the cankerworm, and the caterpiller, and the palmerworm, my great army which I sent among you."}, {"numero": 26, "texto": "And ye shall eat in plenty, and be satisfied, and praise the name of the Lord your God, that hath dealt wondrously with you: and my people shall never be ashamed."}, {"numero": 27, "texto": "And ye shall know that I am in the midst of Israel, and that I am the Lord your God, and none else: and my people shall never be ashamed."}, {"numero": 28, "texto": "And it shall come to pass afterward, that I will pour out my spirit upon all flesh; and your sons and your daughters shall prophesy, your old men shall dream dreams, your young men shall see visions:"}, {"numero": 29, "texto": "And also upon the servants and upon the handmaids in those days will I pour out my spirit."}, {"numero": 30, "texto": "And I will shew wonders in the heavens and in the earth, blood, and fire, and pillars of smoke."}, {"numero": 31, "texto": "The sun shall be turned into darkness, and the moon into blood, before the great and terrible day of the Lord come."}, {"numero": 32, "texto": "And it shall come to pass, that whosoever shall call on the name of the Lord shall be delivered: for in mount Zion and in Jerusalem shall be deliverance, as the Lord hath said, and in the remnant whom the Lord shall call."}]'::jsonb, 'King James Version'),
  ('Jl', 2, 'fr', '[{"numero": 1, "texto": "Sonnez de la trompette en Sion! Faites-la retentir sur ma montagne sainte! Que tous les habitants du pays tremblent! Car le jour de l''''Eternel vient, car il est proche,"}, {"numero": 2, "texto": "Jour de ténèbres et d''''obscurité, Jour de nuées et de brouillards, Il vient comme l''''aurore se répand sur les montagnes. Voici un peuple nombreux et puissant, Tel qu''''il n''''y en a jamais eu, Et qu''''il n''''y en aura jamais dans la suite des âges."}, {"numero": 3, "texto": "Devant lui est un feu dévorant, Et derrière lui une flamme brûlante; Le pays était auparavant comme un jardin d''''Eden, Et depuis, c''''est un désert affreux: Rien ne lui échappe."}, {"numero": 4, "texto": "A les voir, on dirait des chevaux, Et ils courent comme des cavaliers."}, {"numero": 5, "texto": "A les entendre, on dirait un bruit de chars Sur le sommet des montagnes où ils bondissent, On dirait un pétillement de la flamme du feu, Quand elle consume le chaume. C''''est comme une armée puissante Qui se prépare au combat."}, {"numero": 6, "texto": "Devant eux les peuples tremblent, Tous les visages pâlissent."}, {"numero": 7, "texto": "Ils s''''élancent comme des guerriers, Ils escaladent les murs comme des gens de guerre; Chacun va son chemin, Sans s''''écarter de sa route."}, {"numero": 8, "texto": "Ils ne se pressent point les uns les autres, Chacun garde son rang; Ils se précipitent au travers des traits Sans arrêter leur marche."}, {"numero": 9, "texto": "Ils se répandent dans la ville, Courent sur les murailles, Montent sur les maisons, Entrent par les fenêtres comme un voleur."}, {"numero": 10, "texto": "Devant eux la terre tremble, Les cieux sont ébranlés, Le soleil et la lune s''''obscurcissent, Et les étoiles retirent leur éclat."}, {"numero": 11, "texto": "L''''Eternel fait entendre sa voix devant son armée; Car son camp est immense, Et l''''exécuteur de sa parole est puissant; Car le jour de l''''Eternel est grand, il est terrible: Qui pourra le soutenir?"}, {"numero": 12, "texto": "Maintenant encore, dit l''''Eternel, Revenez à moi de tout votre coeur, Avec des jeûnes, avec des pleurs et des lamentations!"}, {"numero": 13, "texto": "Déchirez vos coeurs et non vos vêtements, Et revenez à l''''Eternel, votre Dieu; Car il est compatissant et miséricordieux, Lent à la colère et riche en bonté, Et il se repent des maux qu''''il envoie."}, {"numero": 14, "texto": "Qui sait s''''il ne reviendra pas et ne se repentira pas, Et s''''il ne laissera pas après lui la bénédiction, Des offrandes et des libations pour l''''Eternel, votre Dieu?"}, {"numero": 15, "texto": "Sonnez de la trompette en Sion! Publiez un jeûne, une convocation solennelle!"}, {"numero": 16, "texto": "Assemblez le peuple, formez une sainte réunion! Assemblez les vieillards, Assemblez les enfants, Même les nourrissons à la mamelle! Que l''''époux sorte de sa demeure, Et l''''épouse de sa chambre!"}, {"numero": 17, "texto": "Qu''''entre le portique et l''''autel Pleurent les sacrificateurs, Serviteurs de l''''Eternel, Et qu''''ils disent: Eternel, épargne ton peuple! Ne livre pas ton héritage à l''''opprobre, Aux railleries des nations! Pourquoi dirait-on parmi les peuples: Où est leur Dieu?"}, {"numero": 18, "texto": "L''''Eternel est ému de jalousie pour son pays, Et il épargne son peuple."}, {"numero": 19, "texto": "L''''Eternel répond, il dit à son peuple: Voici, je vous enverrai du blé, Du moût et de l''''huile, Et vous en serez rassasiés; Et je ne vous livrerai plus à l''''opprobre parmi les nations."}, {"numero": 20, "texto": "J''''éloignerai de vous l''''ennemi du nord, Je le chasserai vers une terre aride et déserte, Son avant-garde dans la mer orientale, Son arrière-garde dans la mer occidentale; Et son infection se répandra, Sa puanteur s''''élèvera dans les airs, Parce qu''''il a fait de grandes choses."}, {"numero": 21, "texto": "Terre, ne crains pas, Sois dans l''''allégresse et réjouis-toi, Car l''''Eternel fait de grandes choses!"}, {"numero": 22, "texto": "Bêtes des champs, ne craignez pas, Car les plaines du désert reverdiront, Car les arbres porteront leurs fruits, Le figuier et la vigne donneront leurs richesses."}, {"numero": 23, "texto": "Et vous, enfants de Sion, soyez dans l''''allégresse et réjouissez-vous En l''''Eternel, votre Dieu, Car il vous donnera la pluie en son temps, Il vous enverra la pluie de la première et de l''''arrière-saison, Comme autrefois."}, {"numero": 24, "texto": "Les aires se rempliront de blé, Et les cuves regorgeront de moût et d''''huile."}, {"numero": 25, "texto": "Je vous remplacerai les années Qu''''ont dévorées la sauterelle, Le jélek, le hasil et le gazam, Ma grande armée que j''''avais envoyée contre vous."}, {"numero": 26, "texto": "Vous mangerez et vous vous rassasierez, Et vous célébrerez le nom de l''''Eternel, votre Dieu, Qui aura fait pour vous des prodiges; Et mon peuple ne sera plus jamais dans la confusion."}, {"numero": 27, "texto": "Et vous saurez que je suis au milieu d''''Israël, Que je suis l''''Eternel, votre Dieu, et qu''''il n''''y en a point d''''autre, Et mon peuple ne sera plus jamais dans la confusion."}, {"numero": 28, "texto": "Après cela, je répandrai mon esprit sur toute chair; Vos fils et vos filles prophétiseront, Vos vieillards auront des songes, Et vos jeunes gens des visions."}, {"numero": 29, "texto": "Même sur les serviteurs et sur les servantes, Dans ces jours-là, je répandrai mon esprit."}, {"numero": 30, "texto": "Je ferai paraître des prodiges dans les cieux et sur la terre, Du sang, du feu, et des colonnes de fumée;"}, {"numero": 31, "texto": "Le soleil se changera en ténèbres, Et la lune en sang, Avant l''''arrivée du jour de l''''Eternel, De ce jour grand et terrible."}, {"numero": 32, "texto": "Alors quiconque invoquera le nom de l''''Eternel sera sauvé; Le salut sera sur la montagne de Sion et à Jérusalem, Comme a dit l''''Eternel, Et parmi les réchappés que l''''Eternel appellera."}]'::jsonb, 'Louis Segond 1910'),
  ('Jl', 2, 'es', '[{"numero": 1, "texto": "TOCAD trompeta en Sión, y pregonad en mi santo monte: tiemblen todos los moradores de la tierra; porque viene el día de Jehová, porque está cercano."}, {"numero": 2, "texto": "Día de tinieblas y de oscuridad, día de nube y de sombra, que sobre los montes se derrama como el alba: un pueblo grande y fuerte: nunca desde el siglo fué semejante, ni después de él será jamás en años de generación en generación."}, {"numero": 3, "texto": "Delante de él consumirá fuego, tras de él abrasará llama; como el huerto de Edén será la tierra delante de él, y detrás de él como desierto asolado; ni tampoco habrá quien de él escape."}, {"numero": 4, "texto": "Su parecer, como parecer de caballos; y como gente de á caballo correrán."}, {"numero": 5, "texto": "Como estruendo de carros saltarán sobre las cumbres de los montes; como sonido de llama de fuego que consume hojarascas, como fuerte pueblo aparejado para la batalla."}, {"numero": 6, "texto": "Delante de él temerán los pueblos, pondránse mustios todos los semblantes."}, {"numero": 7, "texto": "Como valientes correrán, como hombres de guerra subirán la muralla; y cada cual irá en sus caminos, y no torcerán sus sendas."}, {"numero": 8, "texto": "Ninguno apretará á su compañero, cada uno irá por su carrera; y aun cayendo sobre la espada no se herirán."}, {"numero": 9, "texto": "Irán por la ciudad, correrán por el muro, subirán por las casas, entrarán por las ventanas á manera de ladrones."}, {"numero": 10, "texto": "Delante de él temblará la tierra, se estremecerán los cielos: el sol y la luna se oscurecerán, y las estrellas retraerán su resplandor."}, {"numero": 11, "texto": "Y Jehová dará su voz delante de su ejército: porque muchos son sus reales y fuertes, que ponen en efecto su palabra: porque grande es el día de Jehová, y muy terrible; ¿y quién lo podrá sufrir?"}, {"numero": 12, "texto": "Por eso pues ahora, dice Jehová, convertíos á mí con todo vuestro corazón, con ayuno y lloro y llanto."}, {"numero": 13, "texto": "Y lacerad vuestro corazón, y no vuestros vestidos; y convertíos á Jehová vuestro Dios; porque misericordioso es y clemente, tardo para la ira, y grande en misericordia, y que se arrepiente del castigo."}, {"numero": 14, "texto": "¿Quién sabe si volverá, y se apiadará, y dejará bendición tras de él, presente y libación para Jehová Dios vuestro?"}, {"numero": 15, "texto": "Tocad trompeta en Sión, pregonad ayuno, llamad á congregación."}, {"numero": 16, "texto": "Reunid el pueblo, santificad la reunión, juntad los viejos, congregad los niños y los que maman: salga de su cámara el novio, y de su tálamo la novia."}, {"numero": 17, "texto": "Entre la entrada y el altar, lloren los sacerdotes, ministros de Jehová, y digan: Perdona, oh Jehová, á tu pueblo, y no pongas en oprobio tu heredad, para que las gentes se enseñoreen de ella. ¿Por qué han de decir entre los pueblos: Dónde está su Dios?"}, {"numero": 18, "texto": "Y Jehová celará su tierra, y perdonará su pueblo."}, {"numero": 19, "texto": "Y responderá Jehová, y dirá á su pueblo: He aquí yo os envío pan, y mosto, y aceite, y seréis saciados de ellos: y nunca más os pondré en oprobio entre las gentes."}, {"numero": 20, "texto": "Y haré alejar de vosotros al del aquilón, y echarélo en la tierra seca y desierta: su faz será hacia el mar oriental, y su fin al mar occidental, y exhalará su hedor; y subirá su pudrición, porque hizo grandes cosas."}, {"numero": 21, "texto": "Tierra, no temas; alégrate y gózate: porque Jehová ha de hacer grandes cosas."}, {"numero": 22, "texto": "Animales del campo, no temáis; porque los pastos del desierto reverdecerán, porque los árboles llevarán su fruto, la higuera y la vid darán sus frutos."}, {"numero": 23, "texto": "Vosotros también, hijos de Sión, alegraos y gozaos en Jehová vuestro Dios; porque os ha dado la primera lluvia arregladamente, y hará descender sobre vosotros lluvia temprana y tardía como al principio."}, {"numero": 24, "texto": "Y las eras se henchirán de trigo, y los lagares rebosarán de vino y aceite."}, {"numero": 25, "texto": "Y os restituiré los años que comió la oruga, la langosta, el pulgón, y el revoltón; mi grande ejército que envié contra vosotros."}, {"numero": 26, "texto": "Y comeréis hasta saciaros, y alabaréis el nombre de Jehová vuestro Dios, el cual hizo maravillas con vosotros: y nunca jamás será mi pueblo avergonzado."}, {"numero": 27, "texto": "Y conoceréis que en medio de Israel estoy yo, y que yo soy Jehová vuestro Dios, y no hay otro: y mi pueblo nunca jamás será avergonzado."}, {"numero": 28, "texto": "Y será que después de esto, derramaré mi Espíritu sobre toda carne, y profetizarán vuestros hijos y vuestras hijas; vuestros viejos soñarán sueños, y vuestros mancebos verán visiones."}, {"numero": 29, "texto": "Y aun también sobre los siervos y sobre las siervas derramaré mi Espíritu en aquellos días."}, {"numero": 30, "texto": "Y daré prodigios en el cielo y en la tierra, sangre, y fuego, y columnas de humo."}, {"numero": 31, "texto": "El sol se tornará en tinieblas, y la luna en sangre, antes que venga el día grande y espantoso de Jehová."}, {"numero": 32, "texto": "Y será que cualquiera que invocare el nombre de Jehová, será salvo: porque en el monte de Sión y en Jerusalem habrá salvación, como Jehová ha dicho, y en los que quedaren, á los cuales Jehová habrá llamado."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jn', 1, 'pt', '[{"numero": 1, "texto": "E veio a palavra do SENHOR a Jonas, filho de Amitai, dizendo:"}, {"numero": 2, "texto": "Levanta-te, vai à grande cidade de Nínive, e prega contra ela; porque sua maldade subiu diante de mim."}, {"numero": 3, "texto": "Porém Jonas se levantou para fugir da presença do SENHOR a Társis, e desceu a Jope; e achou um navio que partia para Társis. Então pagou sua passagem e entrou nele, para ir com eles a Társis [a fim de se distanciar] do SENHOR."}, {"numero": 4, "texto": "Mas o SENHOR fez levantar um grande vento no mar; e fez-se uma tempestade tão grande no mar, que o navio estava a ponto de se quebrar."}, {"numero": 5, "texto": "Então os marinheiros tiveram medo, e cada um clamava a seu deus; e lançaram no mar os objetos que havia no navio, para com eles diminuir o peso. Jonas, porém, havia descido ao interior do navio, e se pôs a dormir profundamente."}, {"numero": 6, "texto": "E o capitão do navio se aproximou dele, e lhe disse: Que há contigo, dorminhoco? Levanta-te, e clama a teu deus; talvez ele se lembre de nós, para que não pereçamos."}, {"numero": 7, "texto": "E disseram cada um a seu companheiro: Vinde, e lancemos sortes, para sabermos por causa de quem este mal [veio] sobre nós. Então lançaram sortes, e a sorte caiu sobre Jonas."}, {"numero": 8, "texto": "Então eles lhe disseram: Conta-nos, por favor, por que nos este mal nos [veio] . Qual é a tua profissão, e de onde vens? Qual é a tua terra, e de que povo és?"}, {"numero": 9, "texto": "E ele lhes respondeu: Sou hebreu, e temo ao SENHOR, o Deus dos céu, que fez o mar e a terra."}, {"numero": 10, "texto": "Então aqueles homens tiveram um grande medo, e lhe disseram: Por que fizeste isto? Pois aqueles homens sabiam que ele estava fugindo do SENHOR, porque ele já havia lhes dito."}, {"numero": 11, "texto": "Então lhe disseram: O que faremos contigo, para que o mar se nos aquiete?Porque o mar cada vez mais se embravecia."}, {"numero": 12, "texto": "E ele lhes respondeu: Tomai-me, e lançai-me ao mar, e o mar se vos aquietará; porque eu sei que foi por minha causa que esta grande tempestade [veio] sobre vós."}, {"numero": 13, "texto": "Mas os homens se esforçavam para remar, tentando voltar à terra firme; porém não conseguiam, porque o mar cada vez mais se embravecia sobre eles."}, {"numero": 14, "texto": "Então clamaram ao SENHOR, e disseram: Ó SENHOR, nós te pedimos para não perecermos por causa da alma deste homem, nem ponhas sangue inocente sobre nós; porque, tu, SENHOR, fizeste como te agradou."}, {"numero": 15, "texto": "Então tomaram a Jonas, e o lançaram ao mar; e o mar se aquietou de seu furor."}, {"numero": 16, "texto": "Por isso aqueles homens temeram ao SENHOR [com] grande temor; e ofereceram sacrifício ao SENHOR, e prometeram votos."}, {"numero": 17, "texto": "Mas o SENHOR havia preparado um grande peixe para que tragasse a Jonas; e Jonas esteve três dias e três noites no ventre do peixe."}]'::jsonb, 'Almeida Livre'),
  ('Jn', 1, 'en', '[{"numero": 1, "texto": "Now the word of the Lord came unto Jonah the son of Amittai, saying,"}, {"numero": 2, "texto": "Arise, go to Nineveh, that great city, and cry against it; for their wickedness is come up before me."}, {"numero": 3, "texto": "But Jonah rose up to flee unto Tarshish from the presence of the Lord, and went down to Joppa; and he found a ship going to Tarshish: so he paid the fare thereof, and went down into it, to go with them unto Tarshish from the presence of the Lord."}, {"numero": 4, "texto": "But the Lord sent out a great wind into the sea, and there was a mighty tempest in the sea, so that the ship was like to be broken."}, {"numero": 5, "texto": "Then the mariners were afraid, and cried every man unto his god, and cast forth the wares that were in the ship into the sea, to lighten it of them. But Jonah was gone down into the sides of the ship; and he lay, and was fast asleep."}, {"numero": 6, "texto": "So the shipmaster came to him, and said unto him, What meanest thou, O sleeper? arise, call upon thy God, if so be that God will think upon us, that we perish not."}, {"numero": 7, "texto": "And they said every one to his fellow, Come, and let us cast lots, that we may know for whose cause this evil is upon us. So they cast lots, and the lot fell upon Jonah."}, {"numero": 8, "texto": "Then said they unto him, Tell us, we pray thee, for whose cause this evil is upon us; What is thine occupation? and whence comest thou? what is thy country? and of what people art thou?"}, {"numero": 9, "texto": "And he said unto them, I am an Hebrew; and I fear the Lord, the God of heaven, which hath made the sea and the dry land."}, {"numero": 10, "texto": "Then were the men exceedingly afraid, and said unto him. Why hast thou done this? For the men knew that he fled from the presence of the Lord, because he had told them."}, {"numero": 11, "texto": "Then said they unto him, What shall we do unto thee, that the sea may be calm unto us? for the sea wrought, and was tempestuous."}, {"numero": 12, "texto": "And he said unto them, Take me up, and cast me forth into the sea; so shall the sea be calm unto you: for I know that for my sake this great tempest is upon you."}, {"numero": 13, "texto": "Nevertheless the men rowed hard to bring it to the land; but they could not: for the sea wrought, and was tempestuous against them."}, {"numero": 14, "texto": "Wherefore they cried unto the Lord, and said, We beseech thee, O Lord, we beseech thee, let us not perish for this man''s life, and lay not upon us innocent blood: for thou, O Lord, hast done as it pleased thee."}, {"numero": 15, "texto": "So they took up Jonah, and cast him forth into the sea: and the sea ceased from her raging."}, {"numero": 16, "texto": "Then the men feared the Lord exceedingly, and offered a sacrifice unto the Lord, and made vows."}, {"numero": 17, "texto": "Now the Lord had prepared a great fish to swallow up Jonah. And Jonah was in the belly of the fish three days and three nights."}]'::jsonb, 'King James Version'),
  ('Jn', 1, 'fr', '[{"numero": 1, "texto": "La parole de l''''Eternel fut adressée à Jonas, fils d''''Amitthaï, en ces mots:"}, {"numero": 2, "texto": "Lève-toi, va à Ninive, la grande ville, et crie contre elle! car sa méchanceté est montée jusqu''''à moi."}, {"numero": 3, "texto": "Et Jonas se leva pour s''''enfuir à Tarsis, loin de la face de l''''Eternel. Il descendit à Japho, et il trouva un navire qui allait à Tarsis; il paya le prix du transport, et s''''embarqua pour aller avec les passagers à Tarsis, loin de la face de l''''Eternel."}, {"numero": 4, "texto": "Mais l''''Eternel fit souffler sur la mer un vent impétueux, et il s''''éleva sur la mer une grande tempête. Le navire menaçait de faire naufrage."}, {"numero": 5, "texto": "Les mariniers eurent peur, ils implorèrent chacun leur dieu, et ils jetèrent dans la mer les objets qui étaient sur le navire, afin de le rendre plus léger. Jonas descendit au fond du navire, se coucha, et s''''endormit profondément."}, {"numero": 6, "texto": "Le pilote s''''approcha de lui, et lui dit: Pourquoi dors-tu? Lève-toi, invoque ton Dieu! peut-être voudra-t-il penser à nous, et nous ne périrons pas."}, {"numero": 7, "texto": "Et ils se dirent l''''un à l''''autre: Venez, et tirons au sort, pour savoir qui nous attire ce malheur. Ils tirèrent au sort, et le sort tomba sur Jonas."}, {"numero": 8, "texto": "Alors ils lui dirent: Dis-nous qui nous attire ce malheur. Quelles sont tes affaires, et d''''où viens-tu? Quel est ton pays, et de quel peuple es-tu?"}, {"numero": 9, "texto": "Il leur répondit: Je suis Hébreu, et je crains l''''Eternel, le Dieu des cieux, qui a fait la mer et la terre."}, {"numero": 10, "texto": "Ces hommes eurent une grande frayeur, et ils lui dirent: Pourquoi as-tu fait cela? Car ces hommes savaient qu''''il fuyait loin de la face de l''''Eternel, parce qu''''il le leur avait déclaré."}, {"numero": 11, "texto": "Ils lui dirent: Que te ferons-nous, pour que la mer se calme envers nous? Car la mer était de plus en plus orageuse."}, {"numero": 12, "texto": "Il leur répondit: Prenez-moi, et jetez-moi dans la mer, et la mer se calmera envers vous; car je sais que c''''est moi qui attire sur vous cette grande tempête."}, {"numero": 13, "texto": "Ces hommes ramaient pour gagner la terre, mais ils ne le purent, parce que la mer s''''agitait toujours plus contre eux."}, {"numero": 14, "texto": "Alors ils invoquèrent l''''Eternel, et dirent: O Eternel, ne nous fais pas périr à cause de la vie de cet homme, et ne nous charge pas du sang innocent! Car toi, Eternel, tu fais ce que tu veux."}, {"numero": 15, "texto": "Puis ils prirent Jonas, et le jetèrent dans la mer. Et la fureur de la mer s''''apaisa."}, {"numero": 16, "texto": "Ces hommes furent saisis d''''une grande crainte de l''''Eternel, et ils offrirent un sacrifice à l''''Eternel, et firent des voeux."}, {"numero": 17, "texto": "L''''Eternel fit venir un grand poisson pour engloutir Jonas, et Jonas fut dans le ventre du poisson trois jours et trois nuits."}]'::jsonb, 'Louis Segond 1910'),
  ('Jn', 1, 'es', '[{"numero": 1, "texto": "Y FUÉ palabra de Jehová á Jonás, hijo de Amittai, diciendo:"}, {"numero": 2, "texto": "Levántate, y ve á Nínive, ciudad grande, y pregona contra ella; porque su maldad ha subido delante de mí."}, {"numero": 3, "texto": "Y Jonás se levantó para huir de la presencia de Jehová á Tarsis, y descendió á Joppe; y halló un navío que partía para Tarsis; y pagando su pasaje entró en él, para irse con ellos á Tarsis de delante de Jehová."}, {"numero": 4, "texto": "Mas Jehová hizo levantar un gran viento en la mar, é hízose una tan gran tempestad en la mar, que pensóse se rompería la nave."}, {"numero": 5, "texto": "Y los marineros tuvieron miedo, y cada uno llamaba á su dios: y echaron á la mar los enseres que había en la nave, para descargarla de ellos. Jonás empero se había bajado á los lados del buque, y se había echado á dormir."}, {"numero": 6, "texto": "Y el maestre de la nave se llegó á él, y le dijo: ¿Qué tienes, dormilón? Levántate, y clama á tu Dios; quizá él tendrá compasión de nosotros, y no pereceremos."}, {"numero": 7, "texto": "Y dijeron cada uno á su compañero: Venid, y echemos suertes, para saber por quién nos ha venido este mal. Y echaron suertes, y la suerte cayó sobre Jonás."}, {"numero": 8, "texto": "Entonces le dijeron ellos: Decláranos ahora por qué nos ha venido este mal. ¿Qué oficio tienes, y de dónde vienes? ¿cuál es tu tierra, y de qué pueblo eres?"}, {"numero": 9, "texto": "Y él les respondió: Hebreo soy, y temo á Jehová, Dios de los cielos, que hizo la mar y la tierra."}, {"numero": 10, "texto": "Y aquellos hombres temieron sobremanera, y dijéronle: ¿Por qué has hecho esto? Porque ellos entendieron que huía de delante de Jehová, porque se lo había declarado."}, {"numero": 11, "texto": "Y dijéronle: ¿Qué te haremos, para que la mar se nos quiete? porque la mar iba á más, y se embravecía."}, {"numero": 12, "texto": "El les respondió: Tomadme, y echadme á la mar, y la mar se os quietará: porque yo sé que por mí ha venido esta grande tempestad sobre vosotros."}, {"numero": 13, "texto": "Y aquellos hombres trabajaron por tornar la nave á tierra; mas no pudieron, porque la mar iba á más, y se embravecía sobre ellos."}, {"numero": 14, "texto": "Entonces clamaron á Jehová, y dijeron: Rogámoste ahora, Jehová, que no perezcamos nosotros por la vida de aqueste hombre, ni pongas sobre nosotros la sangre inocente: porque tú, Jehová, has hecho como has querido."}, {"numero": 15, "texto": "Y tomaron á Jonás, y echáronlo á la mar; y la mar se quietó de su furia."}, {"numero": 16, "texto": "Y temieron aquellos hombres á Jehová con gran temor; y ofrecieron sacrificio á Jehová, y prometieron votos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jn', 2, 'pt', '[{"numero": 1, "texto": "E Jonas orou ao SENHOR seu Deus, desde as entranhas do peixe,"}, {"numero": 2, "texto": "E disse: Clamei da minha angústia ao SENHOR, e ele me respondeu; do ventre do Xeol gritei, [e] tu ouviste minha voz."}, {"numero": 3, "texto": "Pois tu me lançaste no profundo, no meio dos mares, e a correnteza me cercou; todas as tuas ondas e tuas vagas passaram sobre mim."}, {"numero": 4, "texto": "E eu disse: Lançado estou de diante de teus olhos; porém voltarei a ver o teu santo templo."}, {"numero": 5, "texto": "As águas me cercaram até a alma, o abismo me rodeou; as algas se enrolaram à minha cabeça."}, {"numero": 6, "texto": "Desci aos fundamentos dos montes; a terra trancou suas fechaduras a mim para sempre; porém tu tiraste minha vida da destruição, ó SENHOR meu Deus."}, {"numero": 7, "texto": "Quando minha alma desfalecia em mim, eu me lembrei do SENHOR; e minha oração chegou a ti em teu santo templo."}, {"numero": 8, "texto": "Os que dão atenção a coisas inúteis e ilusórias abandonam sua própria misericórdia."}, {"numero": 9, "texto": "Mas eu porém sacrificarei a ti com voz de gratidão; pagarei o que prometi. A salvação [vem] do SENHOR."}, {"numero": 10, "texto": "E o SENHOR falou ao peixe, e este vomitou a Jonas em terra firme."}]'::jsonb, 'Almeida Livre'),
  ('Jn', 2, 'en', '[{"numero": 1, "texto": "Then Jonah prayed unto the Lord his God out of the fish''s belly,"}, {"numero": 2, "texto": "And said, I cried by reason of mine affliction unto the Lord, and he heard me; out of the belly of hell cried I, and thou heardest my voice."}, {"numero": 3, "texto": "For thou hadst cast me into the deep, in the midst of the seas; and the floods compassed me about: all thy billows and thy waves passed over me."}, {"numero": 4, "texto": "Then I said, I am cast out of thy sight; yet I will look again toward thy holy temple."}, {"numero": 5, "texto": "The waters compassed me about, even to the soul: the depth closed me round about, the weeds were wrapped about my head."}, {"numero": 6, "texto": "I went down to the bottoms of the mountains; the earth with her bars was about me for ever: yet hast thou brought up my life from corruption, O Lord my God."}, {"numero": 7, "texto": "When my soul fainted within me I remembered the Lord: and my prayer came in unto thee, into thine holy temple."}, {"numero": 8, "texto": "They that observe lying vanities forsake their own mercy."}, {"numero": 9, "texto": "But I will sacrifice unto thee with the voice of thanksgiving; I will pay that that I have vowed. Salvation is of the Lord."}, {"numero": 10, "texto": "And the Lord spake unto the fish, and it vomited out Jonah upon the dry land."}]'::jsonb, 'King James Version'),
  ('Jn', 2, 'fr', '[{"numero": 1, "texto": "Jonas, dans le ventre du poisson, pria l''''Eternel, son Dieu."}, {"numero": 2, "texto": "Il dit: Dans ma détresse, j''''ai invoqué l''''Eternel, Et il m''''a exaucé; Du sein du séjour des morts j''''ai crié, Et tu as entendu ma voix."}, {"numero": 3, "texto": "Tu m''''as jeté dans l''''abîme, dans le coeur de la mer, Et les courants d''''eau m''''ont environné; Toutes tes vagues et tous tes flots ont passé sur moi."}, {"numero": 4, "texto": "Je disais: Je suis chassé loin de ton regard! Mais je verrai encore ton saint temple."}, {"numero": 5, "texto": "Les eaux m''''ont couvert jusqu''''à m''''ôter la vie, L''''abîme m''''a enveloppé, Les roseaux ont entouré ma tête."}, {"numero": 6, "texto": "Je suis descendu jusqu''''aux racines des montagnes, Les barres de la terre m''''enfermaient pour toujours; Mais tu m''''as fait remonter vivant de la fosse, Eternel, mon Dieu!"}, {"numero": 7, "texto": "Quand mon âme était abattue au dedans de moi, Je me suis souvenu de l''''Eternel, Et ma prière est parvenue jusqu''''à toi, Dans ton saint temple."}, {"numero": 8, "texto": "Ceux qui s''''attachent à de vaines idoles Eloignent d''''eux la miséricorde."}, {"numero": 9, "texto": "Pour moi, je t''''offrirai des sacrifices avec un cri d''''actions de grâces, J''''accomplirai les voeux que j''''ai faits: Le salut vient de l''''Eternel."}, {"numero": 10, "texto": "L''''Eternel parla au poisson, et le poisson vomit Jonas sur la terre."}]'::jsonb, 'Louis Segond 1910'),
  ('Jn', 2, 'es', '[{"numero": 1, "texto": "MAS Jehová había prevenido un gran pez que tragase á Jonás: y estuvo Jonás en el vientre del pez tres días y tres noches."}, {"numero": 2, "texto": "Y oró Jonás desde el vientre del pez á Jehová su Dios,"}, {"numero": 3, "texto": "Y dijo: Clamé de mi tribulación á Jehová, y él me oyó; del vientre del sepulcro clamé, y mi voz oiste."}, {"numero": 4, "texto": "Echásteme en el profundo, en medio de los mares, y rodeóme la corriente; todas tus ondas y tus olas pasaron sobre mí."}, {"numero": 5, "texto": "Y yo dije: Echado soy de delante de tus ojos: mas aun veré tu santo templo."}, {"numero": 6, "texto": "Las aguas me rodearon hasta el alma, rodeóme el abismo; la ova se enredó á mi cabeza."}, {"numero": 7, "texto": "Descendí á las raíces de los montes; la tierra echó sus cerraduras sobre mí para siempre: mas tú sacaste mi vida de la sepultura, oh Jehová Dios mío."}, {"numero": 8, "texto": "Cuando mi alma desfallecía en mí, acordéme de Jehová; y mi oración entró hasta ti en tu santo templo."}, {"numero": 9, "texto": "Los que guardan las vanidades ilusorias, su misericordia abandonan."}, {"numero": 10, "texto": "Yo empero con voz de alabanza te sacrificaré; pagaré lo que prometí. La salvación pertenece á Jehová. Y mandó Jehová al pez, y vomitó á Jonás en tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jn', 3, 'pt', '[{"numero": 1, "texto": "E a palavra do SENHOR veio pela segunda vez a Jonas, dizendo:"}, {"numero": 2, "texto": "Levanta-te, e vai à grande cidade de Nínive, e prega contra ela a pregação que eu te falo."}, {"numero": 3, "texto": "Então Jonas se levantou, e foi a Nínive, conforme a palavra do SENHOR. E Nínive era cidade extremamente grande, de três dias de caminho."}, {"numero": 4, "texto": "E Jonas começou a entrar pela cidade, caminho de um dia, e pregava dizendo: Daqui a quarenta dias Nínive será destruída."}, {"numero": 5, "texto": "E os homens de Nínive creram em Deus; e convocaram um jejum, e se vestiram de sacos, desde o maior até o menor deles."}, {"numero": 6, "texto": "Pois quando esta palavra chegou ao rei de Nínive, ele se levantou de seu trono, e lançou de si sua roupa, e cobriu-se de saco, e se sentou em cinzas."}, {"numero": 7, "texto": "E convocou e anunciou em Nínive, por mandado do rei e de seus maiorais, dizendo: Nem pessoas nem animais, nem bois nem ovelhas, provem coisa alguma, nem se lhes dê alimento, nem bebam água;"}, {"numero": 8, "texto": "E que as pessoas e os animais se cubram de saco, e clamem fortemente a Deus; e convertam- se cada um de seu mau caminho, e da violência que está em suas mãos."}, {"numero": 9, "texto": "Quem sabe Deus mude de ideia e se arrependa, e se afaste do ardor de sua ira, para não perecermos?"}, {"numero": 10, "texto": "E Deus viu a atitude deles, que se converteram de seu mau caminho; então Deus se arrependeu do mal que tinha dito que lhes faria, e não o fez."}]'::jsonb, 'Almeida Livre'),
  ('Jn', 3, 'en', '[{"numero": 1, "texto": "And the word of the Lord came unto Jonah the second time, saying,"}, {"numero": 2, "texto": "Arise, go unto Nineveh, that great city, and preach unto it the preaching that I bid thee."}, {"numero": 3, "texto": "So Jonah arose, and went unto Nineveh, according to the word of the Lord. Now Nineveh was an exceeding great city of three days'' journey."}, {"numero": 4, "texto": "And Jonah began to enter into the city a day''s journey, and he cried, and said, Yet forty days, and Nineveh shall be overthrown."}, {"numero": 5, "texto": "So the people of Nineveh believed God, and proclaimed a fast, and put on sackcloth, from the greatest of them even to the least of them."}, {"numero": 6, "texto": "For word came unto the king of Nineveh, and he arose from his throne, and he laid his robe from him, and covered him with sackcloth, and sat in ashes."}, {"numero": 7, "texto": "And he caused it to be proclaimed and published through Nineveh by the decree of the king and his nobles, saying, Let neither man nor beast, herd nor flock, taste any thing: let them not feed, nor drink water:"}, {"numero": 8, "texto": "But let man and beast be covered with sackcloth, and cry mightily unto God: yea, let them turn every one from his evil way, and from the violence that is in their hands."}, {"numero": 9, "texto": "Who can tell if God will turn and repent, and turn away from his fierce anger, that we perish not?"}, {"numero": 10, "texto": "And God saw their works, that they turned from their evil way; and God repented of the evil, that he had said that he would do unto them; and he did it not."}]'::jsonb, 'King James Version'),
  ('Jn', 3, 'fr', '[{"numero": 1, "texto": "La parole de l''''Eternel fut adressée à Jonas une seconde fois, en ces mots:"}, {"numero": 2, "texto": "Lève-toi, va à Ninive, la grande ville, et proclames-y la publication que je t''''ordonne!"}, {"numero": 3, "texto": "Et Jonas se leva, et alla à Ninive, selon la parole de l''''Eternel. Or Ninive était une très grande ville, de trois jours de marche."}, {"numero": 4, "texto": "Jonas fit d''''abord dans la ville une journée de marche; il criait et disait: Encore quarante jours, et Ninive est détruite!"}, {"numero": 5, "texto": "Les gens de Ninive crurent à Dieu, ils publièrent un jeûne, et se revêtirent de sacs, depuis les plus grands jusqu''''aux plus petits."}, {"numero": 6, "texto": "La chose parvint au roi de Ninive; il se leva de son trône, ôta son manteau, se couvrit d''''un sac, et s''''assit sur la cendre."}, {"numero": 7, "texto": "Et il fit faire dans Ninive cette publication, par ordre du roi et de ses grands; Que les hommes et les bêtes, les boeufs et les brebis, ne goûtent de rien, ne paissent point, et ne boivent point d''''eau!"}, {"numero": 8, "texto": "Que les hommes et les bêtes soient couverts de sacs, qu''''ils crient à Dieu avec force, et qu''''ils reviennent tous de leur mauvaise voie et des actes de violence dont leurs mains sont coupables!"}, {"numero": 9, "texto": "Qui sait si Dieu ne reviendra pas et ne se repentira pas, et s''''il ne renoncera pas à son ardente colère, en sorte que nous ne périssions point?"}, {"numero": 10, "texto": "Dieu vit qu''''ils agissaient ainsi et qu''''ils revenaient de leur mauvaise voie. Alors Dieu se repentit du mal qu''''il avait résolu de leur faire, et il ne le fit pas."}]'::jsonb, 'Louis Segond 1910'),
  ('Jn', 3, 'es', '[{"numero": 1, "texto": "Y FUÉ palabra de Jehová segunda vez á Jonás, diciendo:"}, {"numero": 2, "texto": "Levántate, y ve á Nínive, aquella gran ciudad, y publica en ella el pregón que yo te diré."}, {"numero": 3, "texto": "Y levantóse Jonás, y fué á Nínive, conforme á la palabra de Jehová. Y era Nínive ciudad sobremanera grande, de tres días de camino."}, {"numero": 4, "texto": "Y comenzó Jonás á entrar por la ciudad, camino de un día, y pregonaba diciendo: De aquí á cuarenta días Nínive será destruída."}, {"numero": 5, "texto": "Y los hombres de Nínive creyeron á Dios, y pregonaron ayuno, y vistiéronse de sacos desde el mayor de ellos hasta el menor de ellos."}, {"numero": 6, "texto": "Y llegó el negocio hasta el rey de Nínive, y levantóse de su silla, y echó de sí su vestido, y cubrióse de saco, y se sentó sobre ceniza."}, {"numero": 7, "texto": "E hizo pregonar y anunciar en Nínive, por mandado del rey y de sus grandes, diciendo: Hombres y animales, bueyes y ovejas, no gusten cosa alguna, no se les dé alimento, ni beban agua:"}, {"numero": 8, "texto": "Y que se cubran de saco los hombres y los animales, y clamen á Dios fuertemente: y conviértase cada uno de su mal camino, de la rapiña que está en sus manos."}, {"numero": 9, "texto": "¿Quién sabe si se volverá y arrepentirá Dios, y se apartará del furor de su ira, y no pereceremos?"}, {"numero": 10, "texto": "Y vió Dios lo que hicieron, que se convirtieron de su mal camino: y arrepintióse del mal que había dicho les había de hacer, y no lo hizo."}]'::jsonb, 'Reina-Valera 1909')
